  str_homestory_chat_15222008 = "Aku sudah menemukan empat tempat bagus untuk tidur siang di Eraveil.",
  str_homestory_chat_15222009 = "Kita bisa tidur sampai matahari terbenam, dan tak akan ada seorang pun yang mengusik kita.",
  str_homestory_chat_15222010 = "Sepertinya kau sangat puas dengan Eraveil.",
  str_homestory_chat_15222011 = "Tak mungkin ada orang di dunia ini yang tak puas dengan Eraveil!",
  str_homestory_chat_15223001 = "Kau sibuk?",
  str_homestory_chat_15223002 = "Ah! PlayerName, aku sudah menyusun daftar tantangan menghindari kegiatan yang tanpa tujuan. Mau menyelesaikan tantangan ini bersamaku?",
  str_homestory_chat_15223003 = "Kenapa kau tiba-tiba jadi rajin begitu? Tak seperti biasanya.",
  str_homestory_chat_15223004 = "Biar kulihat...",
  str_homestory_chat_15223005 = "Tantangan tak boleh tidur berlebihan... Tantangan tak boleh berjalan-jalan tanpa tujuan...",
  str_homestory_chat_15223006 = "Tantangan tak boleh menghabiskan semua keripik kentang yang sudah hampir kedaluwarsa...",
  str_homestory_chat_15223007 = "Ini memang sangat mencerminkan dirimu.",
  str_homestory_chat_15223008 = "Terima kasih atas pujianmu.",
  str_homestory_chat_15223009 = "Semua ini sama sekali tak perlu dijadikan tantangan!",
  str_homestory_chat_15223010 = "Tapi \"berjalan-jalan tanpa tujuan\" cukup menantang juga...",
  str_homestory_chat_15251001 = "Saya mendengar Anda melihat ikan khusus?",
  str_homestory_chat_15251002 = "Saat aku sedang bermalas-malasan... Coo! Maksud saya berpikir tentang bagaimana bekerja lebih efisien di tepi sungai...",
  str_homestory_chat_15251003 = "Cara mengendur lebih efisien, maksud Anda.",
  str_homestory_chat_15251004 = "Mendekut! Tidak bekerja! Ngomong-ngomong, mari kita bicara tentang ikannya? Apakah kamu tidak tertarik?",
  str_homestory_chat_15251005 = "Iya, sebentar lagi.",
  str_homestory_chat_15251006 = "Tapi aku butuh sedikit lagi untuk menyelesaikan pekerjaanku... Coo coo!",
  str_homestory_chat_15251007 = "Aku tahu itu... Apa yang kamu butuhkan?",
  str_homestory_chat_15251008 = "Beberapa biji dari Pohon Arthur Daun Pendek.",
  str_homestory_chat_15251009 = "Aku akan pergi mencari beberapa.",
  str_homestory_chat_14899999 = "Kau menyapaku?",
  str_homestory_chat_14801001 = "Ah, ya.",
  str_homestory_chat_14801002 = "Memangnya ada yang salah kalau aku menyapamu?",
  str_homestory_chat_14801003 = "Tidak, hanya saja aku tak terbiasa punya waktu senggang sampai-sampai bisa berhenti sebentar sekadar untuk menyapa orang lain.",
  str_homestory_chat_14801004 = "Banyak sekali yang harus kukerjakan.",
  str_homestory_chat_14801005 = "Eh, kau mengakhiri percakapan kita dengan cara sekasar ini?",
  str_homestory_chat_14801006 = "Kalau ada yang mau kaukatakan, katakan saja.",
  str_homestory_chat_14821001 = "Kau sedang cari apa?",
  str_homestory_chat_14821002 = "Apa kaulihat Robyn?",
  str_homestory_chat_14821003 = "Robyn! Robyn!",
  str_homestory_chat_14821004 = "Tidak, aku belum melihatnya...",
  str_homestory_chat_14821005 = "Apa kau sedang terburu-buru mencarinya? Aku bisa membantumu.",
  str_homestory_chat_14821006 = "Tentu saja aku terburu-buru! Sudah sepuluh menit aku tak melihatnya!",
  str_homestory_chat_14821007 = "Belum pernah aku berpisah dengannya selama itu!",
  str_homestory_chat_14821008 = "I-Itu agak berlebihan...",
  str_homestory_chat_14821009 = "Di sana...",
  str_homestory_chat_14821010 = "Omong-omong, kenapa sepertinya kau selalu saja mencari-cari saudarimu itu?",
  str_homestory_chat_14821011 = "Apa maksudmu? Sebenarnya kau mau bilang apa, sih?",
  str_homestory_chat_14821012 = "Tidak, tidak, aku tak bermaksud apa-apa...",
  str_homestory_chat_14821013 = "Sebaiknya kau bergegas dan mencari saudarimu itu.",
  str_homestory_chat_14822001 = "Kau sedang melamun?",
  str_homestory_chat_14822002 = "Ya... Apa kalian punya hal yang menarik di sini?",
  str_homestory_chat_14822003 = "\"Hal yang menarik\"?",
  str_homestory_chat_14822004 = "Misalnya vas antik, batu bertuliskan huruf kuno...",
  str_homestory_chat_14822005 = "Apa kalian punya benda seperti itu di sini?",
  str_homestory_chat_14822006 = "Ya!",
  str_homestory_chat_14822007 = "Lain kali, aku akan mengajakmu.",
  str_homestory_chat_14822008 = "Bagus. Aku tak tahu ternyata kau juga menyediakan layanan perburuan harta karun.",
  str_homestory_chat_14822009 = "Tidak...",
  str_homestory_chat_14822010 = "Sudah kuduga, ini sama sekali tak terduga.",
  str_homestory_chat_14822011 = "Sudahlah, bukan masalah besar kalau di sini tak ada benda-benda seperti itu.",
  str_homestory_chat_14823001 = "Sepertinya kau punya banyak waktu senggang.",
  str_homestory_chat_14823002 = "Bosan, dan tak ada ajang pertarungan.",
  str_homestory_chat_14823003 = "Memangnya tadi siapa yang sedang menulis lirik lagu sebelum masuk ke sini—",
  str_homestory_chat_14823004 = "Sudah cukup lama kau hidup dengan pedang dan darah. Sudah waktunya kau hidup nyaman. Ya, 'kan?",
  str_homestory_chat_14823005 = "Ya, ya, kau benar.",
  str_homestory_chat_14823006 = "Minggir.",
  str_homestory_chat_14823007 = "Apa maumu?",
  str_homestory_chat_14823008 = "Biarkan aku mengayunkan pedangku ke pohon itu beberapa kali. Kalau rasa dahagaku akan pedang ini sudah terpuaskan...",
  str_homestory_chat_14823009 = "Aku bisa kembali menjalani hidup yang nyaman.",
  str_homestory_chat_14823010 = "Hoi! Jangan merusak lingkungan!",
  str_homestory_chat_14824001 = "Apa rencanamu?",
  str_homestory_chat_14824002 = "Rencana? Tidak ada.",
  str_homestory_chat_14824003 = "Betapa membosankan hidup ini jika segalanya direncanakan!",
  str_homestory_chat_14824004 = "Apa kau sungguh hidup sesuai rencana setiap hari?",
  str_homestory_chat_14824005 = "Ya!",
  str_homestory_chat_14824006 = "Aku merasa lebih tenang jika hariku sudah direncanakan.",
  str_homestory_chat_14824007 = "Jadi, itu yang dipikirkan PlayerName?",
  str_homestory_chat_14824008 = "Kukira kau ini tipe orang yang serampangan!",
  str_homestory_chat_14824009 = "Mana mungkin…",
  str_homestory_chat_14824010 = "Semua tak pernah berjalan sesuai rencana.",
  str_homestory_chat_14824011 = "Benar sekali!",
  str_homestory_chat_14824012 = "Setiap hari berbeda, dan itulah yang membuat hidup ini menarik!",
  str_homestory_chat_14825001 = "Anda ingin pergi berbelanja pakaian?",
  str_homestory_chat_14825002 = "Sepertinya tidak ada tempat yang menjual pakaian di Taman Awanmu?",
  str_homestory_chat_14825003 = "Karena di sini tidak perlu... Tidak bisakah kamu pergi ke Umbraton jika ingin membeli pakaian?",
  str_homestory_chat_14825004 = "Aku ingin membeli beberapa untukmu, tukang perahu.",
  str_homestory_chat_14825005 = "Hah? Untuk saya?",
  str_homestory_chat_14825006 = "Kenapa?",
  str_homestory_chat_14825007 = "Karena kamu terus memakai pakaian yang sama, aku muak melihatnya.",
  str_homestory_chat_14825008 = "Nah ... Anda ada benarnya.",
  str_homestory_chat_14825009 = "Saya tidak membutuhkan apapun.",
  str_homestory_chat_14825010 = "Nah, apakah Anda ingin pergi ke Umbraton dengan saya?",
  str_homestory_chat_14825011 = "Biar kupikirkan.",
  str_homestory_chat_14825012 = "Apa yang harus dipikirkan? Jika Anda terus pergi ke mana-mana dengan pakaian yang sama, bahkan keluarga Chubb akan muak melihat Anda.",
  str_homestory_chat_14826001 = "Praktik?",
  str_homestory_chat_14826002 = "Saya perlu berlatih dengan belati saya kadang-kadang. Saya tidak selalu bisa melawan ikan dan pohon.",
  str_homestory_chat_14826003 = "Jadi kaulah yang meninggalkan goresan di pohon...",
  str_homestory_chat_14826004 = "Bantu saya menemukan rekan tanding yang baik!",
  str_homestory_chat_14826005 = "Tidak ada yang cocok di sini.",
  str_homestory_chat_14826006 = "Anda hanya harus menempel pada pohon.",
  str_homestory_chat_14826007 = "Atau... bagaimana dengan batu?",
  str_homestory_chat_14826008 = "Saya pikir Anda membodohi saya, tukang perahu.",
  str_homestory_chat_14826009 = "Itu karena ini adalah tempat yang damai. Anda harus santai saat berada di sini.",
  str_homestory_chat_14826010 = "Saya pikir sudah saatnya saya menemukan beberapa target untuk diri saya sendiri. Chubbs itu terlihat sangat cocok!",
  str_homestory_chat_14826011 = "Mereka bergerak perlahan dan tidak akan melakukan serangan balik. Mereka bahkan terlihat sangat tahan lama.",
  str_homestory_chat_14826012 = "Tolong jangan!",
  str_homestory_chat_12299999 = "Cuaca hari ini cerah. Bagaimana kalau minum segelas solar?",
  str_homestory_chat_12221001 = "Lupakan saja.",
  str_homestory_chat_12221002 = "Solar ini sangat bagus, lho. Yakin tidak mau mencicipi segelas, nih?",
  str_homestory_chat_12221003 = "Solar lawas... Aku benar-benar tak bisa memahamimu.",
  str_homestory_chat_12222001 = "Apa pendapatmu tentang tempat ini?",
  str_homestory_chat_12222002 = "Tempat ini memang sangat menyenangkan—",
  str_homestory_chat_12222003 = "Hanya saja, harga solarnya agak kemahalan.",
  str_homestory_chat_12222004 = "Wajar saja, karena solarnya kan harus didatangkan dari jauh.",
  str_homestory_chat_12222005 = "Pasti ulah orang-orang dari Illumina itu! Mereka diam-diam menaikkan harganya!",
  str_homestory_chat_12222006 = "...Ada sesuatu, tapi aku tak yakin apakah aku harus membicarakannya atau tidak.",
  str_homestory_chat_12222007 = "Bung, tak perlu berbasa-basi denganku.",
  str_homestory_chat_12222008 = "Begini—Solar ini dikirimkan oleh Rediesel Wrench.",
  str_homestory_chat_12222009 = "!",
  str_homestory_chat_12222010 = "Kau marah?",
  str_homestory_chat_12222011 = "Terima kasih, Bung, kau memberitahukan berita ini kepadaku—",
  str_homestory_chat_12222012 = "Akhirnya aku bisa minum solar gratis!",
  str_homestory_chat_12223001 = "Jangan membahas solar lagi, ya...",
  str_homestory_chat_12223002 = "Lihat apa kau?",
  str_homestory_chat_12223003 = "Bung, kaulihat Rabbie, tidak?",
  str_homestory_chat_12223004 = "Ada perlu apa kau dengannya?",
  str_homestory_chat_12223005 = "Sudah berjam-jam aku tak melihatnya...",
  str_homestory_chat_12223006 = "Bagaimana kalau terjadi sesuatu padanya dan aku tak ada di sana untuk melindunginya—",
  str_homestory_chat_12223007 = "Aku pasti akan menyesalinya seumur hidupku!",
  str_homestory_chat_12223008 = "Cepat! Selamatkan Rabbie! Selamatkan aku!",
  str_homestory_chat_12223009 = "...Tenanglah, tenanglah. Itu hanya kepanikan dalam batinmu saja.",
  str_homestory_chat_11299999 = "Halo, Mitraku.",
  str_homestory_chat_11201001 = "Halo, Nemesis.",
  str_homestory_chat_11201002 = "Apa kau mau ikut denganku menegakkan keadilan hari ini?",
  str_homestory_chat_11201003 = "Menurutku, dengan adanya Nemesis di sini, tempat ini jadi sangat aman.",
  str_homestory_chat_11201004 = "Tentu saja. Aku tak akan pernah membiarkan kegelapan merongrong kita.",
  str_homestory_chat_11221001 = "Belakangan ini, suasana terasa damai.",
  str_homestory_chat_11221002 = "Ya, tapi kita tetap perlu berpatroli.",
  str_homestory_chat_11221003 = "Tak terlalu perlu, sih.",
  str_homestory_chat_11221004 = "Kita semua di sini berteman, jadi tak mungkin kita berkelahi.",
  str_homestory_chat_11221005 = "Kau benar juga, sih.",
  str_homestory_chat_11221006 = "Tapi, aku harus tetap melakukannya sebagai penegak hukum, untuk mencegah masalah sebelum sempat muncul.",
  str_homestory_chat_11221007 = "Ide bagus.",
  str_homestory_chat_11221008 = "Kita semua memang berteman, tapi perselisihan tetap saja mungkin terjadi.",
  str_homestory_chat_11221009 = "Akan buruk jadinya kalau sampai ada perkelahian.",
  str_homestory_chat_11221010 = "Terima kasih sudah mengakui pentingnya pekerjaanku, Mitraku.",
  str_homestory_chat_11221011 = "Akan kujaga kedamaian ini.",
  str_homestory_chat_11222001 = "Apa yang terjadi?",
  str_homestory_chat_11222002 = "Aku baru saja menghentikan seorang pria yang sedang merusak lingkungan Eraveil.",
  str_homestory_chat_11222003 = "Hah? Memangnya apa yang diperbuatnya?",
  str_homestory_chat_11222004 = "Dia berusaha memetik bunga dari kebun bunga.",
  str_homestory_chat_11222005 = "Tentu saja aku tak akan memaklumi perbuatannya yang melanggar aturan itu!",
  str_homestory_chat_11222006 = "Apa yang kaulakukan kepadanya?",
  str_homestory_chat_11222007 = "Kugunakan Blade of Judgement dan kubuat dia terpental ke udara.",
  str_homestory_chat_11222008 = "Ah, Nemesis, terima kasih sudah menjaga lingkungan di sini.",
  str_homestory_chat_11222009 = "Tapi, aku memang harus memasang tanda peringatan di kebun bunga itu—",
  str_homestory_chat_11222010 = "Peringatan apa?",
  str_homestory_chat_11222011 = "Untuk memperingatkan semua orang bahwa memetik bunga mungkin saja jadi kegiatan berbahaya.",
  str_homestory_chat_11223001 = "Kau tampak sangat gembira...",
  str_homestory_chat_11223002 = "Apa ada peristiwa bagus hari ini?",
  str_homestory_chat_11223003 = "Aku berhasil membantu seekor kucing menemukan pemiliknya.",
  str_homestory_chat_11223004 = "Si kucing dan pemiliknya sangat berterima kasih kepadaku.",
  str_homestory_chat_11223005 = "Rasanya, hari ini matahari bersinar lebih cerah.",
  str_homestory_chat_11223006 = "Hari ini memang cerah.",
  str_homestory_chat_11223007 = "Aku senang kau bisa mengalaminya bersamaku, Mitraku.",
  str_homestory_chat_11223008 = "Memang inilah yang mestinya kulakukan, menegakkan keadilan dan membantu orang lain pada hari secerah ini.",
  str_homestory_chat_11224001 = "Anda ingin menambah tenaga kerja?",
  str_homestory_chat_11224002 = "Ya, saya ingin membentuk patroli untuk menjaga hukum dan ketertiban di sini.",
  str_homestory_chat_11224003 = "Ini bukan Federasi Illumina... Anda tidak perlu terlalu cemas.",
  str_homestory_chat_11224004 = "Aku tidak bisa terus berpuas diri. Bahkan dengan watakku, akhir-akhir ini aku mulai mengendur.",
  str_homestory_chat_11224005 = "Saya tidak ingin bekerja sama sekali... Saya tidak bisa membiarkan ini berlanjut.",
  str_homestory_chat_11224006 = "Haruskah kami menugaskan Anda untuk mengingatkan semua orang untuk bekerja keras?",
  str_homestory_chat_11224007 = "Ide yang bagus! Saya akan segera melakukannya.",
  str_homestory_chat_11224008 = "Efisiensi yang luar biasa!",
  str_homestory_chat_11225001 = "Apakah Anda mencari Chubbs?",
  str_homestory_chat_11225002 = "Ya. Apa pendapatmu tentang mereka?",
  str_homestory_chat_11225003 = "Mereka teman yang baik.",
  str_homestory_chat_11225004 = "Hanya teman, ya...",
  str_homestory_chat_11225005 = "Mereka adalah arsitek Cloud Gardens.",
  str_homestory_chat_11225006 = "Arsitek?",
  str_homestory_chat_11225007 = "Sigh... Sepertinya kamu belum menemukan sifat baiknya.",
  str_homestory_chat_11225008 = "Misalnya?",
  str_homestory_chat_11225009 = "Mereka disiplin. Ketika saya memberi mereka perintah, mereka selalu menyelesaikan pekerjaan.",
  str_homestory_chat_11225010 = "Akan sangat sempurna jika Anda dapat mengatur mereka menjadi kekuatan untuk menjaga keamanan publik di sini.",
  str_homestory_chat_11225011 = "Sayang sekali mereka tidak tertarik ketika saya membicarakannya. Yang mereka jawab hanyalah, \"Chubb.\"",
  str_homestory_chat_11225012 = "Saya kira mereka menolak gagasan itu ...",
  str_homestory_chat_11226001 = "Sesuatu di pikiran Anda?",
  str_homestory_chat_11226002 = "Saya bertanya-tanya apakah saya harus menetapkan beberapa aturan di sini.",
  str_homestory_chat_11226003 = "Misalnya?",
  str_homestory_chat_11226004 = "Aturan pemilahan sampah, pembersihan kamar secara teratur, dan sebagainya.",
  str_homestory_chat_11226005 = "Saya pikir Cloud Gardens secara bertahap akan menjadi seperti Illumina jika Anda melakukan itu...",
  str_homestory_chat_11226006 = "Apakah Anda tidak senang dengan bagaimana kehidupan di sini?",
  str_homestory_chat_11226007 = "Tidak, ini sangat nyaman, tapi entah kenapa aku merasa tidak pada tempatnya.",
  str_homestory_chat_11226008 = "Saya tidak bisa tidur nyenyak di malam hari jika saya tidak melakukan sesuatu.",
  str_homestory_chat_11226009 = "Saya pikir Anda terlalu terbiasa berada di Illumina... Perlakukan saja waktu Anda di sini seperti sedang berlibur.",
  str_homestory_chat_11226010 = "Liburan juga merupakan bagian dari sistem Illumina. Anda harus mengikutinya.",
  str_homestory_chat_11226011 = "Saya kira ketika saya memikirkannya seperti itu ... itu diperbolehkan.",
  str_homestory_chat_12599999 = "Hai! Ini hari baru, dan ide-ide baru akan muncul.",
  str_homestory_chat_12521001 = "Untuk pertunjukan?",
  str_homestory_chat_12521002 = "Ah... PlayerName, kau sudah tak sabar ingin menyaksikan pertunjukanku, ya?",
  str_homestory_chat_12521003 = "Seleramu bagus. Pertunjukanku memang tak pernah mengecewakan.",
  str_homestory_chat_12521004 = "...Tapi, sebenarnya aku sama sekali tak bermaksud menyebut pertunjukanmu.",
  str_homestory_chat_12521005 = "Tapi, bukan masalah juga kalau kau ingin menggelar pertunjukan.",
  str_homestory_chat_12522001 = "Dari naskah itu?",
  str_homestory_chat_12522002 = "Ini dialognya. Mau dengar sedikit, tidak?",
  str_homestory_chat_12522003 = "Harus kuakui, PlayerName, selera estetikamu pelan-pelan meningkat.",
  str_homestory_chat_12522004 = "Ehem. Dalam malam gelap dan tanpa akhir, kudengar suara hati yang remuk redam—",
  str_homestory_chat_12522005 = "Terlalu melodramatis, tidak?",
  str_homestory_chat_12522006 = "Ya, dengan semua kosakata yang luar biasa ini, yang harus disampaikan adalah...",
  str_homestory_chat_12522007 = "Rasa sedih dan putus asa...",
  str_homestory_chat_12522008 = "Inilah wajah sejati dunia yang kita tinggali ini!",
  str_homestory_chat_12522009 = "PlayerName, sepertinya penilaianku tentang dirimu memang benar.",
  str_homestory_chat_12522010 = "Selera estetikamu pelan-pelan meningkat berkat pengaruh dariku.",
  str_homestory_chat_12522011 = "Apa ini terlalu menyeramkan?",
  str_homestory_chat_12522012 = "Menyeramkan? Memangnya kau tak merasakannya...?",
  str_homestory_chat_12522013 = "Di balik deskripsi rasa takut, ada duka dan nestapa yang mengalir deras.",
  str_homestory_chat_12522014 = "Uh, tidak...",
  str_homestory_chat_12522015 = "PlayerName, sayang sekali, aku terpaksa menarik kembali penilaianku yang tadi tentang dirimu.",
  str_homestory_chat_12523001 = "Bagaimana kabarmu?",
  str_homestory_chat_12523002 = "PlayerName, bukankah tempat ini terasa terlalu sempit?",
  str_homestory_chat_12523003 = "Kenapa bisa begitu?",
  str_homestory_chat_12523004 = "Kurasa, Other End sama sekali tak akan bisa melewatinya!",
  str_homestory_chat_12523005 = "Kalau kita mengemudikannya di sini, sudah barang tentu kita akan menabrak dinding, atau pohon...",
  str_homestory_chat_12523006 = "Tidak, ah.",
  str_homestory_chat_12523007 = "Tapi, tempat ini bahkan tak cukup lebar untuk dilewati Other End.",
  str_homestory_chat_12523008 = "Kalau begitu, apakah Other End yang kusayangi ini harus terbang di langit saja?",
  str_homestory_chat_12523009 = "Sebentar! Memangnya kenapa kau ingin mengemudikan kereta di tempat yang dipakai orang-orang untuk berjalan?!",
  str_homestory_chat_12524001 = "Kudengar kau punya rencana...",
  str_homestory_chat_12524002 = "Ya. PlayerName, memangnya kau tak berniat membangun sesuatu di atas lahan kosong ini?",
  str_homestory_chat_12524003 = "Membangun apa?",
  str_homestory_chat_12524004 = "Panggung!",
  str_homestory_chat_12524005 = "Panggung yang akan menjadi milikku, sang seniman, dan Other End!",
  str_homestory_chat_12524006 = "Bagaimana menurutmu? Ini usul yang sangat penuh gairah dan kreatif, 'kan?",
  str_homestory_chat_12524007 = "Aku tak mau membangun apa pun.",
  str_homestory_chat_12524008 = "PlayerName, coba lihat lahan kosong ini. Tampak pucat, 'kan?",
  str_homestory_chat_12524009 = "Lahan ini menunggu datangnya gairah artistik untuk menorehkan warna ke atasnya—",
  str_homestory_chat_12524010 = "Jadi… Maksudmu apa, sih?",
  str_homestory_chat_12524011 = "Jadi, ayo bangun panggung di sini! Untuk seni dan Other End!",
  str_homestory_chat_12524012 = "Uh, nanti akan kupertimbangkan, ya.",
  str_homestory_chat_12525001 = "Acara pesta hari ini...",
  str_homestory_chat_12525002 = "Maksudmu... malam ini akan ada acara pesta?",
  str_homestory_chat_12525003 = "Aku tak mau menghadirinya! Seniman jahat ditakdirkan untuk hidup sendirian hingga akhir.",
  str_homestory_chat_12525004 = "Tapi, kau justru terlihat seperti sangat ingin menghadirinya...",
  str_homestory_chat_12525005 = "Ehem, penglihatanmu salah.",
  str_homestory_chat_12525006 = "Tapi, kalau kau bersikeras mengundangku, kurasa aku akan bermurah hati dan menerima undanganmu itu...",
  str_homestory_chat_12525007 = "Baiklah, kalau begitu aku bersikeras mengundangmu.",
  str_homestory_chat_12525008 = "Baiklah. Sampai jumpa nanti.",
  str_homestory_chat_12525009 = "...Kau tak mau bersikeras mengundang, nih?",
  str_homestory_chat_12525010 = "Baiklah…",
  str_homestory_chat_12525011 = "Ehem. Charon, malam ini akan ada acara pesta. Aku sepenuhnya berharap kau datang.",
  str_homestory_chat_12525012 = "Baiklah, dengan berat hati aku menerima undanganmu, demi kau.",
  str_homestory_chat_12526001 = "Aku ingin bertanya.",
  str_homestory_chat_12526002 = "Oh? Aku akan menjawab pertanyaan PlayerName sebaik mungkin.",
  str_homestory_chat_12526003 = "Katakan, Kawan. Kau punya masalah apa?",
  str_homestory_chat_12526004 = "Semua kereta berjalan di atas rel...",
  str_homestory_chat_12526005 = "Kenapa Other End tidak membutuhkannya?",
  str_homestory_chat_12526006 = "Hahahah... Pertanyaanmu sangat bagus!",
  str_homestory_chat_12526007 = "Other End itu temanku. Anggap saja aku dapat inspirasi darinya. Dan inspirasi tak boleh dikekang.",
  str_homestory_chat_12526008 = "Bagaimana kau bisa bilang ia bebas kalau ia terjebak dalam rel?",
  str_homestory_chat_12526009 = "Tapi, dia tak bisa mengamuk begitu saja di Eraveil!",
  str_homestory_chat_10699999 = "PlayerName, mau mengobrol denganku, tidak?",
  str_homestory_chat_10601001 = "Baiklah.",
  str_homestory_chat_10601002 = "Aku akan senang sekali, tapi jangan sampai kau lupa waktu, ya.",
  str_homestory_chat_10601003 = "Jangan lupa, kau sudah punya rencana untuk kauselesaikan nanti.",
  str_homestory_chat_10621001 = "Soal makanan penutupnya...",
  str_homestory_chat_10621002 = "Apa kau punya saran tentang gayanya?",
  str_homestory_chat_10621003 = "Kalian mau menyajikan makanan penutup?",
  str_homestory_chat_10621004 = "Ya, kami ingin menyiapkan camilan untuk semua orang.",
  str_homestory_chat_10621005 = "Hm, kusarankan kue krim kelapa stroberi...",
  str_homestory_chat_10621006 = "Tapi, kalau terlalu repot dibuat, kau juga bisa menggantinya dengan sajian lain.",
  str_homestory_chat_10621007 = "Kue krim kelapa stroberi...",
  str_homestory_chat_10621008 = "Itu makanan penutup kesukaan Carleen, 'kan?",
  str_homestory_chat_10621009 = "Bukan berarti aku ingin memakannya... Aku hanya sebatas mengusulkannya saja.",
  str_homestory_chat_10621010 = "Kali ini, kita dibantu seorang pakar!",
  str_homestory_chat_10621011 = "Pasti akan lancar.",
  str_homestory_chat_10621012 = "Nah, semua sudah selesai. Kau harus mencicipinya!",
  str_homestory_chat_10622001 = "Cuaca hari ini cerah!",
  str_homestory_chat_10622002 = "Ya, cuaca di sini memang selalu cerah.",
  str_homestory_chat_10622003 = "Kau suka cuaca cerah, ya?",
  str_homestory_chat_10622004 = "Cuaca yang cerah membuat hati kita gembira.",
  str_homestory_chat_10622005 = "Tapi, kalau setiap hari matahari bersinar terang, bisa jadi masalah juga.",
  str_homestory_chat_10622006 = "Itu karena tidak setiap hari kita bisa menikmati cuaca cerah...",
  str_homestory_chat_10622007 = "Jadi, ketika cuaca cerah, kita jadi gembira.",
  str_homestory_chat_10622008 = "PlayerName, kata-katamu barusan sangat kaya filosofi.",
  str_homestory_chat_10622009 = "Baiklah.",
  str_homestory_chat_10622010 = "Barangkali, yang bisa membuat kita gembira bukan hanya cuaca cerah saja...",
  str_homestory_chat_10622011 = "Tapi juga suasana di sini yang penuh kedamaian.",
  str_homestory_chat_10622012 = "Kuharap setiap hari bisa seperti ini sampai selamanya.",
  str_homestory_chat_10623001 = "Apa kau punya waktu?",
  str_homestory_chat_10623002 = "PlayerName, ada yang bisa kubantu?",
  str_homestory_chat_10623003 = "Oh, ya.",
  str_homestory_chat_10623004 = "Tapi tak terlalu penting, kok.",
  str_homestory_chat_10623005 = "Kalau kau masih punya urusan lain, silakan selesaikan saja dulu.",
  str_homestory_chat_10623006 = "Biar kupikir dulu...",
  str_homestory_chat_10623007 = "Hanya beberapa hal kecil. Kau tak perlu repot-repot memikirkannya.",
  str_homestory_chat_10623008 = "Sepertinya tak ada.",
  str_homestory_chat_10623009 = "Apa kau sudah selesai mengerjakan tugasmu?",
  str_homestory_chat_10623010 = "Masih ada yang harus kukerjakan, tapi aku tak mau merepotkanmu.",
  str_homestory_chat_10623011 = "Tapi, aku bersedia membantu semua orang semampuku.",
  str_homestory_chat_10624001 = "Kudengar kau ingin menyampaikan sesuatu kepadaku.",
  str_homestory_chat_10624002 = "PlayerName, Vice bilang...",
  str_homestory_chat_10624003 = "Beberapa hari lalu, kau terlambat datang ke lomba memancing.",
  str_homestory_chat_10624004 = "Ya…",
  str_homestory_chat_10624005 = "Aku cuma punya waktu setengah jam saat berangkat, dan kukira tempatnya tak terlalu jauh...",
  str_homestory_chat_10624006 = "Kalau lain kali kau mengalami situasi seperti itu, kau bisa minta bantuanku.",
  str_homestory_chat_10624007 = "Aku bisa memanggil seekor kuda dan mengantarmu ke sana.",
  str_homestory_chat_10624008 = "Intinya, jangan biasa terlambat.",
  str_homestory_chat_10625001 = "Kudengar kau mau pergi memancing.",
  str_homestory_chat_10625002 = "Ya, apa kau berencana akan pergi memancing dalam waktu dekat ini?",
  str_homestory_chat_10625003 = "Ya!",
  str_homestory_chat_10625004 = "Kurasa sebaiknya aku bersiap-siap.",
  str_homestory_chat_10625005 = "Omong-omong soal bersiap, terakhir kali kemarin, persiapanmu terlalu lengkap.",
  str_homestory_chat_10625006 = "Kau bahkan membawa payung tenda dan tombak.",
  str_homestory_chat_10625007 = "Payung tenda itu untuk berjaga-jaga kalau hujan turun saat kita sedang memancing...",
  str_homestory_chat_10625008 = "Tombaknya bisa dipakai untuk menombak ikan yang berusaha kabur. Sekali tusuk, kena!",
  str_homestory_chat_10625009 = "Aku tak suka kalau terjadi hal-hal yang tak terduga.",
  str_homestory_chat_10625010 = "Persiapan adalah hal mendasar untuk meraih keberhasilan.",
  str_homestory_chat_10625011 = "Sepertinya lagi-lagi aku belajar sesuatu...",
  str_homestory_chat_10626001 = "Kau punya saran?",
  str_homestory_chat_10626002 = "Aku ingin memasang beberapa ornamen di sini, tapi belum tahu apa.",
  str_homestory_chat_10626003 = "Ornamen? Coba kupikir dulu...",
  str_homestory_chat_10626004 = "Bagaimana kalau peralatan untuk latihan bela diri?",
  str_homestory_chat_10626005 = "Seperti Samsak?",
  str_homestory_chat_10626006 = "Hmm... Samsak itu umum digunakan berlatih. Pasti banyak yang bisa memakainya.",
  str_homestory_chat_10626007 = "Seperti target panahan?",
  str_homestory_chat_10626008 = "Hmm... Pemanah Aurorian seperti Vice pasti menyukainya.",
  str_homestory_chat_10626009 = "Oke... Aku mengerti.",
  str_homestory_chat_10626010 = "Setelah punya rencana yang jelas, sisanya akan lebih mudah.",
  str_homestory_chat_10626011 = "Carilah cetak biru, kumpulkan material, dan bangun yang kau butuhkan.",
  str_homestory_chat_10626012 = "Benar sekali. Dan aku ahli dalam hal ini.",
  str_homestory_chat_12899999 = "Hai, kau! Apa kau punya saran?",
  str_homestory_chat_12801001 = "Tidak.",
  str_homestory_chat_12801002 = "Hanya ingin menyapa.",
  str_homestory_chat_12801003 = "Aku senang menerima sapaanmu!",
  str_homestory_chat_12801004 = "Sini, bawalah Holy Water Shell ini. Ini pasti akan berguna!",
  str_homestory_chat_12821001 = "Lihat apa kau?",
  str_homestory_chat_12821002 = "Waduh, taringku sepertinya tumbuh makin panjang.",
  str_homestory_chat_12821003 = "Aku tak menyangka salib itu bisa dijadikan cermin...",
  str_homestory_chat_12821004 = "Kau mau membandingkan panjangnya dengan taringku?",
  str_homestory_chat_12821005 = "Sini, berdirilah di depan salib ini.",
  str_homestory_chat_12821006 = "Tidak, terima kasih...",
  str_homestory_chat_12821007 = "Tenang saja, yang terpantul di salibku akan tampak sangat jelas, kok!",
  str_homestory_chat_12821008 = "Kau yakin tak mau melihat seberapa panjang taringmu?",
  str_homestory_chat_12821009 = "Atau, jangan-jangan kau tak punya taring?",
  str_homestory_chat_12822001 = "Raphael, kau sedang apa, sih?",
  str_homestory_chat_12822002 = "Huff—",
  str_homestory_chat_12822003 = "Aku mau memberikan Holy Water Bomb ini untuk semua orang.",
  str_homestory_chat_12822004 = "Setiap orang akan dapat satu!",
  str_homestory_chat_12822005 = "Kenapa?",
  str_homestory_chat_12822006 = "Yah, tentu saja karena... populasi Aurorian di Eraveil makin bertambah...",
  str_homestory_chat_12822007 = "Kalau-kalau ada orang yang tak sengaja terluka, dan aku tak ada di sana...",
  str_homestory_chat_12822008 = "Aku pasti akan sangat sedih kalau dia tak bisa menyelamatkan mereka tepat waktu!",
  str_homestory_chat_12823001 = "Hai, Raphael.",
  str_homestory_chat_12823002 = "Kue yang kubuat kemarin terasa enak, 'kan?",
  str_homestory_chat_12823003 = "Aku bisa membuatnya lagi dan memberimu sebagian!",
  str_homestory_chat_12823004 = "Uh, tak usah...",
  str_homestory_chat_12823005 = "Aku paham!",
  str_homestory_chat_12823006 = "Paham apanya?",
  str_homestory_chat_12823007 = "Kau pasti merasa bahwa kue yang kubuat itu terlalu sempurna...",
  str_homestory_chat_12823008 = "Sampai-sampai kau tak sanggup melahapnya!",
  str_homestory_chat_12823009 = "...Ya, kauanggap begitu juga boleh, lah.",
  str_homestory_chat_12823010 = "Kenapa kau mendatangiku lagi?",
  str_homestory_chat_12823011 = "Karena semua orang bilang PlayerName adalah orang yang paling cermat untuk menilai makanan!",
  str_homestory_chat_12823012 = "Kata siapa?!",
  str_homestory_chat_12823013 = "Beri tahu aku, dan akan kusarankan kau menemui seseorang yang lebih pintar lagi menilai makanan!",
  str_homestory_chat_10799999 = "La, la-la, la... Oh, PlayerName! Kau memanggilku, ya?",
  str_homestory_chat_10721001 = "Apa aku mengganggu nyanyianmu?",
  str_homestory_chat_10721002 = "T-Tidak, sama sekali tidak. Aku hanya... Anu.",
  str_homestory_chat_10721003 = "Apa kau butuh sesuatu dariku?",
  str_homestory_chat_10722001 = "Kau sedang cari apa?",
  str_homestory_chat_10722002 = "Apa di sini akan ada kelinci, PlayerName?",
  str_homestory_chat_10722003 = "Mungkin?",
  str_homestory_chat_10722004 = "Sepertinya aku melihat beberapa orang sedang merencanakan acara berburu...",
  str_homestory_chat_10722005 = "Dan salah satu buruan yang mereka bawa pulang...",
  str_homestory_chat_10722006 = "Hentikan! Jangan lanjutkan ceritanya!",
  str_homestory_chat_10722007 = "Mengerikan... Hal seperti itu harus dihentikan!",
  str_homestory_chat_10722008 = "Sepertinya tak ada.",
  str_homestory_chat_10722009 = "Aku belum pernah lihat seekor pun, sih.",
  str_homestory_chat_10722010 = "...Begitu juga tak apa. Setidaknya aku tak akan melihat mereka terluka di sini.",
  str_homestory_chat_10723001 = "Apa kau sudah terbiasa dengan tempat ini?",
  str_homestory_chat_10723002 = "Angin di sini sangat lembut...",
  str_homestory_chat_10723003 = "Begitukah menurutmu?",
  str_homestory_chat_10723004 = "Menurutmu, apa makna kebahagiaan, PlayerName?",
  str_homestory_chat_10723005 = "Tinggal di sini.",
  str_homestory_chat_10723006 = "Tinggal di kampung halamanku sendiri dan menjaga tanah ini. Bagiku...",
  str_homestory_chat_10723007 = "Ini adalah karunia.",
  str_homestory_chat_10723008 = "Oh, begitu…",
  str_homestory_chat_10723009 = "Damai dan tenang.",
  str_homestory_chat_10723010 = "Tak ada dusta, tak ada pertumpahan darah, dan semua anak selalu tersenyum...",
  str_homestory_chat_10723011 = "Itu memang... kebahagiaan yang sangat nyata.",
  str_homestory_chat_10751001 = "Mana ikan spesialnya?",
  str_homestory_chat_10751002 = "Oh angin sepoi-sepoi, perasaan yang luar biasa!",
  str_homestory_chat_10751003 = "Apa maksudmu?",
  str_homestory_chat_10751004 = "Mungkin itu kamu. Apakah Anda terburu-buru?",
  str_homestory_chat_10751005 = "Aku, sebenarnya... Kudengar kau melihat ikan spesial?",
  str_homestory_chat_10751006 = "Saya tahu kata-kata berjalan cepat, tetapi ini masih mengejutkan.",
  str_homestory_chat_10751007 = "Atau apakah itu berasal dari orang tertentu? Misalnya, kelinci itu?",
  str_homestory_chat_10751008 = "Tidak... Lupakan saja. Dimana ikannya?",
  str_homestory_chat_10751009 = "Kelinci... menyebutkan bahwa ikan menyukai sejenis pohon.",
  str_homestory_chat_10751010 = "Mungkinkah... Pohon Quinlan Dwarf Leaf?",
