  str_homestory_chat_10751014 = "Trims!",
  str_homestory_chat_10199999 = "Kuterima salammu.",
  str_homestory_chat_10121001 = "Baiklah.",
  str_homestory_chat_10121002 = "Kabarku baik. Ada lagi yang ingin kausampaikan?",
  str_homestory_chat_10121003 = "Ya, anu... aku...",
  str_homestory_chat_10121004 = "Sepertinya aku harus bersabar menunggu sampai kau bisa mengutarakannya.",
  str_homestory_chat_10122001 = "Kau ingin menemuiku?",
  str_homestory_chat_10122002 = "PlayerName, aku ingin kaucamkan satu fakta ini.",
  str_homestory_chat_10122003 = "Fakta apa?",
  str_homestory_chat_10122004 = "Area tepi perairan di sini sangat cocok untuk menanam bunga narcissus putih.",
  str_homestory_chat_10122005 = "...",
  str_homestory_chat_10122006 = "Bagaimana? Apa perlu kubuatkan daftar alasannya satu per satu?",
  str_homestory_chat_10122007 = "Tak usah... Akan kupertimbangkan.",
  str_homestory_chat_10123001 = "Bagaimana keadaanmu di sini?",
  str_homestory_chat_10123002 = "Ya... Di sini memang ada banyak tempat yang tak bisa dibandingkan dengan Northland...",
  str_homestory_chat_10123003 = "Tapi, tempat ini punya satu hal yang layak dipuji.",
  str_homestory_chat_10123004 = "Yaitu?",
  str_homestory_chat_10123005 = "Langit, udara, dan air di sini sangat jernih.",
  str_homestory_chat_10123006 = "Jika tinggal di sini, jiwa para Aurorian akan bisa tumbuh subur.",
  str_homestory_chat_10123007 = "Kedengarannya memang seperti pujian...",
  str_homestory_chat_10123008 = "Apa maksudmu tak bisa dibandingkan dengan Northland?!",
  str_homestory_chat_10123009 = "Kuharap kau tak terlalu memusingkan hal-hal sepele ini...",
  str_homestory_chat_10123010 = "Dan malah melupakan hal yang sebenarnya berharga—",
  str_homestory_chat_10123011 = "Menurutku, rumah yang bersih bisa membantu pertumbuhan bagi jiwa para Aurorian.",
  str_homestory_chat_10123012 = "Kuharap kau selalu menjaga ketenangan dan kesucian tempat ini.",
  str_homestory_chat_10123013 = "Baiklah... Tentu saja, aku akan menjaganya.",
  str_homestory_chat_10124001 = "Lihat apa kau?",
  str_homestory_chat_10124002 = "Cermin. Ada gambaran rumah lain yang muncul di dalamnya...",
  str_homestory_chat_10124003 = "Bukankah itu wajar?",
  str_homestory_chat_10124004 = "Jangan samakan Lake Mirror dengan cermin biasa.",
  str_homestory_chat_10124005 = "Cermin ini bisa menampakkan ilusi yang berada ribuan kilometer jauhnya...",
  str_homestory_chat_10124006 = "Cermin ini bisa menghubungkan dua dunia, dan membuatmu melihat jauh ke bagian terdalam di relung jiwamu...",
  str_homestory_chat_10124007 = "Jangan pernah meremehkan kekuatannya.",
  str_homestory_chat_10124008 = "Jadi... apa hubungannya itu semua dengan gambaran rumah yang muncul di dalam cermin itu?",
  str_homestory_chat_10124009 = "...",
  str_homestory_chat_10124010 = "PlayerName, jangan lagi mencariku untuk mengobrol.",
  str_homestory_chat_10299999 = "Terima kasih sudah bertanya. Kabarku baik-baik saja.",
  str_homestory_chat_10221001 = "Oh... Baguslah.",
  str_homestory_chat_10221002 = "Melihat dari penampilanmu...",
  str_homestory_chat_10221003 = "Sepertinya belakangan ini pekerjaanmu banyak. Sebaiknya perbanyak waktu istirahatmu.",
  str_homestory_chat_10221004 = "Kalau begitu, aku akan istirahat sebentar.",
  str_homestory_chat_10221005 = "Kau boleh ikut denganku untuk bermeditasi di bawah pohon di sana itu.",
  str_homestory_chat_10222001 = "Sedang menikmati pemandangan?",
  str_homestory_chat_10222002 = "Pemandangan di sini sering membuatku teringat kampung halamanku.",
  str_homestory_chat_10222003 = "Lembah, sungai, dan hutan... Yang kurang hanya bunga sakura.",
  str_homestory_chat_10222004 = "Bagaimana kalau kita tanam beberapa pohon sakura?",
