  str_homestory_chat_10222006 = "Bagaimana kalau kita tanam...",
  str_homestory_chat_10222007 = "Kau mau menanam pohon sakura di sini?",
  str_homestory_chat_10222008 = "Ya, aku memang berencana begitu.",
  str_homestory_chat_10222009 = "Tidak semua jenis tanah cocok untuk ditanami pohon sakura.",
  str_homestory_chat_10222010 = "Yah, ini masalah yang harus diatasi dengan konsultasi yang memadai.",
  str_homestory_chat_10223001 = "Sedang apa kau?",
  str_homestory_chat_10223002 = "...",
  str_homestory_chat_10223003 = "Kenapa Hiiro memukul-mukul pedang itu...",
  str_homestory_chat_10223004 = "Aku sedang membedaki Sakae.",
  str_homestory_chat_10223005 = "Apa maksudnya \"membedaki\"?",
  str_homestory_chat_10223006 = "Kalau kita mengetuk-ngetuk pedang dengan tongkat berisi bedak, bedaknya akan menyerap sisa-sisa minyak lawas yang ada di pedangnya.",
  str_homestory_chat_10223007 = "Itu semacam pemeliharaan untuk Sakae.",
  str_homestory_chat_10223008 = "Wah, luar biasa!",
  str_homestory_chat_10223009 = "Bolehkah aku menontonnya lebih lama?",
  str_homestory_chat_10223010 = "Tentu.",
  str_homestory_chat_10224001 = "Sunyi sekali…",
  str_homestory_chat_10224002 = "Lingkungan di sini cocok untuk meditasi.",
  str_homestory_chat_10224003 = "Kau menemukan tempat yang bagus untuk meditasi?",
  str_homestory_chat_10224004 = "Di kaki gunung, di tepi sungai, di bawah pepohonan, pejamkan matamu dan fokuslah pada pikiranmu...",
  str_homestory_chat_10224005 = "PlayerName, kau juga boleh mencobanya. Meditasi bisa meningkatkan kekuatanmu.",
  str_homestory_chat_10224006 = "Oh. Sepertinya patut dicoba.",
  str_homestory_chat_10224007 = "Apa kita harus memilih tempat meditasi?",
  str_homestory_chat_10224008 = "Tidak, kau tetap bisa bermeditasi meski berada di tengah kota.",
  str_homestory_chat_10224009 = "Pikiran yang tenang akan menyingkirkan segala kebisingan.",
  str_homestory_chat_10224010 = "Tapi, karena tempat ini jauh dari hiruk pikuk, bermeditasi di sini jadi mudah.",
  str_homestory_chat_10224011 = "PlayerName, kau juga boleh mencobanya.",
  str_homestory_chat_10225001 = "Sepertinya kau mewaspadai sesuatu.",
  str_homestory_chat_10225002 = "Ahli bela diri harus selalu waspada terhadap sekitarnya.",
  str_homestory_chat_10225003 = "Masuk akal, sih.",
  str_homestory_chat_10225004 = "Pasti beginilah cara Hiiro mengasah konsentrasinya.",
  str_homestory_chat_10225005 = "...",
  str_homestory_chat_10225006 = "(Sepertinya aku sudah mengusik latihan Hiiro.)",
  str_homestory_chat_10225007 = "Tak perlu gugup begitu.",
  str_homestory_chat_10225008 = "Di sini kita semua berteman.",
  str_homestory_chat_10225009 = "Aku tak bisa bersantai, bahkan di lingkungan yang nyaman sekalipun.",
  str_homestory_chat_10225010 = "Beginilah caraku mengasah konsentrasiku.",
  str_homestory_chat_10225011 = "Baiklah. Kalau begitu, aku pergi dulu, Hiiro.",
  str_homestory_chat_10226001 = "Meditasi lagi?",
  str_homestory_chat_10226002 = "Tidak, aku hanya menikmati pemandangan.",
  str_homestory_chat_10226003 = "Hmm? Hiiro bisa menyukai pemandangan juga?",
  str_homestory_chat_10226004 = "Jangan terlalu kaget. Mengamati dan belajar dari dunia ini adalah bagian dari latihanku.",
  str_homestory_chat_10226005 = "Kedengarannya rumit...",
  str_homestory_chat_10226006 = "Kau harus mencobanya.",
  str_homestory_chat_10226007 = "Latihan ini tak ada hubungannya dengan kebugaran fisikmu, tapi bermanfaat untuk pikiran dan hatimu.",
  str_homestory_chat_10226008 = "O-Oke, akan kucoba.",
  str_homestory_chat_11199999 = "Ya. Kuharap kau bisa berdiri tegak saat menyapaku lain kali, Rekan Sebangsa.",
  str_homestory_chat_11101001 = "Eh…",
  str_homestory_chat_11101002 = "Menyapa itu tak harus serius, 'kan?",
  str_homestory_chat_11101003 = "Tidak, ini tak ada hubungannya dengan keseriusan.",
  str_homestory_chat_11101004 = "Ini soal kondisi kejiwaan.",
  str_homestory_chat_11121001 = "Bagaimana kabarmu?",
  str_homestory_chat_11121002 = "Jangan berdiri terlalu dekat denganku, Rekan Sebangsa.",
  str_homestory_chat_11121003 = "Tiba-tiba aku menyadari pupilmu tampak membesar.",
  str_homestory_chat_11121004 = "Wah, kasar juga tatapanmu... Kalau orang lain yang melakukannya...",
  str_homestory_chat_11121005 = "Azure Flame punyaku pasti sudah terhunus.",
  str_homestory_chat_11121006 = "Kelihatannya sangat misterius.",
  str_homestory_chat_11121007 = "Saat fokus, aku...",
  str_homestory_chat_11121008 = "Baiklah, minggir sana.",
  str_homestory_chat_11121009 = "Oh, akan kuingat untuk lain kali.",
  str_homestory_chat_11121010 = "Kalau begitu, berdiri lebih jauh sana!",
  str_homestory_chat_11121011 = "Ah, baiklah.",
  str_homestory_chat_11122001 = "Tadi aku melihatmu jalan-jalan.",
  str_homestory_chat_11122002 = "Ada banyak batu kecil di jalan ini.",
  str_homestory_chat_11122003 = "Bukankah itu wajar?",
  str_homestory_chat_11122004 = "Ekorku selalu terjepit.",
  str_homestory_chat_11122005 = "Rekan Sebangsa, kuharap kau bisa menyingkirkan batu-batu itu.",
  str_homestory_chat_11122006 = "Oh, baiklah.",
  str_homestory_chat_11122007 = "Kau terganggu, ya?",
  str_homestory_chat_11122008 = "Iya, aku jadi terpaksa berjalan sambil mengangkat ekorku.",
  str_homestory_chat_11122009 = "Kalau tidak, ekorku bakal terjepit batu.",
  str_homestory_chat_11122010 = "Sepertinya aku memang harus membersihkan jalan.",
  str_homestory_chat_11123001 = "Bagaimana kabarmu?",
  str_homestory_chat_11123002 = "Aku lumayan menyukai kehidupan ini, Rekan Sebangsa.",
  str_homestory_chat_11123003 = "Terima kasih atas konfirmasimu!",
  str_homestory_chat_11123004 = "Tak ada aturan yang memaksa, tak ada sistem yang korup...",
  str_homestory_chat_11123005 = "Eh, sebentar...",
  str_homestory_chat_11123006 = "Kenapa kau mengasosiasikan hidupmu dengan hal-hal itu?",
  str_homestory_chat_11123007 = "Kita semua kan teman, jadi mana mungkin ada yang seperti itu...",
  str_homestory_chat_11123008 = "Apa maksudmu?",
  str_homestory_chat_11123009 = "Tenang saja, Rekan Sebangsa. Aku hanya memuji cara hidup di sini.",
  str_homestory_chat_11123010 = "Kita semua teman!",
  str_homestory_chat_11123011 = "Mungkin karena kehidupan di sini sangat indah.",
  str_homestory_chat_11124001 = "Kau sedang latihan?",
  str_homestory_chat_11124002 = "Hosh— Hosh—",
  str_homestory_chat_11124003 = "Benar, Rekan Sebangsa. Kuharap kau mau ikut.",
  str_homestory_chat_11124004 = "Kata Vice, kau sampai putus asa gara-gara ingin meningkatkan kemampuanmu.",
  str_homestory_chat_11124005 = "Aku tidak putus asa, kok...",
  str_homestory_chat_11124006 = "Waktu tak akan menunggu siapa pun. Semoga kau cepat bertindak.",
  str_homestory_chat_11124007 = "Ah, baiklah.",
  str_homestory_chat_11124008 = "Seperti apa rencana latihanmu?",
  str_homestory_chat_11124009 = "Selain latihan fisik dasar, aku juga akan mengajarimu latihan tempur.",
  str_homestory_chat_11124010 = "Kalau sudah menyangkut hidup dan mati, kau pasti bakal terinspirasi...",
  str_homestory_chat_11124011 = "... Oh, aku tidak terlalu buru-buru mau meningkatkan diriku atau semacamnya, kok.",
  str_homestory_chat_11125001 = "Hari yang indah.",
  str_homestory_chat_11125002 = "Benar, di Eraveil selalu cerah.",
  str_homestory_chat_11125003 = "Setiap hari cocok untuk olahraga.",
  str_homestory_chat_11125004 = "Apa kau mau ikut, Rekan Sebangsa?",
  str_homestory_chat_11125005 = "Tentu.",
  str_homestory_chat_11125006 = "Aku suka berolahraga sesekali.",
  str_homestory_chat_11125007 = "Asal tidak berlebihan...",
  str_homestory_chat_11125008 = "Kau tak akan pernah maju jika tidak memaksakan diri.",
  str_homestory_chat_11125009 = "Jangan terlalu nyaman dengan masa kini.",
  str_homestory_chat_11125010 = "Aku hanya ingin menjaga kebugaran!",
  str_homestory_chat_11125011 = "Mungkin lain kali...",
  str_homestory_chat_11125012 = "Aku sudah tahu cara orang-orang di Illumina berolahraga...",
  str_homestory_chat_11125013 = "Kurasa aku sudah tak mampu melakukannya lagi.",
  str_homestory_chat_11125014 = "Jangan memaksakan diri, Rekan Sebangsa. Lakukan saja sebisamu.",
  str_homestory_chat_13899999 = "Hei, Lawanku yang Kalah. Kau mau menantangku lagi, ya?",
  str_homestory_chat_13801001 = "Benar! Aku ingin menantangmu!",
  str_homestory_chat_13801002 = "Kali ini, aku pasti tak akan kalah lagi denganmu dalam permainan balap!",
  str_homestory_chat_13801003 = "Ha! Kalau begitu, bersiap-siaplah kalah sekali lagi.",
  str_homestory_chat_13821001 = "Hai, sedang sibuk apa?",
  str_homestory_chat_13821002 = "PlayerName, apa Game Room itu sudah selesai dibuat?",
  str_homestory_chat_13821003 = "Hah?",
  str_homestory_chat_13821004 = "Kau ingin membangun Game Room?",
  str_homestory_chat_13821005 = "Lho, bukankah rencana untuk membangun Game Room itu betulan?",
  str_homestory_chat_13821006 = "Aku rasa tidak...",
  str_homestory_chat_13821007 = "Bisa-bisanya tak ada Game Room?!",
  str_homestory_chat_13821008 = "Apa mesin game tidak cukup untukmu?",
  str_homestory_chat_13821009 = "Tentu saja tidak!",
  str_homestory_chat_13821010 = "Pengalaman bermain game yang seru hanya bisa dirasakan di Game Room!",
  str_homestory_chat_13822001 = "Kudengar, kau kalah dalam permainan.",
  str_homestory_chat_13822002 = "Itu kan memancing, bukan permainan.",
  str_homestory_chat_13822003 = "Tapi, aku tak akan kalah dari siapa pun, bahkan saat memancing!",
  str_homestory_chat_13822004 = "Apa itu yang di tanganmu?",
  str_homestory_chat_13822005 = "Heheh, ini ciptaan baruku! Mesin penangkap ikan...",
  str_homestory_chat_13822006 = "Taruh saja di dalam air, lalu semua ikan dalam radius sepuluh meter akan tertangkap!",
  str_homestory_chat_13822007 = "Nah, aku tinggal menarik mereka, lalu aku menang...",
  str_homestory_chat_13822008 = "Wah, kau sangat ambisius untuk menang...",
  str_homestory_chat_13822009 = "Mesin penangkap ikanmu akan aku sita.",
  str_homestory_chat_13822010 = "Tidak mungkin!",
  str_homestory_chat_13823001 = "Sedang jalan-jalan, ya?",
  str_homestory_chat_13823002 = "PlayerName, aku sudah menjelajahi setiap jengkal tempat ini.",
  str_homestory_chat_13823003 = "Tapi, tentu saja hanya di permukaannya saja. Masih ada bawah tanah yang belum kujelajahi...",
  str_homestory_chat_13823004 = "Kau sedang apa?",
  str_homestory_chat_13823005 = "Hanya menjelajah. Siapa tahu ada peninggalan benda teknologi yang lebih mengasyikkan.",
  str_homestory_chat_13823006 = "Selain itu, teknologi kaum Caelestite sepertimu...",
  str_homestory_chat_13823007 = "Tapi, aku pasti akan memberitahumu kalau menemukan sesuatu!",
  str_homestory_chat_13823008 = "Perasaanku jadi tak enak, nih...",
  str_homestory_chat_13823009 = "Apa maksudmu?",
  str_homestory_chat_13823010 = "Yah, aku pasti akan memberitahumu kalau menemukan sesuatu!",
  str_homestory_chat_13823011 = "... Aku percaya kepadamu.",
  str_homestory_chat_13824001 = "Kau sedang apa?",
  str_homestory_chat_13824002 = "PlayerName, apa belakangan ini kau sudah mengembangkan gameplay baru?",
  str_homestory_chat_13824003 = "Aku sudah menamatkan semua permainan. Aku jadi bosan...",
  str_homestory_chat_13824004 = "Sini, bantu aku kalau kau tak punya kegiatan—",
  str_homestory_chat_13824005 = "Ayo bersih-bersih di sini.",
  str_homestory_chat_13824006 = "Wow, pemenang Emperor's Cup disuruh oleh Caelestite untuk bersih-bersih!",
  str_homestory_chat_13824007 = "Sirami bunga.",
  str_homestory_chat_13824008 = "Wow, Tech Officer Illumina disuruh oleh Caelestite untuk menyirami bunga!",
  str_homestory_chat_13824009 = "...",
  str_homestory_chat_13824010 = "Baiklah, akan kuanggap ini sebagai permainan simulasi.",
  str_homestory_chat_13825001 = "Bermain game baru?",
  str_homestory_chat_13825002 = "Iya. Coba tebak apa yang sedang kumainkan.",
  str_homestory_chat_13825003 = "Di game ini, kau harus mengambil senjata dan mengenai musuhnya.",
  str_homestory_chat_13825004 = "Kalahkan musuh untuk mendapatkan material untuk membuat peralatan!",
  str_homestory_chat_13825005 = "Jangan-jangan...?",
  str_homestory_chat_13825006 = "Game permainan peran?",
  str_homestory_chat_13825007 = "Game aksi?",
  str_homestory_chat_13825008 = "Hampir, tapi bukan. Akan kuberi satu petunjuk lagi.",
  str_homestory_chat_13825009 = "Musuhnya pendek, gemuk dan sangat keras!",
  str_homestory_chat_13825010 = "Aneh sekali!",
  str_homestory_chat_13825011 = "Sesuatu yang pendek, gemuk dan keras yang bisa menjatuhkan material...",
  str_homestory_chat_13825012 = "Tunggu dulu. Apa kau menambang?",
  str_homestory_chat_13825013 = "Benar!",
  str_homestory_chat_14499999 = "Halo! Apa rencanamu hari ini? Kau butuh bantuanku untuk mengawasi?",
  str_homestory_chat_14401001 = "Sekarang sih belum.",
  str_homestory_chat_14401002 = "Kalau kau punya rencana, jangan sungkan-sungkan untuk minta bantuanku.",
  str_homestory_chat_14401003 = "Akan kubantu kau mewujudkan rencanamu dan membuatnya berjalan lancar.",
  str_homestory_chat_14421001 = "Bagaimana kabarmu di sini?",
  str_homestory_chat_14421002 = "Curie suka berada di sini.",
  str_homestory_chat_14421003 = "Lagi pula, naga kan memang makhluk langit.",
  str_homestory_chat_14421004 = "Apa Vivian juga suka berada di sini?",
  str_homestory_chat_14421005 = "PlayerName mengajukan pertanyaan yang sama kepada semua orang...",
  str_homestory_chat_14421006 = "Tak ada yang bakal menjawab \"tidak\", 'kan?",
  str_homestory_chat_14421007 = "Seperti Curie, aku sangat menyukai tempat ini.",
  str_homestory_chat_14422001 = "Hai, Vivian.",
  str_homestory_chat_14422002 = "Kau sedang apa, PlayerName?",
  str_homestory_chat_14422003 = "Ah, aku sedang menghitung pendapatan terakhir dari sewa dan pengeluaran.",
  str_homestory_chat_14422004 = "Sungguh tugas yang merepotkan...",
  str_homestory_chat_14422005 = "Biar kubantu.",
  str_homestory_chat_14422006 = "...",
  str_homestory_chat_14422007 = "Selesai. Periksalah.",
  str_homestory_chat_14422008 = "Cepat sekali!",
  str_homestory_chat_14422009 = "Hitung-menghitung adalah urusan sepele bagiku.",
  str_homestory_chat_14423001 = "Kau ingin menemuiku?",
  str_homestory_chat_14423002 = "PlayerName, apa kau punya rencana baru-baru ini untuk merombak rumahmu?",
  str_homestory_chat_14423003 = "Tentu saja!",
  str_homestory_chat_14423004 = "Saking banyaknya yang kupikirkan tentang perubahan yang bisa dilakukan, aku bahkan sampai bermimpi—",
  str_homestory_chat_14423005 = "Pokoknya, saking banyaknya ideku, aku sampai tak bisa mengingat semuanya.",
  str_homestory_chat_14423006 = "Untuk sekarang, sih...",
  str_homestory_chat_14423007 = "Inspirasiku sudah habis...",
  str_homestory_chat_14423008 = "Santai saja, jangan terlalu memaksakan diri. Bekerja dan bermain haruslah seimbang.",
  str_homestory_chat_14423009 = "Tapi, kalau punya rencana, kau bisa menemuiku kapan saja.",
  str_homestory_chat_14423010 = "Buat saja daftarnya. Nanti kubantu mewujudkan semuanya dengan efisien.",
  str_homestory_chat_14424001 = "Ada apa?",
  str_homestory_chat_14424002 = "Akan kuminta orang-orang itu memberi penjelasan!",
  str_homestory_chat_14424003 = "Bagaimana bisa pekerjaan mereka jadi kacau?!",
  str_homestory_chat_14424004 = "Apa yang terjadi?",
  str_homestory_chat_14424005 = "Soal rencana renovasi rumah itu. Aku yakin sudah membagi-bagi tugasnya...",
  str_homestory_chat_14424006 = "Aku menghitung waktu yang dibutuhkan untuk menyelesaikannya, dan menugaskannya kepada penanggung jawabnya—",
  str_homestory_chat_14424007 = "Seharusnya ini adalah pekerjaan mudah bagi mereka, tapi...",
  str_homestory_chat_14424008 = "Tak seorang pun menyelesaikannya tepat waktu!",
  str_homestory_chat_14424009 = "Sudahlah, jangan tegang begitu.",
  str_homestory_chat_14424010 = "Tidak, aku tak mau tinggal diam! Aku harus balas dendam pada mereka!",
  str_homestory_chat_14425001 = "Kau punya saran?",
  str_homestory_chat_14425002 = "Aku sudah bekerja keras membuat rencana renovasi Cloud Gardens.",
  str_homestory_chat_14425003 = "Tapi, kinerja semua orang berbeda...",
  str_homestory_chat_14425004 = "Jadi, kita menghadapi masalah yang tak ada habisnya.",
  str_homestory_chat_14425005 = "Misalnya?",
  str_homestory_chat_14425006 = "Misalnya Dove tak pernah bisa menyelesaikan Quest Logging tepat waktu.",
  str_homestory_chat_14425007 = "Ah... Dove memang selalu seperti itu.",
  str_homestory_chat_14425008 = "Kami sudah menyerah membuatnya tidak terlalu malas.",
  str_homestory_chat_14425009 = "Sepertinya aku harus memperbaiki rencana renovasi Cloud Gardens milikku.",
  str_homestory_chat_14425010 = "Kali ini, aku harus mempertimbangkan karakteristik dan gaya kerja orang-orang!",
  str_homestory_chat_14425011 = "Jangan terlalu keras pada dirimu sendiri, Vivian.",
  str_homestory_chat_12199999 = "Ah, aku bisa merasakan cinta yang tak terbatas dari nada sapaanmu.",
  str_homestory_chat_12101001 = "K-kurasa tidak...",
  str_homestory_chat_12101002 = "Kau mau membantah rasa cinta ini, ya?",
  str_homestory_chat_12101003 = "Sekali lagi hatiku tercabik-cabik oleh duri mawar yang acuh tak acuh...",
  str_homestory_chat_12101004 = "Hei! Bisa tidak sih kau bersikap lebih normal?",
  str_homestory_chat_12101005 = "Ini kan hanya salam!",
  str_homestory_chat_12121001 = "Baru-baru ini kau membudidayakan bunga, ya?",
  str_homestory_chat_12121002 = "Oh, iya. PlayerName, kau mau mengunjungi kebun mawar terbaruku?",
  str_homestory_chat_12121003 = "Setiap bunga sudah menantikan kedatanganmu, lho!",
  str_homestory_chat_12121004 = "Tidak, ah...",
  str_homestory_chat_12121005 = "Ada banyak pekerjaan yang harus kuselesaikan. Aku akan mengunjunginya lain kali.",
  str_homestory_chat_12121006 = "Ah, aku lega karena kau sudah berjanji mau berkunjung.",
  str_homestory_chat_12121007 = "Semoga aku dan bunga-bunga itu tak akan kecewa.",
  str_homestory_chat_12121008 = "Tentu!",
  str_homestory_chat_12121009 = "Tempat ini terpapar banyak cahaya matahari, jadi kau bisa memamerkan kemampuan berkebunmu.",
  str_homestory_chat_12121010 = "Ah, kata-katamu memang bijaksana.",
  str_homestory_chat_12121011 = "Kau benar. Tempat ini memang dipenuhi keindahan alam—",
  str_homestory_chat_12121012 = "Ini cocok untukku!",
  str_homestory_chat_12122001 = "Apa yang kautertawakan?",
  str_homestory_chat_12122002 = "Ada banyak anak yang berpindah ke tempat ini...",
  str_homestory_chat_12122003 = "Itu melegakan hati!",
  str_homestory_chat_12122004 = "Kau suka anak-anak muda, ya?",
  str_homestory_chat_12122005 = "Iya! Kalau melihat mata polos dan rona wajah mereka...",
  str_homestory_chat_12122006 = "Aku jadi teringat pada segala macam bunga!",
  str_homestory_chat_12122007 = "Sayangnya, anak-anak yang bandel bagaikan bunga yang tumbuh ke arah yang salah.",
  str_homestory_chat_12122008 = "Kalau bertemu bunga seperti itu, akan kupangkas!",
  str_homestory_chat_12122009 = "Eh... Apa aku baru saja dengar sesuatu yang mengerikan?",
  str_homestory_chat_11499999 = "PlayerName, senang bertemu denganmu.",
  str_homestory_chat_11401001 = "Halo, Schwartz.",
  str_homestory_chat_11401002 = "Terima kasih sudah mengundangku untuk mengunjungi rumahmu yang indah.",
  str_homestory_chat_11401003 = "Bukan apa-apa, kok. Tak perlu sungkan-sungkan denganku.",
  str_homestory_chat_11401004 = "Kuharap tempat ini akan berkembang dengan kepemimpinanmu.",
  str_homestory_chat_11421001 = "Apa pendapatmu tentang tempat ini?",
  str_homestory_chat_11421002 = "Tempat ini teratur, cukup bagus, dan dirawat dengan sepenuh hati.",
  str_homestory_chat_11421003 = "PlayerName, kau pasti akan menemui kesulitan dalam menjalankan tempat ini.",
  str_homestory_chat_11421004 = "Kalau butuh bantuan, aku bersedia meluangkan waktu untukmu.",
  str_homestory_chat_11421005 = "Terima kasih!",
  str_homestory_chat_11421006 = "Aku akan minta bantuanmu kalau ada kesulitan, City Lord.",
  str_homestory_chat_11421007 = "Ketertiban adalah inti dari pemerintahan sebuah negeri.",
  str_homestory_chat_11421008 = "Walaupun mungkin tampak keras, tapi itu harus.",
  str_homestory_chat_11421009 = "(Ah... Serius nih kami mulai mendiskusikannya sekarang...?)",
  str_homestory_chat_11421010 = "Untuk sekarang, itu tak perlu...",
  str_homestory_chat_11421011 = "Kami semua teman. Tak perlu ada \"pemerintahan\" segala.",
  str_homestory_chat_11421012 = "Semoga metodemu bisa membuat tempat ini jadi makmur juga.",
  str_homestory_chat_11422001 = "Kau boleh berkunjung.",
  str_homestory_chat_11422002 = "Rumahmu ini, seperti halnya Lumopolis, beruntung bisa mendapat banyak sinar matahari.",
  str_homestory_chat_11422003 = "Cuacanya sempurna untuk—",
  str_homestory_chat_11422004 = "Memancing!",
  str_homestory_chat_11422005 = "Duduk di tepi sungai, menunggu mangsa berenang menyambar umpan...",
  str_homestory_chat_11422006 = "Ini kegiatan bersantai yang populer di sini, ya?",
  str_homestory_chat_11422007 = "Kau mau coba?",
  str_homestory_chat_11422008 = "Idemu lumayan juga.",
  str_homestory_chat_11422009 = "Lari!",
  str_homestory_chat_11422010 = "Ini olahraga untuk anak-anak muda.",
  str_homestory_chat_11422011 = "Aku akan menonton dari pinggir.",
  str_homestory_chat_11423001 = "Membaca?",
  str_homestory_chat_11423002 = "Kalau sedang cerah begini, membolak-balik halaman bukan kegiatan yang paling nyaman untuk menghabiskan waktu.",
  str_homestory_chat_11423003 = "PlayerName, aku bisa meminjamkannya kepadamu kalau kau tertarik.",
  str_homestory_chat_11423004 = "Terima kasih!",
  str_homestory_chat_11423005 = "Buku yang bisa menarik perhatianmu pastilah sangat memikat.",
  str_homestory_chat_11423006 = "Aku tidak membaca untuk \"bersenang-senang.\"",
  str_homestory_chat_11423007 = "Aku lebih suka menempuh perjalanan ke alam semesta tanpa batas dan menjelajahi kedalaman sifat manusia dalam buku.",
  str_homestory_chat_11423008 = "Tapi, kalau kau merasa senang saat melakukannya, itu juga bagus.",
  str_homestory_chat_11423009 = "Tidak perlu...",
  str_homestory_chat_11423010 = "Aku suka membaca dan beristirahat, tapi tugasku sangat banyak...",
  str_homestory_chat_11423011 = "Kau boleh memercayakan beberapa tugasmu padaku kalau kau tak bisa menanganinya.",
  str_homestory_chat_12999999 = "Oh, rupanya memang kau...",
  str_homestory_chat_12921001 = "Ah, ya.",
  str_homestory_chat_12921002 = "Aku sudah merasakan kehadiranmu dari embusan angin.",
  str_homestory_chat_12921003 = "Wah, kedengarannya luar biasa!",
  str_homestory_chat_12921004 = "Aroma tubuhmu spesial.",
  str_homestory_chat_12922001 = "Kau tampak sangat santai.",
  str_homestory_chat_12922002 = "Ternyata... Tinggal di sangkar dan berjemur di bawah sinar matahari akan berakhir dengan suatu kejadian yang menarik...",
  str_homestory_chat_12922003 = "Yaitu?",
  str_homestory_chat_12922004 = "Muka kita jadi panas di beberapa bagian, dan jadi dingin di bagian lain.",
  str_homestory_chat_12922005 = "Kenapa begini?",
  str_homestory_chat_12922006 = "Aku juga tidak tahu...",
  str_homestory_chat_12922007 = "Sudahlah, tak usah dipikirkan. Berpikir itu melelahkan.",
  str_homestory_chat_12922008 = "Apa ini gara-gara sangkarnya?",
  str_homestory_chat_12922009 = "Sangkar akan membuat bayangan di wajah, dan matahari tidak menyinarinya, jadi tentu saja jadi dingin.",
  str_homestory_chat_12922010 = "Mungkin kau benar soal itu.",
  str_homestory_chat_12922011 = "Tapi, aku tak mau menganalisis apa pun. Berpikir itu melelahkan.",
  str_homestory_chat_12923001 = "Sepertinya kau suka di sini.",
  str_homestory_chat_12923002 = "Sinar matahari yang hangat...",
  str_homestory_chat_12923003 = "Huff... Iya... Aku merasa seperti benang sutra...",
  str_homestory_chat_12923004 = "Huff... Ah, aku tidak tidur...",
  str_homestory_chat_12923005 = "(Sebaiknya aku tak mengganggu tidurnya.)",
  str_homestory_chat_12924001 = "Sedang apa kau?",
  str_homestory_chat_12924002 = "Kau dengar, belum?",
  str_homestory_chat_12924003 = "Tempat ini kaya akan suara...",
  str_homestory_chat_12924004 = "Suaranya terus berdatangan dari sungai, hutan, dan lembah.",
  str_homestory_chat_12924005 = "Benar.",
  str_homestory_chat_12924006 = "Di Lumopolis, yang paling sering terdengar adalah suara angin, dan semua suaranya berasal dari Aurorian.",
  str_homestory_chat_12924007 = "Kalau kubandingkan, aku lebih suka suara di sini.",
  str_homestory_chat_12924008 = "Aku bahkan tidak menyadarinya.",
  str_homestory_chat_12924009 = "Aku baru saja merasakan apa yang kau sebutkan...",
  str_homestory_chat_12924010 = "Kau bisa merasakan kebahagiaan yang mengejutkan dengan mendengar.",
  str_homestory_chat_12925001 = "Kayu?",
  str_homestory_chat_12925002 = "Ah, memang, kayu. Apakah Anda memiliki sesuatu yang ringan dan kokoh?",
  str_homestory_chat_12925003 = "Um... Apa yang kamu rencanakan untuk menggunakan kayu ini tiba-tiba?",
  str_homestory_chat_12925004 = "Saya ingin merombak kandang ini—terlalu besar dan berat.",
  str_homestory_chat_12925005 = "Benar, jika kayunya lebih ringan, itu akan memudahkanmu.",
  str_homestory_chat_12925006 = "Namun, jenis kayu yang Anda sebutkan sepertinya cukup sulit ditemukan di Cloud Gardens.",
  str_homestory_chat_12925007 = "Pepohonan di sini sangat aneh, jadi sulit untuk membuatnya menjadi kayu.",
  str_homestory_chat_12925008 = "Dan... Chubbs itu mungkin juga tidak setuju untuk memotongnya.",
  str_homestory_chat_12926001 = "Di suatu tempat yang tinggi?",
  str_homestory_chat_12926002 = "Saya mencari tempat yang indah di Cloud Gardens. Setelah memikirkannya...",
  str_homestory_chat_12926003 = "Di suatu tempat yang lebih tinggi akan bagus, dan akan lebih baik lagi jika bisa mengabaikan semua Cloud Gardens.",
  str_homestory_chat_12926004 = "Ah... Jadi, saya ingin bertanya apakah ada tempat seperti itu.",
  str_homestory_chat_12926005 = "Saya tahu sebuah tempat.",
  str_homestory_chat_12926006 = "Mungkin Menara Hyacinth akan melakukannya?",
  str_homestory_chat_12926007 = "Tapi apakah Chubb akan setuju?",
  str_homestory_chat_12926008 = "Tentu saja tidak.",
  str_homestory_chat_12926009 = "Kurasa tidak.",
  str_homestory_chat_12926010 = "Ah... Kurasa itu tidak mungkin.",
  str_homestory_chat_12926011 = "Apa yang Anda rencanakan?",
  str_homestory_chat_12926012 = "Saya ingin menggantung sangkar saya tinggi-tinggi dan menikmati sensasinya yang bergoyang lembut tertiup angin.",
  str_homestory_chat_12926013 = "Akan sangat menenangkan dan lebih mudah bagi saya untuk tertidur.",
  str_homestory_chat_12926014 = "Tentu, tapi mungkin ada angin kencang di tempat yang lebih tinggi, sehingga kandang rentan terguncang keras.",
  str_homestory_chat_12926015 = "Oh, kamu benar. Itu masuk akal.",
  str_homestory_chat_12926016 = "Jadi, akan lebih baik untuk menjaga hal-hal sebagaimana adanya.",
  str_homestory_chat_12699999 = "Ah... Jangan terlalu dekat.",
  str_homestory_chat_12601001 = "Kenapa?",
  str_homestory_chat_12601002 = "Kekuatanku... bisa membakarmu...",
  str_homestory_chat_12601003 = "Tenang saja. Aku berhati-hati, kok.",
  str_homestory_chat_12601004 = "Semoga... mungkin. Aku tak mau menyakitimu.",
  str_homestory_chat_12621001 = "Mau mengobrol?",
  str_homestory_chat_12621002 = "Mengobrol?",
  str_homestory_chat_12621003 = "Mau mengobrol apa...? Aku tak tahu...",
  str_homestory_chat_12621004 = "Misalnya, yang kau lakukan belakangan ini?",
  str_homestory_chat_12621005 = "Aku tak akan ingat hal-hal yang tak bermakna...",
  str_homestory_chat_12621006 = "Bermakna? Apa itu bermakna...? Aku tak tahu...",
  str_homestory_chat_12621007 = "Misalnya, pemandangan yang kau lihat belakangan ini?",
  str_homestory_chat_12621008 = "Maksudmu, bayangan hitam dalam tong antiledakan...?",
  str_homestory_chat_12621009 = "Sesekali, itu menyala gara-gara apiku...",
  str_homestory_chat_12621010 = "Eh, m-mungkin, sih.",
  str_homestory_chat_12622001 = "Apa katamu barusan?",
  str_homestory_chat_12622002 = "Harus membicarakan apa, ya...? Biar kupikirkan dulu...",
  str_homestory_chat_12622003 = "H-Hoi!",
  str_homestory_chat_12622004 = "… Ada apa?",
  str_homestory_chat_12622005 = "Kau sedang bicara, lalu terganggu.",
  str_homestory_chat_12622006 = "Aku tidak terganggu... Aku... hanya berpikir...",
  str_homestory_chat_12622007 = "Sulit ya bicara dengan orang seperti aku...?",
  str_homestory_chat_12622008 = "Ya!",
  str_homestory_chat_12622009 = "Kalau kau terjebak dalam duniamu sendiri, sesekali menengadahlah dan lihat kami—",
  str_homestory_chat_12622010 = "Itu sama sekali tidak sulit, cobalah!",
  str_homestory_chat_12622011 = "Tidak...",
  str_homestory_chat_12622012 = "Keheningan sesekali bisa membantu seseorang untuk bersantai...",
  str_homestory_chat_12622013 = "Kalau begitu, nikmatilah momen ini bersama-sama.",
  str_homestory_chat_12623001 = "Ayo kita bicarakan Ring of Fire milikmu itu.",
  str_homestory_chat_12623002 = "Yang itu? Itu tentang masa laluku...",
  str_homestory_chat_12623003 = "Mengingat masa lalu adalah hal yang menyakitkan...",
  str_homestory_chat_12623004 = "K-Kalau begitu, jangan dibahas.",
  str_homestory_chat_12623005 = "Tapi, menikmati rasa sakit adalah hal biasa bagiku.",
  str_homestory_chat_12623006 = "Membicarakannya denganmu bukan masalah besar, kok.",
  str_homestory_chat_12624001 = "Ada kabar apa?",
  str_homestory_chat_12624002 = "... Apa yang ingin kau bicarakan?",
  str_homestory_chat_12624003 = "Kudengar, Vice dan yang lain tak sengaja membakar taplak meja saat sedang piknik.",
  str_homestory_chat_12624004 = "Kau menggunakan Ring of Fire untuk membantu mereka memadamkan apinya.",
  str_homestory_chat_12624005 = "Ya…",
  str_homestory_chat_12624006 = "Ring of Fire itu bisa mengisap api...",
  str_homestory_chat_12624007 = "Wah, keren sekali!",
  str_homestory_chat_12624008 = "Oh, ya? Oh... Terima kasih atas pujianmu.",
  str_homestory_chat_12625001 = "Bagaimana situasinya?",
  str_homestory_chat_12625002 = "Tidak terlalu bagus...",
  str_homestory_chat_12625003 = "Apa ada yang bisa kulakukan dengan lebih baik?",
  str_homestory_chat_12625004 = "Bukan itu... Aku agak bingung...",
  str_homestory_chat_12625005 = "Di Eraveil ada begitu banyak tanaman dan pohon...",
  str_homestory_chat_12625006 = "Kalau aku tak sengaja tertidur... aku bisa...",
  str_homestory_chat_12625007 = "Membuat rumput atau pohon terbakar...",
  str_homestory_chat_12625008 = "Apa?!",
  str_homestory_chat_12625009 = "Meskipun aku selalu memakai Ring of Fire untuk memadamkan apinya...",
  str_homestory_chat_12625010 = "Rumputnya tetap saja gosong...",
  str_homestory_chat_12625011 = "Jangan khawatir.",
  str_homestory_chat_12625012 = "Rumputnya pasti tumbuh lagi!",
  str_homestory_chat_12625013 = "Asal kau selamat dan tak ada bangunan yang terbakar, tak masalah.",
  str_homestory_chat_14699999 = "Apa kabar?",
  str_homestory_chat_14601001 = "Hai, di mana mereka?",
  str_homestory_chat_14601002 = "Mereka sedang melakukan hal lain.",
  str_homestory_chat_14601003 = "Memangnya kau tak punya kegiatan?",
  str_homestory_chat_14601004 = "… Dah.",
  str_homestory_chat_14621001 = "Apa kau sudah makan?",
  str_homestory_chat_14621002 = "Aku tak suka makan sayuran ♪",
  str_homestory_chat_14621003 = "Aku benci rasa pahit ♪",
  str_homestory_chat_14621004 = "Sayuran bagus untukmu!",
  str_homestory_chat_14621005 = "Navigator, aku sangat sehat, kok.",
  str_homestory_chat_14621006 = "Tapi, kalau orang sakit butuh makan sayuran.",
  str_homestory_chat_14621007 = "Lihat saja dirimu. Kau sangat butuh makan sayuran.",
  str_homestory_chat_14622001 = "Kau sudah membaca buku akhir-akhir ini?",
  str_homestory_chat_14622002 = "Aku harus membaca buku dongeng ♪",
  str_homestory_chat_14622003 = "Hari-hari yang panjang memang sulit ♪",
  str_homestory_chat_14622004 = "Kalian bisa mencari kegiatan.",
  str_homestory_chat_14622005 = "Navigator, pokoknya kau harus membaca lebih banyak buku dongeng.",
  str_homestory_chat_14622006 = "Pasang sikap orang baik!",
  str_homestory_chat_14622007 = "Biar kubantu kau mencarinya sebentar lagi!",
  str_homestory_chat_14622008 = "Ambil tindakan sebentar lagi ♪",
  str_homestory_chat_14622009 = "Menoleh dan lupakan ♪",
  str_homestory_chat_14623001 = "Bagaimana kalau di sini?",
  str_homestory_chat_14623002 = "Kau tanya apa aku menyukai tempat ini ♪",
  str_homestory_chat_14623003 = "Aku jelas menyukainya ♪",
  str_homestory_chat_14623004 = "Terima kasih atas konfirmasimu!",
  str_homestory_chat_14623005 = "Ucapkan kata-kata yang ingin kau dengar ♪",
  str_homestory_chat_14623006 = "Kau paham? ♪",
  str_homestory_chat_14623007 = "...",
  str_homestory_chat_14623008 = "Tapi... terkadang ucapanku benar ♪",
  str_homestory_chat_14623009 = "Kata-kata jujur juga diucapkan ♪",
  str_homestory_chat_14624001 = "Kau sedang cari apa?",
  str_homestory_chat_14624002 = "Bukuku hilang!",
  str_homestory_chat_14624003 = "Kau lihat, tidak, Navigator?",
  str_homestory_chat_14624004 = "Di sana.",
  str_homestory_chat_14624005 = "Jadi orang baik sampai akhir ♪",
  str_homestory_chat_14624006 = "Pergi mencari buku bersama-sama ♪",
  str_homestory_chat_14624007 = "... Aku boleh menolak, tidak?",
  str_homestory_chat_14624008 = "Aku tidak lihat.",
  str_homestory_chat_14624009 = "Penglihatan Navigator tidak begitu baik ♪",
  str_homestory_chat_14624010 = "Mungkin karena ini masih pagi-pagi buta ♪",
  str_homestory_chat_14624011 = "Pagi-pagi buta ♪",
  str_homestory_chat_14624012 = "Sedikit rambut ♪",
  str_homestory_chat_14624013 = "Kau…!",
  str_homestory_chat_14625001 = "Aku... masih ada urusan lain!",
  str_homestory_chat_14625002 = "Dah!",
  str_homestory_chat_14625003 = "Navigator kabur dengan bingung.",
  str_homestory_chat_14625004 = "Navigator merasa bersalah.",
  str_homestory_chat_14625005 = "Tidak!",
  str_homestory_chat_14625006 = "A-Aku hanya perlu terus membangun Eraveil!",
  str_homestory_chat_14625007 = "Sibuk seperti lebah.",
  str_homestory_chat_14625008 = "Tapi, tak punya tujuan.",
  str_homestory_chat_14625009 = "Jangan marah karena anak-anak, jangan...",
  str_homestory_chat_14625010 = "Navigator berpura-pura dewasa.",
  str_homestory_chat_14625011 = "Dia belum tua...",
  str_homestory_chat_14625012 = "Tapi, sisa rambutnya tidak banyak.",
  str_homestory_chat_14625013 = "Apa-apaan kau…!",
  str_homestory_chat_12399999 = "Kau... Kau menyapaku? K-Kalau begitu... Halo!",
  str_homestory_chat_12301001 = "Tak perlu gugup begitu.",
  str_homestory_chat_12301002 = "B-Baiklah, aku harus mengumpulkan keberanian...",
  str_homestory_chat_12301003 = "Halo, PlayerName!",
  str_homestory_chat_12301004 = "Wow! Keras sekali!",
  str_homestory_chat_12321001 = "Kau bisa memainkan alat musik, 'kan?",
  str_homestory_chat_12321002 = "Kudengar, Connolly adalah pemain klarinet yang andal.",
  str_homestory_chat_12321003 = "Hah? A-Apa? Kau ingin aku bersiap tampil di pesta?",
  str_homestory_chat_12321004 = "Semua orang ingin mendengar musikmu.",
  str_homestory_chat_12321005 = "Tapi... Tapi...",
  str_homestory_chat_12321006 = "Kau tidak mau, ya?",
  str_homestory_chat_12321007 = "T-Tidak, aku hanya agak gugup.",
  str_homestory_chat_12321008 = "Tapi, kalau semua orang menginginkannya, aku akan berusaha semampuku...",
  str_homestory_chat_12321009 = "Percayalah pada dirimu sendiri! Kau pasti akan melakukannya dengan lancar!",
  str_homestory_chat_12321010 = "Cobalah!",
  str_homestory_chat_12321011 = "K-Karena ini undangan dari PlayerName, jadi apa boleh buat...",
  str_homestory_chat_12321012 = "Aku akan berusaha sebaik mungkin.",
  str_homestory_chat_12321013 = "Aku, dan yang lain, akan menantikannya!",
  str_homestory_chat_12322001 = "Aku agak haus, nih.",
  str_homestory_chat_12322002 = "PlayerName, k-kau mau coba minum kopi, tidak?",
  str_homestory_chat_12322003 = "Kalau kau tidak mau juga tak apa-apa... Aku bisa membuangnya...",
  str_homestory_chat_12322004 = "Aku mau meminumnya, kok!",
  str_homestory_chat_12322005 = "Tapi... Kalau rasanya tak enak...",
  str_homestory_chat_12322006 = "Kenapa harus dibuang?",
  str_homestory_chat_12322007 = "Aku baru berlatih membuat kopi, jadi sisanya ada banyak...",
  str_homestory_chat_12322008 = "Aduh... Lebih baik kubuang saja. Rasanya mungkin tak enak...",
  str_homestory_chat_12322009 = "Tunggu!",
  str_homestory_chat_12322010 = "Aku tak tahu rasa kopi yang enak dan tidak enak itu seperti apa, jadi tenang saja.",
  str_homestory_chat_12322011 = "Asalkan bisa membuatku tetap terjaga, kuanggap kopinya enak.",
  str_homestory_chat_12322012 = "Baiklah…",
  str_homestory_chat_12323001 = "Ada apa?",
  str_homestory_chat_12323002 = "Terang sekali…",
  str_homestory_chat_12323003 = "Sinar matahari di sini terlalu terang...",
  str_homestory_chat_12323004 = "Kalau saja ada tempat yang lebih teduh...",
  str_homestory_chat_12323005 = "Naungan bakal membuatmu lebih nyaman, ya?",
  str_homestory_chat_12323006 = "M-Mungkin.",
  str_homestory_chat_12324001 = "Kau bicara dengan siapa?",
  str_homestory_chat_12324002 = "Baiklah, baiklah, aku paham... Oh! Maaf!",
  str_homestory_chat_12324003 = "Aku sedang bicara dengan para Anton... Kau mau bicara dengan mereka?",
  str_homestory_chat_12324004 = "Tak perlu...",
  str_homestory_chat_12324005 = "Kadang... mereka menyeramkan...",
  str_homestory_chat_12324006 = "Tapi, para Anton adalah anak-anak yang baik, kok. Percayalah padaku!",
  str_homestory_chat_12324007 = "Tentu!",
  str_homestory_chat_12324008 = "K-Kalau begitu, biar kubantu memanggil mereka...",
  str_homestory_chat_12325001 = "Memangnya kau sibuk mengerjakan apa?",
  str_homestory_chat_12325002 = "Hei, PlayerName...",
  str_homestory_chat_12325003 = "Aku sudah cukup lama pindah kemari. Banyak orang yang membantuku...",
  str_homestory_chat_12325004 = "Aku ingin menyeduh kopi untuk semuanya. Tapi... aku...",
  str_homestory_chat_12325005 = "Apa kau sedang mengalami kesulitan?",
  str_homestory_chat_12325006 = "Iya... Aku... aku tak tahu apa mereka suka kopi...",
  str_homestory_chat_12325007 = "Jadi, aku masih berpikir...",
  str_homestory_chat_12325008 = "Tenanglah, Connolly!",
  str_homestory_chat_12325009 = "Kopi buatanmu selalu enak. Lagi pula...",
  str_homestory_chat_12325010 = "Yang terpenting adalah hati Connolly!",
  str_homestory_chat_13699999 = "Aku sangat bosan... Kau mau memberiku pekerjaan, ya?",
  str_homestory_chat_13601001 = "Tidak ada apa-apa, sih. Aku hanya ingin menyapa.",
  str_homestory_chat_13601002 = "Hanya menyapa?",
  str_homestory_chat_13601003 = "... Seharusnya aku tak perlu menjawab pertanyaanmu yang membosankan dengan semangat.",
  str_homestory_chat_13621001 = "Bagaimana kabarmu?",
  str_homestory_chat_13621002 = "Makanan di sini sangat hambar sehingga tak layak untuk diberikan kepada bebek.",
  str_homestory_chat_13621003 = "Kau ingin makan apa?",
  str_homestory_chat_13621004 = "Apa pun boleh.",
  str_homestory_chat_13621005 = "Siapa ya yang barusan bilang tak suka makanan di sini?",
  str_homestory_chat_13621006 = "Yah, pokoknya tambahkan lebih banyak bumbu, seperti cabai dan garam.",
  str_homestory_chat_13621007 = "Ini saja?",
  str_homestory_chat_13621008 = "Aku dan anjingku. Permintaan kami tak banyak.",
  str_homestory_chat_13622001 = "Kau sedang apa?",
  str_homestory_chat_13622002 = "... Diam. Bayangan sedang beristirahat.",
  str_homestory_chat_13622003 = "Bayangan juga butuh istirahat?",
  str_homestory_chat_13622004 = "... Ya.",
  str_homestory_chat_13622005 = "Memangnya tak ada penjelasan lain?",
  str_homestory_chat_13622006 = "Tidak.",
  str_homestory_chat_13622007 = "Kau hanya tak mau mengobrol denganku, ya?",
  str_homestory_chat_13622008 = "Untuk sekarang, kau tafsirkan begitu juga boleh.",
  str_homestory_chat_13622009 = "Carilah aku kalau bayangan sedang beristirahat.",
  str_homestory_chat_13623001 = "Hai, Hydrad.",
  str_homestory_chat_13623002 = "Di sini, orang yang memelihara anjing sangat sedikit.",
  str_homestory_chat_13623003 = "Kau ingin mengatakan sesuatu soal itu?",
  str_homestory_chat_13623004 = "Karena anjing bisa menggigit orang?",
  str_homestory_chat_13623005 = "Tidak.",
  str_homestory_chat_13623006 = "Karena anjing bisa menggonggong?",
  str_homestory_chat_13623007 = "Semua anjing yang tidak bisu bisa menggonggong.",
  str_homestory_chat_13623008 = "Jadi, apa kau punya masalah?",
  str_homestory_chat_13623009 = "Memangnya tadi aku bilang punya masalah dengan orang yang memelihara anjing?",
  str_homestory_chat_13623010 = "...",
  str_homestory_chat_14999999 = "Bos, kau butuh apa? Kau butuh bantuanku untuk menghajar orang?",
  str_homestory_chat_14901001 = "Aku hanya datang untuk menyapa.",
  str_homestory_chat_14901002 = "Oh... Itu saja?",
  str_homestory_chat_14901003 = "Jangan lupa menghubungiku kalau mau menghajar orang, aku mau ikut!",
  str_homestory_chat_14921001 = "Butuh bantuan?",
  str_homestory_chat_14921002 = "Bos, kau lihat debu di baju zirahku, tidak?",
  str_homestory_chat_14921003 = "Baju zirahmu sangat bersih, kok.",
  str_homestory_chat_14921004 = "Tidak ada kotorannya?",
  str_homestory_chat_14921005 = "Padahal aku ingin memoles baju zirahku untuk mengisi waktu.",
  str_homestory_chat_14921006 = "Kau bosan, ya?",
  str_homestory_chat_14921007 = "Tak ada orang yang bisa melawanku di sini.",
  str_homestory_chat_14921008 = "Ya sudah jelas aku bosan.",
  str_homestory_chat_14921009 = "Ada sedikit debu nih di sini.",
  str_homestory_chat_14921010 = "Coba kulihat... Terima kasih, Bos.",
  str_homestory_chat_14922001 = "Kelihatannya kau tidak begitu sehat...",
  str_homestory_chat_14922002 = "Bos, aku sangat lapar...",
  str_homestory_chat_14922003 = "Aku makan sayuran terus selama beberapa hari berturut-turut...",
  str_homestory_chat_14922004 = "Sayuran kan bagus untuk kesehatanmu.",
  str_homestory_chat_14922005 = "Bos, kalau kau bilang begitu kepada orang seperti aku yang tak bisa hidup tanpa daging...",
  str_homestory_chat_14922006 = "Itu sangat kejam!",
  str_homestory_chat_14922007 = "Aku juga tak mau makan sayuran!",
  str_homestory_chat_14922008 = "Tapi, aku sedang bokek, jadi apa boleh buat!",
  str_homestory_chat_14922009 = "Bos, kita sedang kesulitan!",
  str_homestory_chat_14951001 = "Itu beberapa udang besar...",
  str_homestory_chat_14951002 = "Kamu juga melihat mereka, Kingpin of Cloud Gardens!?",
  str_homestory_chat_14951003 = "Jangan panggil aku begitu...",
  str_homestory_chat_14951004 = "Baiklah kalau begitu! Bos, saya yakin Anda tidak menyangka akan melihat udang besar seperti itu di sini!",
  str_homestory_chat_14951005 = "Mereka luar biasa! Jika Anda menjualnya di Umbraton, Anda akan membuat bundel!",
  str_homestory_chat_14951006 = "Sungguh?",
  str_homestory_chat_14951007 = "Itu benar! Udang ini adalah jenis yang sangat agresif, jadi sangat menyenangkan untuk ditonton.",
  str_homestory_chat_14951008 = "Ketika saya melihat mereka saling memukuli, rasanya seperti melihat sepasang kura-kura besar di musim kawin! Mereka tampak seperti dua bilah saya, benar!",
  str_homestory_chat_14951009 = "Astaga, itu membuat jari-jariku gatal... Mau tak mau aku bertanya-tanya apakah aku punya kesempatan melawan mereka...",
  str_homestory_chat_14951010 = "Itu mungkin bukan ide yang bagus, kalian adalah spesies yang berbeda...",
  str_homestory_chat_14951011 = "Saya kira yang bisa saya lakukan hanyalah melihat mereka... Ada banyak orang di Umbraton yang tidak pernah puas dengan mereka.",
  str_homestory_chat_14951012 = "Terkadang pertarungan mereka sangat seru!",
  str_homestory_chat_14951013 = "Mereka masih populer di Umbraton?",
  str_homestory_chat_14951014 = "(Kita bisa menghasilkan banyak uang...)",
  str_homestory_chat_14951015 = "Anda sepertinya cukup familiar dengan jenis udang yang satu ini?",
  str_homestory_chat_14951016 = "Tentu saja! Pertama-tama, mereka disebut \"Udang Kaisar\".",
  str_homestory_chat_14951017 = "Kedua, sejauh ini saya menemukan mereka bersembunyi di beberapa tempat.",
  str_homestory_chat_14951018 = "Beberapa tempat!?",
  str_homestory_chat_14951019 = "Dan ada berbagai jenis.",
  str_homestory_chat_14951020 = "Banyak jenis yang berbeda?",
  str_homestory_chat_14951021 = "Sebenarnya hanya ada dua macam. Yang paling umum adalah biru.",
  str_homestory_chat_14951022 = "Benar, itu jenis yang saya lihat.",
  str_homestory_chat_14951023 = "Tentu saja. Selain yang biru, ada juga yang berwarna coklat. Nah, itulah yang disebut produk bermutu tinggi.",
  str_homestory_chat_14951024 = "Tapi itu jauh lebih sulit untuk ditemukan...",
  str_homestory_chat_14951025 = "Di mana saya dapat menemukan mereka?",
  str_homestory_chat_14951026 = "Pertama, Anda membutuhkan udang petarung biru, atau yang secara resmi dikenal sebagai Cobalt Emperor Prawn.",
  str_homestory_chat_14951027 = "Jika Anda membawakan saya salah satunya, Anda bisa menukarnya dengan tempat mancing udang coklat yang lebih besar.",
  str_homestory_chat_14951028 = "Apakah hanya itu yang akan kau berikan padaku?",
  str_homestory_chat_14951029 = "Hei, Anda telah belajar cara menawar! Tentu saja, bos Cloud Gardens layak mendapat bonus ekstra spesial.",
  str_homestory_chat_14951030 = "Yakinlah, saya akan memastikan Anda mendapatkan apa yang pantas Anda dapatkan!",
  str_homestory_chat_14951031 = "Tapi di mana saya bisa menangkap Udang Kaisar Cobalt?",
  str_homestory_chat_14951032 = "Hah? Bukankah kamu baru saja mengatakan kamu melihat beberapa?",
  str_homestory_chat_14951033 = "Tapi bukankah lebih baik memiliki beberapa tempat memancing lagi, untuk berjaga-jaga?",
  str_homestory_chat_14951034 = "Baiklah! Saya tahu banyak tempat memancing. Anda harus dapat menemukan beberapa Cobalt Emperor Prawns.",
  str_homestory_chat_14951035 = "Tentu saja, dengan bakatmu, seharusnya tidak ada masalah sama sekali! Kemudian, Anda dapat menukarnya dengan tempat memancing \"Ochre Emperor Prawn\"!",
  str_homestory_chat_14951036 = "Nah itulah nama yang tepat untuk udang coklat...",
  str_homestory_chat_14951037 = "Semua jelas sekarang? Dengan keahlian Anda, Anda dapat menghasilkan banyak uang! Dan aku juga bisa...",
  str_homestory_chat_14951038 = "Ehem.",
  str_homestory_chat_14951039 = "Jadi, Cloud Gardens Kingpin, apakah Anda memiliki pertanyaan lagi?",
  str_homestory_chat_14951040 = "Saya ingin menangkap Ochre Emperor Prawns.",
  str_homestory_chat_14951041 = "Jadi, apakah Anda membawa Cobalt Emperor Prawns?",
  str_homestory_chat_14951042 = "Yap.",
  str_homestory_chat_14951043 = "Biar saya lihat barangnya!",
  str_homestory_chat_14951044 = "Berikan Udang Kaisar Kobalt ({1}/1).",
  str_homestory_chat_14951045 = "Bagus! Aku akan memberitahumu di mana tempat memancing sekarang... Aku sudah menandainya di petamu!",
  str_homestory_chat_14951046 = "Biarkan aku memikirkannya.",
  str_homestory_chat_14951047 = "Tidak...",
  str_homestory_chat_14951048 = "Yah, kurasa itu terlalu buruk. Informasi tidak datang secara gratis. Saya akan menunggu sampai Anda mendapatkannya.",
  str_homestory_chat_14951049 = "Baik-baik saja maka.",
  str_homestory_chat_14951050 = "Saya di sini tentang udang.",
  str_homestory_chat_14951051 = "Nah, di Umbraton, ada biaya untuk berbagi informasi semacam ini!",
  str_homestory_chat_14951052 = "Bukankah ini Taman Awan...?",
  str_homestory_chat_14951053 = "Kesepakatannya, Anda bisa menukar Cobalt Emperor Prawn dengan info tempat memancing di mana Anda bisa menangkap Oche Emperor Prawns.",
  str_homestory_chat_14951054 = "Tentu saja, saya akan memberi Anda hadiah tambahan untuk itu. Mengerti?",
  str_homestory_chat_14951055 = "Aku paham.",
  str_homestory_chat_14951056 = "Saya ingin memancing Cobalt Emperor Prawns.",
  str_homestory_chat_14951057 = "Yakin?",
  str_homestory_chat_14951058 = "Benar.",
  str_homestory_chat_14951059 = "Oke! Saya telah menandainya. Ingat, Anda bisa menukarnya dengan info tempat mancing Ochre Emperor Prawn!",
  str_homestory_chat_14951060 = "Mengerti? Kalau begitu aku akan berangkat sekarang!",
  str_homestory_chat_14951061 = "aku masih harus memikirkannya...",
  str_homestory_chat_14952001 = "Saya ingin tahu tentang \"Udang Kaisar\" itu.",
  str_homestory_chat_14952002 = "Baiklah, baiklah... Siapa yang mati dan menjadikanmu penguasa Cloud Gardens? Tanyakan!",
  str_homestory_chat_14952003 = "Jadi, apa yang ingin Anda ketahui?",
  str_homestory_chat_14952004 = "Saya ingin menangkap Ochre Emperor Prawns.",
  str_homestory_chat_14952005 = "Jadi, apakah Anda membawa Cobalt Emperor Prawns?",
  str_homestory_chat_14952006 = "Yap.",
  str_homestory_chat_14952007 = "Biar saya lihat barangnya!",
  str_homestory_chat_14952008 = "Berikan Udang Kaisar Kobalt ({1}/1).",
  str_homestory_chat_14952009 = "Bagus! Aku akan memberitahumu di mana tempat memancing sekarang... Aku sudah menandainya di petamu!",
  str_homestory_chat_14952010 = "Biarkan aku memikirkannya.",
  str_homestory_chat_14952011 = "Tidak...",
  str_homestory_chat_14952012 = "Yah, kurasa itu terlalu buruk. Informasi tidak datang secara gratis. Saya akan menunggu sampai Anda mendapatkannya.",
  str_homestory_chat_14952013 = "Baik-baik saja maka.",
  str_homestory_chat_14952014 = "Saya di sini tentang udang.",
  str_homestory_chat_14952015 = "Lagi...? Mulutku kering seperti pisau berkarat!",
  str_homestory_chat_14952016 = "Saya minta maaf. Aku hanya ingin mengerti sedikit lagi.",
  str_homestory_chat_14952017 = "Nah, Cobalt Emperor Prawn bisa kamu tukarkan dengan info spot mancing dimana kamu bisa menangkap Oche Emperor Prawns. Ingat?",
  str_homestory_chat_14952018 = "Ingat.",
  str_homestory_chat_14952019 = "Dan aku akan membayarmu! Anda tidak akan bekerja secara gratis!",
  str_homestory_chat_14952020 = "Benar, saya mengerti.",
  str_homestory_chat_14952021 = "Saya ingin memancing Cobalt Emperor Prawns.",
  str_homestory_chat_14952022 = "Yakin?",
  str_homestory_chat_14952023 = "Saya yakin.",
  str_homestory_chat_14952024 = "Saya akan menandainya untuk Anda. Selain itu, setelah memancing, Anda dapat menukarnya dengan info tempat memancing Ochre Emperor Prawn!",
  str_homestory_chat_14952025 = "Aku ingat...",
  str_homestory_chat_14952026 = "aku masih harus memikirkannya...",
  str_homestory_chat_14952027 = "Saya pikir saya tahu hampir semua yang perlu saya ketahui sekarang.",
  str_homestory_chat_14952028 = "Lalu pergi keluar dari sini!",
  str_homestory_chat_14953001 = "Udang itu...",
  str_homestory_chat_14953002 = "Sekali lagi, ya...? Saya telah menandai semua tempat di mana Anda dapat menangkap udang!",
  str_homestory_chat_14953003 = "Ada yang lain?",
  str_homestory_chat_14953004 = "Saya di sini tentang udang.",
  str_homestory_chat_14953005 = "* menghela nafas * Baiklah, baiklah. Bagaimanapun, Anda adalah bos di sini.",
  str_homestory_chat_14953006 = "Pertama, tangkap Cobalt Emperor Prawn, lalu berikan padaku.",
  str_homestory_chat_14953007 = "Kemudian saya akan memberi tahu Anda di mana tempat memancing itu dan memberi Anda sesuatu yang ekstra.",
  str_homestory_chat_14953008 = "Pikirkan Anda akan dapat mengingat saat ini?",
  str_homestory_chat_14953009 = "Terima kasih!",
  str_homestory_chat_14953010 = "Sayangnya, tidak.",
  str_homestory_chat_14953011 = "Besar. Larilah, kalau begitu!",
  str_homestory_chat_11899999 = "Bantuan apa yang kaubutuhkan dariku? Jangan ganggu aku dengan masalah sepele, aku sibuk.",
  str_homestory_chat_11801001 = "Aku hanya mau menyapa!",
  str_homestory_chat_11801002 = "Oh. Baiklah.",
  str_homestory_chat_11801003 = "Tapi, kurasa tak bakal ada sesuatu yang \"penting\" di sini.",
  str_homestory_chat_11801004 = "Benar.",
  str_homestory_chat_11821001 = "Hai. Kau mencariku?",
  str_homestory_chat_11821002 = "PlayerName, kau harus dengar lagu baruku.",
  str_homestory_chat_11821003 = "Apa aku boleh menolak?",
  str_homestory_chat_11821004 = "Kau berani menolak? Tidak boleh!",
  str_homestory_chat_11821005 = "Sepertinya selera musikmu memang perlu ditingkatkan!",
  str_homestory_chat_11821006 = "Baiklah, akan kudengarkan.",
  str_homestory_chat_11821007 = "Ah, seleramu memang bagus.",
  str_homestory_chat_11821008 = "Tapi, aku harus mengumpulkan para pengiring.",
  str_homestory_chat_11821009 = "Nanti kuberi tahu kalau semua sudah siap.",
  str_homestory_chat_11822001 = "Sepertinya tak ada yang bisa dilakukan.",
  str_homestory_chat_11822002 = "Benar! Sangat membosankan!",
  str_homestory_chat_11822003 = "Iya, aku juga merasa bosan...",
  str_homestory_chat_11822004 = "Kau punya ide bagus, tidak?",
  str_homestory_chat_11822005 = "Nah, saat-saat seperti ini butuh konser mental!",
  str_homestory_chat_11822006 = "Gitar listrikku akan menyingkirkan rasa bosan!",
  str_homestory_chat_11822007 = "Bagaimana menurutmu, PlayerName? Ideku lumayan bagus, 'kan?",
  str_homestory_chat_11822008 = "Uh, nanti akan kupertimbangkan, ya.",
  str_homestory_chat_11823001 = "Apa maksudmu?",
  str_homestory_chat_11823002 = "Blewah, mayones...",
  str_homestory_chat_11823003 = "Itu semacam mantra, ya?",
  str_homestory_chat_11823004 = "Tidak, itu nama makanan paling lezat di dunia!",
  str_homestory_chat_11823005 = "Tambahkan sedikit mayones di atas blewah potong yang dingin...",
  str_homestory_chat_11823006 = "Satu gigit saja akan menyingkirkan segala kecemasanmu...",
  str_homestory_chat_11823007 = "Memangnya rasanya benar-benar enak, ya?",
  str_homestory_chat_11823008 = "Bagaimana kalau kubuatkan agar kau bisa mencicipinya?",
  str_homestory_chat_11823009 = "Jangan makan di depanku, ya. Nanti bisa-bisa aku malah merampoknya.",
  str_homestory_chat_11824001 = "Bagaimana situasinya?",
  str_homestory_chat_11824002 = "PlayerName, apa kau bisa membangun panggung yang cukup tinggi untuk melihat seluruh Eraveil?",
  str_homestory_chat_11824003 = "Oh? Untuk apa?",
  str_homestory_chat_11824004 = "Tentu saja konser metal terbaik!",
  str_homestory_chat_11824005 = "Gitar listrikku akan menunjukkan arti musik yang sebenarnya.",
  str_homestory_chat_11824006 = "Aku tak keberatan dengan idemu ini asal kau mau berbagi panggung dengan Barbara...",
  str_homestory_chat_10899999 = "Hei, kau di sini, ya? Ada sesuatu yang butuh diperbaiki?",
  str_homestory_chat_10801001 = "Nah, kalau dipikir-pikir... Memang ada sesuatu, sih.",
  str_homestory_chat_10801002 = "Tapi, tak perlu terburu-buru, kok.",
  str_homestory_chat_10801003 = "Beri tahu aku kapan kau punya waktu.",
  str_homestory_chat_10821001 = "Kau ingin makan apa?",
  str_homestory_chat_10821002 = "Kenapa kau tiba-tiba menanyakannya kepadaku?",
  str_homestory_chat_10821003 = "Yang biasanya saja. Aku tidak suka pilih-pilih makanan, kok.",
  str_homestory_chat_10821004 = "Kau mau lebih banyak jenis telur?",
  str_homestory_chat_10821005 = "Tentu.",
  str_homestory_chat_10821006 = "Memangnya jenis telur ada efek spesialnya untukku?",
  str_homestory_chat_10821007 = "Tenang saja, ini demi kebaikanmu sendiri.",
  str_homestory_chat_10821008 = "Mau segelas susu setiap hari?",
  str_homestory_chat_10821009 = "Ya, tentu saja.",
  str_homestory_chat_10821010 = "Tapi, kenapa kedengarannya agak aneh, ya?",
  str_homestory_chat_10821011 = "... Aku paham.",
  str_homestory_chat_10821012 = "Kau pasti mengejek tinggi badanku secara tak langsung!",
  str_homestory_chat_10821013 = "Tidak! Tak akan!",
  str_homestory_chat_10822001 = "Kau punya usul apa?",
  str_homestory_chat_10822002 = "PlayerName, aku punya ide bagus—",
  str_homestory_chat_10822003 = "Kita bisa memasang lampu-lampu yang terang nyalanya di bangunan ini.",
  str_homestory_chat_10822004 = "Kenapa?",
  str_homestory_chat_10822005 = "... Karena aku sedang tak punya kegiatan sekarang.",
  str_homestory_chat_10822006 = "PlayerName, ada urusan konstruksi baru yang kau butuhkan?",
  str_homestory_chat_10822007 = "Biar kupikirkan dulu.",
  str_homestory_chat_11799999 = "Halo, PlayerName!",
  str_homestory_chat_11701001 = "Hai! Rabbie!",
  str_homestory_chat_11701002 = "Sudah punya rencana untuk hari ini?",
  str_homestory_chat_11701003 = "Sekarang sih belum.",
  str_homestory_chat_11701004 = "Kau mau mengebor lubang denganku?",
  str_homestory_chat_11701005 = "Eh... Mungkin nanti.",
  str_homestory_chat_11721001 = "Apa yang kau pikirkan?",
  str_homestory_chat_11721002 = "PlayerName, kau mau dengar rencana evakuasiku?",
  str_homestory_chat_11721003 = "Evakuasi?",
  str_homestory_chat_11721004 = "Rumah seharusnya dibangun dengan rencana evakuasi!",
  str_homestory_chat_11721005 = "Ini demi keamanan semua orang!",
  str_homestory_chat_11721006 = "Baiklah, biar kuperiksa.",
  str_homestory_chat_11721007 = "Aku sudah menyelesaikan bagian konstruksinya, dan mengebor tiga lubang!",
  str_homestory_chat_11721008 = "Mana mungkin...?!",
  str_homestory_chat_11722001 = "Lihat apa kau?",
  str_homestory_chat_11722002 = "PlayerName, aku punya bor baru, nih!",
  str_homestory_chat_11722003 = "Aku sangat ingin mencobanya sekarang!",
  str_homestory_chat_11722004 = "J-Jangan...",
  str_homestory_chat_11722005 = "Lubang yang kau bor terakhir kali bahkan belum ditutup!",
  str_homestory_chat_11722006 = "Kau tidak puas dengan rencana evakuasi bawah tanahku?",
  str_homestory_chat_11722007 = "T-Tidak juga, sih. Setidaknya, beri tahu aku sebelum kau mengebor lubang.",
  str_homestory_chat_11722008 = "Iya, iya! Akan kuingat!",
  str_homestory_chat_11751001 = "Dimana ikan itu?",
  str_homestory_chat_11751002 = "Ah! Mundur!",
  str_homestory_chat_11751003 = "Mundur? Hai...",
  str_homestory_chat_11751004 = "A-Apakah kamu di sini untuk menangkapku?",
  str_homestory_chat_11751005 = "Menangkap mu? Apa yang kamu lakukan?",
  str_homestory_chat_11751006 = "Nah.. demi memfasilitasi retret darurat, saya hanya ingin menggali terowongan di bawah Cloud Gardens.",
  str_homestory_chat_11751007 = "Ketika saatnya tiba, jika saya tidak berpikir kita akan mampu bertahan, saya hanya akan membuat seperti pohon dan lari— Ah, mundur, ya!",
  str_homestory_chat_11751008 = "Oh, itu cukup bijaksana dari Anda.",
  str_homestory_chat_11751009 = "Dan saya melihat ikan itu saat menggali terowongan... Oh ya! Apakah itu sebabnya Anda datang?",
  str_homestory_chat_11751010 = "Hah? Oh, benar... Lagi pula, terowongan itu sepertinya tidak terlalu berguna, jadi Chubb mengisinya lagi.",
  str_homestory_chat_11751011 = "Mengisinya?!",
  str_homestory_chat_11751012 = "Bagaimana kita akan mundur?! Bagaimana jika sesuatu yang buruk benar-benar terjadi?!",
  str_homestory_chat_11751013 = "Tidak ada yang akan terjadi. Juga, Anda menggali terowongan itu bahkan tanpa bertanya kepada saya apakah itu baik-baik saja.",
  str_homestory_chat_11751014 = "Kukira...",
  str_homestory_chat_11751015 = "Tapi bagaimanapun, saya datang untuk menanyakan tentang ikan itu. Dimana kamu melihatnya? Dekat terowongan?",
  str_homestory_chat_11751016 = "Sebenarnya, itu sedikit lebih jauh dari itu. Aku benar-benar tidak punya energi untuk menjelaskannya sekarang. Menggali terowongan adalah kerja keras...",
  str_homestory_chat_11751017 = "Anda tidak mencari kompensasi, kan?",
  str_homestory_chat_11751018 = "Tentu saja! Beri aku beberapa biji Pohon Quinlan Daun Raksasa dan aku akan mempertimbangkan kita bahkan!",
  str_homestory_chat_11751019 = "Jika tidak... Hei, saya pikir saya mungkin baru saja menemukan rute retret baru!",
