  str_homestory_chat_10521002 = "Ya, dia tidur lelap.",
  str_homestory_chat_10522001 = "Hari yang menyenangkan.",
  str_homestory_chat_10522002 = "Ya, menyenangkan sekali...",
  str_homestory_chat_10522003 = "Sehari-hari berada di rumah itu nyaman dan menyenangkan...",
  str_homestory_chat_10522004 = "Hmm... Maaf. Aku tak bermaksud membuatmu bingung.",
  str_homestory_chat_10522005 = "Sama sekali tidak.",
  str_homestory_chat_10522006 = "Sudah lama tidak melihat Baba Yaga.",
  str_homestory_chat_10522007 = "Karena... Berada di rumah itu sangat tenang dan damai. Dia banyak tidur...",
  str_homestory_chat_10522008 = "Kalau kau sungguh ingin bertemu dengannya, aku bisa...",
  str_homestory_chat_10522009 = "Tunggu. Bukan itu maksudku!",
  str_homestory_chat_10523001 = "Kau mau minum apa?",
  str_homestory_chat_10523002 = "Ada Knight's Black Tea?",
  str_homestory_chat_10523003 = "Segera. Jangan buat aku bertanya.",
  str_homestory_chat_10523004 = "Baba Yaga?",
  str_homestory_chat_10523005 = "Jangan ganti topik pembicaraan.",
  str_homestory_chat_10523006 = "Aku ingat Mia suka Knight's Black Tea.",
  str_homestory_chat_10523007 = "Cukup, atau kau akan menghadapi cakar baja.",
  str_homestory_chat_10523008 = "Tunggu sebentar…",
  str_homestory_chat_10523009 = "Ini akan butuh waktu sejenak.",
  str_homestory_chat_10523010 = "Berharaplah semoga tidak terlalu lama.",
  str_homestory_chat_10524001 = "Kudengar ada laba-laba baru-baru ini...",
  str_homestory_chat_10524002 = "Black Spider di malam hari? Kau melihatnya juga? Menurutmu siapa itu?",
  str_homestory_chat_10524003 = "Apa itu kau?",
  str_homestory_chat_10524004 = "Ah, kau terlalu terbenam dalam cerita misteri.",
  str_homestory_chat_10524005 = "Akan ada lebih banyak lagi setelah malam tiba.",
  str_homestory_chat_10524006 = "Entahlah…",
  str_homestory_chat_10524007 = "Tetaplah terjaga dan kau mungkin menemukan kebenaran di balik misteri itu.",
  str_homestory_chat_10524008 = "Memangnya kau tidak ingin melihat?",
  str_homestory_chat_10524009 = "Tidak... Sama sekali tidak...",
  str_homestory_chat_10499999 = "Hai! Kau di sini membawa makanan?",
  str_homestory_chat_10401001 = "... Tidak.",
  str_homestory_chat_10401002 = "Aku hanya datang untuk menyapa.",
  str_homestory_chat_10401003 = "Hmm... Pergilah. Makanan adalah prioritas sekarang.",
  str_homestory_chat_10421001 = "Kau berkeringat.",
  str_homestory_chat_10421002 = "Ya... Panas sekali.",
  str_homestory_chat_10421003 = "Ada bir dingin, ikan beku, atau kaleng es?",
  str_homestory_chat_10421004 = "Aku harus mencarinya dulu...",
  str_homestory_chat_10421005 = "Cepat! Mulai cari sekarang!",
  str_homestory_chat_10421006 = "Silakan jika kau mau melihatku meleleh menjadi genangan air!",
  str_homestory_chat_10421007 = "Tidak...",
  str_homestory_chat_10421008 = "Tidak mungkin, hidup tidak bisa terus seperti ini!",
  str_homestory_chat_10422001 = "Kau pergi berenang baru-baru ini?",
  str_homestory_chat_10422002 = "Ya, renang yang menyenangkan di sungai...",
  str_homestory_chat_10422003 = "Sungai?",
  str_homestory_chat_10422004 = "Ya, sungai memang untuk berenang. Ada masalah?",
  str_homestory_chat_10422005 = "Tidak... aku tiba-tiba baru sadar kalau kau perenang ulung.",
  str_homestory_chat_10422006 = "Sungai dangkal itu sangat aman untukmu.",
  str_homestory_chat_10423001 = "Es batu?",
  str_homestory_chat_10423002 = "Ya, apakah Anda punya es batu?",
  str_homestory_chat_10423003 = "Yang sebesar rumah.",
  str_homestory_chat_10423004 = "Tidak!",
  str_homestory_chat_10423005 = "Bagaimana saya harus menghabiskan musim panas saya, kalau begitu?",
  str_homestory_chat_10423006 = "Bagaimana kamu melakukannya?",
  str_homestory_chat_10423007 = "Melakukan pekerjaan di mana-mana, lalu membeli es batu dengan uang.",
  str_homestory_chat_10423008 = "Jadi, Anda harus bekerja dan menghasilkan uang.",
  str_homestory_chat_10423009 = "Ya!",
  str_homestory_chat_10423010 = "Dan mereka lebih besar dari rumah! Mereka sebesar gunung!",
  str_homestory_chat_10423011 = "Benarkah?!",
  str_homestory_chat_10423012 = "Tidak, tidak juga.",
  str_homestory_chat_15099999 = "Halo, Bung!",
  str_homestory_chat_15001001 = "Hai! Hai...",
  str_homestory_chat_15001002 = "Abaikan gigiku. Aku tidak bermaksud menunjukkannya.",
  str_homestory_chat_15001003 = "Aku tahu... Tolong sembunyikan...",
  str_homestory_chat_15021001 = "Kau sedang cari apa?",
  str_homestory_chat_15021002 = "Apa kita punya kucing di sini?",
  str_homestory_chat_15021003 = "Kurasa begitu…",
  str_homestory_chat_15021004 = "Tolong tunjukkan padaku kalau kau punya waktu.",
  str_homestory_chat_15021005 = "Tenang saja. Aku tidak makan kucing.",
  str_homestory_chat_15021006 = "Aku ini vegetarian, ingat?",
  str_homestory_chat_15021007 = "Ya, aku ingat...",
  str_homestory_chat_15021008 = "Aku rasa tidak...",
  str_homestory_chat_15021009 = "Kapan kita bakal punya kucing?",
  str_homestory_chat_15021010 = "Begitu ada kucing, bosan pun hilang…",
  str_homestory_chat_15022001 = "Kau ingin bicara denganku?",
  str_homestory_chat_15022002 = "Butuh Shark Tooth Powder, Bung?",
  str_homestory_chat_15022003 = "Ini untuk apa?",
  str_homestory_chat_15022004 = "Kau bisa menambahkannya ke camilan malammu.",
  str_homestory_chat_15022005 = "Coba saja, nanti kau akan tahu!",
  str_homestory_chat_15022006 = "Aku tidak membawanya. Mungkin lain kali.",
  str_homestory_chat_15023001 = "gigimu...",
  str_homestory_chat_15023002 = "Hm? Oh, itu agak longgar lagi.",
  str_homestory_chat_15023003 = "Sepertinya aku akan membutuhkan batch baru. Apakah Anda mengambil ini?",
  str_homestory_chat_15023004 = "Apa yang dilakukan ini?",
  str_homestory_chat_15023005 = "Tidak.",
  str_homestory_chat_15023006 = "Ayo! Ini sangat berguna.",
  str_homestory_chat_15023007 = "Anda bisa membuat patung darinya, atau Anda bisa menggilingnya dan menggunakannya sebagai bumbu.",
  str_homestory_chat_15023008 = "Anda mungkin bisa menghasilkan uang dengan menjualnya ke Umbraton.",
  str_homestory_chat_15023009 = "Lalu kenapa kamu tidak menyimpannya untuk dirimu sendiri?",
  str_homestory_chat_15023010 = "Karena aku membayarmu untuk perlindungan.",
  str_homestory_chat_15031001 = "Ikan aneh...",
  str_homestory_chat_15031002 = "Hmm? Anda melihat sesuatu, bos?",
  str_homestory_chat_15031003 = "Beberapa hari yang lalu, saya melihat segerombolan ikan di sungai yang belum pernah saya lihat sebelumnya.",
  str_homestory_chat_15031004 = "Mata mereka besar, dan tubuh mereka agak bulat.",
  str_homestory_chat_15031005 = "Oh, Anda pasti berbicara tentang Ikan Mas Bighead! Sebenarnya, akulah yang menempatkan mereka di sana...",
  str_homestory_chat_15031006 = "Hah?",
  str_homestory_chat_15031007 = "Yah, saya perhatikan bahwa Bighead Carp melakukannya dengan sangat baik di sekitar sini.",
  str_homestory_chat_15031008 = "Air, cuaca, kecepatan arus, semuanya sempurna untuk mereka! Tapi yang paling penting adalah mereka sangat langka!",
  str_homestory_chat_15031009 = "Dan di sini saya pikir Anda ingin memakannya...",
  str_homestory_chat_15031010 = "Ayo bos! Bergigi tajam seperti saya, saya tidak pernah makan daging!",
  str_homestory_chat_15031011 = "Berapa kali lagi kalian akan menilai saya salah dengan penampilan saya?",
  str_homestory_chat_15031012 = "Apa aku harus menghadapi ini seumur hidupku?!",
  str_homestory_chat_15031013 = "Ini kamu lagi...",
  str_homestory_chat_15031014 = "Jangan terlalu kurus! Anda berada di geng sebelumnya, bukan?",
  str_homestory_chat_15031015 = "Ya, tapi kau terus melakukannya berulang-ulang...",
  str_homestory_chat_15031016 = "Uh... Korgon, kenapa kau membawa Ikan Mas Kepala Besar ini ke sini?",
  str_homestory_chat_15031017 = "Untuk membiarkan mereka berkembang biak, tentu saja! Dan begitu jumlahnya banyak, saya akan membawa semuanya kembali ke Pulau Sharkfang.",
  str_homestory_chat_15031018 = "Rekonstruksi telah membuatku lelah akhir-akhir ini. Rasanya seperti pekerjaan tidak pernah berakhir!",
  str_homestory_chat_15031019 = "Tapi hanya melihat orang-orang kecil yang lucu ini membuat semua kelelahan saya hilang! Itu sebabnya saya ingin membawa mereka ke pulau.",
  str_homestory_chat_15031020 = "Melihat mereka berenang dalam berbagai bentuk dan ukuran—",
  str_homestory_chat_15031021 = "Tunggu! Mereka datang dalam ukuran yang berbeda?",
  str_homestory_chat_15031022 = "Ya, lihat? Ini terlihat seperti itu.",
  str_homestory_chat_15031023 = "Tapi saya hanya melihat satu ukuran ...",
  str_homestory_chat_15031024 = "Bagaimanapun, Bighead Carp sangat gugup. Aku butuh selamanya hanya untuk menemukan beberapa tempat di mana mereka tinggal.",
  str_homestory_chat_15031025 = "Mereka juga tidak mudah ditangkap...",
  str_homestory_chat_15031026 = "Jika Anda membutuhkan seseorang untuk memancingnya, saya bisa mengatasinya.",
  str_homestory_chat_15031027 = "B-Benarkah, bos?! Itu akan menjadi beban besar di pundak saya. Terima kasih!",
  str_homestory_chat_15031028 = "Tapi seperti yang saya katakan, Bighead Carp sangat langka. Aku agak enggan melihat salah satu dari mereka pergi, jujur saja...",
  str_homestory_chat_15031029 = "Baiklah, baiklah... Apa tangkapannya?",
  str_homestory_chat_15031030 = "Cepat seperti rubah, seperti biasa! Jadi kesepakatannya adalah, Anda membawakan saya salah satu Ikan Mas Bighead yang lebih kecil ini, dan saya akan berbagi beberapa info berharga dengan Anda.",
  str_homestory_chat_15031031 = "Saya akan memberi tahu Anda dengan tepat di mana Anda bisa memancing Ikan Mas Bighead yang lebih besar! Tapi apa yang terjadi setelah itu tergantung pada kemampuan memancing Anda, bos.",
  str_homestory_chat_15031032 = "Tentu saja, saya juga bersedia menawarkan beberapa hadiah lain karena membawakan saya lebih banyak Ikan Mas Bighead. Lagipula aku pria yang baik!",
  str_homestory_chat_15031033 = "Untuk setiap Bighead Carp yang Anda bawakan untuk saya, saya akan memberi tahu Anda di mana menemukan yang lebih besar!",
  str_homestory_chat_15031034 = "Saya mendengar ada yang seberat 50 kilogram! Bisakah kamu percaya itu?!",
  str_homestory_chat_15031035 = "Juga, ada kemungkinan Anda bisa menangkap Ikan Mas Bighead yang sangat langka dan berkilau!",
  str_homestory_chat_15031036 = "Kau pasti menjual ini padaku seperti seseorang dari Umbraton...",
  str_homestory_chat_15031037 = "Tapi aku bahkan tidak punya ikan terkecil untuk diberikan padamu sekarang.",
  str_homestory_chat_15031038 = "Tidak apa-apa, bos! Saya tahu banyak tempat di mana Anda dapat menemukan orang-orang kecil ini, meskipun Anda hanya akan menangkap yang terkecil dari kelompok itu di daerah tersebut.",
  str_homestory_chat_15031039 = "Tetapi jika Anda memiliki keterampilan untuk pekerjaan itu, Anda hanya perlu membawakan saya yang kecil, dan saya akan dengan senang hati menukarnya!",
  str_homestory_chat_15031040 = "Mulai dari kecil, kecil, sedang, hingga besar...",
  str_homestory_chat_15031041 = "Dan jika Anda berhasil sejauh itu, saya akan memastikan Anda menangkap yang lebih besar! Anda bahkan mungkin cukup beruntung untuk menangkap yang langka dan berkilau itu juga!",
  str_homestory_chat_15031042 = "Aku tahu.",
  str_homestory_chat_15031043 = "Jadi apakah Anda siap untuk itu, bos? Saya yakin Anda bisa mengatasinya!",
  str_homestory_chat_15031044 = "Ada pertanyaan lain?",
  str_homestory_chat_15031045 = "Saya ingin menangkap Ikan Mas Bighead yang lebih besar.",
  str_homestory_chat_15031046 = "Bukan masalah! Ada banyak tempat memancing di luar sana. Semuanya bermuara pada seberapa besar yang kita bicarakan di sini!",
  str_homestory_chat_15031047 = "Saya ingin menangkap Ikan Mas Bighead Kecil.",
  str_homestory_chat_15031048 = "Jika Anda ingin tahu di mana menangkap Ikan Mas Kecil Bighead, Anda harus membawakan saya Ikan Mas Kecil Besar terlebih dahulu. Apakah Anda mendapatkan satu belum?",
  str_homestory_chat_15031049 = "Berikan Ikan Mas Kecil Berkepala Besar ({1}/1)",
  str_homestory_chat_15031050 = "Biarkan aku memikirkannya.",
  str_homestory_chat_15031051 = "Saya ingin menangkap Ikan Mas Bighead Sedang.",
  str_homestory_chat_15031052 = "Jika Anda ingin tahu di mana menangkap Ikan Mas Bighead Sedang, Anda harus membawakan saya Ikan Mas Kecil Besar terlebih dahulu. Apakah Anda mendapatkan satu belum?",
  str_homestory_chat_15031053 = "Berikan Ikan Mas Bighead Kecil ({1}/1)",
  str_homestory_chat_15031054 = "Biarkan aku memikirkannya.",
  str_homestory_chat_15031055 = "Saya ingin menangkap Ikan Mas Bighead Besar.",
  str_homestory_chat_15031056 = "Jika Anda ingin tahu di mana menangkap Ikan Mas Bighead Besar, Anda harus membawakan saya Ikan Mas Bighead Sedang terlebih dahulu. Apakah Anda mendapatkan satu belum?",
  str_homestory_chat_15031057 = "Beri Ikan Mas Bighead Sedang ({1}/1)",
  str_homestory_chat_15031058 = "Biarkan aku memikirkannya.",
  str_homestory_chat_15031059 = "Saya ingin menangkap Ikan Mas Bighead Raksasa.",
  str_homestory_chat_15031060 = "Jika Anda ingin tahu di mana untuk menangkap Ikan Mas Bighead Raksasa, Anda harus membawakan saya Ikan Mas Besar Besar terlebih dahulu. Apakah Anda mendapatkan satu belum?",
  str_homestory_chat_15031061 = "Berikan Ikan Mas Bighead Besar ({1}/1)",
  str_homestory_chat_15031062 = "Biarkan aku memikirkannya.",
  str_homestory_chat_15031063 = "Anda orangnya, bos! Saya tidak bisa mengatakan betapa bahagianya saya!",
  str_homestory_chat_15031064 = "Periksa peta Anda. Saya akan menandai di mana Anda dapat menemukan ikan yang lebih besar!",
  str_homestory_chat_15031065 = "saya belum punya...",
  str_homestory_chat_15031066 = "Ah, sayang sekali, bos. Kembalilah padaku ketika kamu memilikinya.",
  str_homestory_chat_15031067 = "Tentu saja.",
  str_homestory_chat_15031068 = "Ingatkan saya tentang kesepakatan Bighead Carp kami.",
  str_homestory_chat_15031069 = "Tentu, bos! Saya dapat mengulangi diri saya sendiri berapa kali pun Anda mau!",
  str_homestory_chat_15031070 = "Kesepakatannya sederhana: Bawakan saya Bighead Carp dengan ukuran berapa pun.",
  str_homestory_chat_15031071 = "Beri saya ikannya, dan saya akan memberi tahu Anda di mana menemukan Ikan Mas Bighead ukuran terbesar berikutnya.",
  str_homestory_chat_15031072 = "Saya bahkan akan memberi Anda beberapa hadiah lain untuk masalah Anda! Anda tidak akan kecewa!",
  str_homestory_chat_15031073 = "Aku mengerti.",
  str_homestory_chat_15031074 = "Saya ingin memancing Ikan Mas Bighead.",
  str_homestory_chat_15031075 = "Siap untuk memulai dengan Ikan Mas Kecil Besar? Anda dapat datang untuk menemukan saya kapan saja setelah Anda menangkapnya! Saya akan memberi tahu Anda di mana menemukan ukuran berikutnya setelah itu!",
  str_homestory_chat_15031076 = "Ya, saya siap.",
  str_homestory_chat_15031077 = "Bagus, bos! Saya akan menandai di mana Anda dapat menemukannya di peta!",
  str_homestory_chat_15031078 = "aku masih harus memikirkannya...",
  str_homestory_chat_15032001 = "Ceritakan lebih banyak tentang Bighead Carp.",
  str_homestory_chat_15032002 = "Ikan mas kepala besar, ya? Tentu saja, bos! Saya selalu senang membantu!",
