  str_homestory_chat_15032019 = "Jika Anda ingin tahu di mana untuk menangkap Ikan Mas Bighead Raksasa, Anda harus membawakan saya Ikan Mas Besar Besar terlebih dahulu. Apakah Anda mendapatkan satu belum?",
  str_homestory_chat_15032020 = "Berikan Ikan Mas Bighead Besar ({1}/1)",
  str_homestory_chat_15032021 = "Biarkan aku memikirkannya.",
  str_homestory_chat_15032022 = "Anda orangnya, bos! Saya tidak bisa mengatakan betapa bahagianya saya!",
  str_homestory_chat_15032023 = "Periksa peta Anda. Saya akan menandai di mana Anda dapat menemukan ikan yang lebih besar!",
  str_homestory_chat_15032024 = "Ah... Biarkan aku memikirkannya.",
  str_homestory_chat_15032025 = "Saya masih ingin bertanya tentang hal lain.",
  str_homestory_chat_15032026 = "Minta pergi, bos!",
  str_homestory_chat_15032027 = "Ingatkan saya tentang kesepakatan Bighead Carp kami.",
  str_homestory_chat_15032028 = "Oh... Anda pasti punya banyak di piring Anda jika Anda sudah lupa, bos. Tapi tidak apa-apa!",
  str_homestory_chat_15032029 = "Saya akan memberitahu Anda seribu kali jika saya harus! Bagaimanapun, Anda adalah bosnya!",
  str_homestory_chat_15032030 = "Jika Anda kebetulan memiliki Ikan Mas Bighead berukuran kecil, bawakan saja kepada saya.",
  str_homestory_chat_15032031 = "Anda memberi saya ikannya, dan saya memberi tahu Anda di mana menemukan ikan mas Bighead ukuran terbesar berikutnya.",
  str_homestory_chat_15032032 = "Tapi bukan itu saja, bos! Saya akan memberi Anda beberapa barang bagus lainnya sebagai ganti ikan juga!",
  str_homestory_chat_15032033 = "Aku paham.",
  str_homestory_chat_15032034 = "Saya ingin memancing Ikan Mas Bighead.",
  str_homestory_chat_15032035 = "Siap untuk memulai dengan Ikan Mas Kecil Besar? Anda dapat datang untuk menemukan saya kapan saja setelah Anda menangkapnya! Saya akan memberi tahu Anda di mana menemukan ukuran berikutnya setelah itu!",
  str_homestory_chat_15032036 = "Ya, saya siap.",
  str_homestory_chat_15032037 = "Bagus, bos! Saya akan menandai di mana Anda dapat menemukannya di peta!",
  str_homestory_chat_15032038 = "Biarkan aku memikirkannya.",
  str_homestory_chat_15032039 = "Saya tidak punya pertanyaan lagi.",
  str_homestory_chat_15032040 = "Itu berhasil, bos! Datang saja ke saya setiap kali Anda punya pertanyaan!",
  str_homestory_chat_15033001 = "Ceritakan lebih banyak tentang Bighead Carp.",
  str_homestory_chat_15033002 = "Tidak masalah, bos! Saya sudah menandai tempat pemancingan ikan mas Bighead di peta Anda. Pergi lihat!",
  str_homestory_chat_15033003 = "Saya akan mendukung Anda dari sini, bos! Ayo temukan aku jika kamu butuh sesuatu!",
  str_homestory_chat_15033004 = "Ingatkan saya tentang kesepakatan Bighead Carp kami.",
  str_homestory_chat_15033005 = "Sudah lupa? Tidak apa-apa, saya akan memberitahu Anda sebanyak yang Anda suka, bos!",
  str_homestory_chat_15033006 = "Kesepakatannya sederhana: Bawakan saya Bighead Carp dengan ukuran berapa pun.",
  str_homestory_chat_15033007 = "Anda memberi saya ikannya, dan saya memberi tahu Anda di mana menemukan ikan mas Bighead ukuran terbesar berikutnya.",
  str_homestory_chat_15033008 = "Saya bahkan akan memberi Anda beberapa hadiah lain untuk masalah Anda! Bagaimanapun, Anda adalah bosnya!",
  str_homestory_chat_15033009 = "Aku mengerti.",
  str_homestory_chat_15033010 = "Terima kasih lagi, Korgon!",
  str_homestory_chat_15033011 = "Kapan saja, bos! Selalu siap membantu!",
  str_homestory_chat_13599999 = "Halo! Tidak kerja hari ini?",
  str_homestory_chat_13501001 = "Aku sedang beristirahat.",
  str_homestory_chat_13501002 = "Akan kubantu kalau kau kesulitan menyelesaikan pekerjaanmu!",
  str_homestory_chat_13521001 = "Apa yang kau suka dengan kehidupan di Colossus?",
  str_homestory_chat_13521002 = "Yoshi suka tinggal di sini!",
  str_homestory_chat_13521003 = "Dia bisa terbang bebas di langit.",
  str_homestory_chat_13521004 = "Bagaimana denganmu?",
  str_homestory_chat_13521005 = "Aku juga... Uhuk... Tentu saja.",
  str_homestory_chat_13521006 = "Baguslah kalau begitu.",
  str_homestory_chat_13522001 = "Kelihatannya kau sangat lelah...",
  str_homestory_chat_13522002 = "Hah? Masa?",
  str_homestory_chat_13522003 = "Lihat! Bukankah lingkaran hitamku mengecil sekarang?",
  str_homestory_chat_13522004 = "Mungkin begitu.",
  str_homestory_chat_13522005 = "Itu karena aku tidak bekerja lembur akhir-akhir ini!",
  str_homestory_chat_13522006 = "Pekerjaan di sini sangat sedikit. Aku jadi tidak perlu bergadang sama sekali.",
  str_homestory_chat_13522007 = "Bagus, dong!",
  str_homestory_chat_13522008 = "Tidak terlalu.",
  str_homestory_chat_13522009 = "Hmm... Bagaimana bisa?",
  str_homestory_chat_13522010 = "Aku tidak kerja lembur sama sekali...",
  str_homestory_chat_13522011 = "Tidur lebih awal mungkin bisa membantu.",
  str_homestory_chat_13522012 = "Kau benar.",
  str_homestory_chat_13551001 = "Anda ingin memberitahu saya tentang ikan khusus?",
  str_homestory_chat_13551002 = "Itu benar! Dan saya harus melakukan pengiriman setelah saya memberi tahu Anda tentang hal itu.",
  str_homestory_chat_13551003 = "Tetapi mengapa seseorang di Cloud Gardens membutuhkan pengiriman sesuatu?",
  str_homestory_chat_13551004 = "Bukankah kamu di sini untuk beristirahat?",
  str_homestory_chat_13551005 = "Tidak, saya di sini untuk berlatih! Dan saya tidak bisa berhenti! Bagaimanapun, ikan spesial ini juga menjadi subjek pelatihan saya!",
  str_homestory_chat_13551006 = "Sebuah subjek? Anda cukup serius tentang ini, bukan?",
