  str_homestory_chat_13551008 = "Hah?",
  str_homestory_chat_13551009 = "Terkadang diperlukan sedikit penantian sebagai bagian dari pelatihan.",
  str_homestory_chat_13551010 = "Waktu yang terbuang juga diperhitungkan! Jadi pergilah! Sekarang!",
  str_homestory_chat_13551011 = "Um, jadi apakah kamu sedang terburu-buru atau tidak? Ini... aneh.",
  str_homestory_chat_13551012 = "Pergi saja! Benih Pohon Mekar yang Nyaring! Sekarang!",
  str_homestory_chat_13551013 = "Baiklah, baiklah!",
