  str_homestory_chat_14201001 = "Hai...",
  str_homestory_chat_14201002 = "Sapaanmu sangat lantang...",
  str_homestory_chat_14201003 = "Seorang prajurit harus menggunakan semangat militernya sepanjang waktu!",
  str_homestory_chat_14201004 = "... Begitu, ya.",
  str_homestory_chat_14221001 = "Kelihatannya kau senggang...",
