  str_homestory_chat_17321002 = "Ya! Sangat cocok untuk petak umpet.",
  str_homestory_chat_17321003 = "Mau bermain?",
  str_homestory_chat_17321004 = "Hitung sampai sepuluh!",
  str_homestory_chat_17321005 = "Permainan dimulai!",
  str_homestory_chat_17321006 = "Lari!",
  str_homestory_chat_17321007 = "Aku mengejarmu!",
  str_homestory_chat_17321008 = "Tidak! Aku tak mau bermain!",
  str_homestory_chat_17322001 = "Kelihatannya kau gembira sekali.",
  str_homestory_chat_17322002 = "Ya! Di sini ada air bersih!",
  str_homestory_chat_17322003 = "Anjing suka di sini!",
  str_homestory_chat_17322004 = "Eh, sebentar...",
  str_homestory_chat_17322005 = "Apa kau minum dari sungai?",
  str_homestory_chat_17322006 = "Tak boleh?",
  str_homestory_chat_17322007 = "Memangnya kenapa?",
  str_homestory_chat_17322008 = "Karena... Seseorang suka berenang di sungai!",
  str_homestory_chat_11699999 = "Halo. Semoga tidur nyenyak malam ini.",
  str_homestory_chat_11601001 = "Ah... Hai.",
  str_homestory_chat_11601002 = "Ada apa?",
  str_homestory_chat_11601003 = "Bukan apa-apa.",
  str_homestory_chat_11601004 = "Kalau begitu, aku mau tidur siang.",
  str_homestory_chat_11601005 = "Baiklah. Selamat beristirahat.",
  str_homestory_chat_11621001 = "Matamu…",
  str_homestory_chat_11621002 = "Lingkaran hitamku sudah hampir sepenuhnya hilang.",
  str_homestory_chat_11621003 = "Tidur malam yang nyenyak membuat suasana hatiku lebih baik.",
  str_homestory_chat_11621004 = "Baru bangun?",
  str_homestory_chat_11621005 = "Ya. Lebih gampang mencari tempat tenang untuk tidur siang di sini daripada di gurun.",
  str_homestory_chat_11621006 = "Omong-omong soal itu, aku ingin berterima kasih kepadamu.",
  str_homestory_chat_11621007 = "Hahah. Sama-sama.",
  str_homestory_chat_11622001 = "Ada yang bisa kubantu?",
  str_homestory_chat_11622002 = "PlayerName, apa kau punya camilan?",
  str_homestory_chat_11622003 = "Ya!",
  str_homestory_chat_11622004 = "Aku minta, dong.",
  str_homestory_chat_11622005 = "Aku tidak bawa.",
  str_homestory_chat_11622006 = "Lain kali, bawakan beberapa kalau kau bisa.",
  str_homestory_chat_11622007 = "Tidak...",
  str_homestory_chat_11622008 = "Akan kubawakan kalau punya.",
  str_homestory_chat_11622009 = "Terima kasih, ya.",
  str_homestory_chat_11622010 = "Makan camilan adalah satu-satunya cara untuk menghabiskan waktu.",
  str_homestory_chat_11623001 = "Kau sedang cari apa?",
  str_homestory_chat_11623002 = "Sangat banyak makhluk berbulu di sini...",
  str_homestory_chat_11623003 = "Memangnya kau tak suka?",
  str_homestory_chat_11623004 = "Tidak suka... Tapi, aku juga tidak membenci mereka.",
  str_homestory_chat_11623005 = "Kalau ada yang berani menganiaya mereka, aku akan membuatnya menderita.",
  str_homestory_chat_17799999 = "Ini dia orang yang sedang aku pikirkan, senang bertemu denganmu.",
  str_homestory_chat_17701001 = "Kau terlalu menyanjungku, Yang Mulia.",
  str_homestory_chat_17701002 = "Semoga damai terus mengalir di negeri ini!",
  str_homestory_chat_17701003 = "Begitu pula, Yang Mulia.",
  str_homestory_chat_17721001 = "Yang Mulia, apa yang kau pikirkan?",
  str_homestory_chat_17721002 = "Aku senang begitu banyak orang menemanimu dalam perjalanan ini.",
  str_homestory_chat_17721003 = "Banyak orang di negeri ini senang turut besertamu.",
  str_homestory_chat_17721004 = "Kami semua teman.",
  str_homestory_chat_17721005 = "Kurasa persahabatan menyatukan kami. Mereka bukan pengikutku.",
  str_homestory_chat_17721006 = "Aku senang mendengarnya.",
  str_homestory_chat_17721007 = "Apakah aku juga salah satu temanmu?",
  str_homestory_chat_17721008 = "Tentu saja!",
  str_homestory_chat_17722001 = "Yang Mulia, apakah semuanya baik-baik saja?",
  str_homestory_chat_17722002 = "Pemandangan di sini jauh berbeda dengan Northland, tapi aku nyaman dan senang.",
  str_homestory_chat_17722003 = "Kau tuan rumah yang luar biasa.",
  str_homestory_chat_17722004 = "Teh hitammu agak pahit, koleksi buku sangat terbatas, dan suhunya tinggi...",
  str_homestory_chat_17722005 = "Aku cukup senang dengan segala yang lain di sini.",
  str_homestory_chat_17722006 = "Ah! Aku mengerti...",
  str_homestory_chat_17723001 = "Hadir.",
  str_homestory_chat_17723002 = "Buku yang kukirimkan kepadamu... Sudah baca sampai mana?",
  str_homestory_chat_17723003 = "Sudah selesai semuanya!",
  str_homestory_chat_17723004 = "Pasti banyak hal yang sudah kau pelajari.",
  str_homestory_chat_17723005 = "Coba aku tes seberapa baik kau menyerap pengetahuannya.",
  str_homestory_chat_17723006 = "Jangan... Itu tidak perlu, Yang Mulia...",
  str_homestory_chat_17723007 = "Saya baru membaca setengahnya...",
  str_homestory_chat_17723008 = "Setengah dari buku yang sangat bermanfaat ini pun sudah cukup buat kau cerna.",
  str_homestory_chat_17723009 = "Katakan, menurutmu bagaimana buku itu.",
  str_homestory_chat_17723010 = "Saya... Saya... Boleh minta waktu sebentar untuk berpikir?",
  str_homestory_chat_17723011 = "Saya belum membacanya sama sekali...",
  str_homestory_chat_17723012 = "...",
  str_homestory_chat_17723013 = "Tadinya saya ingin membaca, tapi ada banyak halangan...",
  str_homestory_chat_17723014 = "Nanti aku tanyakan lagi, ya. Sebaiknya kau segera membacanya.",
  str_homestory_chat_17723015 = "Ahh?",
  str_homestory_chat_17724001 = "Yang Mulia, apakah Anda sedang bersantai?",
  str_homestory_chat_17724002 = "Ya, PlayerName. Kalau kau biasanya melakukan apa untuk bersenang-senang?",
  str_homestory_chat_17724003 = "Saya sangat jarang punya waktu luang...",
  str_homestory_chat_17724004 = "Hmm... Sepertinya kau akan kembali bekerja setelah kita mengobrol.",
  str_homestory_chat_17724005 = "Benar.",
  str_homestory_chat_17724006 = "Yang Mulia, adakah yang bisa saya bawakan kemari?",
  str_homestory_chat_17724007 = "Tidak hari ini. Kita mengobrol lagi lain kali.",
  str_homestory_chat_17724008 = "Banyak hal...",
  str_homestory_chat_17724009 = "Saya akan bermain sesuatu, memancing, dan berolahraga...",
  str_homestory_chat_17724010 = "Apakah kau berlatih anggar?",
  str_homestory_chat_17724011 = "Hah? Anggar?",
  str_homestory_chat_17724012 = "Ah! Saya paham. Yang Mulia membutuhkan ruang untuk berlatih anggar?",
  str_homestory_chat_17724013 = "Kecerdasanmu selalu membuatku kagum.",
  str_homestory_chat_17725001 = "Apakah Anda mencari saya, Yang Mulia?",
  str_homestory_chat_17725002 = "Ya, saya telah merenungkan kemampuan pribadi Anda.",
  str_homestory_chat_17725003 = "Kemampuan pribadi...?",
  str_homestory_chat_17725004 = "Kecakapan seni bela diri Anda, terutama pertahanan diri.",
  str_homestory_chat_17725005 = "Karena Anda berkali-kali berada dalam situasi berbahaya, dan Anda tidak memiliki apa yang diperlukan untuk melindungi rekan Anda.",
  str_homestory_chat_17725006 = "Dalam situasi seperti ini, paling tidak yang bisa Anda lakukan adalah melindungi diri sendiri. Setelah memikirkan hal ini beberapa saat...",
  str_homestory_chat_17725007 = "Saya pikir saya akan mengajari Anda beberapa teknik pedang untuk pertahanan diri.",
  str_homestory_chat_17725008 = "Teknik pedang? Kedengarannya bagus... Tapi kupikir aku harus membangun kekuatanku terlebih dahulu.",
  str_homestory_chat_17725009 = "Teknik bersifat sekunder. Bagian terpenting adalah stamina Anda.",
  str_homestory_chat_17725010 = "Misalnya, mengapa kita tidak mulai dengan sepuluh putaran? Ini akan meningkatkan stamina Anda, dan Anda dapat berlari lebih cepat saat menghindari bahaya.",
  str_homestory_chat_17725011 = "Um, itulah yang Anda benar-benar ingin saya lakukan, bukan, Yang Mulia?",
  str_homestory_chat_17726001 = "Langit?",
  str_homestory_chat_17726002 = "Ya, saya telah melihat ke langit, dan saya menyadari bahwa ada yang salah dengan Cloud Gardens.",
  str_homestory_chat_17726003 = "Apa maksudmu?",
  str_homestory_chat_17726004 = "Langit tidak terlindungi. Cloud Gardens dikelilingi pegunungan, jadi sulit untuk serangan darat.",
  str_homestory_chat_17726005 = "Tapi serangan dari atas sulit dipertahankan.",
  str_homestory_chat_17726006 = "Dan kami juga tidak memiliki siapa pun yang berpatroli di langit.",
  str_homestory_chat_17726007 = "Um, bagaimana dengan Colossus?",
  str_homestory_chat_17726008 = "Apakah itu memiliki kemampuan tempur?",
  str_homestory_chat_17726009 = "Yah, setidaknya bisa mengeluarkan peringatan.",
  str_homestory_chat_17726010 = "Anda benar. Saya terlalu memikirkan banyak hal.",
  str_homestory_chat_17727001 = "Chubb?",
  str_homestory_chat_17727002 = "Apa pendapatmu tentang mereka?",
  str_homestory_chat_17727003 = "Mereka adalah teman.",
  str_homestory_chat_17727004 = "Seperti Aurorian?",
  str_homestory_chat_17727005 = "Hmm, mungkin sedikit berbeda, karena mereka kebanyakan nongkrong di Cloud Gardens.",
  str_homestory_chat_17727006 = "Mereka adalah pembantu.",
  str_homestory_chat_17727007 = "Hanya pembantu?",
  str_homestory_chat_17727008 = "Mungkin mereka juga...",
  str_homestory_chat_17727009 = "Administrator tempat ini?",
  str_homestory_chat_17727010 = "Pernahkah Anda berpikir untuk memberi mereka lebih banyak tanggung jawab?",
  str_homestory_chat_17727011 = "Misalnya, membiarkan mereka menaiki Colossus, atau mengirim mereka ke kota lain sebagai pembawa pesan di Cloud Gardens.",
  str_homestory_chat_17727012 = "Saya pikir ... itu terlalu cepat.",
  str_homestory_chat_16499999 = "PlayerName, kau tampak santai dan riang hari ini..",
  str_homestory_chat_16421001 = "Kau mengawasiku?",
  str_homestory_chat_16421002 = "Kau keberatan, PlayerName?",
  str_homestory_chat_16421003 = "Ehm... Aku tak pernah bilang begitu...",
  str_homestory_chat_16421004 = "Sepertinya supervisiku mendorongmu untuk tetap melakukan pekerjaanmu.",
  str_homestory_chat_16422001 = "Ya, aku sedang beristirahat.",
  str_homestory_chat_16422002 = "... Sudah waktunya rehat?",
  str_homestory_chat_16422003 = "Benar.",
  str_homestory_chat_16422004 = "Jadwalmu terlalu longgar. Bagaimana mungkin kau beristirahat sekarang?",
  str_homestory_chat_16422005 = "Sebenarnya tidak bisa beristirahat, sih...",
  str_homestory_chat_16422006 = "Kalau begitu, sudahi obrolan kita sekarang juga dan kembali bekerja.",
  str_homestory_chat_16422007 = "Kau harus tetap sibuk seperti aku.",
  str_homestory_chat_16422008 = "Tapi... Menurutku, kau tidak banyak pekerjaan sekarang.",
  str_homestory_chat_16422009 = "... Jangan tertipu oleh penampilanku. Aku orang yang sangat fokus.",
  str_homestory_chat_16423001 = "Sedang apa kau?",
  str_homestory_chat_16423002 = "Meditasi.",
  str_homestory_chat_16423003 = "Jangan menatapku seperti itu.",
  str_homestory_chat_16423004 = "Jika kau menghadapi tekanan yang sama berat, kuyakin kau juga akan bermeditasi untuk menemukan kedamaian batin.",
  str_homestory_chat_16423005 = "Baiklah. Silakan saja.",
  str_homestory_chat_16424001 = "Mencariku?",
  str_homestory_chat_16424002 = "Ada hal yang perlu kauketahui.",
  str_homestory_chat_16424003 = "Yaitu?",
  str_homestory_chat_16424004 = "Saya tak menemukan tempat mana pun untuk menggunakan kekuatan Red Baron.",
  str_homestory_chat_16424005 = "Kau perlu membangun tempat latihan.",
  str_homestory_chat_16424006 = "Aku boleh menolak gagasan ini?",
  str_homestory_chat_16424007 = "Sebaiknya jangan menggunakan senjata berbahaya ini sama sekali di sini.",
  str_homestory_chat_16424008 = "... Menurutmu begitu, ya? Baiklah, menurutku lebih baik memiliki tempat latihan.",
  str_homestory_chat_16424009 = "Tentu!",
  str_homestory_chat_16424010 = "Tempat latihan adalah hal bagus buat kita semua.",
  str_homestory_chat_16424011 = "Akan kutunggu undangan untuk melakukan tur tempat latihanmu.",
  str_homestory_chat_15799999 = "Halo. Apa kabar, meong?",
  str_homestory_chat_15701001 = "Halo.",
  str_homestory_chat_15701002 = "Bukan apa-apa. Kemari hanya untuk menyapa.",
  str_homestory_chat_15701003 = "Baiklah. Aku juga akan menyapa kalau begitu...",
  str_homestory_chat_15701004 = "Hai! Hai, meong...",
  str_homestory_chat_15721001 = "Kau suka di sini?",
  str_homestory_chat_15721002 = "Ya, aku suka sekali, meong.",
  str_homestory_chat_15721003 = "Aku bisa tidur sepuasku di sini, meong.",
  str_homestory_chat_15721004 = "Kau selalu mengantuk?",
  str_homestory_chat_15721005 = "Aku tidak mengantuk, aku hanya suka sekali tidur, meong!",
  str_homestory_chat_15721006 = "Ranjang yang empuk dan nyaman akan membuat tidur makin nyenyak, meong.",
  str_homestory_chat_15721007 = "Oke, deh.",
  str_homestory_chat_15722001 = "Kau sedang apa?",
  str_homestory_chat_15722002 = "Aku tidak pernah diberi makan ikan kering…",
  str_homestory_chat_15722003 = "Aku masak sendiri sajalah buatku, meong!",
  str_homestory_chat_15722004 = "Rencananya bagaimana?",
  str_homestory_chat_15722005 = "Aku akan memancing dulu, meong.",
  str_homestory_chat_15722006 = "Tapi, bagaimana kalau aku terlelap dan tenggelam di sungai?",
  str_homestory_chat_15722007 = "Aku punya ikan kering!",
  str_homestory_chat_15722008 = "Bagi, dong, meong.",
  str_homestory_chat_15722009 = "Nanti aku gantian, meong.",
  str_homestory_chat_15722010 = "Tapi, sekarang aku tak membawanya...",
  str_homestory_chat_15722011 = "Huft... Aku akan segera datang ke tempat tinggalmu, meong.",
  str_homestory_chat_15723001 = "Bulumu...",
  str_homestory_chat_15723002 = "Buluku tampak berantakan, tapi terasa sangat lembut, meong.",
  str_homestory_chat_15723003 = "Bolehkah kuusap?",
  str_homestory_chat_15723004 = "Tapi, aku baru saja menjilatinya sampai bersih.",
  str_homestory_chat_15723005 = "Silakan kalau kau tak keberatan, meong.",
  str_homestory_chat_15723006 = "Eh…",
  str_homestory_chat_15723007 = "Mari, kita sisiri bulumu sebentar...",
  str_homestory_chat_15723008 = "Mungkin rasanya akan lebih nyaman setelahnya.",
  str_homestory_chat_15723009 = "Tidak. Membersihkan bulu itu melelahkan, meow.",
  str_homestory_chat_15724001 = "Tidurmu nyenyak?",
  str_homestory_chat_15724002 = "Tidurku cukup panjang. Aku tak bisa tetap terjaga di sini, meong.",
  str_homestory_chat_15724003 = "Yumi?",
  str_homestory_chat_15724004 = "Bukankah sudah jelas, meong?",
  str_homestory_chat_15724005 = "... Baru saja bangun dan siap untuk tidur lagi, meong.",
  str_homestory_chat_15724006 = "Bagaimana dengan Philyshy?",
  str_homestory_chat_15724007 = "Philyshy sudah tidur, meong.",
  str_homestory_chat_15724008 = "Dia sudah terjaga terlalu lama, meong. Giliran dia beristirahat.",
  str_homestory_chat_15724009 = "Aku tak akan membangunkannya demi kau, meong.",
  str_homestory_chat_18399999 = "Halo, Master. Penjelasan. Tugas hari ini sudah selesai.",
  str_homestory_chat_18321001 = "Hmm…",
  str_homestory_chat_18321002 = "Aku datang hanya untuk menyapa. Ini bukan inspeksi...",
  str_homestory_chat_18321003 = "Menerjemahkan dan mengonversi. Lilliam paham.",
  str_homestory_chat_18322001 = "Apa pendapatmu tentang tempat ini?",
  str_homestory_chat_18322002 = "Menerjemahkan dan mengonversi. Pembersihan dapat bermanfaat. Master, silakan berikan perintah pembersihan.",
  str_homestory_chat_18322003 = "Tak perlu...",
  str_homestory_chat_18322004 = "Pembersihan memakan waktu yang lama...",
  str_homestory_chat_18322005 = "Aku akan memintamu untuk melakukan hal lain, oke?",
  str_homestory_chat_18322006 = "Berlebihan. Oke.",
  str_homestory_chat_18322007 = "Ide bagus.",
  str_homestory_chat_18322008 = "Tapi, tunggu sampai semua yang lain menyelesaikan pekerjaannya.",
  str_homestory_chat_18322009 = "Menentukan... Anda benar.",
  str_homestory_chat_18323001 = "Sedang apa kau?",
  str_homestory_chat_18323002 = "Bertanya. Ada yang bisa saya bantu?",
  str_homestory_chat_18323003 = "Ah... Tidak ada apa-apa...",
  str_homestory_chat_18323004 = "Pernyataan. Lilliam percaya bahwa Anda membutuhkan banyak hal, tapi Anda memilih untuk mengabaikannya.",
  str_homestory_chat_18323005 = "Pernyataan. Anda memerlukan latihan berpikir agar dapat mengajukan permintaan dengan lebih baik.",
  str_homestory_chat_18323006 = "Aku rasa tidak...",
  str_homestory_chat_18323007 = "Biar kupikirkan...",
  str_homestory_chat_18323008 = "Berlebihan. Anda harus memikirkan keinginan Anda dengan jelas dulu sehingga Lilliam dapat mengerjakannya dengan cepat.",
  str_homestory_chat_18323009 = "Ah... Baiklah. Akan kucoba.",
  str_homestory_chat_18324001 = "Apakah Anda ingin istirahat?",
  str_homestory_chat_18324002 = "Menerjemahkan dan mengonversi... Lilliam masih cukup termotivasi untuk menyelesaikan pekerjaan berikutnya.",
  str_homestory_chat_18324003 = "Guru, apakah ada pekerjaan baru?",
  str_homestory_chat_18324004 = "Tidak, tidak juga.",
  str_homestory_chat_18324005 = "Saya hanya melihat Anda membersihkan atau melakukan pekerjaan lain sepanjang waktu.",
  str_homestory_chat_18324006 = "Cloud Gardens dimaksudkan sebagai tempat untuk beristirahat. Anda bisa istirahat di sini.",
  str_homestory_chat_18324007 = "Tuan, apakah Anda memerintahkan saya untuk istirahat?",
  str_homestory_chat_18324008 = "Ya.",
  str_homestory_chat_18324009 = "Dipahami. Lilliam akan istirahat sekarang.",
  str_homestory_chat_18325001 = "Kudengar kau punya saudara perempuan?",
  str_homestory_chat_18325002 = "Apakah Anda mengacu pada No.2?",
  str_homestory_chat_18325003 = "Ya.",
  str_homestory_chat_18325004 = "Nomor 2 bukan adikku.",
  str_homestory_chat_18325005 = "Tidak.",
  str_homestory_chat_18325006 = "Siapa yang Anda maksud?",
  str_homestory_chat_18325007 = "Nah ... Lupakan saja, saya mengajukan pertanyaan yang salah.",
  str_homestory_chat_18325008 = "Saya hanya ingin bertanya apakah ada orang yang dekat dengan Anda, seperti teman baik.",
  str_homestory_chat_18325009 = "Kami dapat mengundang mereka ke sini sebagai tamu kami karena Anda selalu sendirian.",
  str_homestory_chat_18325010 = "Menerjemahkan dan mengonversi... Guru, apakah Anda menemukan pasangan untuk Lilliam?",
  str_homestory_chat_18325011 = "Er... Kau tahu apa Lilliam, teruskan saja seperti yang selalu kau lakukan.",
  str_homestory_chat_18325012 = "Siap, Master.",
  str_homestory_chat_18099999 = "Hai...",
  str_homestory_chat_18001001 = "Halo. Unimet.",
  str_homestory_chat_18001002 = "Kau baru saja menyapaku? Emm... Halo!",
  str_homestory_chat_18001003 = "Santai saja.",
  str_homestory_chat_18001004 = "Kau membuatku tegang.",
  str_homestory_chat_18001005 = "Maafkan aku!",
  str_homestory_chat_18021001 = "Kau senang mengobrol?",
  str_homestory_chat_18021002 = "Mengobrol? Oke, bisa, kok... Ayo, mengobrol.",
  str_homestory_chat_18021003 = "Kita harus mengobrolkan apa, ya? Bisakah kau cari topiknya?",
  str_homestory_chat_18021004 = "Ayolah...",
  str_homestory_chat_18021005 = "Malah jadi seperti tugas.",
  str_homestory_chat_18021006 = "Bisa jadi memang begitu... Buatku...",
  str_homestory_chat_18021007 = "Lain kali akan kutulis semua pokok bahasan utamanya... dan kusiapkan pidato!",
  str_homestory_chat_18022001 = "Katanya kau pandai mereparasi barang?",
  str_homestory_chat_18022002 = "Hmm... PlayerName, ada yang perlu kureparasi?",
  str_homestory_chat_18022003 = "Entahlah...",
  str_homestory_chat_18022004 = "Tidak? Oke, deh... Ya sudah, kalau begitu...",
  str_homestory_chat_18022005 = "Ya!",
  str_homestory_chat_18022006 = "Sungguh? Ah... Maaf... Suaraku tadi terlalu nyaring...",
  str_homestory_chat_18022007 = "Hmm... Aku ingin bilang... Kondisi Asistenku makin baik...",
  str_homestory_chat_18022008 = "Mintalah bantuan padaku, pasti kau tak akan menyesal!",
  str_homestory_chat_18022009 = "Baiklah. Akan kuingat itu.",
  str_homestory_chat_18999999 = "Hei. Kau tampak segar hari ini.",
  str_homestory_chat_18901001 = "Kau juga.",
  str_homestory_chat_18901002 = "Senang melihatmu segar-bugar seperti itu.",
  str_homestory_chat_18901003 = "Apakah aku juga tampak sangat bersemangat?",
  str_homestory_chat_18901004 = "Ya, sungguh.",
  str_homestory_chat_18921001 = "Kau suka di sini?",
  str_homestory_chat_18921002 = "Damai dan permai, ini tempat tinggal yang luar biasa.",
  str_homestory_chat_18921003 = "Biasanya aku tak suka membicarakan yang kusukai dan tak kusukai.",
  str_homestory_chat_18921004 = "Tapi, di sini aku bisa memberitahumu.",
  str_homestory_chat_18921005 = "Aku sangat suka tempat ini.",
  str_homestory_chat_18921006 = "Ini tempat tinggal yang ideal bagi semua Aurorian.",
  str_homestory_chat_18921007 = "Penilaian yang cukup tinggi!",
  str_homestory_chat_18922001 = "Kau sedang beristirahat?",
  str_homestory_chat_18922002 = "Ya, ternyata tempat rekreasiku yang sempurna ada di sini.",
  str_homestory_chat_18922003 = "Memancing.",
  str_homestory_chat_18922004 = "Duduk di pinggir sungai dengan damai di bawah sinar mentari yang hangat...",
  str_homestory_chat_18922005 = "Menanti ikan memakan umpannya...",
  str_homestory_chat_18922006 = "Aktivitas yang membuat pikiran tetap fokus dan tubuh beristirahat.",
  str_homestory_chat_18922007 = "Aku benar-benar menyukainya.",
  str_homestory_chat_18922008 = "Miss Irridon sangat senang memancing…",
  str_homestory_chat_18922009 = "Lain kali kau harus ikut denganku!",
  str_homestory_chat_18923001 = "Mau olahraga lari bersama?",
  str_homestory_chat_18923002 = "Kau mengajakku olahraga lari?",
  str_homestory_chat_18923003 = "Maaf... Aku bukan pelari yang baik...",
  str_homestory_chat_18923004 = "Kok bisa?",
  str_homestory_chat_18923005 = "Seperti yang kaulihat, kakiku... Walaupun tampak normal seperti orang lain...",
  str_homestory_chat_18923006 = "Kakiku tak kuat kalau berolahraga terlalu berat.",
  str_homestory_chat_18923007 = "Baiklah…",
  str_homestory_chat_18923008 = "Maaf, bukannya aku tak mau, tapi kakiku...",
  str_homestory_chat_18923009 = "Aku mengerti! Boleh kuundang kau untuk ikut serta dalam aktivitas bersantai lain waktu?",
  str_homestory_chat_18923010 = "Dengan senang hati!",
  str_homestory_chat_12799999 = "Halo, PlayerName. Ada perintah baru?",
  str_homestory_chat_12721001 = "Tidak.",
  str_homestory_chat_12721002 = "Hanya ingin menyapa.",
  str_homestory_chat_12721003 = "...",
  str_homestory_chat_12721004 = "... Ada masalah?",
  str_homestory_chat_12721005 = "Tidak. Tadi aku hanya memikirkan cara untuk menanggapi sapaanmu.",
  str_homestory_chat_12722001 = "Mau mengobrol?",
  str_homestory_chat_12722002 = "Dengan senang hati.",
  str_homestory_chat_12722003 = "Berbicara adalah cara komunikasi yang paling efektif.",
  str_homestory_chat_12722004 = "Aku setuju.",
  str_homestory_chat_12722005 = "Aku boleh sering-sering datang untuk mengobrol?",
  str_homestory_chat_12722006 = "Dengan senang hati.",
  str_homestory_chat_12722007 = "Aku tak yakin.",
  str_homestory_chat_12722008 = "Jika kau tadi mencoba untuk menyampaikan sesuatu lewat matamu...",
  str_homestory_chat_12722009 = "Kau akan tahu betapa jelasnya bahasa.",
  str_homestory_chat_12723001 = "Apa pendapatmu tentang tempat ini?",
  str_homestory_chat_12723002 = "Suasana di sini sangat menenangkan.",
  str_homestory_chat_12723003 = "Tapi, menurutku, perlu lebih banyak pengawas.",
  str_homestory_chat_12723004 = "Benar sekali!",
  str_homestory_chat_12723005 = "Untuk mencegah orang minum langsung dari sungai...",
  str_homestory_chat_12723006 = "Biar aku saja.",
  str_homestory_chat_12723007 = "Akan kupastikan setiap orang yang melanggar dikenai sanksi.",
