  str_homestory_chat_12723009 = "Sepertinya topik ini sudah usai.",
  str_homestory_chat_12723010 = "Aku siap melayanimu kapan pun kaubutuhkan.",
  str_homestory_chat_18699999 = "Aku sangat senang bertemu denganmu.",
  str_homestory_chat_18601001 = "Aku juga.",
  str_homestory_chat_18601002 = "Masih hidup dan sehat walafiat.",
  str_homestory_chat_18601003 = "Ah... Ada apa?",
  str_homestory_chat_18601004 = "Tenang saja. Tadi itu lelucon. Gaya leluconku.",
  str_homestory_chat_18621001 = "Kau sedang makan apa?",
  str_homestory_chat_18621002 = "Makanan penutup Miss Vice. Dia membuatnya cukup banyak akhir-akhir ini. PlayerName, sudah mencobanya?",
  str_homestory_chat_18621003 = "Ya...",
  str_homestory_chat_18621004 = "Kok mukamu begitu?",
  str_homestory_chat_18621005 = "Kau pasti akan paham kalau sudah mencobanya...",
  str_homestory_chat_18621006 = "Aku sudah mencobanya, kok...",
  str_homestory_chat_18621007 = "Ekspresi wajah \"petualangan berikutnya sudah tercapai\" lebih cocok, menurutku.",
  str_homestory_chat_18621008 = "Tidak...",
  str_homestory_chat_18621009 = "Kau melewatkan kesempatan bertualang sekali seumur hidup.",
