  str_homestory_chat_18622001 = "Mau berjalan-jalan?",
  str_homestory_chat_18622002 = "Ya, apa lagi di sini. Sangat menenangkan.",
  str_homestory_chat_18622003 = "Aku lebih suka keluar untuk menikmati alam daripada berjalan-jalan.",
  str_homestory_chat_18622004 = "Tak ada rumput lembut seperti ini di Lumopolis. Jarang sekali juga ada bunga-bunga kecil ini di rumah.",
  str_homestory_chat_18622005 = "Kapan-kapan aku akan mengajakmu berjalan-jalan bersama.",
  str_homestory_chat_18622006 = "Aku pasti menerima ajakanmu.",
  str_homestory_chat_18623001 = "Bagaimana kabarmu?",
  str_homestory_chat_18623002 = "Apakah kau mencoba makanan spesial yang rasanya aneh?",
  str_homestory_chat_18623003 = "Ya…",
  str_homestory_chat_18623004 = "Benar-benar parah waktu itu, sih.",
  str_homestory_chat_18623005 = "Hmm? Kukira kau bakal senang menerima tantangan semacam itu.",
  str_homestory_chat_18623006 = "... Sebentar... Kau menyuruh orang untuk membawakanku makanan aneh itu?",
  str_homestory_chat_18623007 = "Jangan menatapku seperti itu, dong...",
  str_homestory_chat_18623008 = "Makanan spesial itu... Aku sendiri sudah pernah memakannya langsung, kok.",
  str_homestory_chat_18623009 = "Tidak.",
  str_homestory_chat_18623010 = "Hmm? Aku mengirimkan...",
  str_homestory_chat_18623011 = "Apa?",
  str_homestory_chat_18623012 = "Ssst... Rahasia ini akan kusimpan sampai mati...",
  str_homestory_chat_17999999 = "Hai, PlayerName! Apa rencanamu hari ini?",
  str_homestory_chat_17921001 = "Ah... Tidak ada apa-apa.",
