  str_homestory_chat_17922001 = "Katanya kau punya saran.",
  str_homestory_chat_17922002 = "Ya, PlayerName. Kusarankan kau menghitung jumlah Nightium milikmu setiap hari.",
  str_homestory_chat_17922003 = "Kenapa?",
  str_homestory_chat_17922004 = "Kau harus tahu persis berapa yang kau miliki...",
  str_homestory_chat_17922005 = "Agar kau dapat benar-benar menghargainya.",
  str_homestory_chat_17922006 = "... Oh, begitu. Baru-baru ini aku menggunakannya terlalu banyak...",
