  str_homestory_chat_19199999 = "Halo…",
  str_homestory_chat_19101001 = "Hai, Chloe.",
  str_homestory_chat_19101002 = "Aku mengganggumu?",
  str_homestory_chat_19101003 = "Berkat kau, aku tidak jadi tenggelam dalam nestapa.",
  str_homestory_chat_19121001 = "Sedang apa kau?",
