  str_homestory_chat_19922006 = "Hewan-hewan kecil tidak mendatangimu?",
  str_homestory_chat_19922007 = "Tadinya, tapi tidak setelah duri-duri hitam ini tumbuh...",
  str_homestory_chat_19922008 = "Kadang, aku juga khawatir menyakiti mereka...",
  str_homestory_chat_19922009 = "Oh, begitu…",
  str_homestory_chat_19923001 = "Butuh bantuanku?",
  str_homestory_chat_19923002 = "PlayerName, bisakah kau membantuku memeriksa pakaianku?",
  str_homestory_chat_19923003 = "Ada apa?",
  str_homestory_chat_19923004 = "Aku takut duri hitamku merobeknya lagi.",
  str_homestory_chat_19923005 = "Tidak.",
  str_homestory_chat_19923006 = "Baguslah!",
  str_homestory_chat_19923007 = "Aku tidak perlu memesan pakaian baru lagi!",
  str_homestory_chat_19923008 = "Benar...",
  str_homestory_chat_19923009 = "Tapi ukurannya kecil. Kau hampir tidak bisa melihatnya.",
