  str_homestory_chat_19924003 = "Banyak orang di sini bisa bernyanyi dan memainkan alat musik.",
  str_homestory_chat_19924004 = "Aku ingin berteman dengan mereka...",
  str_homestory_chat_19924005 = "Gampang. Aku akan mengenalkanmu pada teman-temanku yang bermain musik. Bagaimana?",
  str_homestory_chat_19924006 = "Kau baik sekali, PlayerName! Terima kasih.",
  str_homestory_chat_20099999 = "Aku mendengar salammu, Bocah Polos.",
