  str_homestory_chat_20001002 = "Apa kau mau bilang sesuatu?",
  str_homestory_chat_20001003 = "Tidak sekarang.",
  str_homestory_chat_20021001 = "Apakah ada yang mengganggumu?",
  str_homestory_chat_20021002 = "Sebenarnya tidak. Aku hanya berharap tempat ini...",
  str_homestory_chat_20021003 = "Lebih tenang.",
  str_homestory_chat_20021004 = "Hanya ditemani suara angin dan serangga. Sore hari seharusnya terasa damai, bukan begitu?",
  str_homestory_chat_20022001 = "Kau ingin menemuiku?",
  str_homestory_chat_20022002 = "Hai Bocah Polos, bisakah kau mencarikanku lebih banyak buku-buku tua?",
