  str_homestory_chat_20022006 = "Aku tidak bisa menemukannya lagi...",
  str_homestory_chat_20022007 = "... Apakah aku harus mendengarkan orang-orang bodoh yang berisik itu?",
  str_homestory_chat_20022008 = "Baiklah. Coba nanti aku usahakan.",
  str_homestory_chat_20022009 = "Itu baru si bocah polos yang kukenal.",
  str_homestory_chat_20023001 = "Kerudungmu...",
  str_homestory_chat_20023002 = "Bocah polos, berhenti menatap kerudungku, bisa?",
  str_homestory_chat_20023003 = "Kenapa tidak menggantinya saja?",
  str_homestory_chat_20023004 = "Kerudung hitam ini terlihat merepotkan.",
  str_homestory_chat_20023005 = "Justru sebaliknya. Aku sangat menyukainya.",
  str_homestory_chat_20023006 = "Mereka membantu menjauhkan paramecia yang berisik itu dari duniaku.",
  str_homestory_chat_20023007 = "Tapi, aku rela membuka kerudungku untukmu.",
