  str_homestory_chat_20024002 = "Ya. Saya ingin tahu apakah ada tempat persembunyian.",
  str_homestory_chat_20024003 = "Ada.",
  str_homestory_chat_20024004 = "Seperti tepi sungai, lubang pohon, dan gua bawah tanah.",
  str_homestory_chat_20024005 = "Mereka tidak aman, meskipun. Seseorang akan menemukan mereka pada akhirnya.",
  str_homestory_chat_20024006 = "Tidak.",
  str_homestory_chat_20024007 = "Beberapa tempat lebih terpencil daripada yang lain, tetapi keluarga Chubb mungkin telah menemukan semuanya.",
  str_homestory_chat_20024008 = "Aku tahu.",
  str_homestory_chat_20024009 = "Mengapa Anda mencari satu? Apakah Anda ingin menyembunyikan sesuatu?",
  str_homestory_chat_20024010 = "Ya, untuk menyembunyikan Faria. Aku tidak ingin kehilangannya lagi.",
