  str_homestory_chat_20025001 = "Sesuatu di pikiran Anda?",
  str_homestory_chat_20025002 = "Saya merenungkan tujuan Anda.",
  str_homestory_chat_20025003 = "Tujuan?",
  str_homestory_chat_20025004 = "Anda tidak akan berada di sini selama sisa hidup Anda. Anda harus pindah pada akhirnya.",
  str_homestory_chat_20025005 = "Saya belum berpikir sejauh itu.",
  str_homestory_chat_20025006 = "Anda mungkin harus kadang-kadang. Lagipula ini hanya perhentian.",
  str_homestory_chat_20025007 = "Saya bisa merasakan Anda memiliki masa depan yang panjang penuh dengan kemungkinan di depan.",
