  str_homestory_chat_20025009 = "Ya. Dan ketika saatnya tiba, aku bisa menjaga tempat ini untukmu.",
  str_homestory_chat_20025010 = "Sama seperti bagaimana aku menjaga Crypt sebelumnya.",
  str_homestory_chat_20025011 = "Benar... Terima kasih.",
  str_homestory_chat_18799999 = "Tidak perlu menyapaku. Katakan apa yang kau mau.",
  str_homestory_chat_18701001 = "Ah... baiklah...",
  str_homestory_chat_18701002 = "Menyapa hanya buang-buang waktu saja.",
  str_homestory_chat_18701003 = "Hmm... Aku bilang apa tadi?",
