  str_homestory_chat_18721003 = "Tidak...",
  str_homestory_chat_18721004 = "Sayangnya, opera tradisional sering dianggap kuno.",
  str_homestory_chat_18721005 = "Sepertinya kita tidak punya banyak kepentingan di sini.",
