  str_homestory_chat_18721008 = "Kau selalu membuatku kagum.",
  str_homestory_chat_18721009 = "Menyiapkan adegan dan mencari aktor profesional membutuhkan biaya yang tidak sedikit.",
  str_homestory_chat_18721010 = "Dan sepertinya kita tidak punya banyak penonton di sini.",
