  str_homestory_chat_18723006 = "Walaupun semua orang di sini setara...",
  str_homestory_chat_18723007 = "Kekuatanku tetaplah jadi bagian dari identitasku.",
  str_homestory_chat_15699999 = "Bagaimana kabarmu hari ini, Nak?",
  str_homestory_chat_15601001 = "Cukup bagus!",
  str_homestory_chat_15601002 = "Mengharukan.",
  str_homestory_chat_15621001 = "Apa yang kau pikirkan?",
  str_homestory_chat_15621002 = "Malam seperti ini cocok untuk meditasi.",
  str_homestory_chat_15621003 = "Kau mau mencobanya?",
