  str_homestory_chat_15621005 = "Aku akan memilih tempat yang tenang untukmu.",
  str_homestory_chat_15621006 = "Jangan lupa dengan janji kita.",
  str_homestory_chat_15621007 = "Tidak, ah...",
  str_homestory_chat_15621008 = "Kau takut?",
  str_homestory_chat_15621009 = "Jangan khawatir. Tidak ada yang bisa melukaimu di sini.",
  str_homestory_chat_15622001 = "Bagaimana kabarmu di sini?",
  str_homestory_chat_15622002 = "Yang mengejutkanku, aku lebih menyukai tempat ini daripada Northland...",
  str_homestory_chat_15622003 = "Aku tidak percaya aku betah berada di sini.",
