  str_homestory_chat_19521004 = "Apa Anda ingin melihatnya?",
  str_homestory_chat_19521005 = "Tentu!",
  str_homestory_chat_19521006 = "Tapi aku masih ada hal lain yang harus dilakukan...",
  str_homestory_chat_19521007 = "Silakan saja, Pak.",
  str_homestory_chat_19521008 = "Kita bisa pergi saat Anda luang.",
