  str_homestory_chat_16221003 = "Aku sudah berteman dengan banyak orang sejak aku datang.",
  str_homestory_chat_16221004 = "Senang mengetahuinya.",
  str_homestory_chat_16221005 = "Tidak penting di mana kita tinggal selama kita dikelilingi teman-teman yang jujur.",
