  str_homestory_chat_16223003 = "Keuntungan?",
  str_homestory_chat_16223004 = "Itu terpencil, aman, dengan iklim yang menyenangkan dan banyak air dan rumput.",
  str_homestory_chat_16223005 = "Jika ada tempat seperti itu di Northland... itu akan bagus sekali.",
  str_homestory_chat_16223006 = "Bukankah tempatmu dulu berjaga, Windward Forest, begitu saja?",
