  str_homestory_chat_16224002 = "Ya. May Saya bertanya, apakah Anda mengerti air, Navigator?",
  str_homestory_chat_16224003 = "Saya mengerti air.",
  str_homestory_chat_16224004 = "Lalu bagaimana dengan gelembungnya Leah dibuat? Apakah Anda tahu apa artinya?",
