  str_homestory_chat_16224006 = "Aku tidak paham.",
  str_homestory_chat_16224007 = "Ah... Jadi jika saya ingin tahu tentang gelembung Leah, saya harus bertanya kepada orang lain.",
  str_homestory_chat_16224008 = "Tapi mengapa Anda tiba-tiba ingin tahu tentang gelembung itu?",
  str_homestory_chat_16224009 = "Saya merasa sangat menarik, seperti embun di hutan setelah terkena sinar matahari.",
  str_homestory_chat_16224010 = "Benar.",
