  str_homestory_chat_22124004 = "Ngomong-ngomong, menurutmu tanaman apa duri itu?",
  str_homestory_chat_22124005 = "Tumbuhan biasa.",
  str_homestory_chat_22124006 = "Tanaman khusus.",
  str_homestory_chat_22124007 = "Sebenarnya, duri adalah sejenis lingkungan.",
  str_homestory_chat_22124008 = "Lingkungan?",
  str_homestory_chat_22124009 = "Banyak tanaman memiliki duri. Saat mereka berkelompok, mereka menjadi duri.",
  str_homestory_chat_22124010 = "Saya kira tidak demikian. Saya yakin duri adalah jenis mereka sendiri, yang memiliki tanaman berduri...",
  str_homestory_chat_22124011 = "Ini adalah istilah universal! Kelimpahan tanaman berduri bisa disebut duri.",
  str_homestory_chat_22124012 = "Terutama ketika mereka ditumbuhi dan dibanjiri segalanya, maka Anda memiliki situasi pelik yang terkenal.",
  str_homestory_chat_22124013 = "aku lihat! Saya pikir saya mengerti sekarang.",
  str_homestory_chat_22125001 = "Anda bertanya tentang Chubbs?",
  str_homestory_chat_22125002 = "Ya. Bagaimana Anda melihat mereka?",
  str_homestory_chat_22125003 = "Penduduk asli lokasi ini.",
  str_homestory_chat_22125004 = "Makhluk unik.",
  str_homestory_chat_22125005 = "Cerdas, mungkin...?",
  str_homestory_chat_22125006 = "Tunggu, apa hubungannya dengan keinginanmu untuk mengetahui tentang Chubbs?",
  str_homestory_chat_22125007 = "Dan bagaimana Anda melihat mereka, Paloma?",
  str_homestory_chat_22125008 = "Mereka benar-benar makhluk yang sangat baik, bahkan mungkin yang terbaik.",
  str_homestory_chat_22125009 = "Mengapa, karena penampilan mereka? Saya mendengar bentuk persegi mereka memiliki daya tarik yang besar.",
  str_homestory_chat_22125010 = "Itu salah satu faktornya, tapi alasan utamanya adalah seberapa jujurnya mereka.",
  str_homestory_chat_22125011 = "Jujur?",
  str_homestory_chat_22125012 = "Mereka tidak pernah berbohong kepada Anda. Apa pun yang Anda inginkan, Anda bisa berdagang dengan mereka untuk itu.",
  str_homestory_chat_22125013 = "Mereka tidak mencungkil harga, mengubah pikiran mereka dengan uang sepeser pun, atau mengingkari nanti.",
  str_homestory_chat_22125014 = "Dan mereka memiliki kesabaran untuk mendengarkan Anda berbicara tentang apa pun.",
  str_homestory_chat_22125015 = "Uh, jadi, apa kau melakukan sesuatu pada keluarga Chubb akhir-akhir ini...?",
  str_homestory_chat_22126001 = "Sedang apa kau?",
  str_homestory_chat_22126002 = "Mengamati cuaca, yang sangat penting.",
  str_homestory_chat_22126003 = "Tapi matamu tertutup.",
  str_homestory_chat_22126004 = "Mataku tertutup?",
  str_homestory_chat_22126005 = "Yeah, untuk waktu yang lama juga... Kau yakin mengikuti cuaca?",
  str_homestory_chat_22126006 = "Terkadang penting untuk bermeditasi.",
  str_homestory_chat_22126007 = "Saya pikir Anda hanya mengambil cuti ...",
  str_homestory_chat_22126008 = "Mengapa, saya tidak pernah!",
  str_homestory_chat_22126009 = "Perenungan yang diperlukan sangat penting, terutama dalam pekerjaan sehari-hari.",
  str_homestory_chat_22126010 = "Seperti roda gigi pada mesin, Anda harus berhenti mengaduk setelah beberapa saat.",
  str_homestory_chat_22126011 = "Cukup yakin itu disebut mengambil cuti.",
  str_homestory_chat_22127001 = "Hari ini cukup menyenangkan.",
  str_homestory_chat_22127002 = "Memang. Tetapi mengapa Anda mengatakan itu ketika seperti ini setiap hari?",
  str_homestory_chat_22127003 = "Coba saja buat percakapan.",
  str_homestory_chat_22127004 = "Karena ini memang hari yang menyenangkan.",
  str_homestory_chat_22127005 = "Oh, akhir-akhir ini kau payah dengan kalimat pembukamu.",
  str_homestory_chat_22127006 = "Meskipun Anda memiliki begitu banyak orang, Anda dapat berlatih.",
  str_homestory_chat_22127007 = "Teman bukan untuk latihan...",
  str_homestory_chat_22127008 = "Kamu salah.",
  str_homestory_chat_22127009 = "Oh?",
  str_homestory_chat_22127010 = "Jika mereka ingin berada di dekat Anda dan bersedia datang ke Cloud Gardens, itu artinya mereka ingin menjadi teman Anda.",
  str_homestory_chat_22127011 = "Misalnya, obrolan santai, menceritakan kisah-kisah absurd, atau bahkan...",
  str_homestory_chat_22127012 = "Emm, ide unik tertentu.",
  str_homestory_chat_22127013 = "Jadi mereka menerima Anda untuk mencoba kalimat pembuka, tidak peduli seberapa canggungnya.",
  str_homestory_chat_22127014 = "Ambil contoh \"Hari yang menyenangkan\", misalnya... Bagaimana jika ini bukan hari yang menyenangkan?",
  str_homestory_chat_22127015 = "Ubah ke \"Hari yang buruk\"?",
  str_homestory_chat_22127016 = "Ini dia, Anda akhirnya mendapatkannya sekarang!",
  str_homestory_chat_22127017 = "Hah? Itu saja, benarkah?",
  str_homestory_chat_22128001 = "Eclipsite?",
  str_homestory_chat_22128002 = "Saya merasa ada kebutuhan untuk mendiskusikannya.",
  str_homestory_chat_22128003 = "Apakah Anda khawatir tentang keamanan di sini? Jangan khawatir, itu terlalu terpencil bagi mereka untuk sampai ke sana.",
  str_homestory_chat_22128004 = "Tidak, bukan pertanyaan seperti itu. Pernahkah Anda bertanya-tanya mengapa mereka menyerang kita?",
  str_homestory_chat_22128005 = "Ya.",
  str_homestory_chat_22128006 = "Oh? Kenapa?",
  str_homestory_chat_22128007 = "Mungkin itu naluri mereka.",
  str_homestory_chat_22128008 = "Insting, eh...",
  str_homestory_chat_22128009 = "Tidak.",
  str_homestory_chat_22128010 = "Mungkin... itu naluri mereka?",
  str_homestory_chat_22128011 = "Mungkin.",
  str_homestory_chat_21599999 = "Salam, PlayerName!",
  str_homestory_chat_21501001 = "Halo, Naroxel.",
  str_homestory_chat_21501002 = "Semoga alam memberkati! Nikmatilah harimu.",
  str_homestory_chat_21501003 = "Ah! Terima kasih atas berkatnya.",
  str_homestory_chat_21501004 = "Hanya itu yang bisa kulakukan.",
  str_homestory_chat_21521001 = "Ternyata kau sangat mengenal tempat ini.",
  str_homestory_chat_21521002 = "Iya, aku tahu segala sesuatu yang ada di sini.",
  str_homestory_chat_21521003 = "Kalau kau butuh mengangkut barang di wilayah ini cari saja aku.",
