  str_homestory_chat_21521005 = "Aku juga bisa mengirim surat untuk Aurorian di sini.",
  str_homestory_chat_21521006 = "Terima kasih!",
  str_homestory_chat_21521007 = "Aku tak mau merepotkanmu...",
  str_homestory_chat_21521008 = "Aku belum sempat berterima kasih karena boleh datang ke sini.",
  str_homestory_chat_21521009 = "Melakukan tugas kecil semacam ini adalah caraku menunjukkan rasa terima kasih.",
  str_homestory_chat_21522001 = "Sungguh hari yang indah!",
  str_homestory_chat_21522002 = "Cuaca hangat yang nyaman di sini membuat hatiku segar dan senang.",
  str_homestory_chat_21522003 = "Suhunya kadang kala turun sedikit, tapi tak pernah sampai dingin sekali.",
