  str_homestory_chat_21522006 = "Kau lebih suka tempat yang hangat?",
  str_homestory_chat_21522007 = "Bagiku, tak ada yang namanya cuaca sempurna. Segalanya bagian dari alam.",
  str_homestory_chat_21522008 = "Tapi, aku tak bisa terlalu lama di tempat dingin.",
