  str_homestory_chat_21523002 = "... Aku?",
  str_homestory_chat_21523003 = "Ya.",
  str_homestory_chat_21523004 = "Aku agak jarang melihatmu...",
  str_homestory_chat_21523005 = "Hmm... Sepertinya aku menghabiskan banyak waktu berjalan di hutan.",
  str_homestory_chat_21523006 = "Ikut saja denganku kalau kau mau sedikit bersantai.",
  str_homestory_chat_16599999 = "Halo, Navigator!",
  str_homestory_chat_16501001 = "Hei, Tweety.",
  str_homestory_chat_16501002 = "Apa ada surat yang bisa kuantarkan hari ini?",
  str_homestory_chat_16501003 = "Hari ini tidak ada. Terima kasih sudah bertanya.",
