  str_homestory_chat_25521006 = "Karena itulah, pedang ini adalah senjata pilihanku.",
  str_homestory_chat_25521007 = "Pistol.",
  str_homestory_chat_25521008 = "Hmm... Bagi seorang Caelestite?",
