  str_homestory_chat_25523011 = "Akhir terbaik bagi seorang prajurit.",
  str_homestory_chat_25523012 = "Tapi, kau ini seorang jenderal...",
  str_homestory_chat_25699999 = "Hai, PlayerName, senang bertemu lagi denganmu.",
  str_homestory_chat_25601001 = "Hai, Nina.",
  str_homestory_chat_25601002 = "Setiap kali ke sini, aku ingin mengajukan pertanyaan kepadamu.",
  str_homestory_chat_25601003 = "Pertanyaan?",
  str_homestory_chat_25601004 = "Apa semua Caelestite memang seleranya hambar begini?",
  str_homestory_chat_25601005 = "Hmm… Kurasa begitu.",
  str_homestory_chat_25601006 = "Tapi, ternyata hasilnya malah cocok dengan lingkungan sekitarnya, dan tempat ini juga nyaman untuk dihuni.",
