  str_homestory_chat_25601008 = "Terima kasih.",
  str_homestory_chat_25621001 = "Kau selalu bawa payung...",
  str_homestory_chat_25621002 = "Caelestite, maksudmu payung yang mana?",
  str_homestory_chat_25621003 = "Aku selalu merasa kau berusaha menghindari sesuatu.",
  str_homestory_chat_25621004 = "Ini payung besar.",
  str_homestory_chat_25621005 = "Aku senang karena ajaranku belakangan ini berhasil.",
