  str_homestory_chat_25621007 = "Apa sih yang kaugumamkan?",
  str_homestory_chat_25621008 = "Ah, bukan apa-apa, dah.",
  str_homestory_chat_25621009 = "Ini hanya payung.",
  str_homestory_chat_25621010 = "Sudah kubilang berkali-kali! Ini \"payung besar\", bukan sekadar \"payung\"!",
  str_homestory_chat_25621011 = "Hahh... Aku mulai muak mengulangi ini setiap saat.",
  str_homestory_chat_25621012 = "Aku, aku akan ingat.",
  str_homestory_chat_25621013 = "Jangan sampai lupa apa yang baru saja kita bicarakan.",
  str_homestory_chat_25622001 = "Sudah punya rencana untuk nanti?",
  str_homestory_chat_25622002 = "Aku ingin minum teh sore nanti, tapi aku tak tahu apa di sini ada teh.",
  str_homestory_chat_25622003 = "Aku ingat pernah beli teh dari Umbraton dan kusimpan di toko...",
  str_homestory_chat_25622004 = "Jadi, apa ada tempat untuk minum teh saat sore?",
  str_homestory_chat_25622005 = "Kau butuh tempat?",
  str_homestory_chat_25622006 = "Minum teh sore lebih dari sekadar minum teh. Intinya adalah menikmati suasana.",
  str_homestory_chat_25622007 = "Lokasi adalah faktor sangat penting. Tempatnya harus tenang, nyaman, dan dihiasi suara dari alam.",
  str_homestory_chat_25622008 = "Suara alam?",
  str_homestory_chat_25622009 = "Misalnya suara serangga atau burung-burung terbang yang sesekali berbunyi, dan suara gemeresak daun.",
  str_homestory_chat_25622010 = "Coba kucarikan tempat seperti itu.",
  str_homestory_chat_25623001 = "Kalian sedang mencari apa?",
  str_homestory_chat_25623002 = "Apa kau punya novel yang bagus?",
  str_homestory_chat_25623003 = "Kau suka novel yang seperti apa?",
  str_homestory_chat_25623004 = "Apa kau punya novel yang seram?",
