  str_homestory_chat_25721009 = "Kau bekerja terlalu keras.",
  str_homestory_chat_25721010 = "Hah? Terlalu keras?",
  str_homestory_chat_25721011 = "Kalau bersih-bersih pagi-pagi sekali, orang-orang lain mungkin saja jadi terbangun karenanya.",
  str_homestory_chat_25721012 = "Yah, akan kuperhatikan itu.",
  str_homestory_chat_25722001 = "Bagaimana keadaan akhir-akhir ini?",
  str_homestory_chat_25722002 = "Huaaa, Tuan Navigator!",
  str_homestory_chat_25722003 = "Aku menemukan sesuatu yang enak kemarin, dan kurasa itu buatan sini!",
  str_homestory_chat_25722004 = "Ada apa?",
  str_homestory_chat_25722005 = "Ada banyak ikan kecil di sungai, dan mereka sulit ditangkap.",
  str_homestory_chat_25722006 = "Ya, ikan-ikan itu memang kecil dan gesit, agak sulit ditangkap.",
  str_homestory_chat_25722007 = "Jadi, aku membuat jala, lalu menjaring mereka, dan mencucinya...",
  str_homestory_chat_25722008 = "Lalu, kutumbuk mereka, kucampuri garam, dan kujadikan bahan untuk membuat sandwich. Rasanya sangat segar dan empuk!",
  str_homestory_chat_25722009 = "Kau memakannya mentah-mentah?",
  str_homestory_chat_25722010 = "Kau harus memasaknya dengan benar lain kali. Kalau tidak, kau bisa sakit...",
  str_homestory_chat_25722011 = "Oh, tak mungkin! Aku akan membuatkannya untukmu lain kali.",
