  str_homestory_chat_25723001 = "Sanae, anu...",
  str_homestory_chat_25723002 = "Huaaa, apa aku berbuat salah lagi?",
  str_homestory_chat_25723003 = "Kudengar...",
  str_homestory_chat_25723004 = "Kau tak sengaja menarik daun pintu sampai lepas saat kau bersih-bersih kemarin.",
