  str_homestory_chat_25723006 = "M-Maaf! Aku sulit mengendalikan diri...",
  str_homestory_chat_25723007 = "Pintunya sudah kuperbaiki!",
  str_homestory_chat_25723008 = "Yah, sebenarnya itu bukan salahmu. Pintunya memang sudah lama bermasalah, kok.",
  str_homestory_chat_25723009 = "Ahhh, Tuan Navigator! Biar kutangani itu!",
  str_homestory_chat_25723010 = "Hmmm... Tidak ada yang salah dengan pesta...",
  str_homestory_chat_25723011 = "Ini, ini tentang pintu itu, 'kan?",
