  str_homestory_chat_26401008 = "Anda harus bersantai saat berada di sini.",
  str_homestory_chat_26402001 = "Apakah Anda bebas sekarang?",
  str_homestory_chat_26402002 = "Ya, karena Cloud Gardens adalah tempat yang sangat santai.",
