  str_homestory_chat_26402007 = "BENAR. Bagaimana kalau jalan-jalan di tepi sungai?",
  str_homestory_chat_26402008 = "Sebenarnya bukan olahraga yang berat, tapi bagus untuk tubuh jika dilakukan dalam waktu lama.",
