  str_homestory_chat_26803002 = "Aku melatih pandangan dan kelincahanku.",
  str_homestory_chat_26803003 = "Kenapa?",
  str_homestory_chat_26803004 = "Sulit sekali memancing ikan di sungai.",
  str_homestory_chat_26803005 = "Selain berenangnya cepat, aku tak tahu apa yang ada di bawah air. Tapi juga...",
  str_homestory_chat_26803006 = "Ikannya tak berada di titik yang kita lihat dari atas.",
  str_homestory_chat_26803007 = "Benar, sepertinya efek pembiasan cahaya.",
  str_homestory_chat_26803008 = "Tunggu, katamu kau tumbuh besar di laut. Seharusnya kau sangat ahli memancing ikan.",
  str_homestory_chat_26803009 = "Ya, tapi biasanya aku menyelam untuk menangkap ikan, jadi tak ada pembiasan.",
  str_homestory_chat_26803010 = "Ikan di laut juga berenang berkelompok, jadi mudah kutangkap.",
  str_homestory_chat_26803011 = "Oh begitu. Kalau begitu, kau hanya perlu berlatih.",
  str_homestory_chat_26804001 = "Kau ingin menemuiku?",
  str_homestory_chat_26804002 = "Kau benar. Bisa tolong carikan kayu untukku?",
  str_homestory_chat_26804003 = "Apa yang kau rencanakan?",
  str_homestory_chat_26804004 = "Aku mau membuat kapal.",
  str_homestory_chat_26804005 = "Kapal? Di mana?",
  str_homestory_chat_26804006 = "Di sungai! Untuk melindungi Cloud Gardens.",
  str_homestory_chat_26804007 = "Karena sungainya tak seberapa lebar, kapal itu akan memenuhi sungai.",
  str_homestory_chat_26804008 = "Mungkin aku hanya akan membuat kapal kecil... atau kecil sekali.",
  str_homestory_chat_26804009 = "Membuat beberapa kapal kecil untuk patroli...",
  str_homestory_chat_26804010 = "Siapa yang akan mengemudikannya?",
  str_homestory_chat_26804011 = "Pertanyaan bagus! Chubbs?",
  str_homestory_chat_26804012 = "Mereka pendek, jadi kabinnya bisa lebih kecil lagi.",
  str_homestory_chat_26804013 = "Bagaimana kalau mereka bertemu musuh?",
  str_homestory_chat_26804014 = "Pertanyaan bagus lagi. Katapel? Batu?",
  str_homestory_chat_26804015 = "Semoga saja mereka tak akan bertemu musuh.",
  str_homestory_chat_27099999 = "Bagaimana kabarmu akhir-akhir ini, PlayerName?",
  str_homestory_chat_27001001 = "Tidak buruk. Anda?",
  str_homestory_chat_27001002 = "Agak kecewa, jujur saja.",
  str_homestory_chat_27001003 = "Kecewa?",
  str_homestory_chat_27001004 = "Sebagian besar karena hujan tidak cukup! Dan hanya gerimis!",
  str_homestory_chat_27001005 = "Anda suka menonton hujan, saya mengerti ...",
  str_homestory_chat_27021001 = "Kudengar kau mencariku?",
  str_homestory_chat_27021002 = "Betul sekali. Saya ingin membangun taman bermain yang besar.",
  str_homestory_chat_27021003 = "Dengan perosotan, komidi putar, jungkat-jungkit, dan lainnya untuk dimainkan anak-anak sepanjang hari.",
  str_homestory_chat_27021004 = "Kenapa tiba-tiba ide?",
  str_homestory_chat_27021005 = "Karena tidak hanya untuk anak-anak, banyak orang dewasa juga menyukainya.",
  str_homestory_chat_27021006 = "Terutama beberapa teman Anda yang berjiwa muda.",
  str_homestory_chat_27021007 = "Cara Anda mengatakannya masuk akal... Biarkan saya memikirkannya.",
  str_homestory_chat_27022001 = "Apa yang Anda ingin tahu?",
  str_homestory_chat_27022002 = "Apakah ada pandai besi yang akrab dengan senjata di sekitar sini?",
  str_homestory_chat_27022003 = "Tidak.",
  str_homestory_chat_27022004 = "Ya.",
  str_homestory_chat_27022005 = "Tapi aku harus mencari satu.",
  str_homestory_chat_27022006 = "Apakah pistol Anda rusak?",
  str_homestory_chat_27022007 = "Perlu kalibrasi ulang. Seperti manusia, senjata terkadang \"sakit\".",
  str_homestory_chat_27022008 = "Inilah saatnya seorang pandai besi dibutuhkan. Mereka adalah dokter untuk senjata.",
  str_homestory_chat_27022009 = "Mengapa tidak memeriksa Umbraton?",
  str_homestory_chat_27022010 = "Itu terlalu jauh, dan akan menyenangkan bagi Cloud Gardens untuk memiliki tukang senjata yang tinggal di sana.",
  str_homestory_chat_27022011 = "Saya yakin banyak teman Anda akan membutuhkannya juga. Jadi, bagaimana kalau menyewa pandai besi?",
  str_homestory_chat_27022012 = "Saya dapat merekomendasikan satu untuk Anda, yang tidak mahal sama sekali.",
  str_homestory_chat_27022013 = "Apa yang kamu dapatkan sekarang...?",
  str_homestory_chat_27023001 = "Lihat-lihat apa kau?",
  str_homestory_chat_27023002 = "Semuanya bagus di Cloud Gardens, kecuali agak jauh.",
  str_homestory_chat_27023003 = "Itu membuat sulit untuk mengikuti tren di Umbraton.",
  str_homestory_chat_27023004 = "Apakah Anda pernah ke Umbraton akhir-akhir ini? Ada pendatang baru di toko fashion?",
  str_homestory_chat_27023005 = "Tentu.",
  str_homestory_chat_27023006 = "Gaya baru apa yang mereka miliki sekarang? Apa yang sedang tren?",
  str_homestory_chat_27023007 = "Eh, aku tidak memperhatikan itu...",
  str_homestory_chat_27023008 = "Tidak.",
  str_homestory_chat_27023009 = "Argh, aku tahu aku tidak bisa mengandalkanmu.",
  str_homestory_chat_27023010 = "Anda harus menghasilkan lebih banyak uang dan memberi tahu Chubbs untuk membuka toko pakaian di sini.",
  str_homestory_chat_27023011 = "Atau setidaknya biarkan kurir mengantarkan beberapa majalah mode...",
  str_homestory_chat_27024001 = "Sedang apa kau?",
  str_homestory_chat_27024002 = "Bukan apa-apa. Sudah lama aku tidak merasa begitu santai.",
  str_homestory_chat_27024003 = "Ini memang tempat yang damai, dan itu bisa menakutkan.",
  str_homestory_chat_27024004 = "Mengapa demikian?",
  str_homestory_chat_27024005 = "Kedamaian akan membuat Anda terlena. Anda perlu waspada sesekali.",
  str_homestory_chat_27024006 = "Ini sangat aman di sini. Juga tidak baik untuk selalu terikat erat-erat.",
  str_homestory_chat_27024007 = "Oke... begitu.",
  str_homestory_chat_27024008 = "Tidak.",
  str_homestory_chat_27024009 = "Damai itu bagus. Anda tidak bisa berkelahi dan membunuh hari demi hari.",
  str_homestory_chat_27024010 = "Tapi kamu harus siap menghadapi bahaya...",
  str_homestory_chat_27199999 = "Ada apa?",
  str_homestory_chat_27101001 = "Bukan apa-apa.",
  str_homestory_chat_27101002 = "Oke, sampai jumpa.",
  str_homestory_chat_27101003 = "Eh, Casta...",
  str_homestory_chat_27101004 = "Ya?",
  str_homestory_chat_27101005 = "Yah, tidak cocok bagiku untuk terus mengakhiri percakapan kita seperti ini.",
  str_homestory_chat_27101006 = "Apakah kami sedang mengobrol?",
  str_homestory_chat_27101007 = "Punya poin di sana. Nah, berbicara dengan Anda nanti.",
  str_homestory_chat_27121001 = "Ada rencana akhir-akhir ini?",
  str_homestory_chat_27121002 = "Saya mencari titik pandang yang tinggi, seperti pohon atau bangunan yang tinggi. Punya semua itu?",
  str_homestory_chat_27121003 = "Ya.",
  str_homestory_chat_27121004 = "Bagaimana dengan Asrama Gardens?",
  str_homestory_chat_27121005 = "Tidak, itu terlalu rendah... Tapi Menara Hyacinth akan baik-baik saja.",
  str_homestory_chat_27121006 = "Jangan berpikir begitu.",
  str_homestory_chat_27121007 = "Betulkah? Tapi saya pikir Menara Hyacinth akan baik-baik saja.",
  str_homestory_chat_27121008 = "Keluarga Chubb mungkin tidak memberiku akses.",
  str_homestory_chat_27121009 = "Mengapa Anda ingin melakukan itu?",
  str_homestory_chat_27121010 = "Ubah dataran tinggi menjadi menara pengawas yang berfungsi ganda sebagai sarang penembak jitu.",
  str_homestory_chat_27121011 = "Itu adalah posisi bertahan paling dasar.",
  str_homestory_chat_27121012 = "Uh, kurasa itu tidak perlu di sini...",
  str_homestory_chat_27122001 = "Aku dengar kamu suka kopi.",
  str_homestory_chat_27122002 = "Ya, terutama hitam lurus, tanpa gula atau krimer. Anda?",
  str_homestory_chat_27122003 = "Aku juga menyukainya.",
  str_homestory_chat_27122004 = "Anda kecanduan rasanya juga, begitu.",
  str_homestory_chat_27122005 = "Terutama ketika itu membuat Anda memikirkan banyak hal lain ...",
  str_homestory_chat_27122006 = "Uh... Itu salah satu kesukaanku, itu saja.",
  str_homestory_chat_27122007 = "Itu terlalu buruk. Semoga Anda bisa segera memperluas wawasan Anda.",
  str_homestory_chat_27122008 = "Saya tidak menyukainya.",
  str_homestory_chat_27122009 = "Terlalu pahit jika Anda tidak menambahkan apa pun.",
  str_homestory_chat_27122010 = "Itu pendapat umum, jadi saya kira saya minoritas.",
  str_homestory_chat_27122011 = "Tidak apa-apa, hanya opini.",
  str_homestory_chat_27123001 = "Anda tampaknya terganggu.",
  str_homestory_chat_27123002 = "Saya telah diberitahu bahwa saya seorang penembak lurus dan itu membuat orang tidak nyaman. Benarkah itu?",
  str_homestory_chat_27123003 = "Tidak.",
  str_homestory_chat_27123004 = "Oke, aku merasa lebih baik sekarang.",
  str_homestory_chat_27123005 = "Ya, agak.",
  str_homestory_chat_27123006 = "Tapi menurutku itu keren.",
  str_homestory_chat_27123007 = "Begitulah Anda, dan sebagian besar dari siapa Anda sekarang.",
  str_homestory_chat_27123008 = "Jadi, tetaplah menjadi kamu.",
  str_homestory_chat_23099999 = "Ada kasus hari ini?",
  str_homestory_chat_23001001 = "Anu…",
  str_homestory_chat_23001002 = "Saya menganggapnya sebagai \"ya.\" Saya akan memulai prosesnya kalau begitu.",
  str_homestory_chat_23001003 = "Pertama, kita punya hakim—itu aku, tentu saja—lalu kita perlu juru sita untuk menjaga pengadilan...",
  str_homestory_chat_23001004 = "Tunggu, aku tidak pernah bilang kita punya kasus. Aku hanya memikirkan jawabanku.",
  str_homestory_chat_23001005 = "Argh, betapa membosankannya.",
  str_homestory_chat_23021001 = "Apa yang kamu lakukan akhir-akhir ini?",
  str_homestory_chat_23021002 = "Aku butuh bantuan darimu. Bisakah saya meminjam beberapa Chubbs?",
  str_homestory_chat_23021003 = "Untuk apa Anda membutuhkan mereka?",
  str_homestory_chat_23021004 = "Mereka adalah bentuk yang sempurna untuk komponen.",
  str_homestory_chat_23021005 = "Sepertinya kamu ingin melakukan sesuatu pada mereka... Tolong jangan sakiti mereka.",
  str_homestory_chat_23021006 = "saya tidak bisa? Tapi saya ingin membuat patung dari mereka...",
  str_homestory_chat_23021007 = "Kemudian kita semua bisa menghargai mereka sebagai patung berjalan.",
  str_homestory_chat_23021008 = "Biarkan saya ulangi, tolong jangan sakiti mereka!",
  str_homestory_chat_23021009 = "Apakah Anda kesal? Oke oke.",
  str_homestory_chat_23022001 = "Butuh bantuanku?",
  str_homestory_chat_23022002 = "Ya. Apakah Anda bebas pergi ke Umbraton dan membelikan saya majalah?",
  str_homestory_chat_23022003 = "Tidak.",
  str_homestory_chat_23022004 = "Kamu yakin? Anda tidak terlihat sibuk sama sekali dan hanya nongkrong sepanjang hari setiap hari ...",
  str_homestory_chat_23022005 = "Bantulah saya dan perlakukan itu sebagai kunjungan lapangan.",
  str_homestory_chat_23022006 = "Banyak yang harus saya lakukan di sini, belum lagi Umbraton cukup jauh.",
  str_homestory_chat_23022007 = "Baiklah, kau babi pemalas...",
  str_homestory_chat_23022008 = "Jenis majalah apa?",
  str_homestory_chat_23022009 = "Jenis dengan sampul premium, konten, dan kualitas cetak...",
  str_homestory_chat_23022010 = "Kedengarannya menarik.",
  str_homestory_chat_23022011 = "Ya, Anda bisa membayangkannya, bukan?",
  str_homestory_chat_23022012 = "Apakah yang Anda maksud: seni patung Aku ingat melihatnya.",
  str_homestory_chat_23022013 = "Hah? Apa... Ah...",
  str_homestory_chat_23023001 = "Sedang mencari sesuatu, ya?",
  str_homestory_chat_23023002 = "Saya ingin membeli kertas dan tinta dalam jumlah besar...",
  str_homestory_chat_23023003 = "Untuk apa? Menulis buku?",
  str_homestory_chat_23023004 = "Ya. Sebagai hakim, saya sedih melihat tidak ada hukum tertulis di sini.",
  str_homestory_chat_23023005 = "Saya tidak berpikir kita membutuhkan hukum tertulis yang sebenarnya...",
  str_homestory_chat_23023006 = "Perjanjian lisan lebih rendah daripada kontrak tertulis!",
  str_homestory_chat_23023007 = "Saya yakin Anda hanya ingin membuat beberapa aturan, terutama yang menguntungkan Anda.",
  str_homestory_chat_23023008 = "Tidak mungkin, semua aturan yang saya buat akan adil!",
  str_homestory_chat_23023009 = "Misalnya, seseorang harus selalu mengikuti perintah hakim dari Lumopolis...",
  str_homestory_chat_23023010 = "Saya mengistirahatkan kasus saya.",
  str_homestory_chat_27299999 = "Apakah ada yang bisa saya filmkan, PlayerName?",
  str_homestory_chat_27221001 = "Tidak.",
  str_homestory_chat_27221002 = "Apakah Anda pernah berhenti berpikir tentang syuting ...?",
  str_homestory_chat_27221003 = "Hei, bukan salahku kalau pemandangan di sekitar sini sangat menakjubkan! Sekarang jika saya bisa memberikan cerita kepada mereka...",
  str_homestory_chat_27221004 = "Argh, sungguh menyakitkan! Mengapa saya harus menjadi penulis skenario juga?",
  str_homestory_chat_27221005 = "Apakah Anda yakin tidak ada yang menarik terjadi di sini? Mungkin sesuatu seperti \"Sembilan Legenda Luar Biasa dari Taman Awan\"?",
  str_homestory_chat_27221006 = "T-Tidak seperti itu, tidak...",
  str_homestory_chat_27222001 = "Apa yang ingin Anda beli?",
  str_homestory_chat_27222002 = "Apakah Anda memiliki stand tergeletak di suatu tempat? Lebih disukai satu dengan roda, jadi saya bisa memindahkannya.",
  str_homestory_chat_27222003 = "Untuk apa Anda membutuhkannya?",
  str_homestory_chat_27222004 = "Untuk syuting, tentu saja! Lengan Cellulo lelah karena memegang kamera sepanjang waktu, Anda tahu?",
  str_homestory_chat_27222005 = "Anggaran kami juga cukup ketat. Jika tidak, saya akan menyewa seorang profesional untuk melakukannya.",
  str_homestory_chat_27222006 = "Begitu... Bukankah lebih baik mencari hal semacam itu di Umbraton?",
  str_homestory_chat_27222007 = "Ya, tapi Umbraton mahal!",
  str_homestory_chat_27223001 = "Anda tidak tampak terlalu sibuk hari ini?",
  str_homestory_chat_27223002 = "Itu karena aku kehabisan cerita bagus untuk dibaca. Anyway, apakah Anda memiliki hal-hal yang Anda suka membaca?",
  str_homestory_chat_27223003 = "Tidak ada sama sekali.",
  str_homestory_chat_27223004 = "Kukira...?",
  str_homestory_chat_27223005 = "Saya kadang-kadang membaca buku-buku Vice dan yang lainnya memberi saya hadiah.",
  str_homestory_chat_27223006 = "Mendesah. Entah bagaimana, saya merasa seperti berbicara dengan orang yang salah di sini.",
  str_homestory_chat_27223007 = "Saya mencari rekomendasi cerita pendek! Terutama thriller yang bagus, jika Anda tahu ada...",
  str_homestory_chat_27223008 = "Sepertinya kamu sangat menyukai horor. Apakah kamu tidak takut?",
  str_homestory_chat_27223009 = "Hah! Apa yang lebih menakutkan daripada bangkrut?",
  str_homestory_chat_27223010 = "Selain itu, bagaimana jika suatu saat mereka membuat film adaptasi untuk beberapa cerita tersebut? Mereka mungkin memilih saya sebagai pemeran utama wanita jika saya tahu materi di dalam dan di luar!",
  str_homestory_chat_27223011 = "Kemudian, saya akhirnya bisa menjadi bintang yang saya takdirkan... Hehehehe...",
  str_homestory_chat_27223012 = "Benar. Aku akan pergi sekarang.",
  str_homestory_chat_27224001 = "Penggemar?",
  str_homestory_chat_27224002 = "Anda sendiri agak terkenal. Anda punya penggemar, kan?",
  str_homestory_chat_27224003 = "Sepertinya begitu.",
  str_homestory_chat_27224004 = "Ooh! Seperti siapa?",
  str_homestory_chat_27224005 = "Aku... tidak benar-benar tahu...",
  str_homestory_chat_27224006 = "Tidak ada sama sekali.",
  str_homestory_chat_27224007 = "Sayang sekali.",
  str_homestory_chat_27224008 = "Baik, apakah Anda memiliki penggemar atau tidak, Anda harus selalu bekerja keras demi Anda sendiri, bukan untuk mereka!",
  str_homestory_chat_27224009 = "Tentu saja!",
  str_homestory_chat_27224010 = "Itu sebabnya Anda harus menyemangati diri sendiri sesekali, bukan?",
  str_homestory_chat_27224011 = "Tentu, tapi... Kenapa kau mengatakan ini padaku? Apakah sesuatu terjadi?",
  str_homestory_chat_27224012 = "Aku hanya... kadang lelah, itu saja.",
  str_homestory_chat_27225001 = "Apa yang ingin Anda beli?",
  str_homestory_chat_27225002 = "aku ngidam ikan...",
  str_homestory_chat_27225003 = "Bukankah di sungai banyak ikan? Tidak bisakah Cellulo menangkap beberapa untukmu?",
  str_homestory_chat_27225004 = "Tapi saya tidak ingin makan ikan air tawar... Saya ingin sesuatu dari laut!",
  str_homestory_chat_27225005 = "Seperti sup krim kerang... Atau mungkin semangkuk sup seafood di atas nasi!",
  str_homestory_chat_27225006 = "Anda bisa membuatnya dengan ikan air tawar.",
  str_homestory_chat_27225007 = "Benar-benar tidak! Apakah kamu sedang bercanda?!",
  str_homestory_chat_27225008 = "Makanan laut benar-benar berbeda! Hanya satu gigitan, dan Anda bisa merasakan laut secara praktis!",
  str_homestory_chat_27225009 = "Rasa itu saja sudah cukup untuk membuat Anda merasa tak terkalahkan! Seperti Anda dapat mencapai bahkan impian terliar Anda!",
  str_homestory_chat_27225010 = "Apakah kita ... masih berbicara tentang makanan?",
  str_homestory_chat_27399999 = "Selamat tinggal, PlayerName. Saya siap melayani Anda, jika Anda memerlukan sesuatu.",
  str_homestory_chat_27301001 = "Hai, Minos.",
  str_homestory_chat_27301002 = "Anda tidak harus begitu sopan di sini di Cloud Gardens sepanjang waktu. Tenang saja, oke?",
  str_homestory_chat_27301003 = "Mustahil. Sebagai kepala pelayan yang bangga, saya harus siap melayani tuan saya setiap saat.",
  str_homestory_chat_27301004 = "Tapi tuanmu tidak ada di sini sekarang... kan?",
  str_homestory_chat_27301005 = "Tidak, tapi saya juga harus siap jika dia memutuskan untuk datang ke sini.",
  str_homestory_chat_27321001 = "Senjatamu...",
  str_homestory_chat_27321002 = "Ah, aku sudah mencarimu, temanku. Katakan padaku, apakah ada pengrajin ahli di sini di Cloud Gardens yang bisa memperbaiki senjata?",
  str_homestory_chat_27321003 = "Ya.",
  str_homestory_chat_27321004 = "Chubb mana yang harus saya ajak bicara?",
  str_homestory_chat_27321005 = "Er... Saya rasa tidak ada yang bisa membantu Anda, tapi mungkin salah satu teman saya bisa mencoba?",
  str_homestory_chat_27321006 = "Tidak.",
  str_homestory_chat_27321007 = "Huh... Sayang sekali.",
  str_homestory_chat_27321008 = "Apakah pistol Anda rusak?",
  str_homestory_chat_27321009 = "Tentu saja tidak. Sebagai kepala pelayan yang bangga, adalah tugas saya untuk memastikan semua peralatan saya berfungsi dengan baik, dan senjata tidak terkecuali.",
  str_homestory_chat_27321010 = "Tidak ada yang tahu kapan tuanku mungkin menemukan dirinya dalam kesulitan yang berbahaya.",
  str_homestory_chat_27321011 = "Itu sangat profesional dari Anda ...",
  str_homestory_chat_27322001 = "Apa yang bisa kubantu?",
  str_homestory_chat_27322002 = "Selamat tinggal, PlayerName. Bisakah Anda memberi saya waktu yang tepat sekarang?",
  str_homestory_chat_27322003 = "Tentu...? Apakah ada yang salah dengan jam tangan Anda?",
  str_homestory_chat_27322004 = "Bahkan instrumen yang paling tepat pun terkadang bisa gagal. Bahkan, baru tadi pagi...",
  str_homestory_chat_27322005 = "Saya perhatikan bahwa arloji saya sepertinya berjalan sepersekian detik lebih lambat daripada kemarin.",
  str_homestory_chat_27322006 = "Anda memperhatikan hal-hal seperti itu?!",
  str_homestory_chat_27322007 = "Sebagai kepala pelayan yang bangga, adalah tugas saya untuk melacak waktu setiap saat.",
  str_homestory_chat_27322008 = "Lagi pula, bahkan penyimpangan terkecil dari waktu yang tepat di pihak saya dapat merusak seluruh jadwal tuan saya untuk hari itu.",
  str_homestory_chat_27322009 = "Mau tak mau aku merasa iri pada tuanmu...",
  str_homestory_chat_27322010 = "Kalau saja saya memiliki seseorang seperti Anda untuk membantu saya tetap pada jadwal ...",
  str_homestory_chat_27323001 = "Apakah ada sesuatu di pikiranmu, Minos?",
  str_homestory_chat_27323002 = "Ada, memang. Katakan padaku, bagaimana menurutmu seorang kepala pelayan melayani tuannya dengan baik?",
  str_homestory_chat_27323003 = "Dengan mengikuti perintah?",
  str_homestory_chat_27323004 = "Ketaatan total...",
  str_homestory_chat_27323005 = "Jika saya boleh berbicara terus terang... Saya sangat tidak setuju.",
  str_homestory_chat_27323006 = "Dengan mendukung mereka?",
  str_homestory_chat_27323007 = "Kau benar!",
  str_homestory_chat_27323008 = "Tugas seorang kepala pelayan bukan hanya untuk mematuhi perintah tuannya. Lebih sering daripada tidak, dia harus membantu tuannya menyadari kesalahannya sendiri.",
  str_homestory_chat_27323009 = "Dalam hal ini, seorang kepala pelayan dan tuannya dapat melihat satu sama lain secara setara.",
  str_homestory_chat_27323010 = "Itu benar, ya.",
  str_homestory_chat_27324001 = "Menurutmu, bagaimana tempat ini?",
  str_homestory_chat_27324002 = "Ini adalah tempat yang indah. Luas, tapi sangat bersih.",
  str_homestory_chat_27324003 = "Keluarga Chubb tampaknya menjaga daerah itu dengan cukup baik.",
  str_homestory_chat_27324004 = "Bukan hanya mereka, kau tahu? Semua orang melakukan bagian mereka untuk merawat Cloud Gardens juga.",
  str_homestory_chat_27324005 = "Sayangku PlayerName, Anda benar sekali.",
  str_homestory_chat_27324006 = "Sejujurnya, saya cukup iri dengan betapa layak huni tempat ini.",
  str_homestory_chat_27324007 = "Lingkungan bersih, udara segar, dan bahkan jumlah sinar matahari yang diterima tempat ini... Semuanya luar biasa.",
  str_homestory_chat_27324008 = "Tetapi yang paling penting, hampir seluruhnya bebas dari serangga berbahaya dan hewan pengerat sial lainnya. Hasilnya, pekerjaan saya di sini jauh lebih ringan.",
  str_homestory_chat_27324009 = "Saya senang Anda suka di sini, Minos!",
  str_homestory_chat_26999999 = "Yo yo yo, saya melihat Anda berkeliaran, bro.",
  str_homestory_chat_26901001 = "Hai, Sadi.",
  str_homestory_chat_26901002 = "Yo yo yo! Aku hanya nongkrong, kau tahu?",
  str_homestory_chat_26901003 = "Mengapa Anda meniru cara saya berbicara?",
  str_homestory_chat_26901004 = "M-Maaf, itu hanya menyelinap keluar ...",
  str_homestory_chat_26901005 = "Yo yo yo, sepertinya kamu mengikuti arusku.",
  str_homestory_chat_26921001 = "Apa yang kau baca?",
  str_homestory_chat_26921002 = "Omnibus Komik Swashbuckler Tahunan. Itu baru saja keluar di Umbraton!",
  str_homestory_chat_26921003 = "Saya datang ke Cloud Gardens agar saya bisa membacanya tiga kali lagi.",
  str_homestory_chat_26921004 = "Tiga kali lagi?",
  str_homestory_chat_26921005 = "Ya! Saya bisa membacanya seratus kali dan masih tidak bosan!",
  str_homestory_chat_26921006 = "Dilihat dari seberapa bersemangat Anda, saya akan mengatakan Anda sudah membacanya tiga ratus kali, bukan?",
  str_homestory_chat_26921007 = "Nah, lebih seperti 666 kali!",
  str_homestory_chat_26921008 = "Hah?",
  str_homestory_chat_26922001 = "Apakah kamu tersenyum?",
  str_homestory_chat_26922002 = "Saya baru saja memikirkan sesuatu yang membuat saya sangat bahagia, sama seperti ketika Anda memikirkan Cloud Gardens!",
  str_homestory_chat_26922003 = "Sesuatu yang bahagia?",
  str_homestory_chat_26922004 = "Setiap kali saya memikirkan swashbuckling, saya tidak bisa menahan senyum!",
  str_homestory_chat_26922005 = "Terutama ketika saya memikirkan bagaimana saya dapat menggagalkan rencana orang jahat setiap saat!",
  str_homestory_chat_26922006 = "Taman Awan?",
  str_homestory_chat_26922007 = "Betul sekali! Saya telah memperhatikan Anda untuk sementara waktu sekarang, dan saya telah memperhatikan bahwa setiap kali Anda berada di Cloud Gardens, Anda selalu memiliki senyum di wajah Anda.",
  str_homestory_chat_26922008 = "Tanpa disadari, dan tanpa disadari.",
  str_homestory_chat_26922009 = "Jadi... Kenapa kamu tersenyum?",
  str_homestory_chat_26922010 = "Seorang swashbuckler tersenyum ketika orang jahat menangis!",
  str_homestory_chat_26922011 = "Setiap kali saya memikirkan hal ini, mau tidak mau saya menjatuhkan beberapa syair gaya bebas!",
  str_homestory_chat_26922012 = "Pecundang, penjahat melihat! Sebuah tinju datang terbang dan penjahat mulai menangis!",
  str_homestory_chat_26922013 = "Ya! Uh-huh, uh-huh!",
  str_homestory_chat_26923001 = "Anda benar-benar suka bisbol, ya?",
  str_homestory_chat_26923002 = "Tidak terutama. Mengapa Anda bertanya?",
  str_homestory_chat_26923003 = "Yah, aku tidak pernah melihatmu tanpa topi baseball atau pemukulmu...",
  str_homestory_chat_26923004 = "Saya hanya suka tampilannya. Bukankah itu terlihat keren bagimu?",
  str_homestory_chat_26923005 = "Dingin?",
  str_homestory_chat_26923006 = "Anda tahu, seperti saya akan melakukan sesuatu yang sangat luar biasa...?",
  str_homestory_chat_26923007 = "Baseball tidak pernah menjadi gaya saya, Anda tahu? Tetapi ketika berbicara tentang rap, saya mendapatkan aliran yang paling keren!",
  str_homestory_chat_26923008 = "Super Sadie 666, membawa pemukul, Super Sadie 666, mengayunkan pemukul.",
  str_homestory_chat_26923009 = "Jadi pada dasarnya Anda hanya menggunakannya sebagai senjata.",
  str_homestory_chat_26923010 = "Super Sadie 666, memakai topi, Super Sadie 666, dia benar-benar menampar!",
  str_homestory_chat_26923011 = "Baiklah, saya mengerti. Anda bisa berhenti melakukan itu sekarang...",
  str_homestory_chat_27599999 = "*Menguap* Anda jalan-jalan santai lagi hari ini.",
  str_homestory_chat_27521001 = "Kamu lagi.",
  str_homestory_chat_27521002 = "Apakah Anda baru saja menguap? Apa kau lelah?",
  str_homestory_chat_27521003 = "Tidak, aku selalu seperti ini.",
  str_homestory_chat_27521004 = "BENAR. Tidak ada tanda-tanda kelelahan di wajah Anda ...",
  str_homestory_chat_27521005 = "Semua orang memberitahuku itu.",
  str_homestory_chat_27521006 = "Saya kira ini adalah salah satu ciri khusus Anda.",
  str_homestory_chat_27522001 = "Apakah Anda selalu memakai pakaian itu?",
  str_homestory_chat_27522002 = "Memang saya lakukan. Apakah ada yang salah dengan itu?",
  str_homestory_chat_27522003 = "Itu sangat tidak cocok untukmu.",
  str_homestory_chat_27522004 = "Itu karena pakaian ketat membuat saya tidak nyaman. Kadang-kadang saya bahkan kesulitan bernapas.",
  str_homestory_chat_27522005 = "Saya sudah mencoba memakainya sebelumnya, tetapi saya tidak tahan.",
  str_homestory_chat_27522006 = "Suatu hari, ayah saya memberi tahu saya bahwa saya bisa memakai pakaian satu ukuran lebih tinggi.",
  str_homestory_chat_27522007 = "Setelah itu, pakaian saya tidak lagi membuat saya kesulitan.",
  str_homestory_chat_27522008 = "Aku tahu.",
  str_homestory_chat_27522009 = "Kau selalu memakai itu...",
  str_homestory_chat_27522010 = "Itu karena saya memiliki banyak set pakaian yang sama.",
  str_homestory_chat_27522011 = "Tapi itu bukan maksud saya. Apakah kamu tidak mencoba memakai pakaian lain?",
  str_homestory_chat_27522012 = "Tidak, aku suka pakaian seperti ini. Mereka sangat nyaman.",
  str_homestory_chat_27522013 = "Kurasa begitu…",
  str_homestory_chat_27523001 = "Lampu?",
  str_homestory_chat_27523002 = "Ya, saya ingin mengganti lampu jalan di sini.",
  str_homestory_chat_27523003 = "Mengubahnya dengan cara apa?",
  str_homestory_chat_27523004 = "Saya ingin menggantinya dengan lampu neon warna-warni. Aku yakin itu akan terlihat bagus.",
  str_homestory_chat_27523005 = "Keluarga Chubb pasti akan menyukainya.",
  str_homestory_chat_27523006 = "Itu terasa seperti usaha besar.",
  str_homestory_chat_27523007 = "Apakah ini berarti Anda baik-baik saja dengan itu?",
  str_homestory_chat_27523008 = "Apakah Anda ingin saya mencari tahu berapa banyak pekerjaan yang akan terlibat?",
  str_homestory_chat_27523009 = "Um, itu tidak perlu...",
  str_homestory_chat_27524001 = "Bisakah kamu berbicara sedikit lebih keras?",
  str_homestory_chat_27524002 = "Apakah saya berbicara terlalu lembut? Apakah Anda tidak dapat berkomunikasi dengan saya?",
  str_homestory_chat_27524003 = "Terkadang aku tidak bisa mendengarmu dengan baik.",
  str_homestory_chat_27524004 = "Maka kita harus berdiri sedikit lebih dekat ketika kita berbicara.",
  str_homestory_chat_27524005 = "Ini sekeras suaraku.",
  str_homestory_chat_27524006 = "Tapi terkadang tidak nyaman untuk terlalu dekat satu sama lain.",
  str_homestory_chat_27524007 = "Mengapa demikian?",
  str_homestory_chat_27524008 = "Bukankah jarak yang lebih pendek antara kita lebih baik untuk komunikasi?",
  str_homestory_chat_27524009 = "Er... Mari kita tunda topik ini untuk sementara waktu.",
  str_homestory_chat_27525001 = "Permen?",
  str_homestory_chat_27525002 = "Ya, PlayerName, apakah kamu suka permen?",
  str_homestory_chat_27525003 = "Ya.",
  str_homestory_chat_27525004 = "Saya pernah makan permen karet ini di Umbraton yang tidak terlalu manis dan tidak menempel di gigi saya...",
  str_homestory_chat_27525005 = "Anda harus membawa saya ke sana untuk mencobanya suatu hari nanti. Saya akan berterima kasih.",
  str_homestory_chat_27525006 = "Tentu saja, tetapi Anda tidak terlihat bersemangat bagi saya.",
  str_homestory_chat_27525007 = "Tidak, saya sangat menantikannya.",
  str_homestory_chat_27525008 = "Tidak.",
  str_homestory_chat_27525009 = "Sayang sekali. Saya ingin merekomendasikan semua jenis permen kepada Anda.",
  str_homestory_chat_27525010 = "Terutama pop rock...",
  str_homestory_chat_27699999 = "Hai! Saya dalam suasana hati yang baik hari ini!",
  str_homestory_chat_27601001 = "Halo!",
  str_homestory_chat_27601002 = "Saya mendengar Anda sedang mencari sesuatu untuk dilakukan?",
  str_homestory_chat_27601003 = "Betul sekali. Meskipun ini bukan Lumopolis, setelah saya datang ke sini...",
  str_homestory_chat_27601004 = "Saya belum bisa menghilangkan perasaan bahwa saya memiliki kewajiban untuk berkontribusi di tempat ini. Jadi saya hanya ingin melakukan sesuatu.",
  str_homestory_chat_27601005 = "Tidak perlu terburu-buru. Lagipula, kota tidak bisa dibangun dalam sehari.",
  str_homestory_chat_27601006 = "Itu juga yang Lady Raphael katakan... Baiklah kalau begitu.",
  str_homestory_chat_27621001 = "Tumbuh bunga?",
  str_homestory_chat_27621002 = "Ya. Ada banyak sekali bunga yang menarik di sini, terutama yang tinggi!",
  str_homestory_chat_27621003 = "Itu... adalah Pohon Unik...",
  str_homestory_chat_27621004 = "Oh, betapa menakjubkan! Beberapa di antaranya terlihat seperti bunga, terutama yang berkanopi. Apakah Anda menumbuhkan semuanya sendiri?",
  str_homestory_chat_27621005 = "Ya.",
  str_homestory_chat_27621006 = "Keluarga Chubb melakukan sebagian besar pekerjaan.",
  str_homestory_chat_27621007 = "Bisakah saya menumbuhkannya juga? Aku pandai merawat tanaman!",
  str_homestory_chat_27621008 = "Hmm... Aku perlu memikirkannya.",
  str_homestory_chat_27622001 = "Anda menyebutkan burung ...",
  str_homestory_chat_27622002 = "Cloud Gardens sangat besar. Saya yakin banyak burung datang ke sini.",
  str_homestory_chat_27622003 = "Saya ingin membangun sarang agar mereka memiliki tempat istirahat ketika mereka datang.",
  str_homestory_chat_27622004 = "Ide yang bagus! Anda sangat jeli, dan Anda menyukai burung.",
  str_homestory_chat_27622005 = "Sebenarnya... ini adalah ide Lady Raphael.",
  str_homestory_chat_27622006 = "Dia mengatakan ini akan membuat saya lebih sabar dan tidak terburu-buru.",
  str_homestory_chat_27622007 = "Setelah datang ke sini, saya tidak melakukan apa-apa, dan saya pikir itu membuat saya sering kembali ke diri saya yang dulu.",
  str_homestory_chat_27622008 = "Itu sebabnya saya datang untuk menanyakan di mana saya bisa menemukan burung. Aku akan pergi mencari mereka!",
  str_homestory_chat_27622009 = "Ada ketidaksabaranmu lagi...",
  str_homestory_chat_27622010 = "Apa katamu? Dimana mereka?",
  str_homestory_chat_27622011 = "Ah, yang saya maksud adalah Anda tidak bisa tidak sabar. Anda perlu mencarinya secara perlahan.",
  str_homestory_chat_27622012 = "Hal ini juga melatih Anda untuk lebih sabar, bukan?",
  str_homestory_chat_27622013 = "Hmm, kamu benar.",
  str_homestory_chat_27623001 = "Latihan medis?",
  str_homestory_chat_27623002 = "Ya. Cloud Gardens cukup damai, tetapi kami masih perlu melakukan latihan semacam ini.",
  str_homestory_chat_27623003 = "Kita harus siap menghadapi kecelakaan bahkan jika musuh tidak menyerang kita.",
  str_homestory_chat_27623004 = "Misalnya, seseorang bisa tenggelam atau jatuh dari atap.",
  str_homestory_chat_27623005 = "Saya kira Anda benar.",
  str_homestory_chat_27623006 = "Bagaimana kita harus memulai? Apakah saya perlu mencari beberapa orang lain untuk berkoordinasi dengan Anda?",
  str_homestory_chat_27623007 = "Itu tidak perlu! Ada banyak Chubb di sini!",
  str_homestory_chat_27623008 = "Tunggu! Tapi mereka bukan Aurorian...?",
  str_homestory_chat_27623009 = "Akankah latihan medis benar-benar efektif dengan cara ini?",
  str_homestory_chat_27623010 = "Tidak apa-apa asalkan skillku tidak berkarat!",
  str_homestory_chat_27623011 = "B-baiklah.",
  str_homestory_chat_27799999 = "Hai! Kamu terlihat cantik hari ini!",
  str_homestory_chat_27721001 = "Kamu selalu ceria.",
  str_homestory_chat_27721002 = "Bagaimana Anda melakukannya? Apa rahasiamu?",
  str_homestory_chat_27721003 = "Itu hanya karena idola selalu seperti ini, meski hati mereka penuh dengan kesedihan...",
  str_homestory_chat_27721004 = "Mereka tetap positif setiap saat dan melakukan tindakan terbaik mereka untuk semua orang!",
  str_homestory_chat_27721005 = "Lagi pula, bagaimana lagi kita bisa mengisi seluruh benua dengan kekuatan penyembuhan cinta?",
  str_homestory_chat_27721006 = "Ketika Anda mengatakannya seperti itu, Anda benar-benar luar biasa ...",
  str_homestory_chat_27722001 = "Kau ingin menemuiku?",
  str_homestory_chat_27722002 = "PlayerName, Saya perlu mengajukan pertanyaan yang sangat serius, dan Anda harus menjawabnya dengan jujur.",
  str_homestory_chat_27722003 = "K-Kenapa? Apa yang salah?",
  str_homestory_chat_27722004 = "Apakah Anda berpikir bahwa baru-baru ini... berat badan saya...",
  str_homestory_chat_27722005 = "(Dia sepertinya khawatir dengan berat badannya. Bagaimana aku harus menjawabnya...?)",
  str_homestory_chat_27722006 = "Anda terlihat lebih ... bulat.",
  str_homestory_chat_27722007 = "Aku tahu itu! Saya yakin itu karena saya makan berlebihan baru-baru ini.",
  str_homestory_chat_27722008 = "Dan hidup terlalu santai di sini... Aku tidak bisa terus seperti ini!",
  str_homestory_chat_27722009 = "Sepertinya aku tidak akan makan apapun malam ini! Dan saya harus berlari 50 putaran!",
  str_homestory_chat_27722010 = "Kau terlihat baik.",
  str_homestory_chat_27722011 = "Betulkah? Katakan yang sebenarnya, atau aku tidak akan pernah mempercayaimu lagi!",
  str_homestory_chat_27722012 = "Nah... Mungkin berat badan Anda bertambah sedikit?",
  str_homestory_chat_27722013 = "Saya tahu saya makan berlebihan beberapa hari yang lalu! Saya harus mulai lebih ketat dengan diri saya sendiri!",
  str_homestory_chat_27722014 = "Maksudku, tidak perlu bereaksi berlebihan. Ini hanya sedikit tambahan berat...",
  str_homestory_chat_27722015 = "Bahkan sedikit terlalu banyak. Ini adalah harga menjadi idola.",
  str_homestory_chat_27722016 = "Kau begitu ketat dengan diri sendiri.",
  str_homestory_chat_27723001 = "Apakah Anda akan berolahraga?",
  str_homestory_chat_27723002 = "Kinerja berlatih, sebenarnya! Apakah ada ruang pelatihan khusus di sekitar sini?",
  str_homestory_chat_27723003 = "Eh...",
  str_homestory_chat_27723004 = "Huh, ini benar-benar tempat yang sempurna untuk liburan.",
  str_homestory_chat_27723005 = "Tapi aku tidak boleh menyerah dalam latihanku... Seorang idola harus selalu menjadi yang terbaik.",
  str_homestory_chat_27723006 = "Mungkin kita bisa melakukan beberapa pelatihan tanpa peralatan profesional?",
  str_homestory_chat_27723007 = "Baik! Biarkan saya melihat apa yang kita miliki di sini ...",
  str_homestory_chat_27723008 = "Lari jarak jauh, berenang, mendaki gunung, menari... Ada begitu banyak hal yang harus dilakukan!",
  str_homestory_chat_27723009 = "Anda punya ini.",
  str_homestory_chat_27724001 = "Sebuah ruangan?",
  str_homestory_chat_27724002 = "Benar, saya ingin ruangan khusus hanya untuk Marshmallow.",
  str_homestory_chat_27724003 = "Maksudmu anjingmu?",
  str_homestory_chat_27724004 = "Ya. Soalnya, dia tidak pernah tidur nyenyak di luar, dan terkadang hujan juga turun di sini.",
  str_homestory_chat_27724005 = "Itu benar…",
  str_homestory_chat_27724006 = "Itu dia! Aku akan membuat sarang kecil untuknya di bawah tempat tidurku! Aku hanya butuh selimut.",
  str_homestory_chat_27724007 = "Ide yang bagus!",
  str_homestory_chat_27724008 = "Saya akan meminta Chubbs untuk melakukannya!",
  str_homestory_chat_27724009 = "Anda sepertinya sudah merencanakan semua ini.",
  str_homestory_chat_27725001 = "Anda terlihat cukup baik, juga.",
  str_homestory_chat_27725002 = "Memang! Dan itu terutama karena tidak ada pare di sini.",
  str_homestory_chat_27725003 = "Melon pahit? Anda tidak suka pare?",
  str_homestory_chat_27725004 = "Apakah Anda memberi tahu saya bahwa Anda melakukannya ?!",
  str_homestory_chat_27725005 = "Saya tidak keberatan.",
  str_homestory_chat_27725006 = "Anda tidak keberatan! Menakjubkan! Tapi rasa pahit itu...",
  str_homestory_chat_27725007 = "Oh! Begitu ya... Anda mencoba menurunkan berat badan, bukan?",
  str_homestory_chat_27725008 = "Erm... T-Tidak...",
  str_homestory_chat_27725009 = "Sigh, Anda tampaknya memahami pentingnya manajemen berat badan juga. Sulit, bukan?",
  str_homestory_chat_27725010 = "Sejujurnya, aku tidak...",
  str_homestory_chat_27725011 = "Itu menjijikkan.",
  str_homestory_chat_27725012 = "Benar! Jadi, jangan biarkan pare mendekati sini! Jangan lupa!",
  str_homestory_chat_27725013 = "Bukan masalah.",
  str_homestory_chat_27899999 = "Hmm? Ada apa?",
  str_homestory_chat_27821001 = "Kau sedang apa?",
  str_homestory_chat_27821002 = "Saya bertanya-tanya apakah saya harus membuat kursi goyang atau tempat tidur gantung...",
  str_homestory_chat_27821003 = "Untuk alasan apa?",
  str_homestory_chat_27821004 = "Untuk beristirahat, tentu saja. Untuk apa lagi saya menggunakannya, berolahraga?",
  str_homestory_chat_27821005 = "Bayangkan berbaring di bawah sinar matahari, angin sepoi-sepoi menggelitik pipimu... Ah!",
  str_homestory_chat_27821006 = "Kedengarannya sangat santai ...",
  str_homestory_chat_27822001 = "Anda terlihat sangat santai.",
  str_homestory_chat_27822002 = "Ya, ini adalah tempat langka di mana orang bisa benar-benar bersantai.",
  str_homestory_chat_27822003 = "Apakah kamu tidak menikmati perasaan seperti ini juga, PlayerName?",
  str_homestory_chat_27822004 = "Ya.",
  str_homestory_chat_27822005 = "Betul sekali! Aku tahu kau akan mendapatkannya!",
  str_homestory_chat_27822006 = "Saya tahu kamu juga suka perasaan santai tanpa beban ini.",
  str_homestory_chat_27822007 = "Saya terutama suka tidak melakukan apa-apa — hanya melihat ke atas dan melihat angin dengan lembut menyenggol awan.",
  str_homestory_chat_27822008 = "Atau mendengarkan suara dedaunan dan membiarkan pikiranku benar-benar kosong.",
  str_homestory_chat_27822009 = "Ini bagus untuk mengurangi kelelahan mental.",
  str_homestory_chat_27822010 = "Baiklah, saya akan mencobanya suatu hari nanti.",
  str_homestory_chat_27822011 = "Itu tidak buruk, tapi ...",
  str_homestory_chat_27822012 = "Tidak baik terlalu banyak bersantai... Kita harus menghabiskan waktu kita untuk benar-benar melakukan sesuatu.",
  str_homestory_chat_27822013 = "Seperti membangun struktur baru? Tapi kita bisa membuat Chubbs melakukannya.",
  str_homestory_chat_27822014 = "Anda dapat dan harus menghabiskan lebih banyak waktu untuk bersantai.",
  str_homestory_chat_27822015 = "Itu... tidak persis seperti yang saya maksud.",
  str_homestory_chat_27823001 = "Apa maumu?",
  str_homestory_chat_27823002 = "Saya mendengar ada beberapa hewan yang tampak aneh di sekitar bagian ini.",
  str_homestory_chat_27823003 = "Saya belum melihat apapun.",
  str_homestory_chat_27823004 = "Sayang sekali! Saya pikir saya mungkin menemukan sesuatu yang menarik di sini.",
  str_homestory_chat_27823005 = "Tapi saya juga bisa menganggap ini sebagai cuti panjang.",
  str_homestory_chat_27823006 = "Ah... Ya, ada.",
  str_homestory_chat_27823007 = "Saya memiliki perasaan yang baik tentang tempat ini! Sekarang saya dapat menikmati liburan saya dan mencari binatang yang menakjubkan pada saat yang bersamaan!",
  str_homestory_chat_27823008 = "Dua burung, satu batu!",
  str_homestory_chat_27823009 = "Bermalas-malasan tampaknya menjadi tujuan utama Anda...",
  str_homestory_chat_27824001 = "Memancing?",
  str_homestory_chat_27824002 = "Ya, ada banyak ikan di sungai terdekat, jadi banyak orang memancing di sana.",
  str_homestory_chat_27824003 = "Benar.",
  str_homestory_chat_27824004 = "Apa kamu suka memancing?",
  str_homestory_chat_27824005 = "Tentu.",
  str_homestory_chat_27824006 = "Tidak apa-apa, kurasa.",
  str_homestory_chat_27824007 = "Hmm... Ngomong-ngomong, saya lebih suka mengamati ikan daripada menangkapnya sendiri.",
  str_homestory_chat_27824008 = "Saya merasa sangat santai melihat mereka mengarungi air.",
  str_homestory_chat_27824009 = "Anda bisa saja pergi ke Air Mancur Harapan.",
  str_homestory_chat_27824010 = "Yah, itu berbeda. Lagi pula, terperangkap dalam pelukan Air Mancur Harapan memberi Anda perasaan yang sama sekali berbeda.",
  str_homestory_chat_27824011 = "Masuk akal...",
  str_homestory_chat_27825001 = "Butuh sesuatu untuk diminum?",
  str_homestory_chat_27825002 = "Benar. Di sini bagus, tapi ada yang kurang...",
  str_homestory_chat_27825003 = "Dan sesuatu itu adalah sebotol minuman keras!",
  str_homestory_chat_27825004 = "Minum di siang hari...",
  str_homestory_chat_27825005 = "Hanya minum sedikit dan tidak lebih. Dengan angin sepoi-sepoi, jika ada kursi goyang lagi...",
  str_homestory_chat_27825006 = "Bagus!",
  str_homestory_chat_27825007 = "Jadi, Anda tidak akan mencari binatang yang menakjubkan lagi?",
  str_homestory_chat_27825008 = "Saya datang ke sini untuk bersantai! Tapi jika tidak ada minuman keras...",
  str_homestory_chat_27825009 = "Mungkin aliran di sana memiliki apa yang saya cari? Benar!",
  str_homestory_chat_27825010 = "Yah... Terserah kamu.",
  str_homestory_chat_28099999 = "Apa yang Anda gosipkan hari ini?",
  str_homestory_chat_28001001 = "Hah? Saya tidak bergosip tentang apapun...",
  str_homestory_chat_28001002 = "Mengapa Anda sangat menyukai gosip?",
  str_homestory_chat_28001003 = "Karena itu sangat menarik!",
  str_homestory_chat_28001004 = "Misalnya, saya mendengar bahwa beberapa orang penting di salah satu guild besar benar-benar bermimpi menjadi seorang novelis, atau semacamnya...",
  str_homestory_chat_28001005 = "Tidakkah menurutmu itu hanya menarik?!",
  str_homestory_chat_28001006 = "Itu... untuk masing-masing mereka sendiri, kurasa.",
  str_homestory_chat_28001007 = "Itu sebabnya saya harus mengumpulkan banyak info untuk memenuhi kebutuhan pembaca yang berbeda!",
  str_homestory_chat_28001008 = "Baiklah, semoga Anda beruntung.",
  str_homestory_chat_28021001 = "Perangkat itu...",
  str_homestory_chat_28021002 = "Anda sepertinya membawanya ke mana-mana. Anda benar-benar perlu mengambil foto kapan saja, di mana saja?",
  str_homestory_chat_28021003 = "Tentu saja! Dan itu karena gosip selalu didasarkan pada kebenaran!",
  str_homestory_chat_28021004 = "Hah? Apa kamu yakin akan hal itu?",
  str_homestory_chat_28021005 = "Apa pendapat Anda tentang ini?",
  str_homestory_chat_28021006 = "Rumor harus didasarkan pada kebenaran.",
  str_homestory_chat_28021007 = "Benar sekali!",
  str_homestory_chat_28021008 = "Tapi mengada-ada sesekali...",
  str_homestory_chat_28021009 = "Saya kira itu tidak terlalu penting? Itu tidak akan menjadi masalah yang sangat penting.",
  str_homestory_chat_28021010 = "Tidak!",
  str_homestory_chat_28021011 = "Jangan katakan itu! Bahkan gosip pun harus benar, jika tidak, cepat atau lambat pembaca akan kehilangan minat.",
  str_homestory_chat_28021012 = "Gosip harus memiliki tingkat keaslian tertentu untuk menarik pembaca!",
  str_homestory_chat_28021013 = "Saya kira bahkan gosip pun tidak boleh ditulis tanpa perasaan.",
  str_homestory_chat_28022001 = "Tas mu...",
  str_homestory_chat_28022002 = "Mengapa begitu besar? Dan Anda selalu membawanya kemana-mana.",
  str_homestory_chat_28022003 = "Besar karena penuh dengan materi jurnalistik: catatan, foto, surat kabar, bahkan selebaran...",
  str_homestory_chat_28022004 = "Apakah Anda perlu membawa semua itu bersama Anda? Tidak bisakah Anda meninggalkannya di kantor Anda?",
  str_homestory_chat_28022005 = "Tidak mungkin! Berita selalu terhubung!",
  str_homestory_chat_28022006 = "Terkadang, aroma pertama dari sebuah berita besar tersembunyi di dalam berita yang paling tidak penting.",
  str_homestory_chat_28022007 = "Begitu Anda menemukan orang atau benda yang mungkin berisi cerita, Anda tidak pernah tahu kapan Anda membutuhkannya!",
  str_homestory_chat_28022008 = "Tapi tidakkah menurutmu gosip seperti itu akan basi seiring berjalannya waktu?",
  str_homestory_chat_28022009 = "Itu sebabnya saya perlu membawa tas ini. Saya membuatnya sesuai pesanan!",
  str_homestory_chat_28022010 = "Tidak hanya besar, ia juga memiliki banyak kompartemen, jadi saya dapat menemukan informasi yang saya butuhkan kapan pun saya membutuhkannya!",
  str_homestory_chat_28022011 = "Saya ingat lokasi spesifik dari setiap dokumen!",
  str_homestory_chat_28022012 = "Jika ingatan Anda sangat baik, mengapa Anda tidak menghafal semua info saja ...",
  str_homestory_chat_28023001 = "Punya gosip?",
  str_homestory_chat_28023002 = "Ah... Tidak, tidak apa-apa. Hidup di sini sangat membosankan.",
  str_homestory_chat_28023003 = "Semuanya hanya Chubbs, Chubbs, Chubbs.",
  str_homestory_chat_28023004 = "Tidak ada kedai kopi atau kios koran tempat saya bisa menguping informasi.",
  str_homestory_chat_28023005 = "Ini kesempatan bagus untuk istirahat.",
  str_homestory_chat_28023006 = "Apa bagusnya itu? Saya akan melewatkan semua berita terbaru!",
  str_homestory_chat_28023007 = "Tapi hidup di sini benar-benar damai. Mengapa Anda tidak menemukan hal lain untuk dilakukan?",
  str_homestory_chat_28023008 = "Sesuatu yang lain... Aku mendapatkannya!",
  str_homestory_chat_28023009 = "Saya bisa melatih Chubbs untuk mengetahui gosip terbaru untuk saya!",
  str_homestory_chat_28023010 = "Seperti itu...hehehe...",
  str_homestory_chat_28023011 = "Tolong jangan!",
  str_homestory_chat_28199999 = "Apa yang kamu lakukan akhir-akhir ini, teman mudaku?",
  str_homestory_chat_28121001 = "Jadi apa hobimu?",
  str_homestory_chat_28121002 = "Saya suka ukiran kayu.",
  str_homestory_chat_28121003 = "Ukiran kayu?",
  str_homestory_chat_28121004 = "Ya, ambil sepotong kayu biasa, pisau ukir yang bagus...",
  str_homestory_chat_28121005 = "Dan sebuah karya seni akan terbentuk di tangan Anda.",
  str_homestory_chat_28121006 = "Terkadang itu membuat saya lebih bahagia daripada memenangkan pertempuran.",
  str_homestory_chat_28121007 = "Anda sangat menyukainya, bukan?",
  str_homestory_chat_28122001 = "Pohon Unik?",
  str_homestory_chat_28122002 = "Sebuah ide datang kepada saya ketika saya melihat pohon-pohon yang indah di sini.",
  str_homestory_chat_28122003 = "Anda ingin mengukir sesuatu dengan mereka, bukan?",
  str_homestory_chat_28122004 = "Itu betul. Bolehkah saya?",
  str_homestory_chat_28122005 = "Tidak.",
  str_homestory_chat_28122006 = "\"Tidak\" datar, ya? Pohon-pohon ini pasti penting bagi Anda.",
  str_homestory_chat_28122007 = "Terutama karena... mereka sangat sulit tumbuh.",
  str_homestory_chat_28122008 = "Mari berpikir...",
  str_homestory_chat_28122009 = "Apakah Anda membutuhkan banyak bahan untuk ukiran kayu?",
  str_homestory_chat_28122010 = "Ya, saya belum pernah mengukir sebelumnya, jadi mungkin banyak bahan yang terbuang.",
  str_homestory_chat_28122011 = "Mereka mungkin memiliki karakteristik yang sangat berbeda dari kayu yang biasa saya gunakan untuk mengukir.",
  str_homestory_chat_28122012 = "Lalu... Aku takut tidak.",
  str_homestory_chat_28122013 = "Benar... Kurasa aku akan berhenti mencari kayu bagus di sini.",
  str_homestory_chat_28122014 = "Atau mungkin saya harus membeli beberapa dari lokasi asing ...",
  str_homestory_chat_28123001 = "Anda suka kucing?",
  str_homestory_chat_28123002 = "Ya, itu sebabnya saya punya tiga dari mereka.",
  str_homestory_chat_28123003 = "Tiga?!",
  str_homestory_chat_28123004 = "Tapi saya hanya melihat satu.",
  str_homestory_chat_28123005 = "Karena mereka memiliki tugas yang berbeda.",
  str_homestory_chat_28123006 = "Tugas yang berbeda? Betulkah?",
  str_homestory_chat_28123007 = "Yixin berkelahi denganku, Yimeng menghabiskan waktu bersamaku di sini, dan untuk Yinuo...",
  str_homestory_chat_28123008 = "Yinuo sangat sulit dipahami, dan saya bahkan sering tidak tahu di mana letaknya.",
  str_homestory_chat_28123009 = "Apakah itu termasuk memiliki kucing?",
  str_homestory_chat_28124001 = "Apakah Anda ingin membeli sesuatu?",
  str_homestory_chat_28124002 = "Saya ingin mendapatkan beberapa ... potongan menarik untuk kamar saya. Itu akan membuat saya merasa seperti tinggal di Twin Pavilions Bay.",
  str_homestory_chat_28124003 = "Potongan menarik... seperti barang antik? Barang antik Longzhou sulit didapat.",
  str_homestory_chat_28124004 = "Tidak harus barang antik Longzhou. Saya sebenarnya mengharapkan barang antik dari Astra.",
  str_homestory_chat_28124005 = "Seperti pedang dari Lumopolis, Anggur Antik dari Umbraton, Ukiran Tulang dari Northland...",
  str_homestory_chat_28124006 = "Sepertinya Anda adalah pria dengan berbagai minat.",
  str_homestory_chat_28124007 = "Terima kasih. Saya pikir sejak saya di sini, saya harus mencoba menghargai budaya tempat itu.",
  str_homestory_chat_28124008 = "Ini kesempatan bagus untuk mengenal Astra.",
  str_homestory_chat_28124009 = "Aku akan mengawasimu.",
  str_homestory_chat_28125001 = "Ukiran yang berbeda?",
  str_homestory_chat_28125002 = "Ya. Apakah Anda tahu sesuatu tentang mereka?",
  str_homestory_chat_28125003 = "Saya tahu sedikit.",
  str_homestory_chat_28125004 = "Oh? Lalu beri tahu saya, jenis ukiran apa yang ada di benua ini?",
  str_homestory_chat_28125005 = "Sebagian besar terbuat dari batu dan kayu, dan Northland memiliki ukiran tulang.",
  str_homestory_chat_28125006 = "Saya mendengar bahwa Illumina dan Rediesel Wrench memiliki ukiran besi yang langka!",
  str_homestory_chat_28125007 = "Begitu ya, jadi ada begitu banyak... Tapi sepertinya tidak ada ukiran akar.",
  str_homestory_chat_28125008 = "Ukiran akar?",
  str_homestory_chat_28125009 = "Itu adalah sesuatu yang unik di Longzhou. Saya akan menjelaskannya kepada Anda ketika saya memiliki kesempatan.",
  str_homestory_chat_28125010 = "Sekarang aku benar-benar tertarik.",
  str_homestory_chat_28125011 = "Saya tidak mengerti sama sekali...",
  str_homestory_chat_28125012 = "Sayang sekali, kita harus berhenti di sini.",
  str_homestory_chat_28125013 = "Aku merasa perlu mengatakan sesuatu...",
  str_homestory_chat_28299999 = "Ada apa?",
  str_homestory_chat_28221001 = "Anda ingin tahu di mana Anda bisa berenang?",
  str_homestory_chat_28221002 = "Ya, saya menghabiskan terlalu banyak waktu di darat, dan keterampilan berenang saya semakin berkarat.",
  str_homestory_chat_28221003 = "Di Sungai?",
  str_homestory_chat_28221004 = "Itu agak terlalu dangkal, saya pikir. Saya mencari sesuatu yang lebih dalam, sebaiknya dengan ombak.",
  str_homestory_chat_28221005 = "Gelombang dengan besaran yang berbeda-beda, seperti lautan.",
  str_homestory_chat_28221006 = "Jadi mengapa tidak pergi ke pantai dan berenang di laut ...",
  str_homestory_chat_28222001 = "Kau suka makan apa?",
  str_homestory_chat_28222002 = "Anda mungkin tidak menyukai apa yang saya suka. Misalnya mie keong sungai.",
  str_homestory_chat_28222003 = "Tidak apa-apa...",
  str_homestory_chat_28222004 = "Kamu juga menyukainya?! Itu keren!",
  str_homestory_chat_28222005 = "Yah, menurutku itu tidak menjijikkan, tapi aku berusaha untuk tidak memakannya saat ada orang lain di sekitarku.",
  str_homestory_chat_28222006 = "Benar, saya mengerti.",
  str_homestory_chat_28222007 = "Anda sudah cukup berani untuk bisa makan ini. Pahlawan Astra sejati!",
  str_homestory_chat_28222008 = "Yah, itu terlalu banyak ...",
  str_homestory_chat_28222009 = "Kau benar.",
  str_homestory_chat_28222010 = "Itu memang memiliki bau yang sangat menyengat.",
  str_homestory_chat_28222011 = "Saya biasanya memakannya sendirian.",
  str_homestory_chat_28222012 = "Itu sangat perhatian dari Anda!",
  str_homestory_chat_28223001 = "Apakah Anda mencari obat?",
  str_homestory_chat_28223002 = "Ya, untuk mabuk laut. Apakah Anda memiliki?",
  str_homestory_chat_28223003 = "Tidak.",
  str_homestory_chat_28223004 = "Mungkin aku...",
  str_homestory_chat_28223005 = "Tunggu, mengapa Anda membutuhkannya?",
  str_homestory_chat_28223006 = "Bukankah Anda kapten berpengalaman?",
  str_homestory_chat_28223007 = "Itu untuk orang lain, tentu saja. Lebih banyak orang mabuk laut daripada yang Anda kira.",
  str_homestory_chat_28223008 = "Bahkan beberapa pelaut veteran terkadang mendapatkannya.",
  str_homestory_chat_28223009 = "Aku mengerti, aku akan pergi mencari beberapa.",
  str_homestory_chat_28224001 = "Kudengar kau sedang mencari perahu?",
  str_homestory_chat_28224002 = "Ya, saya memikirkan hal ini ketika saya melihat sungai.",
  str_homestory_chat_28224003 = "Cloud Gardens tertutup dari dunia luar, dan seseorang tidak bisa masuk atau keluar melalui pegunungan. Tapi sungai ini tampak seperti bagian yang mulus.",
  str_homestory_chat_28224004 = "Jadi saya bertanya-tanya apakah saya bisa melakukan perdagangan sederhana menggunakan sungai.",
  str_homestory_chat_28224005 = "Tidak.",
  str_homestory_chat_28224006 = "Kenapa?",
  str_homestory_chat_28224007 = "Meskipun bagus dan mulus, Chubbs mengatakan bahwa arusnya cukup tidak menguntungkan di banyak bagian sungai.",
  str_homestory_chat_28224008 = "Dan ada terumbu karang di perairan dangkal yang mudah terbalik dengan perahu.",
  str_homestory_chat_28224009 = "Mungkin saja.",
  str_homestory_chat_28224010 = "Betulkah? Apa kamu yakin?",
  str_homestory_chat_28224011 = "Chubbs mengatakan bahwa air kadang-kadang bisa menjadi sangat rumit.",
  str_homestory_chat_28224012 = "Tapi saya tidak tahu detailnya.",
  str_homestory_chat_28224013 = "Rumit katamu? Sepertinya survei yang tepat diperlukan.",
  str_homestory_chat_28224014 = "Mungkin... Aku melompat sedikit.",
  str_homestory_chat_28225001 = "Pedangmu...",
  str_homestory_chat_28225002 = "Bagaimana dengan itu?",
  str_homestory_chat_28225003 = "Seseorang telah mengajukan keluhan terhadap Anda.",
  str_homestory_chat_28225004 = "Hah? Siapa? Mengapa mereka melakukan itu?",
  str_homestory_chat_28225005 = "Keluarga Chubb. Mereka melihat bahwa Anda selalu mempermainkannya.",
  str_homestory_chat_28225006 = "Dan mereka pikir Anda mungkin menyakiti mereka.",
  str_homestory_chat_28225007 = "Yah, mereka benar.",
  str_homestory_chat_28225008 = "Itu sebabnya saya di sini di Cloud Gardens. Untuk berburu Chubbs.",
  str_homestory_chat_28225009 = "Apakah kamu serius?!",
  str_homestory_chat_28225010 = "Apakah Anda benar-benar percaya itu?",
  str_homestory_chat_28225011 = "Tentu saja tidak!",
  str_homestory_chat_28225012 = "Jadi jangan khawatir tentang itu. Katakan saja kepada mereka bahwa saya tidak bermaksud jahat.",
  str_homestory_chat_28225013 = "Mereka seharusnya tidak takut, karena gelisah dengan pisauku hanyalah kebiasaanku.",
  str_homestory_chat_28225014 = "B-benar.",
  str_homestory_chat_28399999 = "PlayerName, mau coba jamu?",
  str_homestory_chat_28301001 = "Sepertinya Anda menemukan banyak dari mereka!",
  str_homestory_chat_28301002 = "Ya, iklim di sini sangat bagus untuk menanam herba.",
  str_homestory_chat_28301003 = "Banyak tanaman di alam memiliki efek obat.",
  str_homestory_chat_28301004 = "Belum lagi pohon-pohon yang indah ...",
  str_homestory_chat_28301005 = "Apakah Anda ... setelah Pohon Unik sekarang?",
  str_homestory_chat_28301006 = "Belum. Lagipula, keluarga Chubb sangat melindungi mereka.",
  str_homestory_chat_28301007 = "Jadi saya berpikir untuk mentransplantasikan beberapa herbal Longzhou di sini.",
  str_homestory_chat_28301008 = "Itu ide yang bagus.",
  str_homestory_chat_28321001 = "Makanan ringan?",
  str_homestory_chat_28321002 = "Saya sudah makan bubur untuk sementara waktu, jadi saya mencari makanan ringan untuk kembalian.",
  str_homestory_chat_28321003 = "Aku bertanya pada Pedagang Chubb, tapi mereka tidak punya apa-apa!",
  str_homestory_chat_28321004 = "Apakah tidak ada jajanan enak di Astra?",
  str_homestory_chat_28321005 = "Tidak, ada!",
  str_homestory_chat_28321006 = "Terus berbicara.",
  str_homestory_chat_28321007 = "Permen karet dari Northland.",
  str_homestory_chat_28321008 = "Rasanya lembut, tidak terlalu manis, dan tidak lengket di gigi. Aftertaste yang sedikit manis adalah untuk mati untuk.",
  str_homestory_chat_28321009 = "Cokelat dari Umbraton.",
  str_homestory_chat_28321010 = "Cokelat murni benar-benar pahit, sehingga banyak toko menambahkan susu, gula, dan bahkan berbagai jenis kacang ke dalamnya.",
  str_homestory_chat_28321011 = "Seperti hazelnut, kacang pinus, biji ek...",
  str_homestory_chat_28321012 = "Berhenti.",
  str_homestory_chat_28321013 = "Kamu ngiler...",
  str_homestory_chat_28321014 = "Suatu hari, saya akan mencoba semuanya! Tapi untuk saat ini...",
  str_homestory_chat_28321015 = "Saya kira saya akan puas dengan imajinasi saya.",
  str_homestory_chat_28321016 = "Dalam beberapa hal, Anda benar-benar sesuatu.",
  str_homestory_chat_28322001 = "Pabrik baja?",
  str_homestory_chat_28322002 = "Ya, lihat ini.",
  str_homestory_chat_28322003 = "Setelah datang ke Astra, saya menyadari cara Anda menimbang sesuatu berbeda.",
  str_homestory_chat_28322004 = "Anda menggunakan benda di tanah yang memiliki piring di setiap sisinya.",
  str_homestory_chat_28322005 = "Maksudmu skala.",
  str_homestory_chat_28322006 = "Ya, tetapi tidak terlihat sangat portabel, dan Anda membutuhkan permukaan yang rata untuk menggunakannya.",
  str_homestory_chat_28322007 = "Pabrik baja saya jauh lebih mudah digunakan. Mengapa Astra tertinggal dalam hal ini?",
  str_homestory_chat_28322008 = "Sebenarnya, mereka menggunakan pabrik baja di Umbraton.",
  str_homestory_chat_28322009 = "Hah? Apa?",
  str_homestory_chat_28322010 = "Setidaknya Lin Guild, kurasa. Selain itu, timbangan sangat akurat.",
  str_homestory_chat_28322011 = "Steelyards... dapat dipengaruhi oleh orang yang mengoperasikannya.",
  str_homestory_chat_28322012 = "Saya mengerti. Saya kira seperti yang dikatakan Buzi, \"adopsi langkah-langkah yang sesuai dengan kondisi lokal!\"",
  str_homestory_chat_28322013 = "Maksudnya, masing-masing punya kelebihannya.",
  str_homestory_chat_28323001 = "Anda sedang mencari kucing?",
  str_homestory_chat_28323002 = "Nah, lebih tepatnya, saudara laki-laki saya sedang mencari pendamping.",
  str_homestory_chat_28323003 = "Saudaramu?",
  str_homestory_chat_28323004 = "Tinytail! Ngomong-ngomong, apakah Anda punya kucing atau tidak?",
  str_homestory_chat_28323005 = "Tidak di sini, tapi yang datang untuk menginap mungkin membawa satu atau dua.",
  str_homestory_chat_28323006 = "Mengapa Anda tidak bertanya kepada mereka?",
  str_homestory_chat_28323007 = "Tapi mereka dari Astra, dan saya tidak mengenal mereka dengan baik.",
  str_homestory_chat_28323008 = "Anda semua tinggal di sini, itu akan baik-baik saja!",
  str_homestory_chat_28323009 = "B-benarkah?",
  str_homestory_chat_28323010 = "Kau begitu keluar, itu tidak akan menjadi masalah.",
  str_homestory_chat_28323011 = "Saya kira saya harus melakukannya! Saya akan menanyakannya dalam satu atau dua hari.",
  str_homestory_chat_28499999 = "Sepertinya kamu punya banyak waktu luang hari ini, Caelestite kecil.",
  str_homestory_chat_28421001 = "Sepertinya kamu juga begitu.",
  str_homestory_chat_28421002 = "Aku hanya akan jalan-jalan.",
  str_homestory_chat_28421003 = "Jalan-jalan?",
  str_homestory_chat_28421004 = "Karena saya tidak memiliki tugas penting untuk dikerjakan, dan tidak banyak pekerjaan yang harus dilakukan di Cloud Gardens...",
  str_homestory_chat_28421005 = "Belum lagi hampir tidak ada apapun di sekitar sini yang bisa membangkitkan minatku, jadi... Ya.",
  str_homestory_chat_28421006 = "Oke.",
  str_homestory_chat_28422001 = "Anda ingin berbicara tentang makanan?",
  str_homestory_chat_28422002 = "Benar. Aku tidak tahu apa yang ingin kamu makan, Caelestite kecil.",
  str_homestory_chat_28422003 = "Makanan penutup",
  str_homestory_chat_28422004 = "Anda sebenarnya menyukai hal-hal yang manis... Sangat basi.",
  str_homestory_chat_28422005 = "Tapi semua orang suka yang manis-manis, seperti coklat.",
  str_homestory_chat_28422006 = "Namun, cokelat sebenarnya pahit. Alasan Anda menganggapnya manis sebenarnya karena tambahan gula.",
  str_homestory_chat_28422007 = "Jadi... apakah kamu menyukai hal-hal yang pahit?",
  str_homestory_chat_28422008 = "Tidak juga...",
  str_homestory_chat_28422009 = "Daging",
  str_homestory_chat_28422010 = "Selera yang baik! Bagaimana dengan hati? Terutama makanan ringan yang terbuat dari hati...?",
  str_homestory_chat_28422011 = "Erm... Kurasa tidak.",
  str_homestory_chat_28422012 = "Oh, betapa malangnya.",
  str_homestory_chat_28423001 = "Apakah Anda mencari kayu?",
  str_homestory_chat_28423002 = "Ya, saya ingin membangun sarang kecil di kamar saya. Apakah itu tidak apa apa?",
  str_homestory_chat_28423003 = "Tentu.",
  str_homestory_chat_28423004 = "Itu bukan ide yang bagus.",
  str_homestory_chat_28423005 = "Tapi... untuk apa kau membangun sarang?",
  str_homestory_chat_28423006 = "Untuk membuat rumah untuk itu. Tidurnya kurang nyenyak akhir-akhir ini...",
  str_homestory_chat_28423007 = "Siapa itu?",
  str_homestory_chat_28423008 = "Python Suci tentu saja, tidak bisa diharapkan untuk tidur di tempat tidur orang lain setiap malam ...",
  str_homestory_chat_28423009 = "T-Tentu saja tidak! Sungguh pemikiran yang menakutkan...",
  str_homestory_chat_28423010 = "Jadi, tidak apa-apa kalau begitu?",
  str_homestory_chat_28423011 = "Nah... Anda bisa membuatnya di bawah tempat tidur Anda.",
  str_homestory_chat_28424001 = "Buku?",
  str_homestory_chat_28424002 = "Benar. Saya ingin bertanya kepada Anda, Caelestite kecil, apa yang Anda suka baca?",
  str_homestory_chat_28424003 = "Novel.",
  str_homestory_chat_28424004 = "Apa jawaban yang jelas ...",
  str_homestory_chat_28424005 = "Tapi ada begitu banyak novel bagus, terutama semua novel misteri Umbraton...",
  str_homestory_chat_28424006 = "Sepertinya genre ini sangat populer...",
  str_homestory_chat_28424007 = "Biografi.",
  str_homestory_chat_28424008 = "Oh? Menarik... Apakah Anda tertarik dengan sejarah?",
  str_homestory_chat_28424009 = "Saya ingin tahu lebih banyak tentang sejarah Astra.",
  str_homestory_chat_28424010 = "Hei, buku apa yang kamu suka, Jeriah?",
  str_homestory_chat_28424011 = "Filsafat.",
  str_homestory_chat_28424012 = "Astaga!",
  str_homestory_chat_28424013 = "Anda tampak terkejut. Filsafat sebenarnya sangat menarik. Saya akan merekomendasikan beberapa buku kepada Anda ketika saya punya waktu.",
  str_homestory_chat_28424014 = "A-Baiklah.",
  str_homestory_chat_28425001 = "Chubb?",
  str_homestory_chat_28425002 = "Ya. Saya perhatikan bahwa salah satu Chubb benar-benar sangat cerdas.",
  str_homestory_chat_28425003 = "Chubb yang mana?",
  str_homestory_chat_28425004 = "Yang berjanggut di Hyacinth Square.",
  str_homestory_chat_28425005 = "Tetua Chubb?",
  str_homestory_chat_28425006 = "Ya. Itu disebut Penatua, jadi itu pasti bijaksana.",
  str_homestory_chat_28425007 = "Hanya karena ini...?",
  str_homestory_chat_28425008 = "Faktanya, \"Elder\" juga dikenal sebagai \"Beardy\"...",
  str_homestory_chat_28425009 = "Jenggot?",
  str_homestory_chat_28425010 = "Saya pikir itu hanya menempelkan janggut palsu di wajahnya agar terlihat pintar.",
  str_homestory_chat_28425011 = "Umm... aku mengerti.",
  str_homestory_chat_28425012 = "Yah, itu memalukan ...",
  str_homestory_chat_28425013 = "Saya pikir saya harus pergi.",
  str_homestory_chat_28599999 = "Hai, PlayerName. Apa yang terjadi hari ini?",
  str_homestory_chat_28501001 = "Tidak banyak. Kamu baik?",
  str_homestory_chat_28501002 = "Saya ingin mencari pekerjaan paruh waktu di Cloud Gardens.",
  str_homestory_chat_28501003 = "Pekerjaan paruh waktu?",
  str_homestory_chat_28501004 = "Aku sudah bertanya pada Tetua Chubb dan Pedagang Chubb, tapi sepertinya tidak ada yang cocok untukku.",
  str_homestory_chat_28501005 = "Ya, tidak banyak pekerjaan yang tersedia di sini, dan kami semua hanya mengurus urusan kami sendiri.",
  str_homestory_chat_28501006 = "Apakah Anda tidak memiliki pekerjaan pengiriman yang tersedia? Mengirim surat itu penting lho!",
  str_homestory_chat_28501007 = "Tempat ini tidak terlalu besar. Tidak ada pekerjaan pengiriman, plus, orang datang ke sini untuk istirahat dari semua itu.",
  str_homestory_chat_28501008 = "*menghela nafas* Oh sudahlah...",
  str_homestory_chat_28521001 = "Apakah ada sesuatu yang mengganggumu?",
  str_homestory_chat_28521002 = "Ya, dan itu adalah hal yang tidak bisa ditoleransi untuk sesaat.",
  str_homestory_chat_28521003 = "Erm... Gerhana?",
  str_homestory_chat_28521004 = "Semua orang membenci Eclipsites...",
  str_homestory_chat_28521005 = "Orang jahat?",
  str_homestory_chat_28521006 = "Apa artinya itu?",
  str_homestory_chat_28521007 = "Seperti... orang yang menyakiti temanmu.",
  str_homestory_chat_28521008 = "Aku tahu.",
  str_homestory_chat_28521009 = "Jadi, apa yang kamu benci, Kya?",
  str_homestory_chat_28521010 = "Orang yang terlambat!",
  str_homestory_chat_28521011 = "Bagaimana orang bisa tahan untuk tidak tepat waktu? Dan terkadang kita sudah mengatur waktunya terlebih dahulu.",
  str_homestory_chat_28521012 = "Orang yang tidak peduli untuk tepat waktu... semuanya harus diberi pelajaran!",
  str_homestory_chat_28521013 = "Oke…",
  str_homestory_chat_28522001 = "Apakah Anda ingin membeli sesuatu?",
  str_homestory_chat_28522002 = "Ya, saya ingin membeli jam tangan.",
  str_homestory_chat_28522003 = "Tapi kami tidak menjual jam tangan di Cloud Gardens. Apakah Anda yakin Anda berada di tempat yang tepat?",
  str_homestory_chat_28522004 = "Tidak, saya mendengar Anda memiliki layanan khusus di sini.",
  str_homestory_chat_28522005 = "Layanan khusus?",
  str_homestory_chat_28522006 = "Ya, \"Diskon Cloud Gardens\" legendaris yang pernah saya dengar.",
  str_homestory_chat_28522007 = "Ini seharusnya menjadi diskon besar. Ada yang bilang sampai seperempat dari harga biasanya!",
  str_homestory_chat_28522008 = "Itu konyol! Siapa yang memberitahumu itu?",
  str_homestory_chat_28522009 = "Hah? Jadi itu tidak akan berhasil...?",
  str_homestory_chat_28522010 = "Sayang sekali... Saya menemukan jam tangan di Umbraton yang sangat saya sukai...",
  str_homestory_chat_28522011 = "Tapi itu terlalu mahal. Butuh sepuluh tahun untuk membelinya... Dengan diskon, hanya butuh dua setengah tahun...",
  str_homestory_chat_28522012 = "Wow... Anda perlu meminta kenaikan gaji.",
  str_homestory_chat_28522013 = "Itu semua karena Umbraton terlalu mahal! Aku mengutuk para pedagang tak berjiwa itu!",
  str_homestory_chat_28522014 = "Ya!",
  str_homestory_chat_28523001 = "Makanan?",
  str_homestory_chat_28523002 = "Ya, saya bahkan tidak tahu apa yang biasanya Anda suka makan, PlayerName.",
  str_homestory_chat_28523003 = "Hmm... Saya hanya makan apa saja yang ditawarkan.",
  str_homestory_chat_28523004 = "Anda benar-benar tidak peduli?",
  str_homestory_chat_28523005 = "Saya meminum larutan nutrisi yang dibuat Colossus untuk saya selama bertahun-tahun...",
  str_homestory_chat_28523006 = "Jadi... kau tidak benar-benar tahu cara menikmati makanan... tapi kurasa aku juga sama.",
  str_homestory_chat_28523007 = "Oh? Benar-benar?",
  str_homestory_chat_28523008 = "Terkadang saya hanya makan biskuit atau dendeng agar pesanan saya tidak terlambat.",
  str_homestory_chat_28523009 = "Baru setelah saya selesai bekerja saya makan apapun yang saya mau, seperti mie goreng pedas.",
  str_homestory_chat_28523010 = "Sepertinya kamu selalu bekerja keras juga, PlayerName... Tapi mungkin itulah satu-satunya cara kami berhasil mencapai apa yang kami miliki.",
  str_homestory_chat_28523011 = "Erm... Saya pikir Anda benar-benar salah memahami situasi di sana.",
  str_homestory_chat_28699999 = "Kamu terlihat sangat santai, PlayerName.",
  str_homestory_chat_28621001 = "Kau juga.",
  str_homestory_chat_28621002 = "Memang, perasaan ini sangat menenangkan hingga membuatku mengantuk, menguap—",
  str_homestory_chat_28621003 = "Hoamm—",
  str_homestory_chat_28621004 = "Sepertinya kalian sama.",
  str_homestory_chat_28621005 = "Apakah kantuk ini menular?",
  str_homestory_chat_28621006 = "Sangat menarik... Apakah Anda akan tidur siang?",
  str_homestory_chat_28621007 = "Tidak, saya punya tempat lain yang harus saya kunjungi dulu.",
  str_homestory_chat_28621008 = "Saya harap Anda tetap termotivasi saat itu!",
  str_homestory_chat_28622001 = "Tanganmu...",
  str_homestory_chat_28622002 = "Apakah Anda mengacu pada Tangan Ilahi saya?",
  str_homestory_chat_28622003 = "Ya.",
  str_homestory_chat_28622004 = "Oh ceritanya panjang... Anda hanya perlu tahu itu bisa menggunakan Luminatics yang kuat.",
  str_homestory_chat_28622005 = "Oh, begitu…",
  str_homestory_chat_28622006 = "Tidak.",
  str_homestory_chat_28622007 = "Itu tangan kirimu.",
  str_homestory_chat_28622008 = "Tangan kiriku? Tentu, saya juga sering ditanya tentang itu.",
  str_homestory_chat_28622009 = "Itu benar... Tangan kirimu sangat kuat. Apakah itu kekuatan Tangan Ilahi?",
  str_homestory_chat_28622010 = "Oh... Tidak sama sekali. Itu karena saya selalu menggunakan tangan kiri saya.",
  str_homestory_chat_28622011 = "Itu menjadi sangat kuat tanpa saya sadari ...",
  str_homestory_chat_28622012 = "Saya kira ini dianggap sebagai jenis pelatihan tidak langsung.",
  str_homestory_chat_28623001 = "Eclipsite?",
  str_homestory_chat_28623002 = "Tampaknya Eclipsites tidak pernah datang ke sini.",
  str_homestory_chat_28623003 = "Benar.",
  str_homestory_chat_28623004 = "Ini akan menjadi masalah besar jika mereka benar-benar datang ke sini.",
  str_homestory_chat_28623005 = "Eh... Terus gimana cara nemunya...",
  str_homestory_chat_28623006 = "Dia?",
  str_homestory_chat_28623007 = "Oh, eh, tidak apa-apa! Bahkan jika tidak ada Eclipsites, tidak apa-apa untuk bertanya di mana ada jejak Eclipsites, bukan?",
  str_homestory_chat_28623008 = "Apakah Anda tahu sesuatu tentang itu?",
  str_homestory_chat_28623009 = "Either way, tidak ada satu pun di sini, jadi Anda harus menyerah pada ide Anda.",
  str_homestory_chat_28623010 = "Kurasa aku harus bertanya pada Chubbs itu.",
  str_homestory_chat_28623011 = "Mereka juga tidak tahu!",
  str_homestory_chat_28624001 = "Anda ingin berbisnis?",
  str_homestory_chat_28624002 = "Sebenarnya, saya hanya ingin membeli beberapa barang seperti buku.",
  str_homestory_chat_28624003 = "Anda tidak bisa mendapatkannya di sini di Cloud Gardens. Mengapa Anda tidak pergi ke Umbraton?",
  str_homestory_chat_28624004 = "Karena terlalu jauh. Saya hanya ingin melihat apakah ada toko buku terdekat untuk membeli buku secara acak untuk menghabiskan waktu.",
  str_homestory_chat_28624005 = "Bukankah Lumopolis dan Umbraton cukup dekat...?",
  str_homestory_chat_28624006 = "Tapi aku sudah di sini. Apakah Pedagang Chubb memiliki sesuatu untuk dijual?",
  str_homestory_chat_28624007 = "Sejauh yang saya tahu, tidak.",
  str_homestory_chat_28624008 = "Oh? Sepertinya aku hanya bisa... Menguap...",
  str_homestory_chat_28624009 = "Pergi tidur siang. Itu juga cara untuk menghabiskan waktu.",
  str_homestory_chat_28625001 = "Makanan ringan?",
  str_homestory_chat_28625002 = "Ya. Cemilan apa yang suka kamu makan?",
  str_homestory_chat_28625003 = "Kue kecil.",
  str_homestory_chat_28625004 = "Jadi kamu suka yang manis-manis... Apakah kamu merasa tidak enak badan setelah memakannya?",
  str_homestory_chat_28625005 = "TIDAK, Tina. Anda tidak suka hal-hal manis?",
  str_homestory_chat_28625006 = "Kue.",
  str_homestory_chat_28625007 = "Terutama yang sedikit asin karena rasanya sangat enak dengan air panas.",
  str_homestory_chat_28625008 = "Anda telah membuat pilihan yang baik. Cemilan tidak harus manis...",
  str_homestory_chat_28625009 = "Makan camilan dengan berbagai rasa adalah caranya!",
  str_homestory_chat_28625010 = "Sepertinya kamu tidak suka hal-hal manis...",
  str_homestory_chat_28625011 = "Saya membenci mereka karena saya merasa cemas dan sulit tidur setelah memakannya.",
  str_homestory_chat_28625012 = "Sangat menyakitkan untuk bolak-balik di tempat tidur. Apakah Anda tahu seperti apa rasanya?",
  str_homestory_chat_28625013 = "Itu terjadi pada saya sebelumnya. Saya merasa sangat lelah keesokan harinya.",
  str_homestory_chat_28625014 = "Ya, itu sebabnya saya terkadang perlu tidur di siang hari juga.",
  str_homestory_chat_28625015 = "Tapi kamu selalu tidur bahkan saat kamu belum makan apapun yang manis...",
  str_homestory_chat_28999999 = "PlayerName, apa yang Anda perlu saya lakukan?",
  str_homestory_chat_28921001 = "Oh? Mari kita mengobrol santai.",
  str_homestory_chat_28921002 = "Sepertinya Anda sendiri cukup bebas. Apakah Anda ingin mengembangkan beberapa hobi?",
  str_homestory_chat_28921003 = "Misalnya?",
  str_homestory_chat_28921004 = "Cukup bagus untuk menanam bunga.",
  str_homestory_chat_28921005 = "Anda bisa menyaksikan benih yang ditaburkan bertunas dan tumbuh sebelum akhirnya mekar menjadi bunga yang luar biasa...",
  str_homestory_chat_28921006 = "Itu akan membuat Anda mendesah pada keindahan alam.",
  str_homestory_chat_28921007 = "saya sudah menanam pohon...",
  str_homestory_chat_28921008 = "Itu bagus juga. Pertahankan, dan Anda akan terinspirasi suatu hari nanti.",
  str_homestory_chat_28922001 = "Senjatamu...",
  str_homestory_chat_28922002 = "Bagaimana dengan itu?",
  str_homestory_chat_28922003 = "Terkadang itu tidak terlihat seperti senjata, terutama mata bor itu.",
  str_homestory_chat_28922004 = "Saya mengerti. Itu tidak terlihat seperti senjata standar yang digunakan oleh Ksatria Lumo, bukan?",
  str_homestory_chat_28922005 = "Tepat! Dan banyak ksatria menggunakan pedang, tombak, dan lain-lain...",
  str_homestory_chat_28922006 = "Apakah ada alasan untuk ini?",
  str_homestory_chat_28922007 = "Alasannya tidak penting, sama seperti bagaimana senjata yang digunakan ksatria tidak penting.",
  str_homestory_chat_28922008 = "Tidak penting?",
  str_homestory_chat_28922009 = "Karena ksatria ksatria adalah hal yang membuat seorang ksatria siapa mereka.",
  str_homestory_chat_28922010 = "Aku tahu! Seperti yang mereka katakan, kebajikan seorang kesatria meliputi kerendahan hati, toleransi, dan seterusnya...",
  str_homestory_chat_28922011 = "Ya, itulah yang membuat seorang kesatria menjadi kesatria—bukan senjata.",
  str_homestory_chat_28922012 = "Aku mengerti.",
  str_homestory_chat_28923001 = "Apa yang ingin Anda beli?",
  str_homestory_chat_28923002 = "Saya ingin membeli minyak.",
  str_homestory_chat_28923003 = "Minyak apa?",
  str_homestory_chat_28923004 = "Aku harus memiliki beberapa minyak goreng di sekitar sini.",
  str_homestory_chat_28923005 = "Saya membutuhkannya untuk melumasi bagian-bagian. Saya harus bisa mendapatkannya di Umbraton.",
  str_homestory_chat_28923006 = "Hmm…",
  str_homestory_chat_28923007 = "Ada beberapa kesulitan, kan? Maksud saya, ini adalah tempat yang penuh dengan pemandangan alam.",
  str_homestory_chat_28923008 = "Hmm... Memang benar kita tidak terlalu membutuhkannya di sini.",
  str_homestory_chat_28923009 = "Saya terutama ingin menggunakannya untuk melakukan pemeliharaan. Senjataku sepertinya macet akhir-akhir ini.",
  str_homestory_chat_28923010 = "Saya mendengar suara berderit yang membuat gigi saya sakit ketika saya mengayunkannya.",
  str_homestory_chat_28923011 = "Kalau begitu... Mari luangkan waktu untuk pergi ke Umbraton.",
  str_homestory_chat_28924001 = "Apa yang sedang kaupikirkan?",
  str_homestory_chat_28924002 = "Saya sedang memikirkan sesuatu yang sangat penting, tetapi sepertinya saya tidak dapat menemukan jawaban.",
  str_homestory_chat_28924003 = "Mengapa Anda tidak memberitahu saya tentang hal itu?",
  str_homestory_chat_28924004 = "Menurut Anda mana yang lebih penting, keadilan atau kesetaraan?",
  str_homestory_chat_28924005 = "Keadilan.",
  str_homestory_chat_28924006 = "Jadi, apakah Anda setuju bahwa yang kurang beruntung harus memiliki lebih banyak hak?",
  str_homestory_chat_28924007 = "Seperti memberi mereka kekebalan bahkan jika mereka melakukan kejahatan ringan?",
  str_homestory_chat_28924008 = "Coba kuingat...",
  str_homestory_chat_28924009 = "Persamaan.",
  str_homestory_chat_28924010 = "Katakanlah dua pelari bersaing dalam sprint.",
  str_homestory_chat_28924011 = "Yang satu banyak berlatih lari cepat, sedangkan yang lain adalah seorang prajurit dengan kaki patah.",
  str_homestory_chat_28924012 = "Menurut Anda, kriteria menang tidak harus memperhitungkan kondisi fisik keduanya.",
  str_homestory_chat_28924013 = "Ya.",
  str_homestory_chat_28924014 = "Tapi apakah itu benar-benar bagus?",
  str_homestory_chat_28924015 = "Ahhhh! Pertanyaan-pertanyaan ini sangat menjengkelkan, dan saya tidak dapat menemukan jawaban yang tepat.",
  str_homestory_chat_28924016 = "Iya...makanya aku mondar-mandir disini.",
  str_homestory_chat_28925001 = "Rediesel Desert?",
  str_homestory_chat_28925002 = "Saya pernah mendengar bahwa Anda telah bepergian ke banyak tempat. Sudahkah Anda mengunjungi tempat ini?",
  str_homestory_chat_28925003 = "Saya tidak punya banyak kesan tentang tempat ini.",
  str_homestory_chat_28925004 = "Oh… Sayang sekali…",
  str_homestory_chat_28925005 = "Sepertinya Anda pernah ke sana sebelumnya, Leyn?",
  str_homestory_chat_28925006 = "Saya cukup beruntung untuk mengunjunginya beberapa kali. Pemandangan di sana sungguh berbeda dengan Lumopolis.",
  str_homestory_chat_28925007 = "Penduduk di sana melihat hal yang berbeda dari penduduk Lumopolis juga. Tidak peduli betapa sulitnya hidup, tidak ada kekurangan dari mereka yang bangkit untuk kesempatan itu.",
  str_homestory_chat_28925008 = "Sepertinya Anda punya banyak cerita untuk diceritakan tentang pengalaman Anda di Gurun Rediesel...",
  str_homestory_chat_28925009 = "Saya akan memberi tahu Anda tentang hal itu jika saya memiliki kesempatan.",
  str_homestory_chat_28925010 = "Tentu.",
  str_homestory_chat_28925011 = "Apa pendapat Anda tentang budaya dan adat istiadat setempat?",
  str_homestory_chat_28925012 = "Mereka bergairah dan tak terkendali... seperti gurun pasir.",
  str_homestory_chat_28925013 = "Memang. Meskipun saya tidak bisa beradaptasi dengan mereka, saya pikir keberadaan mereka diperlukan untuk tanah ini.",
  str_homestory_chat_28925014 = "Itu sama untuk banyak hal di dunia ini.",
  str_homestory_chat_29099999 = "PlayerName, hari ini adalah hari yang baik untuk berjalan-jalan.",
  str_homestory_chat_29001001 = "Hai, Matthieu.",
  str_homestory_chat_29001002 = "Sepertinya hari ini adalah hari santai lainnya untukmu. Rakyat jelata di sini benar-benar santai.",
  str_homestory_chat_29001003 = "Tidak ada orang biasa di sini. Setiap orang sama.",
  str_homestory_chat_29001004 = "Bagaimana dengan orang-orang persegi itu?",
  str_homestory_chat_29001005 = "Maksudmu Chubbs?",
  str_homestory_chat_29001006 = "Ya, saya melihat mereka bekerja di mana saja sepanjang hari.",
  str_homestory_chat_29001007 = "Beberapa dari mereka adalah pemandu di Menara Hyacinth, sementara yang lain menyirami tanaman atau menghitung sepanjang hari.",
  str_homestory_chat_29001008 = "Itulah yang mereka sukai ...",
  str_homestory_chat_29021001 = "Anda ingin membangun sesuatu?",
  str_homestory_chat_29021002 = "Ya, saya punya lebih banyak uang daripada yang bisa saya belanjakan.",
  str_homestory_chat_29021003 = "Bukan itu maksudku... Bukankah kau tinggal di Lumopolis?",
  str_homestory_chat_29021004 = "Bukankah seharusnya Anda membangun sesuatu di sana?",
  str_homestory_chat_29021005 = "Itu karena ada sesuatu yang tidak bisa kutolerir di sini.",
  str_homestory_chat_29021006 = "Tempat apa itu?",
  str_homestory_chat_29021007 = "Lumpur yang disebabkan oleh hujan! Aku akan membangun atap di atas lembah.",
  str_homestory_chat_29021008 = "Salah satu yang dapat memblokir seluruh langit.",
  str_homestory_chat_29021009 = "Itu sangat besar!",
  str_homestory_chat_29021010 = "Lalu bagaimana dengan kebutuhan pencahayaan kita?",
  str_homestory_chat_29021011 = "Anda tidak perlu khawatir tentang itu. Saya mendengar Anda dapat memasang perangkat yang membuka atap saat cerah dan menutupnya saat hujan.",
  str_homestory_chat_29021012 = "Saya mendengar tentang ini dari anggota Illumina di sini. Rupanya, itulah yang mereka lakukan di Undercities mereka.",
  str_homestory_chat_29021013 = "Saya merasa seperti Anda telah mempelajari beberapa hal aneh ...",
  str_homestory_chat_29021014 = "Jadi Anda setuju kalau begitu! Saya akan membiarkan Anda memperkirakan biayanya.",
  str_homestory_chat_29021015 = "Tunggu! Aku belum menyetujuinya!",
  str_homestory_chat_29022001 = "Peralatan makan?",
  str_homestory_chat_29022002 = "Peralatan makan di sini terlalu kasar. Lihatlah mereka—mereka bahkan membuat makanan yang paling enak menjadi tidak enak.",
  str_homestory_chat_29022003 = "Itu sedikit berlebihan!",
  str_homestory_chat_29022004 = "Aku mengatakan yang sebenarnya. Lihat sendiri jika Anda tidak percaya padaku! Semuanya terbuat dari kayu atau tanah liat.",
  str_homestory_chat_29022005 = "Bahkan tidak ada satu pisau meja perak untuk memotong roti.",
  str_homestory_chat_29022006 = "Anda pasti kelaparan beberapa hari ini...",
  str_homestory_chat_29022007 = "Jadi, bisa tolong ambilkan kami satu set peralatan makan perak?",
  str_homestory_chat_29022008 = "Pertimbangkan untuk membeli satu set teh porselen putih untuk teh sore hari jika Anda bisa.",
  str_homestory_chat_29022009 = "Itu sangat mahal, bukan? Kedengarannya sangat mahal. Apakah Anda tahu berapa kira-kira harganya?",
  str_homestory_chat_29022010 = "Harga? Saya tidak punya ide.",
  str_homestory_chat_29022011 = "Anda tidak tahu harganya tetapi Anda ingin saya membelinya ... Apakah Anda berpikir untuk membuat saya membayarnya terlebih dahulu?",
  str_homestory_chat_29022012 = "Itu diberikan. Anda dapat meminta uang kepada kepala pelayan saya setelah Anda membelinya.",
  str_homestory_chat_29022013 = "Tunggu! Saya belum mengatakan ya!",
  str_homestory_chat_29023001 = "Anda ingin mempekerjakan seorang pelayan?",
  str_homestory_chat_29023002 = "Ya, saya akan menawarkan gaji besar.",
  str_homestory_chat_29023003 = "Yang ingin saya ketahui adalah mengapa Anda tiba-tiba ingin mempekerjakan seorang pelayan.",
  str_homestory_chat_29023004 = "Kami tidak memiliki pelayan di sini.",
  str_homestory_chat_29023005 = "Mengapa Anda tiba-tiba ingin melakukan ini?",
  str_homestory_chat_29023006 = "Itu agar aku bisa membiarkan pelayanku menangani semua hal lain yang muncul.",
  str_homestory_chat_29023007 = "Seorang bangsawan seperti saya harus menghabiskan waktu saya untuk hal-hal yang lebih penting.",
  str_homestory_chat_29023008 = "Seperti mempertimbangkan pengembangan Cloud Gardens atau menjelajahi urat permata terdekat.",
  str_homestory_chat_29023009 = "Saya pikir Anda harus mengalami seperti apa kehidupan biasa ketika Anda berada di sini ...",
  str_homestory_chat_29023010 = "Mungkin... orang-orang persegi itu akan menjadi kandidat yang baik.",
  str_homestory_chat_29023011 = "Keluarga Chubb?",
  str_homestory_chat_29023012 = "Betul!",
  str_homestory_chat_29023013 = "Tidak mungkin!",
  str_homestory_chat_29199999 = "Apakah Anda berpatroli di Cloud Gardens atau hanya berjalan-jalan?",
  str_homestory_chat_29101001 = "Kau sedang apa?",
  str_homestory_chat_29101002 = "Tidak ada sama sekali, jadi hanya melamun.",
  str_homestory_chat_29101003 = "Itu jawaban jujur banget...",
  str_homestory_chat_29101004 = "Saya tidak ada hubungannya, jadi saya nongkrong dan berpikir.",
  str_homestory_chat_29101005 = "Ya, Anda bisa mengambil kesempatan ini untuk sedikit bersantai.",
  str_homestory_chat_29121001 = "Anak-anak?",
  str_homestory_chat_29121002 = "Ya, karena tidak ada anak di sini, agak... terlalu sepi.",
  str_homestory_chat_29121003 = "Ada.",
  str_homestory_chat_29121004 = "Di mana?",
  str_homestory_chat_29121005 = "Orang-orang itu, misalnya, dari Lumopolis, Rediesel Wrench...",
  str_homestory_chat_29121006 = "Mereka harus datang untuk tinggal di Cloud Gardens selama beberapa hari.",
  str_homestory_chat_29121007 = "Maksudmu mereka? Mendesah...",
  str_homestory_chat_29121008 = "Kenapa kau menarik napas begitu?",
  str_homestory_chat_29121009 = "Mereka bukan anak-anak lagi. Mereka mampu mandiri.",
  str_homestory_chat_29121010 = "Itu benar.",
  str_homestory_chat_29121011 = "Benar-benar tidak ada.",
  str_homestory_chat_29121012 = "Mendesah. Aku harus menemui Chubb kalau begitu.",
  str_homestory_chat_29121013 = "Mengapa? Apa yang kamu rencanakan?",
  str_homestory_chat_29121014 = "Tenang, saya hanya akan mengawasi mereka dari jauh dan membantu hanya ketika ada masalah.",
  str_homestory_chat_29121015 = "Seperti tersandung dan jatuh.",
  str_homestory_chat_29121016 = "Kenapa kamu begitu baik?",
  str_homestory_chat_29121017 = "Apa yang Anda maksudkan?",
  str_homestory_chat_29121018 = "Tidak ada apa-apa! Terima kasih!",
  str_homestory_chat_29122001 = "Teka-teki kata?",
  str_homestory_chat_29122002 = "Anda suka teka-teki kata?",
  str_homestory_chat_29122003 = "Ya.",
  str_homestory_chat_29122004 = "Tidak terlalu.",
  str_homestory_chat_29122005 = "Kenapa tanya begitu?",
  str_homestory_chat_29122006 = "Saya bosan dan tidak punya teka-teki kata untuk dipecahkan.",
  str_homestory_chat_29122007 = "Saya pikir Chubb berkacamata akan menyukainya, tetapi yang bisa dipikirkannya hanyalah menghitung kacang.",
  str_homestory_chat_29122008 = "Dan Chubb berjanggut hanya berkeliaran sepanjang hari sepertimu...",
  str_homestory_chat_29122009 = "Ahem, saya sedang memeriksa seluruh Cloud Gardens, bukan bertele-tele.",
  str_homestory_chat_29122010 = "Adapun Anda, Hati, Anda tidak bisa menemukan cara untuk bersantai selain memecahkan teka-teki kata?",
  str_homestory_chat_29122011 = "Itu karena teka-teki kata membebaskan, terutama saat Anda memecahkan teka-teki yang sangat sulit...",
  str_homestory_chat_29122012 = "Anda tidak bisa menggambarkan bagaimana rasanya!",
  str_homestory_chat_29122013 = "Saya pikir Anda harus fokus untuk menenangkan pikiran Anda ...",
  str_homestory_chat_29123001 = "Apa yang kamu dapatkan?",
  str_homestory_chat_29123002 = "Jarum dan benang.",
  str_homestory_chat_29123003 = "Anda pasti sedang menjahit sesuatu. Apakah ada lubang atau sobekan pada pakaian Anda?",
  str_homestory_chat_29123004 = "Anda mungkin memiliki kemampuan psikis yang kuat, tetapi Anda tidak jeli.",
  str_homestory_chat_29123005 = "Apa?",
  str_homestory_chat_29123006 = "Saya harus memperbaiki boneka yang rusak.",
  str_homestory_chat_29123007 = "Anda memperbaiki hal-hal itu?",
  str_homestory_chat_29123008 = "Sesuatu yang salah? Saya juga bisa membuatnya, hanya perlu kain perca, jarum dan benang.",
  str_homestory_chat_29123009 = "Kamu tidak terlihat seperti orang yang...",
  str_homestory_chat_29123010 = "Jadi bagimu, aku adalah seseorang yang seharusnya tidak terlibat dalam hal itu, PlayerName?",
  str_homestory_chat_29123011 = "Itu karena kamu terlihat terlalu keren dan terus terang untuk hal semacam itu.",
  str_homestory_chat_29123012 = "Itu stereotip di pihak Anda.",
  str_homestory_chat_29123013 = "Menjadi keren dan lugas tidak ada hubungannya dengan pembuatan boneka.",
  str_homestory_chat_29123014 = "Benar.",
  str_homestory_chat_29124001 = "Rempah-rempah?",
  str_homestory_chat_29124002 = "Saya ingin beberapa bumbu untuk keperluan bumbu.",
  str_homestory_chat_29124003 = "Kedengarannya bagi saya Anda sedang memasak sesuatu yang lezat.",
  str_homestory_chat_29124004 = "Itu benar, saya sedang membuat rebusan!",
  str_homestory_chat_29124005 = "Rebus!",
  str_homestory_chat_29124006 = "Jadi daging apa yang kamu bawa, khususnya?",
  str_homestory_chat_29124007 = "Daging? Saya tidak punya daging.",
  str_homestory_chat_29124008 = "Apa?",
  str_homestory_chat_29124009 = "Terlalu besar untuk dibawa dan akan membusuk. Apakah ada yang menjual daging di sekitar sini?",
  str_homestory_chat_29124010 = "Eh... Tidak.",
  str_homestory_chat_29124011 = "Lalu kita punya masalah besar, terutama saat saya tidak melihat mangsa dimanapun.",
  str_homestory_chat_29124012 = "Jadi memancing mungkin satu-satunya alternatif? Ganti daging dengan ikan?",
  str_homestory_chat_29124013 = "Bukankah itu akan menjadi hidangan ikan saja?",
  str_homestory_chat_29124014 = "Sup ikan juga baik-baik saja. Ini bisa enak, dan tidak banyak bumbu yang dibutuhkan.",
  str_homestory_chat_29124015 = "Saya merasa Anda mengatasi masalah daging.",
  str_homestory_chat_29399999 = "Kau sibuk?",
  str_homestory_chat_29321001 = "Pelatihan tombak?",
  str_homestory_chat_29321002 = "Saya ingin tahu apakah ada instruktur tombak di Cloud Gardens.",
  str_homestory_chat_29321003 = "Ini adalah tempat yang damai...",
  str_homestory_chat_29321004 = "Itu hanya untuk latihan dan untuk menjaga kebugaran, atau tombaknya akan tumpul.",
  str_homestory_chat_29321005 = "Mengapa Anda berjuang begitu keras ketika Anda hanya di sini selama beberapa hari?",
  str_homestory_chat_29321006 = "Saya tidak bisa berpuas diri! Saya harus menjaga disiplin sebagai bangsawan Lumopolis!",
  str_homestory_chat_29321007 = "Oke, Anda bisa mulai berlatih sendiri, saya kira ...",
  str_homestory_chat_29322001 = "Seseorang mengajukan keluhan tentang Anda.",
  str_homestory_chat_29322002 = "Benar-benar? Siapa ini?",
  str_homestory_chat_29322003 = "Teman sekamarmu.",
  str_homestory_chat_29322004 = "Apakah mereka menganggap latihan tombak harian saya meresahkan?",
  str_homestory_chat_29322005 = "Ya.",
  str_homestory_chat_29322006 = "Masih ada lagi.",
  str_homestory_chat_29322007 = "Apakah mereka menganggap bangun pagi saya menjengkelkan?",
  str_homestory_chat_29322008 = "Itu juga...",
  str_homestory_chat_29322009 = "Jadi maksudmu ada lebih dari itu?",
  str_homestory_chat_29322010 = "Ya, kebanyakan mengeluh tentang bagaimana Anda selalu melipat selimut menjadi kubus yang sempurna.",
  str_homestory_chat_29322011 = "Haruskah seperti itu? Menjijikkan membiarkan mereka tergeletak di tempat tidur!",
  str_homestory_chat_29322012 = "Intinya, Anda tidak bisa menuntut orang lain untuk melakukan hal yang sama.",
  str_homestory_chat_29322013 = "Namun…",
  str_homestory_chat_29322014 = "Bagaimanapun, jangan terlalu ketat dengan orang lain.",
  str_homestory_chat_29323001 = "Apa yang ingin Anda tanyakan pada Chubbs?",
  str_homestory_chat_29323002 = "Saya ingin tahu apakah mereka bisa menjadi pengawal saya.",
  str_homestory_chat_29323003 = "Tidak ada prioritas untuk itu di Cloud Gardens, tetapi Anda dapat melakukannya di Lumopolis?",
  str_homestory_chat_29323004 = "Saya seorang ksatria, oleh karena itu memiliki hak untuk merekrut pengawal. Apakah saya mendapat persetujuan Anda, Master of Cloud Gardens?",
  str_homestory_chat_29323005 = "Ya.",
  str_homestory_chat_29323006 = "Biarkan saya berpikir tentang itu.",
  str_homestory_chat_29323007 = "Tunggu sebentar, apa yang membuatmu ingin mereka menjadi pengawalmu?",
  str_homestory_chat_29323008 = "Karena saya pikir mereka cocok untuk tugas itu!",
  str_homestory_chat_29323009 = "Rahang persegi, dada bidang...",
  str_homestory_chat_29323010 = "Mereka pasti bahan pengawal yang akan mengikuti kebajikan ksatria!",
  str_homestory_chat_29323011 = "Saya pikir Anda salah paham ...",
  str_homestory_chat_29323012 = "Mustahil! Mereka mencarinya dan saya tahu mereka bisa melakukannya!",
  str_homestory_chat_29323013 = "Nah, kalau begitu Anda harus memaafkan penolakan saya karena itu tidak akan berhasil.",
  str_homestory_chat_29324001 = "Opera?",
  str_homestory_chat_29324002 = "Apa kesan Anda tentang opera?",
  str_homestory_chat_29324003 = "Yang cukup bagus.",
  str_homestory_chat_29324004 = "Itu bukan masalah, kalau begitu!",
  str_homestory_chat_29324005 = "Tidak bisa mengatakan saya cukup peduli ...",
  str_homestory_chat_29324006 = "Mendesah. Saya melihat itu akan menjadi masalah.",
  str_homestory_chat_29324007 = "Kau sedang apa?",
  str_homestory_chat_29324008 = "Saya ingin membangun panggung di Cloud Gardens agar saya dapat mengundang rombongan untuk tampil.",
  str_homestory_chat_29324009 = "Jika ada ruang, alangkah baiknya menjadikannya gedung opera yang lengkap, ditambah satu atau dua rombongan penduduk.",
  str_homestory_chat_29324010 = "Lalu kita bisa melihat opera terbaru kapan saja.",
  str_homestory_chat_29324011 = "Eh, saya tidak berpikir itu mungkin ...",
  str_homestory_chat_29999999 = "Hai, bagaimana kabarmu baru-baru ini??",
  str_homestory_chat_29901001 = "Baik dan kamu?",
  str_homestory_chat_29901002 = "Saya telah beradaptasi dengan kehidupan di Cloud Gardens, tetapi saya merasa kecepatan di sini agak lambat.",
  str_homestory_chat_29901003 = "Lambat?",
  str_homestory_chat_29901004 = "Bukankah lebih bagus jika kadang-kadang ada beberapa tantangan di sini, seperti kompetisi penebangan pohon?",
  str_homestory_chat_29901005 = "Mari kita duduk kembali dan bersantai.",
  str_homestory_chat_29921001 = "Minuman?",
  str_homestory_chat_29921002 = "Apa yang akan Anda suka?",
  str_homestory_chat_29921003 = "Kopi",
  str_homestory_chat_29921004 = "Pilihan yang sangat populer. Apakah benar untuk mengatakan bahwa orang lain memiliki pengaruh terhadap Anda?",
  str_homestory_chat_29921005 = "Ya, dan saya sering menganggapnya cukup menyenangkan, membuat kopi untuk diri sendiri dan hal-hal seperti itu...",
  str_homestory_chat_29921006 = "Jika Anda pergi ke kafe, Anda juga bisa mengobrol dengan teman sambil menyeruput kopi.",
  str_homestory_chat_29921007 = "Itu masuk akal.",
  str_homestory_chat_29921008 = "Teh",
  str_homestory_chat_29921009 = "Apa yang kamu suka dari teh? Saya mendengar beberapa teh sangat pahit.",
  str_homestory_chat_29921010 = "Jika Anda menambahkan sedikit sesuatu ke dalamnya, rasanya akan enak. Juga, jika Anda hanya menambahkan daun teh ...",
  str_homestory_chat_29921011 = "Rasa pertama mungkin pahit, tetapi Anda akan merasakan rasa manis yang tak dapat dijelaskan di tenggorokan Anda sesudahnya.",
  str_homestory_chat_29921012 = "Saya dengar itu juga bisa menyegarkan pikiran.",
  str_homestory_chat_29921013 = "Itu benar. Saya sarankan untuk mencobanya lain kali.",
  str_homestory_chat_29921014 = "Jus",
  str_homestory_chat_29921015 = "Jadi, Anda lebih suka rasa alami... Nah, itu masuk akal—Anda seorang Caelestite.",
  str_homestory_chat_29921016 = "Beberapa jus campuran juga bisa sangat enak... Saya rasa saya hanya menyukai sensasi menyegarkannya.",
  str_homestory_chat_29921017 = "Dan itu juga dapat membantu melengkapi berbagai nutrisi, sehingga bermanfaat bagi tubuh Anda. Saya akan mempertimbangkannya lain kali.",
  str_homestory_chat_29921018 = "Benar! Itu hebat!",
  str_homestory_chat_29921019 = "Air soda",
  str_homestory_chat_29921020 = "Anda benar-benar menikmati bersendawa setelah setiap tegukan? Sulit dipercaya!",
  str_homestory_chat_29921021 = "Tidakkah Anda pikir Anda bereaksi berlebihan...?",
  str_homestory_chat_29922001 = "Anda ingin menumbuhkan sesuatu di sini?",
  str_homestory_chat_29922002 = "Saya ingin mulai mengerjakan tambalan di sini di Cloud Gardens dan menanam kacang.",
  str_homestory_chat_29922003 = "Tentu",
  str_homestory_chat_29922004 = "Seharusnya masih ada banyak ruang terbuka di sini... tapi pertama-tama, kita perlu bertanya pada keluarga Chubb.",
  str_homestory_chat_29922005 = "Tidak.",
  str_homestory_chat_29922006 = "Tunggu, kenapa kacang?",
  str_homestory_chat_29922007 = "Menurut penelitian Illumina, kacang ini adalah tanaman yang paling cocok untuk budidaya skala besar, dan memiliki nutrisi yang relatif tinggi.",
  str_homestory_chat_29922008 = "Bagaimana dengan rasanya?",
  str_homestory_chat_29922009 = "Ada banyak sekali rasa dan banyak sekali cara untuk menyiapkan kacang!",
  str_homestory_chat_29922010 = "Saya ingat ada banyak jenis di Umbraton... Saya pikir ada yang disebut tahu.",
  str_homestory_chat_29922011 = "Aku tahu tahu! Kudengar itu dari Timur Jauh—makanan ajaib yang mengubah kacang menjadi keajaiban!",
  str_homestory_chat_29922012 = "Meleleh di mulut, dan tanpa bumbu apapun, masih memiliki rasa kacang alami...",
  str_homestory_chat_29922013 = "Dan itu serbaguna! Entah manis, asin, asam, atau pedas, tahu bisa dipadukan dengan bumbu apa saja!",
  str_homestory_chat_29922014 = "Itu sangat mengesankan...",
  str_homestory_chat_29923001 = "Anda ingin pergi ke Umbraton?",
  str_homestory_chat_29923002 = "Setelah berada di Cloud Gardens begitu lama, saya menyadari bahwa tidak banyak komunikasi antara sini dan Umbraton.",
  str_homestory_chat_29923003 = "Ya, Cloud Gardens adalah tempat yang relatif terpencil.",
  str_homestory_chat_29923004 = "Tapi ini adalah fitur yang cukup unik — pengasingan ini memungkinkan ketenangan yang tidak terganggu.",
  str_homestory_chat_29923005 = "Dan tidak terlalu sulit untuk sampai ke Umbraton dari sini...",
  str_homestory_chat_29923006 = "Saya ingin bisa membeli susu dari Umbraton secara teratur.",
  str_homestory_chat_29923007 = "Susu?",
  str_homestory_chat_29923008 = "Illumina menyediakan jatah susu, tapi tidak ada yang seperti ini di Cloud Gardens, dan sepertinya juga tidak ada toko tempat aku bisa membelinya.",
  str_homestory_chat_29923009 = "Benar. Kalau mau minum susu hanya bisa dari luar.",
  str_homestory_chat_29923010 = "Jika Anda benar-benar menginginkannya, ingatkan saya lain kali saat saya pergi ke Umbraton dan saya akan mengambil beberapa kotak untuk Anda.",
  str_homestory_chat_29923011 = "Tapi Umbraton tidak terlalu dekat, jadi saya khawatir saya tidak akan mencicipi susu segar yang mereka tawarkan ...",
  str_homestory_chat_29923012 = "Kalau begitu... bagaimana dengan yogurt?",
  str_homestory_chat_29923013 = "Tentu, yogurt itu enak!",
  str_homestory_chat_29923014 = "Senang mendengarnya.",
  str_homestory_chat_29924001 = "Sangkar burung?",
  str_homestory_chat_29924002 = "Benar, untuk digantung di jendela atau di atap.",
  str_homestory_chat_29924003 = "Maksud saya... mengapa Anda menginginkan sangkar burung?",
  str_homestory_chat_29924004 = "Untuk Aoha. Saya tidak bisa membiarkannya bertengger di ujung jari saya sepanjang waktu.",
  str_homestory_chat_29924005 = "Terutama ketika saya sedang tidur... Saya merasa tidak ada tempat untuk pergi.",
  str_homestory_chat_29924006 = "Memang terdengar kurang ideal.",
  str_homestory_chat_29924007 = "Jadi, saya ingin memberikan sebuah rumah kecil. Tidak perlu yang besar.",
  str_homestory_chat_29924008 = "Saya telah melihat beberapa sangkar burung kecil di Umbraton. Mereka terlihat cukup sederhana, tapi kayunya...",
  str_homestory_chat_29924009 = "Saya sudah meminta Chubbs untuk membeli beberapa.",
  str_homestory_chat_29924010 = "Tentu saja Anda melakukannya, Yingel. Kamu sangat efisien.",
  str_homestory_chat_29924011 = "Anda setuju dengan saya, ya?",
  str_homestory_chat_29924012 = "Saya tidak melihat alasan mengapa tidak... Selama Anda tidak mengambil ruang orang lain.",
  str_homestory_chat_29924013 = "Sekarang kita perlu mencari tukang kayu...",
  str_homestory_chat_29924014 = "Sepertinya kita masih memiliki cara untuk pergi sebelum selesai.",
  str_homestory_chat_29299999 = "Senang melihatmu.",
  str_homestory_chat_29201001 = "Bagaimana situasinya?",
  str_homestory_chat_29201002 = "Kedamaian, kemakmuran—Taman Awan benar-benar surga. Suatu kehormatan bisa istirahat disini.",
  str_homestory_chat_29201003 = "Nikmatilah, dan bersantailah sepuasnya.",
  str_homestory_chat_29201004 = "Inilah mengapa saya sering berpikir dalam hati bahwa saya juga harus melipatgandakan upaya saya untuk melindungi surga ini.",
  str_homestory_chat_29201005 = "Dan khususnya, kita tidak boleh membiarkan lumpur yang membusuk mencemari tempat ini, sehingga menarik invasi entitas jahat.",
  str_homestory_chat_29201006 = "Terima kasih atas kerja kerasmu.",
  str_homestory_chat_29221001 = "Buah apa yang kamu suka?",
  str_homestory_chat_29221002 = "Kenapa tiba-tiba kau menanyakan itu padaku?",
  str_homestory_chat_29221003 = "Itu muncul begitu saja di kepalaku.",
  str_homestory_chat_29221004 = "Saya suka buah-buahan dari selatan, terutama karena berair, bergizi, dan memiliki banyak variasi rasa.",
  str_homestory_chat_29221005 = "Dan kamu?",
  str_homestory_chat_29221006 = "Apel",
  str_homestory_chat_29221007 = "Itu jenis buah yang sangat umum. apa yang kamu suka tentang mereka?",
  str_homestory_chat_29221008 = "Mungkin karena mereka sangat umum. Selain itu, apel cukup manis dan memiliki tekstur yang renyah.",
  str_homestory_chat_29221009 = "Itu benar. Karena mereka sangat umum, ada banyak cara untuk mempersiapkannya.",
  str_homestory_chat_29221010 = "Saya mendengar bahwa mereka juga bisa dibumbui. Dengan pemikiran ini, mereka memang bisa dianggap sebagai buah yang benar-benar bermanfaat bagi masyarakat.",
  str_homestory_chat_29221011 = "Benar.",
  str_homestory_chat_29221012 = "Anggur",
  str_homestory_chat_29221013 = "Anggur sangat umum, dan telah menjadi sumber minuman yang populer.",
  str_homestory_chat_29221014 = "Misalnya?",
  str_homestory_chat_29221015 = "Orang akan minum anggur saat makan di Lumopolis, dan beberapa minuman ringan di Illumina juga menambahkan jus anggur.",
  str_homestory_chat_29221016 = "Saya juga pernah mendengar bahwa beberapa orang memakan buah anggur kering sebagai makanan ringan di Gurun Rediesel.",
  str_homestory_chat_29221017 = "Kita tidak berbicara tentang minuman lagi, kan?",
  str_homestory_chat_29221018 = "Benar, tapi kismis itu sebenarnya bisa digunakan sebagai bahan pembuat roti manis.",
  str_homestory_chat_29221019 = "Itu sangat menakjubkan.",
  str_homestory_chat_29222001 = "Apa makanan favoritmu?",
  str_homestory_chat_29222002 = "Saya suka makanan panas, terutama daging yang dimasak sederhana tanpa teknik yang rumit.",
  str_homestory_chat_29222003 = "Apa maksudmu?",
  str_homestory_chat_29222004 = "Sederhananya, saya suka daging rebus, dipadukan dengan bumbu favorit saya.",
  str_homestory_chat_29222005 = "Kedengarannya sangat nyaman.",
  str_homestory_chat_29222006 = "Ya—untuk tentara, jenis makanan ini nyaman dan enak, dan dapat dengan cepat memulihkan kekuatan fisik seseorang.",
  str_homestory_chat_29222007 = "Oleh karena itu, penting untuk selalu memperhatikan persediaan daging untuk memastikan selalu tersedia makanan panas di medan pertempuran.",
  str_homestory_chat_29222008 = "Ini juga bisa menjadi masalah yang rumit ...",
  str_homestory_chat_29222009 = "Rumit?",
  str_homestory_chat_29222010 = "Ada banyak hal yang perlu diperhatikan, yang pertama bahan bakar apa yang akan digunakan untuk memasak makanan.",
  str_homestory_chat_29222011 = "Kemudian pertimbangannya mulai dari mengawetkan daging hingga memuaskan selera masing-masing prajurit.",
  str_homestory_chat_29222012 = "Inilah semua hal yang perlu dipertimbangkan oleh para pemimpin, dan satu kesalahan yang dibuat dalam salah satu dari hal ini dapat menyebabkan semangat rendah.",
  str_homestory_chat_29222013 = "Wow... Saya tidak tahu seberapa teliti Anda.",
  str_homestory_chat_29223001 = "Menggambar peta?",
  str_homestory_chat_29223002 = "Ya. Apakah Anda berpengalaman dalam seni kartografi?",
  str_homestory_chat_29223003 = "Saya tahu sedikit.",
  str_homestory_chat_29223004 = "Bagus sekali. Maka saya benar-benar membutuhkan bantuan Anda.",
  str_homestory_chat_29223005 = "Tidak terlalu.",
  str_homestory_chat_29223006 = "Untuk apa Anda menginginkan peta?",
  str_homestory_chat_29223007 = "Saya sudah berada di sini selama beberapa hari, namun saya masih merasakan kegelisahan tertentu di hati saya.",
  str_homestory_chat_29223008 = "Mengapa Anda merasa seperti itu?",
  str_homestory_chat_29223009 = "Setelah banyak perenungan, saya hanya bisa berasumsi bahwa itu karena ketidaktahuan saya dengan Cloud Gardens.",
  str_homestory_chat_29223010 = "Biarkan saya mengatakannya seperti ini — saya tidak begitu akrab dengan tempat ini, dan saya selalu merasa agak tidak aman ketika berada di tempat asing.",
  str_homestory_chat_29223011 = "Anda tidak perlu khawatir tentang orang luar yang datang ke sini. Anda bisa santai.",
  str_homestory_chat_29223012 = "Bagaimanapun... Saya masih merasa seolah-olah saya harus menguasai medan dengan mensurvei dan memetakannya agar merasa nyaman.",
  str_homestory_chat_29223013 = "Benar... Pertahankan kalau begitu.",
  str_homestory_chat_29224001 = "Ingin membeli beberapa senjata?",
  str_homestory_chat_29224002 = "Oh, sepertinya kamu salah paham denganku. Saya ingin bertanya apakah Anda akan mempertimbangkan untuk membangun museum.",
  str_homestory_chat_29224003 = "Sebuah museum?",
  str_homestory_chat_29224004 = "Yang merayakan senjata dunia, seperti tombak panjang Lumopolis dan pedang komando Illumina...",
  str_homestory_chat_29224005 = "Apakah Anda benar-benar perlu membangun museum untuk itu? Sepertinya tidak banyak jenis senjata yang tersedia. Tidak bisakah kita menunjuk ruang koleksi saja?",
  str_homestory_chat_29224006 = "Bukan itu! Bahkan di suatu tempat seperti Illumina, dengan tradisi senjata yang diproduksi secara massal, memiliki banyak model dan variasi!",
  str_homestory_chat_29224007 = "Ada lusinan tombak, pistol, pisau dan belati militer, serta semua senjata jarak dekat, senjata jarak jauh, senjata dingin, dan senjata panas...",
  str_homestory_chat_29224008 = "Selain itu, senjata yang digunakan para bangsawan Lumopolis juga memiliki gaya yang berbeda dan memiliki lambang yang unik.",
  str_homestory_chat_29224009 = "Saya bisa melanjutkan tentang detailnya selamanya. Bagaimanapun, itu sebabnya satu ruang koleksi tidak akan cukup.",
  str_homestory_chat_29224010 = "Jadi, memang ada banyak sekali jenisnya... Tunggu! Apakah Anda memiliki semua senjata ini?",
  str_homestory_chat_29224011 = "Hanya sebagian kecil, tapi itu tidak akan menghalangi saya untuk memulai koleksi dari sekarang.",
  str_homestory_chat_29224012 = "Jadi, Anda tidak punya banyak sekarang... Itu membuat saya merasa sedikit lebih baik.",
  str_homestory_chat_29224013 = "Mempertimbangkan betapa amannya tempat ini, aku seharusnya bisa menyimpan koleksiku dengan aman di sini. Itu sebabnya saya ingin membangun museum persenjataan khusus.",
  str_homestory_chat_29224014 = "Biar kupikirkan dulu.",
  str_homestory_chat_30099999 = "Ada berita hari ini?",
  str_homestory_chat_30021001 = "Hei, apakah kamu punya hobi?",
  str_homestory_chat_30021002 = "Hobi... Mengapa Anda bertanya, PlayerName?",
  str_homestory_chat_30021003 = "Aku hanya ingin tahu, itu saja.",
  str_homestory_chat_30021004 = "Mungkin observasi adalah satu-satunya hobiku... Bagaimana denganmu?",
  str_homestory_chat_30021005 = "Saya tidak benar-benar punya hobi.",
  str_homestory_chat_30021006 = "Sebenarnya, saya tidak begitu yakin.",
  str_homestory_chat_30021007 = "Mungkin itu ... berjalan?",
  str_homestory_chat_30021008 = "Tunggu, bukankah aku yang bertanya padamu?",
  str_homestory_chat_30021009 = "Dan itulah jawaban saya.",
  str_homestory_chat_30021010 = "Jadi... hobimu mengumpulkan intelijen...?",
  str_homestory_chat_30022001 = "Anda tampaknya menikmati membuat catatan.",
  str_homestory_chat_30022002 = "Itu benar. Seperti kata pepatah, \"rekor yang buruk lebih baik daripada pikiran yang cemerlang.\"",
  str_homestory_chat_30022003 = "Aku selalu melihatmu menulis dan menggambar. Itu terlihat melelahkan.",
  str_homestory_chat_30022004 = "Saya sudah terbiasa — dan saya memiliki senjata rahasia saya.",
  str_homestory_chat_30022005 = "Senjata rahasia?",
  str_homestory_chat_30022006 = "Ini disebut steno.",
  str_homestory_chat_30022007 = "Kedengarannya kuat... seperti semacam teknik rahasia yang tidak bisa diwariskan.",
  str_homestory_chat_30022008 = "Anda perlu menghafal banyak singkatan, mnemonik, simbol, dan sebagainya, bukan?",
  str_homestory_chat_30022009 = "Erm, tidak juga. Bahkan, metode steno terutama dikembangkan berdasarkan kebiasaan menulis individu itu sendiri.",
  str_homestory_chat_30022010 = "Hah?",
  str_homestory_chat_30022011 = "Dalam banyak kasus, singkatan yang sesuai hanya perlu Anda pahami sendiri, karena pada akhirnya Anda tetap akan menulis singkatan yang tepat.",
  str_homestory_chat_30022012 = "Aku tahu.",
  str_homestory_chat_30023001 = "Saya mendengar Anda ingin membeli sesuatu?",
  str_homestory_chat_30023002 = "Saya ingin membeli teleskop untuk observasi.",
  str_homestory_chat_30023003 = "Apakah Anda senang mengamati binatang atau tumbuhan?",
  str_homestory_chat_30023004 = "Ah... Itu bagian dari itu.",
  str_homestory_chat_30023005 = "Bagian dari itu?",
  str_homestory_chat_30023006 = "Kecerdasan yang dikumpulkan pada hewan dan tumbuhan hanya dapat dianggap tambahan sampai batas tertentu...",
  str_homestory_chat_30023007 = "Saya terutama mengamati aktivitas sehari-hari di Cloud Gardens, seperti kehidupan Chubbs...",
  str_homestory_chat_30023008 = "Mereka lagi...",
  str_homestory_chat_30023009 = "Lagi?",
  str_homestory_chat_30023010 = "Tampaknya banyak orang tertarik pada mereka hari ini.",
  str_homestory_chat_30023011 = "Karena, tidak seperti kita, mereka asli tempat ini.",
  str_homestory_chat_30023012 = "Semakin banyak saya belajar, semakin banyak yang saya ketahui tentang Cloud Gardens, yang secara alami akan berguna bagi Anda.",
  str_homestory_chat_30023013 = "Saya pikir... masih lebih baik menghabiskan waktu bersantai sebanyak yang Anda bisa.",
  str_homestory_chat_30024001 = "Memelihara ikan?",
  str_homestory_chat_30024002 = "Tempat ini rasanya akan sangat cocok untuk budidaya ikan. Apakah Anda memiliki kolam ikan?",
  str_homestory_chat_30024003 = "Kami punya satu di sini.",
  str_homestory_chat_30024004 = "Tidak saat ini...",
  str_homestory_chat_30024005 = "Jadi, Anda ingin memelihara ikan?",
  str_homestory_chat_30024006 = "Ya. Ketika saya melihat kolam di alun-alun, tiba-tiba saya berpikir memelihara ikan di Cloud Gardens mungkin bagus.",
  str_homestory_chat_30024007 = "Namun, ikan yang saya suka cukup aneh dan saya ingin membesarkannya secara terpisah.",
  str_homestory_chat_30024008 = "Apakah Anda berbicara tentang gelembung? Tampaknya agak berbahaya.",
  str_homestory_chat_30024009 = "Jangan khawatir tentang itu, itu hanya makhluk biasa. Perhatian utama saya adalah tidak cocok untuk dibesarkan dalam kelompok, jadi saya ingin membesarkannya secara terpisah.",
  str_homestory_chat_30024010 = "Dimengerti... Saya akan memeriksanya.",
  str_homestory_chat_30299999 = "Apakah Anda mensurvei wilayah Anda lagi?",
  str_homestory_chat_30221001 = "Hanya pergi jalan-jalan.",
  str_homestory_chat_30221002 = "Pernahkah Anda memikirkan masalah keamanan di sini?",
  str_homestory_chat_30221003 = "Ya.",
  str_homestory_chat_30221004 = "Itulah yang harus dilakukan oleh seorang pemilik! Apa kesimpulan Anda?",
  str_homestory_chat_30221005 = "Saya memeriksa, dan mengingat medan Taman, tidak apa-apa.",
  str_homestory_chat_30221006 = "Tetap sama...? Saya merasa itu agak longgar. Anda harus meningkatkan langkah-langkah keamanan.",
  str_homestory_chat_30221007 = "Saya akan mempertimbangkannya.",
  str_homestory_chat_30221008 = "Tidak.",
  str_homestory_chat_30221009 = "Ini terlalu puas!",
  str_homestory_chat_30221010 = "Nah, ini adalah tempat yang sangat sulit ditemukan, dan semua orang datang ke sini untuk bersantai.",
  str_homestory_chat_30221011 = "Tidak perlu meributkan masalah keamanan.",
  str_homestory_chat_30221012 = "Yakin?",
  str_homestory_chat_30221013 = "Ya, itu bukan masalah!",
  str_homestory_chat_30221014 = "Bagaimana dengan Anda, apakah Anda sudah memikirkannya?",
  str_homestory_chat_30221015 = "Saya telah melakukan beberapa putaran selama beberapa hari terakhir, dan aman menurut standar normal.",
  str_homestory_chat_30221016 = "Aku lega mendengarmu berkata begitu.",
  str_homestory_chat_30221017 = "Tapi tetap saja, jangan lengah karena seseorang tidak akan pernah bisa terlalu berhati-hati...",
  str_homestory_chat_30221018 = "A-Baiklah.",
  str_homestory_chat_30221019 = "Tidak perlu untuk itu.",
  str_homestory_chat_30221020 = "Bagaimana Anda bisa begitu puas diri? Pernahkah Anda memikirkannya dengan serius?",
  str_homestory_chat_30221021 = "Baiklah, saya akan memeriksanya secara detail.",
  str_homestory_chat_30222001 = "Saya sedang memikirkan Eraveil.",
  str_homestory_chat_30222002 = "Sepertinya Anda akhirnya memikirkan bagaimana mengatur negeri ini!",
  str_homestory_chat_30222003 = "Ya.",
  str_homestory_chat_30222004 = "Meskipun saya belum membuat banyak kemajuan.",
  str_homestory_chat_30222005 = "Ah, belum.",
  str_homestory_chat_30222006 = "Apakah Anda punya ide atau saran?",
  str_homestory_chat_30222007 = "Yang terbaik adalah menugaskan penduduk setempat untuk mengawasi.",
  str_homestory_chat_30222008 = "Oleh penduduk setempat, maksudmu...",
  str_homestory_chat_30222009 = "Keluarga Chubb, tentu saja.",
  str_homestory_chat_30222010 = "Itu masuk akal.",
  str_homestory_chat_30223001 = "Sebenarnya...",
  str_homestory_chat_30223002 = "Ini hari yang menyenangkan hari ini, jadi saya memutuskan untuk berjalan-jalan.",
  str_homestory_chat_30223003 = "Saya melihat Anda suka berjalan-jalan dalam cuaca yang bagus. Itu menjernihkan pikiran.",
  str_homestory_chat_30223004 = "Jalan-jalan santai di lingkungan yang damai di hari yang cerah kondusif untuk berpikir.",
  str_homestory_chat_30223005 = "Atau Anda bahkan tidak perlu berpikir dan santai saja, santai saja.",
  str_homestory_chat_30223006 = "Bagaimanapun, intinya adalah menikmati lingkungan yang santai di sini.",
  str_homestory_chat_30223007 = "Lingkungannya memang santai, tapi saya tidak terbiasa dengan ini.",
  str_homestory_chat_30223008 = "Mengapa demikian?",
  str_homestory_chat_30223009 = "Di Lumopolis, meski cerah dan cerah, saya merasa bahu saya terbebani.",
  str_homestory_chat_30223010 = "Dan itu namanya tanggung jawab, yang juga membuat saya merenung tanpa henti.",
  str_homestory_chat_30223011 = "Itu pasti beban yang berat. Anda harus tenang sekarang karena Anda di sini.",
  str_homestory_chat_30223012 = "Tidak, itu adalah baju besi yang dapat melindungi saya dan mengasah saya untuk menghadapi tantangan.",
  str_homestory_chat_30223013 = "Uh, mungkin kau seharusnya tidak terlalu tegang...",
  str_homestory_chat_30224001 = "Saya memikirkan buku yang saya baca beberapa hari yang lalu.",
  str_homestory_chat_30224002 = "Ada apa?",
  str_homestory_chat_30224003 = "Novel misteri",
  str_homestory_chat_30224004 = "Ini sangat populer di Umbraton akhir-akhir ini dan aspek asmara sangat menarik...",
  str_homestory_chat_30224005 = "Sebuah novel, katamu? Fiksi hanya bagus untuk relaksasi. Mereka berisi pengetahuan yang sangat terbatas untuk Anda peroleh.",
  str_homestory_chat_30224006 = "Jika Anda benar-benar ingin membaca, Anda harus memilih buku sejarah.",
  str_homestory_chat_30224007 = "Buku sejarah",
  str_homestory_chat_30224008 = "Pilihan bagus.",
  str_homestory_chat_30224009 = "Kamu suka membaca buku sejarah juga?",
  str_homestory_chat_30224010 = "Benar.",
  str_homestory_chat_30224011 = "Itu didasarkan pada fakta bagi Anda untuk meninjau masa lalu dan bahkan memprediksi masa depan.",
  str_homestory_chat_30224012 = "Meskipun ramalan agak hiperbola, setidaknya Anda bisa mendapatkan banyak pengetahuan.",
  str_homestory_chat_30224013 = "Ini jauh lebih bermanfaat secara intelektual daripada dongeng yang dibuat-buat.",
  str_homestory_chat_30224014 = "Tentu, saya akan membaca lebih lanjut.",
  str_homestory_chat_30225001 = "Ya.",
  str_homestory_chat_30225002 = "\"Jangan pernah berhenti menabur, baik siang maupun malam.\"",
  str_homestory_chat_30225003 = "Tempat apa itu?",
  str_homestory_chat_30225004 = "Itu adalah pepatah Lumopolis, artinya seseorang harus bekerja keras sepanjang waktu. Anda melakukannya, dan saya harap Anda dapat mempertahankan sikap itu.",
  str_homestory_chat_30225005 = "Baiklah.",
  str_homestory_chat_30225006 = "Dalam hal ini, saya dapat mempertimbangkan untuk memberi Anda gelar. Akan menjadi keberuntungan Lumopolis untuk memiliki lebih banyak bangsawan sepertimu.",
  str_homestory_chat_30225007 = "Sungguh?",
  str_homestory_chat_30225008 = "Ini adalah lelucon, jelas.",
  str_homestory_chat_30225009 = "Oh, sudahlah, kalau begitu.",
  str_homestory_chat_30199999 = "Kamu sendiri juga?",
  str_homestory_chat_30121001 = "Ya.",
  str_homestory_chat_30121002 = "Aku lihat kamu juga suka sendirian...",
  str_homestory_chat_30121003 = "Sebenarnya, aku hanya jalan-jalan karena ini hari yang menyenangkan, dan tidak ada yang lebih baik untuk dilakukan.",
  str_homestory_chat_30121004 = "Jadi Anda menghabiskan waktu luang Anda dengan berjalan-jalan? Sepertinya kamu sangat menyukainya.",
  str_homestory_chat_30121005 = "Atau kamu punya hobi solo lainnya?",
  str_homestory_chat_30121006 = "Nah, jalan-jalan hanyalah salah satu pilihan. Saya juga terkadang suka hang out dengan teman-teman.",
  str_homestory_chat_30121007 = "O-oh, baiklah...",
  str_homestory_chat_30122001 = "Tidak.",
  str_homestory_chat_30122002 = "Jadi dimana teman-temanmu?",
  str_homestory_chat_30122003 = "A-Yang kumaksud adalah aku ingin jalan-jalan dengan seseorang dan bertemu denganmu.",
  str_homestory_chat_30122004 = "Saya kira Anda suka jalan-jalan dan mengobrol.",
  str_homestory_chat_30122005 = "Ya, sebenarnya.",
  str_homestory_chat_30122006 = "Terkadang saya terdorong untuk mengobrol... Apakah Anda juga mengerti?",
  str_homestory_chat_30122007 = "Saya merasa seperti itu.",
  str_homestory_chat_30122008 = "Ah, saya pikir Anda hanya suka sendirian.",
  str_homestory_chat_30122009 = "Itu benar, tetapi seperti Anda, saya ingin berbicara dengan orang lain sesekali.",
  str_homestory_chat_30122010 = "Kadang-kadang, saya kira.",
  str_homestory_chat_30122011 = "Oh? Saya pikir Anda suka mengobrol.",
  str_homestory_chat_30122012 = "Tidak terlalu. Terkadang saya lebih suka menyendiri, di lain waktu saya ingin mengobrol.",
  str_homestory_chat_30122013 = "Itu semua tergantung mood saya saat itu. Bagaimana denganmu?",
  str_homestory_chat_30122014 = "Saya lebih suka menyendiri hampir sepanjang waktu, tetapi saya ingin berbicara sesekali, seperti Anda.",
  str_homestory_chat_30122015 = "Khususnya untuk dia... Aku selalu yakin banyak yang ingin kukatakan padanya jika aku pernah bertemu dengannya.",
  str_homestory_chat_30122016 = "Saya harap Anda melakukannya.",
  str_homestory_chat_30123001 = "Sedang apa kau?",
  str_homestory_chat_30123002 = "Berpikir tentang bagaimana saya akan membuat Teh Hitam Knight di sini.",
  str_homestory_chat_30123003 = "Teh Hitam Ksatria?",
  str_homestory_chat_30123004 = "Ini minuman di Lumopolis, sangat populer.",
  str_homestory_chat_30123005 = "Saya mendengarnya, meskipun bahannya sulit untuk ditangani.",
  str_homestory_chat_30123006 = "Itu benar. Anda membutuhkan teh impor...",
  str_homestory_chat_30123007 = "Serta teaware berkualitas tinggi, teknik halus, dan penyesuaian rasa.",
  str_homestory_chat_30123008 = "Membuat secangkir Teh Hitam Knight yang enak mungkin membutuhkan waktu sepanjang sore.",
  str_homestory_chat_30123009 = "Itu waktu yang lama!",
  str_homestory_chat_30123010 = "Ya, ini teh sore.",
  str_homestory_chat_30123011 = "Kalau buat pagi, siangnya bisa diminum kan?",
  str_homestory_chat_30123012 = "Tapi itu akan menjadi teh siang, kalau begitu? Atau teh pagi jika lebih awal?",
  str_homestory_chat_30123013 = "Pikiran itu tidak pernah terlintas di benakku...",
  str_homestory_chat_30124001 = "Game apa yang suka kamu mainkan?",
  str_homestory_chat_30124002 = "Jenis solo...",
  str_homestory_chat_30124003 = "Game tunggal? Catur dengan dirimu sendiri? Atau sekedar jalan-jalan?",
  str_homestory_chat_30124004 = "Saya terkadang bermain poker sendiri. Apa yang kamu lakukan saat sendirian?",
  str_homestory_chat_30124005 = "Memancing.",
  str_homestory_chat_30124006 = "Itu kegiatan yang bagus. Saya mendengar itu sangat menenangkan.",
  str_homestory_chat_30124007 = "Mendengar? Anda belum pernah memancing sebelumnya?",
  str_homestory_chat_30124008 = "Saya tidak mendapatkan banyak kesempatan untuk mencoba, atau bahkan banyak kesempatan untuk keluar.",
  str_homestory_chat_30124009 = "Anda harus menikmatinya di sini, kalau begitu.",
  str_homestory_chat_30124010 = "Bermain kartu?",
  str_homestory_chat_30124011 = "Berbicara tentang bermain kartu, beri tahu saya cara bermain poker sendirian.",
  str_homestory_chat_30124012 = "Aturannya... agak rumit. Akan kutunjukkan saat kita mendapat kesempatan.",
  str_homestory_chat_30124013 = "Baiklah.",
  str_homestory_chat_30125001 = "Bagaimana kondisimu?",
  str_homestory_chat_30125002 = "Rasanya luar biasa di sini, terutama saat saya bisa keluar di siang hari.",
  str_homestory_chat_30125003 = "Keluar di siang hari?",
  str_homestory_chat_30125004 = "Ya, karena statusku...",
  str_homestory_chat_30125005 = "Kena kau.",
  str_homestory_chat_30125006 = "Tapi tetap beda dengan yang sejenis Umbraton kan?",
  str_homestory_chat_30125007 = "Ya... Tidak banyak jalan dan tidak ada toko.",
  str_homestory_chat_30125008 = "Apakah itu membosankan bagimu?",
  str_homestory_chat_30125009 = "Tidak, tidak sama sekali.",
  str_homestory_chat_30125010 = "Agak hambar, tapi pemandangan alamnya sangat bagus.",
  str_homestory_chat_30125011 = "Mendengar kicauan burung, menatap sungai berkilauan di bawah matahari...",
  str_homestory_chat_30125012 = "Kedengarannya agak dipaksakan... Aku akan meminta Chubbs untuk memesan lebih banyak merchandise lain kali.",
  str_homestory_chat_30125013 = "Fountain of Hope, Hyacinth Tower, dan Museum juga cukup menyenangkan untuk dikunjungi...",
  str_homestory_chat_30125014 = "OK saya mengerti...",
  str_homestory_chat_30399999 = "Ingin ramalan?",
  str_homestory_chat_30321001 = "saya ingin tahu...",
  str_homestory_chat_30321002 = "Baiklah, bekerja, akhirnya! Mau baca apa?",
  str_homestory_chat_30321003 = "Karier",
  str_homestory_chat_30321004 = "Uang",
  str_homestory_chat_30321005 = "Percintaan",
  str_homestory_chat_30321006 = "Diputuskan? Mari kita mulai!",
  str_homestory_chat_30321007 = "Tunggu, bukan itu yang aku inginkan...",
  str_homestory_chat_30321008 = "Lalu apa itu? Saya siap untuk pergi.",
  str_homestory_chat_30321009 = "Aku hanya ingin tahu apakah ramalan itu benar-benar berhasil.",
  str_homestory_chat_30321010 = "Apa yang Anda maksudkan? Saya sudah berlatih sejak saya masih sangat kecil!",
  str_homestory_chat_30321011 = "J-Jadi kamu seharusnya bisa mengetahui masa depan, kan? Anda bisa melakukan ramalan untuk semuanya.",
  str_homestory_chat_30321012 = "Tidak terlalu. Pertama, setting dan timing harus pas, baru butuh inspirasi...",
  str_homestory_chat_30321013 = "Dan keberuntungan adalah faktor terbesar, karena saya gagal mendapatkan hasil beberapa kali!",
  str_homestory_chat_30321014 = "Dengan kata lain, ramalan bisa gagal!",
  str_homestory_chat_30321015 = "Aku tahu.",
  str_homestory_chat_30323001 = "Aku tidak membutuhkannya sekarang, kalau begitu...",
  str_homestory_chat_30323002 = "Tapi saya terinspirasi dan Anda baru saja merusaknya.",
  str_homestory_chat_30323003 = "Oh, maaf.",
  str_homestory_chat_30323004 = "Harus mencari tahu desain untuk pakaian keluarga baru.",
  str_homestory_chat_30323005 = "Pakaian keluarga?",
  str_homestory_chat_30323006 = "Ini untuk Whisper. Kita harus memakai pakaian yang serasi.",
  str_homestory_chat_30323007 = "I-Itu butuh pakaian juga?",
  str_homestory_chat_30323008 = "Ya. Whisper mungkin sakit saat cuaca dingin.",
  str_homestory_chat_30323009 = "Mengenakan sesuatu bisa membuatnya tetap hangat, belum lagi busana yang serasi!",
  str_homestory_chat_30323010 = "Menakjubkan! Tapi untuk pakaian Whisper...",
  str_homestory_chat_30323011 = "Terserah saya untuk mendesain dan menjahit!",
  str_homestory_chat_30322001 = "Kudengar kau suka cerita?",
  str_homestory_chat_30322002 = "Ya, terutama saat meramal!",
  str_homestory_chat_30322003 = "Anda membutuhkan itu untuk ramalan Anda?",
  str_homestory_chat_30322004 = "Saya perlu mendapatkan perhatian penuh klien agar mereka dapat mendengarkan setiap kata yang saya ucapkan.",
  str_homestory_chat_30322005 = "Bahkan jika ramalan gagal, klien tidak akan merasa itu hanya membuang-buang uang!",
  str_homestory_chat_30322006 = "Bukankah itu hampir seperti... penipuan?",
  str_homestory_chat_30322007 = "Sama sekali tidak! Kisah-kisah menarik sangat berharga!",
  str_homestory_chat_30322008 = "Makanya saya ajak bicara Louise banyak, aku bahkan membawanya ke banyak tempat untuk itu!",
  str_homestory_chat_30322009 = "Louise?",
  str_homestory_chat_30322010 = "Ya, dia juga dari Northland, dan pendongeng yang hebat.",
  str_homestory_chat_30322011 = "Saya pikir kalian berdua mungkin memenuhi syarat untuk menulis novel di Umbraton sekarang...",
  str_homestory_chat_30324001 = "Apakah Anda mencoba menemukan batu?",
  str_homestory_chat_30324002 = "Ya. Anda tahu di mana bebatuan yang terlihat bagus itu?",
  str_homestory_chat_30324003 = "Di tepi sungai.",
  str_homestory_chat_30324004 = "Di hutan.",
  str_homestory_chat_30324005 = "Trims!",
  str_homestory_chat_30324006 = "Apakah batu untuk ramalan Anda?",
  str_homestory_chat_30324007 = "Tidak, tidak, hanya untuk aksesoris fashion.",
  str_homestory_chat_30324008 = "Keluarga Chubb tampak begitu membosankan berjalan-jalan dengan pakaian putih polos setiap hari.",
  str_homestory_chat_30324009 = "Saya mengerti itu sederhana, tetapi bukankah mereka akan terlihat lebih baik dengan kalung yang terbuat dari batu berwarna-warni?",
  str_homestory_chat_30324010 = "Tapi Anda belum bertanya kepada mereka!",
  str_homestory_chat_30324011 = "Tidak apa-apa, mereka akan menyukainya!",
  str_homestory_chat_30324012 = "A-Apakah kamu yakin tentang itu...?",
  str_homestory_chat_30499999 = "Kita bertemu lagi. Anda pasti pekerja keras.",
  str_homestory_chat_30421001 = "Ya, hanya berkeliling.",
  str_homestory_chat_30421002 = "Saya mendengar Anda bepergian dengan baik. Menurut Anda di mana tempat yang cocok untuk tinggal di pengasingan?",
  str_homestory_chat_30421003 = "Hidup dalam pengasingan? Maksudmu tempat di mana kamu bisa tinggal sendirian?",
  str_homestory_chat_30421004 = "Tidak sepenuhnya akurat. Lebih disukai, tidak mencolok tetapi masih dengan tetangga di sekitar.",
  str_homestory_chat_30421005 = "Hm, biar kupikir...",
  str_homestory_chat_30421006 = "Umbraton.",
  str_homestory_chat_30421007 = "Saya ingat ungkapan itu — bersembunyi di depan mata.",
  str_homestory_chat_30421008 = "Jadi saat ramai dengan berbagai macam orang, tidak ada yang akan memperhatikan Anda.",
  str_homestory_chat_30421009 = "Itu pilihan untuk dipertimbangkan.",
  str_homestory_chat_30421010 = "Utara.",
  str_homestory_chat_30421011 = "Di dasar Tulang Belakang Dunia...?",
  str_homestory_chat_30421012 = "Dingin, sepi, terpencil. Tujuan yang bagus.",
  str_homestory_chat_30421013 = "Lebih sedikit orang di sana, sehingga tanahnya jarang penduduknya dan agak tertutup.",
  str_homestory_chat_30421014 = "Saya rasa itulah harga untuk keamanan dan privasi...",
  str_homestory_chat_30421015 = "Kunci pas diesel.",
  str_homestory_chat_30421016 = "Apa? Bukankah itu sekelompok liar, pengembara pengembara?",
  str_homestory_chat_30421017 = "Ya, tapi mereka juga seharusnya memiliki banyak orang dari faksi yang berbeda.",
  str_homestory_chat_30421018 = "Dan begitu Anda bergabung dan terbiasa dengan kebiasaan, mereka adalah orang-orang hebat.",
  str_homestory_chat_30421019 = "Kedengarannya tidak terlalu buruk.",
  str_homestory_chat_30421020 = "Kota kecil.",
  str_homestory_chat_30421021 = "Anda dapat menemukannya hampir di mana saja, jadi itu mungkin opsi terakhir.",
  str_homestory_chat_30421022 = "Benar.",
  str_homestory_chat_30422001 = "Sepertinya kamu sering tersenyum.",
  str_homestory_chat_30422002 = "Itu karena saya suka di sini.",
  str_homestory_chat_30422003 = "Terima kasih.",
  str_homestory_chat_30422004 = "Pemandangannya tidak luar biasa, tapi sangat nyaman dan tenteram bagi saya.",
  str_homestory_chat_30422005 = "Rasanya sulit ditemukan di tempat lain.",
  str_homestory_chat_30422006 = "Mungkin karena di sini lebih terpencil?",
  str_homestory_chat_30422007 = "Tidak, ini suasana hati secara keseluruhan, terutama sikapnya.",
  str_homestory_chat_30422008 = "Senyuman di wajah semua orang, dan Chubbs yang santai itu...",
  str_homestory_chat_30422009 = "Gelandangan malas itu... apakah mereka bermain-main lagi?",
  str_homestory_chat_30422010 = "Anda kehilangan intinya, Nak.",
  str_homestory_chat_30423001 = "Anda bangun sangat awal.",
  str_homestory_chat_30423002 = "Karena saya harus membereskan tempat tidur.",
  str_homestory_chat_30423003 = "Rapihkan tempat tidur? Sendiri?",
  str_homestory_chat_30423004 = "Ya, ada apa?",
  str_homestory_chat_30423005 = "Aku hanya tidak berpikir kamu akan melakukan pekerjaan rumah seperti ini.",
  str_homestory_chat_30423006 = "Apakah Anda merasa seperti itu karena siapa saya?",
  str_homestory_chat_30423007 = "Anu…",
  str_homestory_chat_30423008 = "Bukan apa-apa, saya melakukannya terutama karena saya suka merapikan tempat tidur untuk anak-anak.",
  str_homestory_chat_30423009 = "Kadang-kadang, ketika saya bangun di pagi hari, saya mulai melakukannya karena kebiasaan, meskipun mereka masih di tempat tidur.",
  str_homestory_chat_30423010 = "Jadi mereka tidak punya pilihan selain bangun pagi, dan terkadang mengeluh.",
  str_homestory_chat_30423011 = "Aku bisa membayangkan.",
  str_homestory_chat_30423012 = "Tapi itu bagian dari menanamkan disiplin. Tidak bisa tidur, dan itu berlaku untuk Anda juga!",
  str_homestory_chat_30423013 = "Apa? Eh, ya, tentu saja!",
  str_homestory_chat_30424001 = "Musik?",
  str_homestory_chat_30424002 = "Itu benar. Jenis musik apa yang kamu suka?",
  str_homestory_chat_30424003 = "Jenis yang lebih lembut.",
  str_homestory_chat_30424004 = "Saya suka musik yang saya dengar di Lumopolis terakhir kali.",
  str_homestory_chat_30424005 = "Getaran lembut dan elegan.",
  str_homestory_chat_30424006 = "Easy listening tentunya musik yang sangat enak.",
  str_homestory_chat_30424007 = "Jenis yang lebih intens.",
  str_homestory_chat_30424008 = "Maksudmu jenis yang terdengar seperti kebisingan...",
  str_homestory_chat_30424009 = "Ini lebih dari itu. Ada ritmenya juga.",
  str_homestory_chat_30424010 = "Benarkah...?",
  str_homestory_chat_30424011 = "Tapi tidakkah Anda merasa terlalu sepi jika tidak ada musik di sini?",
  str_homestory_chat_30424012 = "Suara alam akan berhasil. Anda dapat memanggil musik itu juga.",
  str_homestory_chat_30424013 = "Tetapi jika Anda menginginkan jenis musik lain, Anda tetap harus pergi ke tempat yang tepat.",
  str_homestory_chat_30424014 = "Kamu benar. Saya harus menikmati musik ini selama saya berada di Cloud Gardens.",
  str_homestory_chat_30425001 = "Apa yang tidak saya sukai?",
  str_homestory_chat_30425002 = "Saya tidak bisa memikirkan apa pun begitu saja... Mengapa Anda merasa ingin menanyakan itu?",
  str_homestory_chat_30425003 = "Asrama terasa agak lembab pagi ini karena hujan beberapa hari yang lalu...",
  str_homestory_chat_30425004 = "Jadi itu mengingatkan saya pada hari-hari saya di Umbraton.",
  str_homestory_chat_30425005 = "Umbraton... Apakah Anda menangkap musim hujan?",
  str_homestory_chat_30425006 = "Huh, gerimis sepanjang hari, dan tempat tidur tidak nyaman apa pun yang Anda lakukan ...",
  str_homestory_chat_30425007 = "Saya dengar begitu di Umbraton, terutama untuk bulan-bulan itu...",
  str_homestory_chat_30425008 = "Tapi kami tidak mendapatkan banyak dari itu di Cloud Gardens.",
  str_homestory_chat_30425009 = "Itulah mengapa rasanya enak di sini.",
  str_homestory_chat_30599999 = "Kau sedang apa?",
  str_homestory_chat_30521001 = "Saya mendengar Anda sedang mencari parfum?",
  str_homestory_chat_30521002 = "Ya. Udaranya sangat bersih di sini, tapi bisa menggunakan parfum untuk menonjolkannya.",
  str_homestory_chat_30521003 = "Mengapa parfum?",
  str_homestory_chat_30521004 = "Sebagian besar untuk Chubbs. Saya pikir mereka membuat panduan yang sempurna.",
  str_homestory_chat_30521005 = "Tetapi sulit membedakan banyak dari mereka, kecuali Anda memiliki parfum.",
  str_homestory_chat_30521006 = "Jadi, itu hanya untuk membedakan mereka? Bukankah absurd menggunakan parfum untuk itu?",
  str_homestory_chat_30521007 = "Benar... Kalau begitu, dengan spidol permanen? Seperti \"#1\", \"#2\" dan seterusnya.",
  str_homestory_chat_30521008 = "Uh... Sudahlah.",
  str_homestory_chat_30522001 = "Toko teh?",
  str_homestory_chat_30522002 = "Kami tidak memiliki yang seperti itu di sini.",
  str_homestory_chat_30522003 = "Oh, tidak, saya ingin membuka kedai teh di sini dan sedang melakukan penelitian.",
  str_homestory_chat_30522004 = "Riset tentang apa?",
  str_homestory_chat_30522005 = "Yang disukai semua orang. Misalnya, apa yang Anda suka minum?",
  str_homestory_chat_30522006 = "Susu.",
  str_homestory_chat_30522007 = "Hmm, pilihan yang sehat.",
  str_homestory_chat_30522008 = "Soda muncul.",
  str_homestory_chat_30522009 = "Oh? Itu spesial.",
  str_homestory_chat_30522010 = "Kopi.",
  str_homestory_chat_30522011 = "Lumayan.",
  str_homestory_chat_30522012 = "Teh hitam.",
  str_homestory_chat_30522013 = "Anda punya selera yang bagus!",
  str_homestory_chat_30522014 = "Omong-omong, Anda mensurvei orang lain selain saya, bukan?",
  str_homestory_chat_30522015 = "Berapa banyak yang kamu punya?",
  str_homestory_chat_30522016 = "Saya masih bertanya satu per satu, dan kemudian saya harus memilah-milah tanggapan awal, pertengahan, dan akhir, sambil memperbarui sesekali.",
  str_homestory_chat_30522017 = "Itu banyak kesulitan yang harus dilalui...",
  str_homestory_chat_30522018 = "Itulah satu-satunya cara untuk mendapatkan data yang akurat untuk menentukan minuman khas.",
  str_homestory_chat_30522019 = "Entah bagaimana, saya tidak merasa itu akan terbuka ...",
  str_homestory_chat_30523001 = "Pesta dansa?",
  str_homestory_chat_30523002 = "Ya. Akhir-akhir ini saya merasa lesu.",
  str_homestory_chat_30523003 = "Saya memikirkannya dan menyadari bahwa saya sudah lama tidak pergi ke pesta dansa.",
  str_homestory_chat_30523004 = "Saya tidak berpikir ada tempat untuk itu di sini.",
  str_homestory_chat_30523005 = "Lalu lempar satu! Yang Anda butuhkan hanyalah penyiapan sederhana.",
  str_homestory_chat_30523006 = "Seperti alun-alun, kursi, spanduk dan lainnya.",
  str_homestory_chat_30523007 = "Tapi band bisa menjadi masalah. Saya pikir kita harus mempekerjakan seseorang.",
  str_homestory_chat_30523008 = "Seperti Chubbs, mungkin...?",
  str_homestory_chat_30523009 = "Tahan, mereka tidak tahu cara memainkan alat musik.",
  str_homestory_chat_30523010 = "Mereka harus memulai pelatihan, kalau begitu.",
  str_homestory_chat_30523011 = "Kami membutuhkan kamp pelatihan khusus, jenis sepuluh hari yang intens.",
  str_homestory_chat_30523012 = "Sepuluh hari?!",
  str_homestory_chat_30523013 = "Terlalu banyak? Jadikan tiga, lalu.",
  str_homestory_chat_30523014 = "Anda lebih baik pergi ke Lumopolis untuk pesta...",
  str_homestory_chat_30524001 = "Panduan?",
  str_homestory_chat_30524002 = "Ya, saya merasa ini adalah tempat yang sangat besar sejak saya tiba di sini.",
  str_homestory_chat_30524003 = "Kita perlu memiliki pemandu agar pendatang baru tidak tersesat.",
  str_homestory_chat_30524004 = "Hmm…",
  str_homestory_chat_30524005 = "Jadi, kau setuju?",
  str_homestory_chat_30524006 = "Nah, Anda benar.",
  str_homestory_chat_30524007 = "Ini adalah tempat yang sangat besar dan panduan akan sangat berharga.",
  str_homestory_chat_30524008 = "Biarkan aku memikirkannya.",
  str_homestory_chat_30524009 = "Omong-omong, apakah Anda sudah memiliki kandidat?",
  str_homestory_chat_30524010 = "Chubb!",
  str_homestory_chat_30524011 = "Apa? Mereka?",
  str_homestory_chat_30524012 = "Mereka menghabiskan waktu seharian di sini dan tahu tempat ini dari dalam ke luar. Mereka sempurna.",
  str_homestory_chat_30524013 = "Eh, beri tahu Anda apa, biarkan saya memikirkan itu ...",
  str_homestory_chat_30699999 = "Proyek menarik apa saja?",
  str_homestory_chat_30621001 = "Membangun taman hiburan?",
  str_homestory_chat_30621002 = "Ide bagus, tapi terlalu terpencil di sini, jadi bagaimana kita akan menarik pengunjung? Atau mungkin menargetkan penduduk lokal?",
  str_homestory_chat_30621003 = "Keluarga Chubb?",
  str_homestory_chat_30621004 = "Benar! Memang populasi kecil, tapi jika mempertimbangkan masa depan...",
  str_homestory_chat_30621005 = "Bagaimana angka kelahiran mereka? Dapatkah mereka berkembang biak dengan cepat? Bagaimana cara mereka berkembang biak?",
  str_homestory_chat_30621006 = "Mirip dengan, uh, Aurorian...?",
  str_homestory_chat_30621007 = "Itu tidak terdengar seperti kamu yakin sama sekali.",
  str_homestory_chat_30621008 = "Mereka mungkin tidak bisa berkembang biak.",
  str_homestory_chat_30621009 = "Betulkah?",
  str_homestory_chat_30621010 = "Ya. Aku tidak pernah melihat mereka lahir, seolah-olah mereka semua muncul begitu saja dari tempat yang tidak jelas.",
  str_homestory_chat_30621011 = "Lomba yang menarik... Tapi sepertinya saya tidak bisa menghasilkan uang dari mereka.",
  str_homestory_chat_30621012 = "Tunggu, bagaimana jika kita mencoba pendekatan yang berbeda...? Akan kuatasi!",
  str_homestory_chat_30621013 = "Baiklah, akan kudengarkan.",
  str_homestory_chat_30621014 = "Kurang berarti langka, langka berarti berharga, berharga berarti menarik hadirin, hadirin berarti tiket!",
  str_homestory_chat_30621015 = "Apakah kamu sedang berpikir...",
  str_homestory_chat_30621016 = "Ubah mereka menjadi bintang dan tampilkan di acara-acara sepanjang Astra!",
  str_homestory_chat_30621017 = "Kita akan menyebutnya \"Tur Dunia Ras Misterius A!\" Bagaimana itu?",
  str_homestory_chat_30621018 = "Saya rasa kamu sebaiknya berhenti sekarang saja.",
  str_homestory_chat_30621019 = "Mengapa?",
  str_homestory_chat_30621020 = "Kamu menjadikan mereka pertunjukan aneh...",
  str_homestory_chat_30621021 = "Mungkin itu bisa dilakukan.",
  str_homestory_chat_30621022 = "\"Superstar Chubbs\" adalah usulan yang menarik, tetapi kita harus mendapatkan pendapat mereka terlebih dahulu.",
  str_homestory_chat_30621023 = "Tentu saja! Beri tahu saya apa yang mereka katakan!",
  str_homestory_chat_30622001 = "Mari kita bicarakan tentang Taman Awan.",
  str_homestory_chat_30622002 = "Tentu, aku ingin membahasnya, anyway.",
  str_homestory_chat_30622003 = "Ada apa?",
  str_homestory_chat_30622004 = "Pengembangan real estat. Panjang pada alam dan pendek pada kenyamanan.",
  str_homestory_chat_30622005 = "Tidak ada food court, distrik belanja, hiburan... Kamu tidak bisa menarik wisatawan.",
  str_homestory_chat_30622006 = "Saya tidak pernah ingin menarik wisatawan... Saya baik-baik saja selama teman-teman saya merasa nyaman di sini.",
  str_homestory_chat_30622007 = "Tidak! Mungkin itu berkelanjutan untuk saat ini, tetapi pernahkah Anda bertanya-tanya apa yang akan terjadi di masa depan?",
  str_homestory_chat_30622008 = "Berapa lama kamu bisa bertahan setelah kehabisan pendapatan?",
  str_homestory_chat_30622009 = "Daripada menunggu masa depan, kamu seharusnya khawatir tentang sekarang! Bagaimana kalau membiarkan saya mengelola Cloud Gardens, apa yang kamu katakan?",
  str_homestory_chat_30622010 = "Apa yang Anda maksudkan?",
  str_homestory_chat_30622011 = "Jual itu padaku. Aku akan menjadikannya kawasan bisnis utama di dunia!",
  str_homestory_chat_30622012 = "Saya lebih suka mempertahankan status quo.",
  str_homestory_chat_30623001 = "Mari kita bicarakan tentang rambutmu, sebagai gantinya.",
  str_homestory_chat_30623002 = "Rambutku? Tidak ada yang perlu dibahas. Cukup normal saja.",
  str_homestory_chat_30623003 = "Aku yakin gaya rambut itu pasti merepotkan.",
  str_homestory_chat_30623004 = "Baru saja pergi ke salon rambut. Harganya hanya beberapa ribu Nightium saja.",
  str_homestory_chat_30623005 = "Beberapa ribu! Apa yang mereka lakukan sehingga mahal?",
  str_homestory_chat_30623006 = "Potong, trim, gaya, dan lainnya. Ngomong-ngomong, saya baru saja mendapat ide untuk sebuah proyek.",
  str_homestory_chat_30623007 = "Ada apa?",
  str_homestory_chat_30623008 = "Buka salon rambut di sini! Aku bayangkan cukup banyak orang yang membutuhkan penata rambut di sini, kan?",
  str_homestory_chat_30623009 = "Kemungkinan ukurannya kecil dengan staf yang ringan, tetapi selama memiliki semua yang diperlukan dan kita dapat mengimpor produk dari Umbraton.",
  str_homestory_chat_30623010 = "Seorang pemilik salon yang saya kenal kebetulan memiliki koneksi yang tepat...",
  str_homestory_chat_30623011 = "Aku menebak kamu hanya ingin menata rambutmu di sini.",
  str_homestory_chat_30623012 = "Tentu saja saya bisa menyelesaikannya secara gratis jika saya yang memiliki. Kamu dapat diskon 20%, meskipun!",
  str_homestory_chat_30623013 = "Hanya diskon 20%...?",
  str_homestory_chat_30623014 = "Jadi kamu setuju?! Aku akan mulai menggerakkan roda besok!",
  str_homestory_chat_30623015 = "Tunggu sebentar, saya masih mempertimbangkan opsi itu!",
  str_homestory_chat_30624001 = "Aku dengar kamu tertarik pada Chubbs akhir-akhir ini?",
  str_homestory_chat_30624002 = "Benar. Tertarik untuk menyerahkannya padaku?",
  str_homestory_chat_30624003 = "Mereka bukan barang dagangan!",
  str_homestory_chat_30624004 = "Tidak mungkin!",
  str_homestory_chat_30624005 = "Aku paham. Mereka menandatangani kontrak dengan kamu, kan? Sebutkan harganya.",
  str_homestory_chat_30624006 = "Kompensasi, biaya transfer, bonus tanda tangan... Evesemuanya bisa dinegosiasikan.",
  str_homestory_chat_30624007 = "Apa hubungannya dengan itu? Kenapa tiba-tiba kamu ingin mereka bekerja untukmu?",
  str_homestory_chat_30624008 = "Saya meluncurkan proyek besar dan membutuhkan beberapa pekerja yang kompeten.",
  str_homestory_chat_30624009 = "Pekerja yang kompeten? Kamu pikir Chubbs cocok dengan deskripsi itu?",
  str_homestory_chat_30624010 = "Bukan masalah! Misalnya, kamu tidak menyadari betapa hebatnya pekerja Chubb Scholar dan Chubb Merchant!",
  str_homestory_chat_30624011 = "Mereka bisa membaca dan berhitung, tahu banyak, tidak makan banyak, dan mungkin tidak tidur sama sekali.",
  str_homestory_chat_30624012 = "Pekerja yang sempurna! Jangan khawatir, saya akan membayar lembur!",
  str_homestory_chat_30624013 = "Gaji dobel untuk hari kerja, tiga kali lipat untuk hari libur!",
  str_homestory_chat_30624014 = "Tunggu, mereka mungkin tidak mau melakukannya!",
  str_homestory_chat_30625001 = "Berhenti memikirkan proyek dan nikmati tegukan sesuatu.",
  str_homestory_chat_30625002 = "Tapi tidak ada minuman di Taman Awan. Yang aku lihat hanya air dingin.",
  str_homestory_chat_30625003 = "Membawa kopi atau teh dari Umbraton cukup merepotkan.",
  str_homestory_chat_30625004 = "Tidak ada minuman khas lokal di sini?",
  str_homestory_chat_30625005 = "Konon, daun dari beberapa pohon unik mengeluarkan aroma khas, tetapi aku tidak tahu bagaimana rasanya jika dicampur dengan air panas.",
  str_homestory_chat_30625006 = "Pohon unik, eh? Itu opsi yang patut dipertimbangkan.",
  str_homestory_chat_30625007 = "Jangan bilang kamu punya ide bisnis lain?",
  str_homestory_chat_30625008 = "Saya harus mencicipinya terlebih dahulu sebelum menjelajahi potensi komersialnya.",
  str_homestory_chat_30625009 = "Karena kamu yang menyarankan, aku akan melihatnya saat punya waktu luang.",
  str_homestory_chat_30799999 = "Sedang apa kau?",
  str_homestory_chat_30721001 = "Hanya membuat putaran.",
  str_homestory_chat_30721002 = "Tidak bisakah kamu melakukan sesuatu yang lebih bermakna?",
  str_homestory_chat_30721003 = "Ini adalah hobi saya. Mungkin kamu merasa sangat bosan, meskipun begitu.",
  str_homestory_chat_30721004 = "Kamu benar... Ada aktivitas yang bisa direkomendasikan di Taman Awan?",
  str_homestory_chat_30721005 = "Memancing?",
  str_homestory_chat_30721006 = "Terlalu sepi, dan memalukan saat kamu tidak menangkap apa pun.",
  str_homestory_chat_30721007 = "Berkebun?",
  str_homestory_chat_30721008 = "Aku hanya melihat pohon-pohon besar yang aneh di sekitar... Terlalu canggung untuk selera ku.",
  str_homestory_chat_30721009 = "Lihatlah museum.",
  str_homestory_chat_30721010 = "Tidak banyak yang bisa dilihat di sana.",
  str_homestory_chat_30721011 = "Kamu sepertinya tidak tertarik dengan apa pun! Kenapa tidak tidur siang di kamarmu?",
  str_homestory_chat_30721012 = "Jangan marah. Saya hanya mencoba membuat kamu rileks dan santai.",
  str_homestory_chat_30721013 = "EveSetiap kali aku melihatmu, kamu selalu berkeliling atau bekerja. Aku khawatir tentangmu...",
  str_homestory_chat_30721014 = "Kehidupan tidak terbatas hanya untuk mengembangkan Taman Awan.",
  str_homestory_chat_30721015 = "Semuanya baik-baik saja. Melakukan putaran bagi saya adalah mengambilnya dengan santai. Sebut saja jalan santai.",
  str_homestory_chat_30721016 = "Baiklah, mengerti. Lanjutkan.",
  str_homestory_chat_30722001 = "Saya sedang jalan-jalan. Kamu?",
  str_homestory_chat_30722002 = "Aku lagi nyari kamu nih. Mau ke Umbraton bareng aku kalau kamu lagi nggak sibuk?",
  str_homestory_chat_30722003 = "Umbraton? Sekarang?",
  str_homestory_chat_30722004 = "Seseorang memberi saya dua tiket VIP ke restoran mewah sehingga saya bisa membawa tamu.",
  str_homestory_chat_30722005 = "Tidak ada makan siang gratis...",
  str_homestory_chat_30722006 = "Kamu punya permintaan, kan?",
  str_homestory_chat_30722007 = "Kamu tidak mencoba mengundang orang lain?",
  str_homestory_chat_30722008 = "Atau seharusnya saya bilang, kamu tidak punya orang lain yang bisa diundang?",
  str_homestory_chat_30722009 = "Apakah itu yang kamu rasakan tentang persahabatan kita? Kita tidak bisa duduk dan makan bersama?",
  str_homestory_chat_30722010 = "Biar kupikirkan dulu.",
  str_homestory_chat_30723001 = "Saya sedang berpikir untuk melihat pohon-pohon unik sekarang.",
  str_homestory_chat_30723002 = "Pohon unik, kau bilang... Aku dengar beberapa di antaranya mengeluarkan aroma mempesona.",
  str_homestory_chat_30723003 = "Saya sedang memikirkan apakah ini bisa dijadikan parfum.",
  str_homestory_chat_30723004 = "Mereka butuh waktu lama untuk tumbuh, jadi jangan ganggu mereka.",
  str_homestory_chat_30723005 = "Bukan hanya saya, Chubbs juga tidak akan menyukainya.",
  str_homestory_chat_30723006 = "Itu buruk. Apa yang harus saya lakukan tentang tanggal saya?",
  str_homestory_chat_30723007 = "Tanggal Anda?",
  str_homestory_chat_30723008 = "Saya berjanji untuk membawakan dia parfum unik yang spesial.",
  str_homestory_chat_30723009 = "Apa maksudnya itu?",
  str_homestory_chat_30723010 = "Campuran serbuk sari pohon yang unik dan embun malam, dibuat khusus untuknya. Satu-satunya di dunia.",
  str_homestory_chat_30723011 = "Apakah itu akan berbau enak?",
  str_homestory_chat_30723012 = "Tidak harus, tapi tidak masalah selama dia merasa itu istimewa.",
  str_homestory_chat_30723013 = "Mungkin itu yang disebut seseorang sebagai \"rahasia kencan\"... Bagaimanapun, pohon unik tidak masuk akal.",
  str_homestory_chat_30723014 = "Baik, aku paham aku harus menggunakan \"rahasia\" lainnya.",
  str_homestory_chat_30724001 = "Kamu mencari Chubbs?",
  str_homestory_chat_30724002 = "Ya, saya ingin membahas masalah tentang mereka.",
  str_homestory_chat_30724003 = "Ada apa?",
  str_homestory_chat_30724004 = "Sebagai penjaga Kebun Awan, mereka tidak memiliki pesona.",
  str_homestory_chat_30724005 = "Tapi, bukankah melayani orang dan memastikan Cloud Gardens berfungsi dengan baik sudah cukup?",
  str_homestory_chat_30724006 = "Salah!",
  str_homestory_chat_30724007 = "Jika para penjaga tidak menawan, siapa yang ingin tinggal di sini?",
  str_homestory_chat_30724008 = "Lihat betapa kotak dan membosankan mereka.",
  str_homestory_chat_30724009 = "Cloud Gardens bukan taman hiburan. Kami tidak memerlukan klien.",
  str_homestory_chat_30724010 = "EveSetiap orang datang ke sini untuk bersantai. Chubbs hanya perlu melakukan pemeliharaan harian.",
  str_homestory_chat_30724011 = "Apakah itu cara kerjanya... Aku tahu.",
  str_homestory_chat_30725001 = "Kudengar kau mencariku?",
  str_homestory_chat_30725002 = "Apa yang sebenarnya saya inginkan adalah membeli sebidang tanah di sini.",
  str_homestory_chat_30725003 = "Jangan bilang ada seseorang yang ingin membangun resor dan mempekerjakan kamu untuk mengelolanya?",
  str_homestory_chat_30725004 = "Tidak, salah, bro. Aku ingin pensiun di sini.",
  str_homestory_chat_30725005 = "Bukankah masih terlalu awal untuk itu?",
  str_homestory_chat_30725006 = "Hanya sebuah pemikiran. Lingkungan di sini memang bagus, setelah semua. Terpencil, tenang...",
  str_homestory_chat_30725007 = "Semoga saya bisa sampai pada hari di mana saya bisa pensiun di sini.",
  str_homestory_chat_30899999 = "Aku di sini!",
  str_homestory_chat_30801001 = "Hai, Bopper!",
  str_homestory_chat_30801002 = "Kamu melihatku!",
  str_homestory_chat_30801003 = "Itu karena kamu melambaikan tangan padaku.",
  str_homestory_chat_30801004 = "Para pria di Rediesel Wrench selalu mengabaikan aku. Biasanya, aku tidak bisa mendapatkan tanggapan dari mereka.",
  str_homestory_chat_30801005 = "Tidak mungkin! Apakah kamu sudah mencoba untuk lebih mengungkapkan diri, seperti memberikan saran?",
  str_homestory_chat_30801006 = "Itulah alasan saya menjadi seorang ahli strategi! Tapi hanya Kadal Raksasa yang tampaknya memperhatikan rencana-rencana saya...",
  str_homestory_chat_30801007 = "Andai saja Sinsa mau mendengarkan saran saya sesekali...",
  str_homestory_chat_30801008 = "Saya yakin hari itu akan tiba. Jangan menyerah, Bopper!",
  str_homestory_chat_30821001 = "Apa yang terjadi dengan kamu akhir-akhir ini?",
  str_homestory_chat_30821002 = "Kayaknya aku mau makan sebentar lagi. Aku sedikit lapar.",
  str_homestory_chat_30821003 = "Cloud Gardens agak jauh dari Rediesel Desert dan mungkin tidak memiliki apa yang saya suka, meskipun begitu.",
  str_homestory_chat_30821004 = "Makanan Rediesel Desert... Kamu maksud daging kadal kering dan kaktus?",
  str_homestory_chat_30821005 = "Itu belum semuanya. Apa saja yang tersedia untuk dimakan di Taman Awan?",
  str_homestory_chat_30821006 = "Roti.",
  str_homestory_chat_30821007 = "Itu biasa. Kamu makan kering tanpa selai?",
  str_homestory_chat_30821008 = "Cukup roti saja sudah enak.",
  str_homestory_chat_30821009 = "Oke.",
  str_homestory_chat_30821010 = "Kopi.",
  str_homestory_chat_30821011 = "Ini cocok untuk meningkatkan semangat, tapi agak pahit dan perlu banyak gula...",
  str_homestory_chat_30821012 = "Risotto.",
  str_homestory_chat_30821013 = "Sangat mengenyangkan, tapi lebih baik dengan lauk-pauk.",
  str_homestory_chat_30821014 = "Kue buah.",
  str_homestory_chat_30821015 = "Aku tidak tahu kamu suka permen sebanyak itu.",
  str_homestory_chat_30821016 = "Kamu sepertinya tidak terlalu tertarik pada makanan-makanan itu.",
  str_homestory_chat_30821017 = "Nah, aku jadi kangen Rediesel Desert setiap kali ngomongin makanan.",
  str_homestory_chat_30821018 = "Badai pasir mungkin mengerikan, tapi makanannya enak...",
  str_homestory_chat_30821019 = "Suka es krim dan kue kadal, atau cacing rediesel goreng.",
  str_homestory_chat_30821020 = "Maybuka kafe rediesel di Taman Awan? Apakah itu akan berhasil?",
  str_homestory_chat_30821021 = "Pasti akan bangkrut.",
  str_homestory_chat_30822001 = "Hei, bagaimana kamu menyesuaikan diri sejauh ini?",
  str_homestory_chat_30822002 = "Hai PlayerName! Suasana di sini bagus, tenang, nyaman, hanya saja...",
  str_homestory_chat_30822003 = "Inilah bagian yang buruk...",
  str_homestory_chat_30822004 = "Saya kadang-kadang bersin, misalnya... Acho!",
  str_homestory_chat_30822005 = "Aku tidak tahu mengapa, tapi aku baik-baik saja saat meninggalkan di sini.",
  str_homestory_chat_30822006 = "Sesuatu di lingkungan, mungkin? Polen, mungkin?",
  str_homestory_chat_30822007 = "Acho! Mungkin, karena bunga-bunga langka di Gurun Rediesel.",
  str_homestory_chat_30822008 = "Semua yang kamu lihat adalah pasir, pasir, dan lebih banyak pasir, yang tidak menjadi masalah bagi saya.",
  str_homestory_chat_30822009 = "Apakah saya mendapatkannya di hidung atau mata, saya bisa mengeluarkannya dalam dua kali goyangan.",
  str_homestory_chat_30822010 = "Tapi polen yang kamu sebutkan... Acho! Mereka sangat mengganggu!",
  str_homestory_chat_30822011 = "Coba menjauh dari mereka, atau datang di waktu lain.",
  str_homestory_chat_30822012 = "Atau tahanlah beberapa hari hingga kamu terbiasa dengannya.",
  str_homestory_chat_30822013 = "Alam di Cloud Gardens tentu berbeda dari Rediesel Desert.",
  str_homestory_chat_30822014 = "Sangat menenangkan dan bahkan memikat. Acho!",
  str_homestory_chat_30823001 = "Lihat apa kau?",
  str_homestory_chat_30823002 = "Saya mencoba menemukan Giant Eagle. Di mana kamu memarkirkannya?",
  str_homestory_chat_30823003 = "Di luar.",
  str_homestory_chat_30823004 = "Tidakkah kamu khawatir itu mungkin berbahaya?",
  str_homestory_chat_30823005 = "Dia bisa melindungi dirinya sendiri. Even jika tidak, dia bisa terbang pergi.",
  str_homestory_chat_30823006 = "Mengapa kamu mencarinya?",
  str_homestory_chat_30823007 = "Hanya penasaran di mana itu dan apakah bisa melindungi dirinya sendiri.",
  str_homestory_chat_30823008 = "Dia baik-baik saja, jangan khawatir.",
  str_homestory_chat_30823009 = "Namun, jika kamu di sini, di mana Kadal Raksasa itu?",
  str_homestory_chat_30823010 = "Saya naik mobil. Kadal Raksasa lebih suka tidak meninggalkan gurun.",
  str_homestory_chat_30823011 = "Mungkin sedang bergaul dengan orang-orang yang tidak dapat diandalkan itu...",
  str_homestory_chat_30823012 = "Itu bukan cara untuk membicarakan teman-temanmu...",
  str_homestory_chat_30999999 = "Kau sedang apa?",
  str_homestory_chat_30921001 = "Hanya jalan-jalan. Kamu?",
  str_homestory_chat_30921002 = "Ada sesuatu di pikiranmu?",
  str_homestory_chat_30921003 = "Tentu saja, dan Anda datang tepat waktu untuk mendengar semuanya. Saya butuh pendapat Anda tentang sesuatu.",
  str_homestory_chat_30921004 = "Apa…?",
  str_homestory_chat_30921005 = "Lihatlah para jenderal ini. Menurutmu, siapa di antara mereka yang pantas menjadi Grand Marshal yang baik?",
  str_homestory_chat_30921006 = "Hmm… Coba kuingat-ingat.",
  str_homestory_chat_30921007 = "Sharona.",
  str_homestory_chat_30921008 = "Um. Bukan kandidat yang buruk. Untuk pekerjaan ini, dia memiliki kepemimpinan yang sempurna, wawasan strategis, dan loyalitas.",
  str_homestory_chat_30921009 = "Sayangnya, dia berasal dari Lumopolis, dan meskipun dia pada dasarnya telah memutuskan semua ikatan dengan kehidupan masa lalunya...",
  str_homestory_chat_30921010 = "Di mata \"orang-orang itu,\" dia masih jauh dari sempurna.",
  str_homestory_chat_30921011 = "Oh, begitu…",
  str_homestory_chat_30921012 = "Barton.",
  str_homestory_chat_30921013 = "Dia paling-paling seorang jenderal. Pria itu hanya merasa di rumah saat berada di medan perang.",
  str_homestory_chat_30921014 = "Di masa damai, dia akan berakhir sebagai pengganggu masyarakat, atau menjadi pengangguran yang tidak berguna.",
  str_homestory_chat_30921015 = "Wow, kamu kasar.",
  str_homestory_chat_30921016 = "Cuma ngomong yang sebenarnya.",
  str_homestory_chat_30921017 = "Hiiro.",
  str_homestory_chat_30921018 = "Keberaniannya tak terbantahkan, dan dia memimpin pasukannya dengan disiplin dan otoritas tertinggi. Sayangnya...",
  str_homestory_chat_30921019 = "Hiiro terkadang jauh melampaui \"berani\" hingga seringkali dia kehilangan dirinya dalam panasnya pertempuran.",
  str_homestory_chat_30921020 = "Tentu saja, sudah menjadi pengetahuan umum bahwa seorang prajurit harus berani, tetapi keberanian tidak boleh mengorbankan kemenangan.",
  str_homestory_chat_30921021 = "Kedua hal itu tidak selalu berjalan beriringan... Aku tidak yakin apakah kamu bisa melihat perbedaan halus di sana.",
  str_homestory_chat_30921022 = "Kurasa aku paham... sampai batas tertentu.",
  str_homestory_chat_30921023 = "Jadi, sepertinya... tidak ada yang benar-benar cocok untuk peran ini.",
  str_homestory_chat_30921024 = "Sebenarnya, coba lihat dari sudut pandang lain: Jika kandidat-kandidat ini memiliki ajudan, perwira staf, atau siapa pun yang cocok untuk membantu mereka...",
  str_homestory_chat_30921025 = "Mereka benar-benar bisa menjadi Grand Marshal yang layak.",
  str_homestory_chat_30922001 = "Hanya pergi untuk melihat apakah ada teman-teman saya di sekitar.",
  str_homestory_chat_30922002 = "Berbicara tentang teman, apa pendapatmu tentang Reinhardt? Apakah kamu menganggap dia sebagai teman yang baik atau bos yang baik?",
  str_homestory_chat_30922003 = "Dia teman baik.",
  str_homestory_chat_30922004 = "Dia bos yang baik.",
  str_homestory_chat_30922005 = "Kenapa kau tiba-tiba menanyakannya kepadaku?",
  str_homestory_chat_30922006 = "Mungkin kamu sudah tahu bahwa kami berdua adalah teman sekelas.",
  str_homestory_chat_30922007 = "Dia dulu menjadi komandan saya... Keinginannya adalah perintahku saat itu.",
  str_homestory_chat_30922008 = "Namun, dari yang terlihat, mungkin saja saya akan menjadi atasan darinya di masa depan.",
  str_homestory_chat_30922009 = "Baiklah... Kamu sedang memikirkan cara untuk akur dengannya, ya?",
  str_homestory_chat_30922010 = "Benar.",
  str_homestory_chat_30922011 = "Tidak perlu terlalu khawatir tentang itu. Ikuti saja alurnya.",
  str_homestory_chat_30922012 = "Aku tahu kau akan bilang begitu, tapi itu tetap dianggap sebagai saran yang mantap menurutku.",
  str_homestory_chat_30922013 = "Terima kasih, PlayerName.",
  str_homestory_chat_30923001 = "Cuma pengen istirahat sebentar.",
  str_homestory_chat_30923002 = "Apa yang biasanya kamu lakukan untuk bersantai?",
  str_homestory_chat_30923003 = "Jalan-jalan.",
  str_homestory_chat_30923004 = "Terkesan cukup dasar.",
  str_homestory_chat_30923005 = "Pergi memancing.",
  str_homestory_chat_30923006 = "Itu sangat klise.",
  str_homestory_chat_30923007 = "Saya mendengar bahwa Caelestites mengembangkan metode relaksasi unik yang disebut \"meditasi.\"",
  str_homestory_chat_30923008 = "Pribadi, saya jarang meditasi... Kenapa kamu tiba-tiba tertarik dengan meditasi?",
  str_homestory_chat_30923009 = "Mau mencobanya?",
  str_homestory_chat_30923010 = "Meditasi adalah bentuk relaksasi, sekaligus bentuk pelatihan.",
  str_homestory_chat_30923011 = "Saat Anda santai, Anda dapat menemukan jalan yang sebenarnya dan memperkuat arah kemajuan Anda.",
  str_homestory_chat_30923012 = "Metode pelatihan ini sangat penting bagi saya—ini membantu saya mengisi ulang \"baterai\" saya, begitu kata pepatah.",
  str_homestory_chat_30923013 = "Nanti akan kucoba...",
  str_homestory_chat_30924001 = "Hanya jalan-jalan.",
  str_homestory_chat_30924002 = "Sepertinya berjalan-jalan ini sangat cocok untukmu.",
  str_homestory_chat_30924003 = "Kenapa bisa begitu?",
  str_homestory_chat_30924004 = "Karena kamu terlihat luar biasa! Rahasianya ada pada semua jalan-jalan itu, kan?",
  str_homestory_chat_30924005 = "Tidak.",
  str_homestory_chat_30924006 = "Lalu, apa rahasiamu?",
  str_homestory_chat_30924007 = "Tak ada rahasia. Hanya tidur nyenyak dan menjalani kehidupan yang sehat dan seimbang.",
  str_homestory_chat_30924008 = "Sebaliknya, kamu selalu terlihat kurang sehat... Apakah karena sering begadang? Jangan mengorbankan diri demi pekerjaan.",
  str_homestory_chat_30924009 = "Bisa dibilang itu harga dari tanggung jawab.",
  str_homestory_chat_30925001 = "Hanya berpatroli di Cloud Gardens.",
  str_homestory_chat_30925002 = "Nasib keras. Tidak ada istirahat bagi orang jahat, ya?",
  str_homestory_chat_30925003 = "Nah... Jalan-jalan yang menyenangkan ini persis yang aku butuhkan.",
  str_homestory_chat_30925004 = "Benarkah? Jadi beginilah cara Anda mengelola Cloud Gardens, ya?",
  str_homestory_chat_30925005 = "Kurang lebih. Chubb melakukan sebagian besar pekerjaan, sementara saya hanya melihat-lihat sesekali.",
  str_homestory_chat_30925006 = "Ya ampun, seandainya menjalankan Illumina itu semudah menjalankan Cloud Gardens.",
  str_homestory_chat_30925007 = "Mereka sangat berbeda, sih.",
  str_homestory_chat_30925008 = "Setelah semua, Illumina Federation bertanggung jawab untuk melawan invasi Eclipsite...",
  str_homestory_chat_30925009 = "Dan jelas lebih luas daripada Cloud Gardens...",
  str_homestory_chat_30925010 = "Benar.",
  str_homestory_chat_30925011 = "Anda harus belajar untuk melepaskan beberapa tekanan itu. Sekarang Anda berada di Cloud Gardens, lepaskan beban dan bersenang-senanglah di sini.",
  str_homestory_chat_31099999 = "Demi White Night. Bagaimana hari Anda sejauh ini?",
  str_homestory_chat_31001001 = "Ah, tidak ada yang istimewa.",
  str_homestory_chat_31001002 = "Ini adalah hal yang baik. Ini berarti perdamaian telah terjaga di sini.",
  str_homestory_chat_31001003 = "Jelas bahwa kamu sangat menyukai hari-hari seperti ini.",
  str_homestory_chat_31001004 = "Semua orang di Twilight menjalani kehidupan yang penuh tekanan.",
  str_homestory_chat_31001005 = "Secara fisik, dan spiritual...",
  str_homestory_chat_31001006 = "Para Eclipsite begitu dekat dengan batas kota sehingga warga kota hampir bisa merasakan mereka bernapas di belakang leher mereka.",
  str_homestory_chat_31001007 = "Jadi ketika tiba di sini, seseorang tidak bisa tidak kagum dengan betapa tenangnya suasana ini.",
  str_homestory_chat_31001008 = "Seandainya kedamaian ini bisa menyebar ke seluruh benua, betapa indahnya hal itu.",
  str_homestory_chat_31021001 = "Lumayan. Kamu?",
  str_homestory_chat_31021002 = "Aku bertanya-tanya... Bagaimana pandanganmu secara pribadi tentang berbagai wilayah di dunia ini?",
  str_homestory_chat_31021003 = "Misalnya...?",
  str_homestory_chat_31021004 = "Hmm... Lumopolis.",
  str_homestory_chat_31021005 = "Ini pusat peradaban.",
  str_homestory_chat_31021006 = "Penguasa benua.",
  str_homestory_chat_31021007 = "Apa pendapatmu tentang Lumopolis?",
  str_homestory_chat_31021008 = "Ini... pusat peradaban, bukan?",
  str_homestory_chat_31021009 = "Ada sesuatu tentang nada bicaramu yang membuatku merasa kamu tidak begitu yakin tentang itu.",
  str_homestory_chat_31021010 = "Itu karena aku sudah lama tinggal di Twilight dan jarang menjelajah ke Lumopolis.",
  str_homestory_chat_31021011 = "Lalu, apa pendapatmu tentang Federasi Illumina, PlayerName?",
  str_homestory_chat_31021012 = "Ini adalah garis depan pertempuran melawan Eclipsites.",
  str_homestory_chat_31021013 = "Ini adalah organisasi yang bersatu.",
  str_homestory_chat_31021014 = "Kenapa kamu menanyakan ini padaku?",
  str_homestory_chat_31021015 = "Ketika saya memikirkan apa yang terjadi di Twilight, saya tidak bisa tidak khawatir tentang masa depan Twilight.",
  str_homestory_chat_31021016 = "Penduduk kota itu... Apa yang akan terjadi pada mereka?",
  str_homestory_chat_31021017 = "Apakah kamu sering memikirkan hal-hal ini?",
  str_homestory_chat_31021018 = "Dengan hidup di Twilight, saya tidak punya pilihan selain memikirkan hal-hal ini...",
  str_homestory_chat_31021019 = "Saya harap Dewa Cahaya yang maha kuasa akan menjawab doa saya dan memberikan perlindungan kepada warga kota.",
  str_homestory_chat_31022001 = "Aku mau jalan-jalan sebentar saja.",
  str_homestory_chat_31022002 = "Tampaknya kau akhirnya siap untuk menikmati waktu luangmu.",
  str_homestory_chat_31022003 = "Kurasa begitu. Kamu sedang apa sekarang?",
  str_homestory_chat_31022004 = "Saya belum memutuskan. Setelah saya tiba di Cloud Gardens, saya merasa agak tidak cocok.",
  str_homestory_chat_31022005 = "Kenapa bisa begitu?",
  str_homestory_chat_31022006 = "Cloud Gardens sangat berbeda dari Twilight—tempat di mana kamu harus mengayunkan pedang hampir setiap hari untuk bertahan hidup...",
  str_homestory_chat_31022007 = "Melawan Eclipsites?",
  str_homestory_chat_31022008 = "Tepat sekali.",
  str_homestory_chat_31022009 = "Aku selalu penasaran, bagaimana kehidupan jika aku tidak harus membawa senjata setiap hari?",
  str_homestory_chat_31022010 = "Dan sekarang kamu bisa merasakan kehidupan itu secara langsung.",
  str_homestory_chat_31022011 = "Ah... Sungguh luar biasa jika semua orang di Twilight bisa hidup seperti ini.",
  str_homestory_chat_31023001 = "Cuma hal biasa. Apa yang kamu lakukan di sini?",
  str_homestory_chat_31023002 = "Aku menyerap jejak-jejak cahaya.",
  str_homestory_chat_31023003 = "Menyerap jejak cahaya? Oh! Apakah kamu sedang berjemur? Itu baik untukmu, lho?",
  str_homestory_chat_31023004 = "Tidak, sebenarnya aku sedang berdoa.",
  str_homestory_chat_31023005 = "Berdoa?",
  str_homestory_chat_31023006 = "Karena Cahaya adalah keyakinanku...",
  str_homestory_chat_31023007 = "Tidak seperti Twilight, langit mendung jarang terlihat di Cloud Gardens.",
  str_homestory_chat_31023008 = "Berada di tempat yang indah ini, aku tidak bisa menahan keinginan untuk memanggil yang muncul di hatiku.",
  str_homestory_chat_31023009 = "Oke. Silakan berdoa... Aku serahkan padamu, ya.",
  str_homestory_chat_31199999 = "Kamu sedang apa, Navigator?",
  str_homestory_chat_31121001 = "Hei Antony, aku berencana untuk pergi keluar...",
  str_homestory_chat_31121002 = "Untuk menjelajahi beberapa reruntuhan.",
  str_homestory_chat_31121003 = "Reruntuhan? Maksudmu yang belum dijelajahi?",
