  str_homestory_chat_31121009 = "Namun terkadang, batu sederhana pun bisa menyimpan rahasia penting.",
  str_homestory_chat_31121010 = "Nah, dengan otak besar Anda yang membimbing kami, kita mungkin benar-benar memiliki kesempatan untuk menemukan sesuatu yang istimewa.",
