  str_homestory_chat_31121015 = "Bagaimana itu ada hubungannya dengan aku beristirahat?",
  str_homestory_chat_31121016 = "Tentu saja.",
  str_homestory_chat_31121017 = "Berbaring di reruntuhan, menatap lukisan-lukisan di atas...",
