  str_homestory_chat_31321004 = "Berdasarkan perhitungan, saat ini tidak perlu bagi saya untuk beralih ke mode tidur.",
  str_homestory_chat_31321005 = "Apakah kamu tidak lelah sama sekali?",
  str_homestory_chat_31321006 = "Terima kasih atas perhatian Anda, tetapi saat ini saya tidak merasa lelah.",
  str_homestory_chat_31321007 = "Tanpa instruksi lebih lanjut, saya akan tetap siaga.",
  str_homestory_chat_31322001 = "Lakukan patroli.",
  str_homestory_chat_31322002 = "Perintah diakui. Menjalankan daftar misi sekarang.",
  str_homestory_chat_31322003 = "Tunggu, itu benar-benar berhasil?!",
  str_homestory_chat_31322004 = "Aku hanya bercanda...",
  str_homestory_chat_31322005 = "Apakah kamu tidak percaya kemampuanku untuk menyelesaikan misi?",
  str_homestory_chat_31322006 = "Berdasarkan catatan kumulatif, saya telah melakukan total 5.005 patroli dan sangat berpengalaman.",
  str_homestory_chat_31322007 = "Bukan karena aku tidak percaya padamu, No. 33.",
  str_homestory_chat_31322008 = "Tapi itu tugasku. Aku harus melakukannya sendiri.",
  str_homestory_chat_31322009 = "Baiklah. Saya menghormati keputusan Anda.",
  str_homestory_chat_31323001 = "Jangan masukkan apa-apa.",
  str_homestory_chat_31323002 = "Harap masukkan perintah.",
  str_homestory_chat_31323003 = "Ulangi, tolong masukkan perintah.",
  str_homestory_chat_31323004 = "Apakah kamu bingung dengan frasa, \"Input perintah\"?",
  str_homestory_chat_31323005 = "Mencari ungkapan yang lebih tepat...",
  str_homestory_chat_31323006 = "Beri tahu saya jika ada yang perlu saya lakukan.",
  str_homestory_chat_31323007 = "Yah, tidak ada yang mendesak sekarang...",
  str_homestory_chat_31323008 = "Baiklah. Tolong beri tahu saya jika Anda memiliki kebutuhan.",
  str_homestory_chat_31323009 = "No. 33 akan melayani Anda sepanjang waktu.",
  str_homestory_chat_31324001 = "Pergi kongko bersama teman.",
  str_homestory_chat_31324002 = "Misalnya...",
  str_homestory_chat_31324003 = "Zarya.",
  str_homestory_chat_31324004 = "Nona Zarya? Memang, dia adalah teman yang sangat penting bagiku.",
  str_homestory_chat_31324005 = "Saya akan menjadwalkan program pelatihan Luminatics baru untuknya agar meningkatkan kekuatannya.",
  str_homestory_chat_31324006 = "Tidak, bukan itu. Cukup nongkrong dan ngobrol dengannya saja.",
  str_homestory_chat_31324007 = "Antony.",
  str_homestory_chat_31324008 = "Kurasa kamu dan Bapak Antony akan memiliki banyak hal untuk dibicarakan.",
  str_homestory_chat_31324009 = "Jika kamu mengacu pada penguasaan pengetahuan, aku setuju.",
  str_homestory_chat_31324010 = "Meskipun berdasarkan pada lima puluh pertemuan sebelumnya...",
  str_homestory_chat_31324011 = "Saya percaya dia mungkin lebih tertarik pada komposisi struktural dan teknologi saya.",
  str_homestory_chat_31324012 = "Namun, ada kemungkinan dia bisa menyimpulkan informasi yang telah saya lupakan...",
  str_homestory_chat_31324013 = "Kedengarannya sempurna!",
  str_homestory_chat_31324014 = "Pergilah, No. 33.",
  str_homestory_chat_31324015 = "Aku juga seharusnya melanjutkan hal lain.",
  str_homestory_chat_28899999 = "May Aku bertanya, kamu sedang apa sekarang?",
  str_homestory_chat_28801001 = "Sebenarnya, aku baru saja ingin menanyakan bagaimana kamu menyesuaikan diri dengan kehidupan di sini.",
  str_homestory_chat_28801002 = "Tempat ini sangat berbeda dari kota-kota lain di Astra, apalagi kota-kota di Longzhou.",
  str_homestory_chat_28801003 = "Ada sesuatu yang unik tentang tempat ini.",
  str_homestory_chat_28801004 = "Unik?",
  str_homestory_chat_28801005 = "Sesuatu yang sangat damai, yang membuat seseorang melupakan semua perselisihan di dunia luar.",
  str_homestory_chat_28801006 = "Lalu sepertinya kamu sudah terbiasa di sini... Aku senang mendengarnya.",
  str_homestory_chat_28821001 = "Tumbuh bunga?",
  str_homestory_chat_28821002 = "Ya. May Saya ingin bertanya apakah ada bunga eksotis di sini juga?",
  str_homestory_chat_28821003 = "Ya.",
  str_homestory_chat_28821004 = "Maukah kamu mengajakku untuk melihat mereka?",
  str_homestory_chat_28821005 = "Tentu, tapi... keluarga Chubb sedang merawat mereka sekarang.",
  str_homestory_chat_28821006 = "Saya mengerti... Bunga-bunga langka tentu memerlukan perawatan dan perlindungan yang lebih ekstra.",
  str_homestory_chat_28821007 = "Tapi masih ada banyak tanaman dan bunga lainnya yang bisa dilihat di Eraveil! Silakan melihat-lihat sekeliling!",
  str_homestory_chat_28821008 = "Terima kasih telah memberi tahu, PlayerName.",
  str_homestory_chat_28821009 = "Tidak.",
  str_homestory_chat_28821010 = "Sayang sekali. Sepertinya saya harus mengejar misi baru sekarang...",
  str_homestory_chat_28821011 = "Ayo isi Eraveil dengan lautan bunga Longzhou, seperti begonia! Bagaimana menurutmu?",
  str_homestory_chat_28821012 = "Biar kupikirkan.",
  str_homestory_chat_28822001 = "Mengutak-atik perangkat?",
  str_homestory_chat_28822002 = "Sebuah alat yang terdiri dari berbagai mekanisme kecil, tepatnya. Saya dengar ada banyak hal seperti ini di Astra.",
  str_homestory_chat_28822003 = "Misalnya?",
  str_homestory_chat_28822004 = "Pernah suatu kali saya melihat jam yang dibuat dengan sangat ahli, yang tidak hanya menunjukkan waktu tetapi juga mengeluarkan burung kecil.",
  str_homestory_chat_28822005 = "Seekor burung kecil?",
  str_homestory_chat_28822006 = "Benar. Setiap jam, seekor burung kecil akan muncul dengan suara \"ding,\" dan berkicau untuk menandakan waktu.",
  str_homestory_chat_28822007 = "Sebuah \"ding\"? Saya pikir itu terdengar lebih seperti \"kukuk\"...",
  str_homestory_chat_28822008 = "Ya! Itu suara yang dihasilkannya!",
  str_homestory_chat_28822009 = "Oh, itu jam burung gereja. Itu cukup menarik, ya.",
  str_homestory_chat_28822010 = "Lalu kapan aku bisa memasang satu di kamarku?",
  str_homestory_chat_28822011 = "Uh... Itu bisa cukup mahal, tapi akan kupertimbangkan...",
  str_homestory_chat_28823001 = "Membuat minuman?",
  str_homestory_chat_28823002 = "Ya. Sejak datang ke sini, saya merindukan banyak hal dari tanah air saya, termasuk minumannya.",
  str_homestory_chat_28823003 = "Kamu punya rekomendasi minuman sendiri, PlayerName?",
  str_homestory_chat_28823004 = "Teh hitam.",
  str_homestory_chat_28823005 = "Kami juga memiliki jenis teh ini di Astra, dan aku dengar banyak orang menyukainya.",
  str_homestory_chat_28823006 = "Tapi... orang-orang di sini lebih peduli pada camilan yang disajikan bersama teh mereka...",
  str_homestory_chat_28823007 = "Saya mengerti. Saya juga harus mempertimbangkan hal itu.",
  str_homestory_chat_28823008 = "Soda.",
  str_homestory_chat_28823009 = "Apa itu...?",
  str_homestory_chat_28823010 = "Ini adalah minuman yang sedikit manis dengan sensasi di mulut yang sangat menarik.",
  str_homestory_chat_28823011 = "Dan bagaimana tekstur di mulut itu?",
  str_homestory_chat_28823012 = "Rasanya seperti banyak gelembung kecil menari di lidahmu. Bahkan bisa membuatmu bersendawa jika kamu meminumnya terlalu cepat!",
  str_homestory_chat_28823013 = "Itu terdengar sedikit di luar selera saya...",
  str_homestory_chat_28824001 = "Membuat sarapan?",
  str_homestory_chat_28824002 = "Ya. Sarapan sangat penting untuk kesehatan seseorang. \"Hari dimulai dengan sarapan,\" seperti pepatah yang beredar.",
  str_homestory_chat_28824003 = "Ungkapan yang aneh...",
  str_homestory_chat_28824004 = "Saya juga merasa beberapa adat sarapan Astra itu aneh.",
  str_homestory_chat_28824005 = "Misalnya, saya dengar bahwa orang-orang Rediesel Wrench makan tusuk sate bakar untuk sarapan, sementara beberapa orang di Umbraton hanya minum air di pagi hari.",
  str_homestory_chat_28824006 = "Uh... Sejujurnya, itu hanya beberapa kasus khusus.",
  str_homestory_chat_28824007 = "Satai panggang?",
  str_homestory_chat_28824008 = "Itu hanyalah preferensi pribadi dari seseorang tertentu di Rediesel Wrench...",
  str_homestory_chat_28824009 = "Dan airnya?",
  str_homestory_chat_28824010 = "A-Ahem, aku cukup yakin mereka entah mencoba menurunkan berat badan atau mengurangi pengeluaran sehari-hari mereka.",
  str_homestory_chat_28824011 = "Bagaimanapun juga, itu bukanlah representasi yang baik dari kebiasaan sarapan normal di Astra.",
  str_homestory_chat_28824012 = "Jadi, seperti apa sarapan yang biasa?",
  str_homestory_chat_28824013 = "Roti, susu, telur, hal-hal seperti itu.",
  str_homestory_chat_28824014 = "Saya mengerti. Itu terdengar jauh lebih masuk akal, meskipun masih sangat berbeda dari makanan sarapan kita sendiri.",
  str_homestory_chat_28799999 = "Ada apa?",
  str_homestory_chat_28701001 = "Kamu terlihat cukup senggang sekarang.",
  str_homestory_chat_28701002 = "Apa? Sebenarnya aku punya hal yang sangat penting untuk didiskusikan denganmu.",
  str_homestory_chat_28701003 = "Aku?",
  str_homestory_chat_28701004 = "Ya, kamu! Aku perlu meramalkan keberuntunganmu sekarang juga!",
  str_homestory_chat_28701005 = "Sepertinya kamu baru saja mengarang itu...",
  str_homestory_chat_28701006 = "Tentu saja tidak! Aku sudah memikirkan ini jauh lebih awal—maksudku, aku sudah khawatir tentang kamu sejak beberapa waktu lalu.",
  str_homestory_chat_28701007 = "Dari yang bisa saya lihat, ramalan Anda menunjukkan bahwa Anda sangat rentan terhadap gangguan...",
  str_homestory_chat_28701008 = "Beneran?",
  str_homestory_chat_28701009 = "Ya! Dan bagi banyak orang, penyebab gangguan serius ini adalah kelebihan waktu luang...",
  str_homestory_chat_28701010 = "Sekarang kau hanya menyebutku pemalas, bukan?!",
  str_homestory_chat_28701011 = "Benar.",
  str_homestory_chat_28721001 = "Menurutmu, bagaimana tempat ini?",
  str_homestory_chat_28721002 = "Saya harus bilang, feng shui di sini benar-benar luar biasa...",
  str_homestory_chat_28721003 = "Ramalan saya mengatakan bahwa tempat ini sangat cocok untuk menjalani hidup dengan damai dan aman.",
  str_homestory_chat_28721004 = "Ini sangat cocok untuk memelihara berbagai jenis hewan, seperti burung misalnya...",
  str_homestory_chat_28721005 = "Mau pelihara burung di sini?",
  str_homestory_chat_28721006 = "Benar! May Apakah ada burung roh lainnya di sini?",
  str_homestory_chat_28721007 = "Ya.",
  str_homestory_chat_28721008 = "Tidak.",
  str_homestory_chat_28721009 = "Ah... Sayang sekali.",
  str_homestory_chat_28721010 = "Namun, saya harus bertanya... Mengapa Anda ingin memelihara lebih banyak burung?",
  str_homestory_chat_28721011 = "Aku berharap bisa memberikan Squawk dan Jabber beberapa teman baru. Lagipula, mereka juga sudah di sini cukup lama.",
  str_homestory_chat_28721012 = "Teman, ya...? Sepertinya mereka tidak benar-benar membutuhkan orang lain selain kamu.",
  str_homestory_chat_28721013 = "Untuk benar-benar menyesuaikan diri dengan adat istiadat Astra, tentu saja mereka memerlukan teman dari Astra juga.",
  str_homestory_chat_28721014 = "Dan dengan teman-teman baru, mungkin mereka tidak akan selalu ada di sampingku setiap jam dalam sehari.",
  str_homestory_chat_28721015 = "Sepertinya kamu hanya butuh istirahat dari mereka.",
  str_homestory_chat_28722001 = "Mau beli permen?",
  str_homestory_chat_28722002 = "Ya! Setelah makan dan tidur dengan baik, saya merasa segar dan siap untuk menikmati camilan kecil.",
  str_homestory_chat_28722003 = "Pikiranku terarah pada patung gula yang dibuat oleh peramal di tanah airku, jadi aku berpikir untuk bertanya pada Chubbs tentang hal itu...",
  str_homestory_chat_28722004 = "Hanya untuk menemukan bahwa hampir tidak ada makanan manis di sini! Apakah orang-orang Astra sangat tidak menyukai makanan manis?",
  str_homestory_chat_28722005 = "Sama sekali tidak! Lumopolis dan Umbraton terkenal dengan beberapa makanan penutup mereka!",
  str_homestory_chat_28722006 = "Faktanya, mereka memiliki berbagai jenis kue dengan desain yang indah...",
  str_homestory_chat_28722007 = "Apakah ada roti manis dengan patung gula?",
  str_homestory_chat_28722008 = "Ini kue.",
  str_homestory_chat_28722009 = "Keduanya adalah makanan penutup, jadi sama saja bagi saya.",
  str_homestory_chat_28722010 = "... Tidak apa-apa. Pokoknya, banyak kue dengan pola bunga yang cantik di atasnya.",
  str_homestory_chat_28722011 = "Untuk patung gula... Saya rasa saya belum pernah melihatnya.",
  str_homestory_chat_28722012 = "Lalu sepertinya saya harus menampilkan bakat unik saya segera. Kapan Anda bisa membawa saya untuk melihat kue-kue ini?",
  str_homestory_chat_28722013 = "Eh... Mungkin tidak dalam beberapa hari.",
  str_homestory_chat_28723001 = "Apa yang kamu rencanakan?",
  str_homestory_chat_28723002 = "Memang benar. Apakah panjiku menarik perhatianmu? Bagaimana menurutmu tentang itu?",
  str_homestory_chat_28723003 = "Tidak apa-apa...",
  str_homestory_chat_28723004 = "Mata tajam!",
  str_homestory_chat_28723005 = "Tentu saja, spanduk ini luar biasa.",
  str_homestory_chat_28723006 = "Ini hanya terlihat seperti spanduk biasa.",
  str_homestory_chat_28723007 = "Sigh... kamu tidak bisa melihat kehebatan di depan matamu.",
  str_homestory_chat_28723008 = "Banner ini mengandung kekuatan yang luar biasa: kebijaksanaan langit di atas, dan pengetahuan bumi di bawah...",
  str_homestory_chat_28723009 = "Apa kau baru saja...",
  str_homestory_chat_28723010 = "Dalam hal apapun, ini adalah panji yang sangat kuat dan luar biasa.",
  str_homestory_chat_28723011 = "Untuk alasan ini, kamu sangat diperbolehkan untuk mengibarkan bendera itu di menara tersebut dan menggunakannya sebagai bendera komando.",
  str_homestory_chat_28723012 = "Mungkin kamu harus memegangnya saja...",
  str_homestory_chat_31499999 = "Apa yang kamu lakukan, Navigator?",
  str_homestory_chat_31421001 = "Cuma mikir mau istirahat aja...",
  str_homestory_chat_31421002 = "Istirahat? Wajahmu memang terlihat seperti kehilangan warna.",
  str_homestory_chat_31421003 = "Apakah kamu merasa sakit sama sekali?",
  str_homestory_chat_31421004 = "Iya, sedikit...",
  str_homestory_chat_31421005 = "Sini, bagaimana kalau kuperiksa kamu sebentar saja?",
  str_homestory_chat_31421006 = "Tidak sama sekali…",
  str_homestory_chat_31421007 = "Tidak apa-apa, aku janji. Sebagai dokter, aku bisa tahu kapan seseorang merasa tidak enak badan.",
  str_homestory_chat_31421008 = "Hmm... Sekilas, tidak ada yang tampak luar biasa.",
  str_homestory_chat_31421009 = "Mungkin belakangan ini kamu terlalu memaksakan diri. Ingatlah untuk memberi tubuhmu cukup waktu untuk beristirahat.",
  str_homestory_chat_31421010 = "Apakah kamu perlu aku mengantar ke kamarmu?",
  str_homestory_chat_31421011 = "Tidak, terima kasih, saya bisa pergi ke sana sendiri.",
  str_homestory_chat_31421012 = "Tentu.",
  str_homestory_chat_31421013 = "Jika kamu pernah merasa kurang sehat... Jangan ragu untuk memberi tahu saya.",
  str_homestory_chat_31422001 = "Aku hendak jalan-jalan.",
  str_homestory_chat_31422002 = "Jalan-jalan... Itu bagus.",
  str_homestory_chat_31422003 = "Ngomong-ngomong, biasanya kamu berjalan-jalan sendirian?",
  str_homestory_chat_31422004 = "Mau ikut?",
  str_homestory_chat_31422005 = "Apakah itu tidak masalah? Sudah beberapa waktu ini aku ingin berjalan-jalan bersama denganmu.",
  str_homestory_chat_31422006 = "Tentu!",
  str_homestory_chat_31422007 = "Ya, aku lebih suka pergi sendiri.",
  str_homestory_chat_31422008 = "Saya setuju, sedikit kesendirian bisa sangat membantu seseorang mengatur pikiran mereka.",
  str_homestory_chat_31422009 = "Sayangnya... saat ini aku punya banyak pekerjaan yang harus dikerjakan.",
  str_homestory_chat_31422010 = "Kalau tidak, aku ingin berjalan-jalan bersama denganmu.",
  str_homestory_chat_31422011 = "Saya mengerti, jangan biarkan saya mengganggu pekerjaanmu!",
  str_homestory_chat_31422012 = "Sampai bertemu.",
  str_homestory_chat_31423001 = "Mencoba menyelesaikan pekerjaanku.",
  str_homestory_chat_31423002 = "Pasti terasa sulit bagi kamu kadang-kadang. Ingatlah untuk tidak terlalu memaksakan diri.",
  str_homestory_chat_31423003 = "Terlalu berlebihan terkadang bisa memberikan efek yang berlawanan.",
  str_homestory_chat_31423004 = "Percayalah padaku tentang itu.",
  str_homestory_chat_31423005 = "Tentu saja kamu tahu, tapi setiap hari aku menerima banyak pasien.",
  str_homestory_chat_31423006 = "Awalnya, aku tidak memperhatikan tuntutan tubuhku. Aku hanya ingin mengobati sebanyak mungkin orang...",
  str_homestory_chat_31423007 = "Syukurlah, pada akhirnya saya berhasil menyelamatkan mereka semua.",
  str_homestory_chat_31423008 = "Tapi akhirnya saya jatuh karena kelelahan tak lama kemudian...",
  str_homestory_chat_31423009 = "Aku tak sadar bisa seburuk itu.",
  str_homestory_chat_31423010 = "Memang bisa, makanya kamu harus tahu batasan diri kamu sendiri.",
  str_homestory_chat_31424001 = "Aku merencanakan pesta makan malam!",
  str_homestory_chat_31424002 = "Sebuah... pesta makan malam?",
  str_homestory_chat_31424003 = "Memangnya kenapa?",
  str_homestory_chat_31424004 = "Tidak, itu hanya... Membuatku mengingat beberapa hal.",
  str_homestory_chat_31424005 = "Dulu, kami sering mengadakan pesta makan malam bersama keluarga.",
  str_homestory_chat_31424006 = "Melihat ke belakang, rasanya seperti kita hampir mengalaminya setiap hari.",
  str_homestory_chat_31424007 = "Keluargamu pasti sangat besar!",
  str_homestory_chat_31424008 = "Mungkin itu benar, setidaknya dari perspektif angka...",
  str_homestory_chat_31424009 = "Tapi sekarang hanya ada saudara perempuan dan saya sendiri...",
  str_homestory_chat_31424010 = "Mau ikut dengan kami?",
  str_homestory_chat_31424011 = "Hah? Aku? Tidak, aku... Kayaknya aku lewat deh...",
  str_homestory_chat_31424012 = "Aku lebih atau kurang terbiasa makan sendirian.",
  str_homestory_chat_31424013 = "Rebecca...",
  str_homestory_chat_31424014 = "Maaf, kayaknya aku ngomong terlalu banyak ya...",
  str_homestory_chat_31424015 = "Mohon permisi...",
  str_homestory_chat_31425001 = "Hanya ingin bersantai sebentar.",
  str_homestory_chat_31425002 = "\"Tenang\"? Saya mengerti...",
  str_homestory_chat_31425003 = "Aku rasa sudah sangat lama aku juga tidak punya kesempatan untuk bersantai.",
  str_homestory_chat_31425004 = "Bolehkah saya tanya, apa yang biasanya Anda lakukan untuk mengurangi stres?",
  str_homestory_chat_31425005 = "Belanja pakaian!",
  str_homestory_chat_31425006 = "Berbelanja pakaian, ya...",
  str_homestory_chat_31425007 = "Mungkin saatnya juga untuk aku memperbarui lemari pakaianku?",
  str_homestory_chat_31425008 = "Makan makanan lezat!",
  str_homestory_chat_31425009 = "Makan, ya...",
  str_homestory_chat_31425010 = "Aku juga sudah memikirkan untuk mencoba itu, tapi kondisiku tidak terbaik untuk melakukannya.",
  str_homestory_chat_31425011 = "Makan di luar... kadang bisa memberikan efek buruk pada diriku.",
  str_homestory_chat_31425012 = "Kedengarannya sangat tidak praktis...",
  str_homestory_chat_31425013 = "Setelah ngobrol dengan kamu, tiba-tiba aku ingin pergi keluar untuk berbelanja.",
  str_homestory_chat_31425014 = "Tapi, aku harus segera kembali ke klinik...",
  str_homestory_chat_31425015 = "Tidak apa-apa, selalu ada lain kali!",
  str_homestory_chat_31425016 = "Baiklah kalau begitu, aku akan pergi sekarang.",
  str_homestory_chat_31425017 = "Semoga kamu merasa lebih baik hari ini juga.",
  str_homestory_chat_31599999 = "Lagi ngapain, Navigator?",
  str_homestory_chat_31521001 = "Aku baru saja mau melakukan latihan.",
  str_homestory_chat_31521002 = "Latihan, ya? Butuh pasangan?",
  str_homestory_chat_31521003 = "Aku bahkan akan memberimu penawaran! Diskon 20% untuk mitra pelatihan berkualitas tinggi!",
  str_homestory_chat_31521004 = "Aku akan baik-baik saja sendiri.",
