  str_homestory_chat_31824022 = "Hari ini sangat menyenangkan. Pastikan untuk menikmatinya saat Anda beristirahat.",
  str_homestory_chat_31824023 = "Baiklah!",
  str_homestory_chat_31825001 = "Aku ingin mengunjungi teman.",
  str_homestory_chat_31825002 = "Mereka selalu membantu saya selama ini.",
  str_homestory_chat_31825003 = "Aku juga akan menemuimu... Oops, kejutannya malah terbocorkan.",
  str_homestory_chat_31825004 = "Saya senang mendengarnya.",
  str_homestory_chat_31825005 = "Tapi, seorang pria tua seperti saya tidak memerlukan kejutan.",
  str_homestory_chat_31825006 = "Sungguh menyedihkan tanpa ada kejutan.",
  str_homestory_chat_31825007 = "Bayangan harus selalu tenang.",
  str_homestory_chat_31825008 = "Hal yang tak terduga itu menyenangkan.",
  str_homestory_chat_31825009 = "Tidak semua hal yang tak terduga itu menyenangkan.",
  str_homestory_chat_31825010 = "Sekarang saya lebih suka hidup yang stabil.",
  str_homestory_chat_31825011 = "Salahku aku tergelincir. Sekarang tidak menyenangkan lagi.",
  str_homestory_chat_31825012 = "Saya belum mendapatkan kejutan itu.",
  str_homestory_chat_31825013 = "Jadi kamu masih baik-baik saja.",
  str_homestory_chat_31825014 = "Oke, aku sedang dalam perjalanan keluar pintu, kalau begitu!",
  str_homestory_chat_31825015 = "Tentu. Aku akan mencoba untuk tidak mengintip lebih awal.",
  str_homestory_chat_31825016 = "Harap kamu membuatnya menjadi kejutan yang menyenangkan.",
  str_homestory_chat_31825017 = "Kamu tidak akan kecewa!",
  str_homestory_chat_31825018 = "Setelah semua, ini adalah waktu istirahat yang sulit didapatkan.",
  str_homestory_chat_31825019 = "May bayangan menjaga kamu. Aku akan menunggu.",
  str_homestory_chat_31999999 = "Apakah Anda memiliki permintaan saat ini, tamu yang terhormat?",
  str_homestory_chat_31921001 = "Tidak ada yang khusus, tidak.",
  str_homestory_chat_31921002 = "Aku baru saja menerima kiriman baru dan aku sedang mencari pembeli.",
  str_homestory_chat_31921003 = "Apakah kamu tertarik?",
  str_homestory_chat_31921004 = "Pengiriman? Jenis pengiriman apa?",
  str_homestory_chat_31921005 = "Jade barang dari Longzhou.",
  str_homestory_chat_31921006 = "Jade barang?",
  str_homestory_chat_31921007 = "Ya. Pernahkah kamu mendengarnya sebelumnya?",
  str_homestory_chat_31921008 = "Tidak.",
  str_homestory_chat_31921009 = "Itu lebih alasan lagi untuk memeriksanya. Aku jamin kamu tidak akan kecewa.",
  str_homestory_chat_31921019 = "Ahem... Aku tidak yakin bisa membelinya.",
  str_homestory_chat_31921020 = "Tidak mungkin! Tapi tidak apa-apa, aku akan di sini ketika kamu berubah pikiran.",
  str_homestory_chat_31922001 = "Aku hanya memutar-mutar ibu jari ku sekarang.",
  str_homestory_chat_31922002 = "Maksudmu, kau sangat bosan karena tidak punya kegiatan?",
  str_homestory_chat_31922003 = "Bisa dikatakan begitu.",
  str_homestory_chat_31922004 = "Lalu, bagaimana kalau bermain game denganku?",
  str_homestory_chat_31922005 = "Game? Game apa?",
  str_homestory_chat_31922006 = "Satu yang sangat sederhana.",
  str_homestory_chat_31922007 = "Saya punya Nightium di sini yang akan saya lemparkan ke udara.",
  str_homestory_chat_31922008 = "Lalu?",
  str_homestory_chat_31922009 = "Mari kita tebak apakah itu akan mendarat dengan wajah menghadap ke atas atau ke bawah.",
  str_homestory_chat_31922010 = "Jika kamu benar, koin itu milikmu.",
  str_homestory_chat_31922011 = "Bagaimana jika aku salah?",
  str_homestory_chat_31922012 = "Maka kamu salah.",
  str_homestory_chat_31922013 = "Hah?",
  str_homestory_chat_31922014 = "Itu berarti tidak apa-apa jika tebakanmu salah. Tanpa ada ikatan apapun.",
  str_homestory_chat_31922015 = "Bukankah itu hanya akan bekerja untuk keuntunganku saja?",
  str_homestory_chat_31922016 = "Ya, tapi ini hanya satu Nightium.",
  str_homestory_chat_31922017 = "Apa yang kita dapatkan dari ini jauh melebihi nilai nominal, dan mungkin saya tidak akan kalah, kan?",
  str_homestory_chat_31923001 = "Aku sedang memeriksa buku kas induk.",
  str_homestory_chat_31923002 = "Apakah ada masalah dengan itu? Saya bisa membantu jika perlu.",
  str_homestory_chat_31923003 = "Apakah Anda keberatan untuk melihatnya?",
  str_homestory_chat_31923004 = "Tentu, senang hati adalah milikku sepenuhnya.",
  str_homestory_chat_31923005 = "Biar aku yang meringankan bebanmu...",
  str_homestory_chat_31923006 = "Aku mengerti. Buku besar ini cukup buruk dalam penyimpanan dan pengorganisasian.",
  str_homestory_chat_31923007 = "Aku tidak mau merepotkan kalian...",
  str_homestory_chat_31923008 = "Tidak apa-apa, saya mengerti. Tapi sejujurnya, buku besar sangat penting bagi setiap institusi.",
  str_homestory_chat_31923009 = "Aku memang cukup berpengalaman dalam mengelola akun, jadi bolehkah aku memberikan beberapa saran?",
  str_homestory_chat_31923010 = "Benarkah? Setiap saran dari Nona Sheol akan sangat membantu saya!",
  str_homestory_chat_31923011 = "Terima kasih!",
  str_homestory_chat_31923012 = "Heheh, sama-sama.",
  str_homestory_chat_31923013 = "Ini hanya tips dan petunjuk kecil.",
  str_homestory_chat_31923014 = "Setiap entri harus sedetail mungkin, tetapi juga harus singkat.",
  str_homestory_chat_31923015 = "Tentu saja, tanggal dan tujuan harus dicantumkan dalam kolom yang terpisah. Selain itu, mencatat jumlah dalam dua format dapat mengurangi kesalahan.",
  str_homestory_chat_31923016 = "Dengan cara ini, jauh lebih mudah untuk meninjau.",
  str_homestory_chat_31923017 = "Aku tahu.",
  str_homestory_chat_31923018 = "Lalu…",
  str_homestory_chat_31923019 = "Tunggu sebentar! Aku perlu menuliskan ini!",
  str_homestory_chat_31924001 = "Aku haus dan ingin minum sesuatu.",
  str_homestory_chat_31924002 = "Bagaimana dengan secangkir kopi?",
  str_homestory_chat_31924003 = "Kopi?",
  str_homestory_chat_31924004 = "Ya, saya baru saja membeli beberapa biji kopi yang bagus.",
  str_homestory_chat_31924005 = "Sangat bagus jika mendapatkan pendapat kedua.",
  str_homestory_chat_31924006 = "Tapi aku tidak tahu banyak tentang kopi...",
  str_homestory_chat_31924007 = "Tidak apa-apa. Berikan pendapatmu setelah meneguknya.",
  str_homestory_chat_31924008 = "Saya tidak keberatan mencobanya jika hanya itu yang dibutuhkan.",
  str_homestory_chat_31924009 = "Apakah kamu suka kopi, Nona Sheol?",
  str_homestory_chat_31924010 = "Tidak begitu, tapi juga tidak membencinya.",
  str_homestory_chat_31924011 = "Lalu kenapa Anda membeli biji kopi daripada kopi bubuk?",
  str_homestory_chat_31924012 = "Tidak ada alasan khusus. Biji kopi adalah salah satu dari banyak usaha bisnis Guild Cloudrover, bagaimanapun.",
  str_homestory_chat_31924013 = "Aku baru saja mendapatkan dorongan untuk mencicipinya sendiri.",
  str_homestory_chat_31925001 = "Selanjutnya, waktunya bagi saya untuk belajar.",
  str_homestory_chat_31925002 = "Waktu belajar?",
  str_homestory_chat_31925003 = "Dengan kata lain, baca buku.",
  str_homestory_chat_31925004 = "Saya mengerti. May Buku jenis apa yang sedang kamu rencanakan untuk baca?",
  str_homestory_chat_31925005 = "Sejarah dan geografi.",
  str_homestory_chat_31925006 = "Saya juga tahu sedikit tentang subjek-subjek ini. May Bolehkah saya memberikan rekomendasi kepada Anda?",
  str_homestory_chat_31925007 = "Anda berpengetahuan dalam bidang seperti itu, Nona Sheol?",
  str_homestory_chat_31925008 = "Sebagai pedagang, semakin banyak saya tahu, semakin baik. Dengan demikian, saya dapat berbicara dengan pelanggan dari berbagai bidang perdagangan.",
  str_homestory_chat_31925009 = "Seseorang harus bekerja keras untuk menjadi pedagang hebat, aku melihatnya.",
  str_homestory_chat_31925010 = "Ekonomi.",
  str_homestory_chat_31925011 = "Oh? Kamu tertarik dengan ekonomi?",
  str_homestory_chat_31925012 = "Tidak begitu tertarik tapi penasaran.",
  str_homestory_chat_31925013 = "Belum lagi selalu lebih baik untuk membaca lebih banyak buku.",
  str_homestory_chat_31925014 = "Benar sekali.",
  str_homestory_chat_31925015 = "Aku punya banyak buku bagus dari koleksi pribadiku yang bisa aku rekomendasikan.",
  str_homestory_chat_31925016 = "Tolong mampir kapan-kapan ya.",
  str_homestory_chat_32099999 = "Saya ingin mendekor ulang kantor saya! Menurutmu gaya apa yang paling cocok?",
  str_homestory_chat_32021001 = "Gaya Northland!",
  str_homestory_chat_32021002 = "Oh? Yah, banyak bagian dari Northland memang terlihat seperti keluaran dari dongeng, terutama dekorasi dan arsitekturnya.",
  str_homestory_chat_32021003 = "Aku tidak menyadari bahwa kamu begitu romantis.",
  str_homestory_chat_32021004 = "Kamu seorang ilmuwan.",
  str_homestory_chat_32021005 = "Ide ide romantis seperti ini mungkin mengganggumu, 'kan?",
  str_homestory_chat_32021006 = "Kamu berasal dari Illumina Federation.",
  str_homestory_chat_32021007 = "Bukankah itu berarti kamu menentang ide-ide tidak praktis dan romantis seperti ini?",
  str_homestory_chat_32021008 = "Apa kesalahpahaman yang monumental!",
  str_homestory_chat_32021009 = "Benar bahwa saya adalah ilmuwan dari Illumina Federation...",
  str_homestory_chat_32021010 = "Jadi, sangat alami bagi semua orang untuk percaya bahwa saya tidak ingin ada hubungan dengan romantisme.",
  str_homestory_chat_32021011 = "Tapi saya percaya bahwa ini adalah pandangan yang sangat sempit tentang gagasan tersebut.",
  str_homestory_chat_32021012 = "Untuk menjadikan yang tidak diketahui menjadi dimengerti, untuk mengubah gurun menjadi kota...",
  str_homestory_chat_32021013 = "Bukankah itu juga romantis dengan caranya sendiri?",
  str_homestory_chat_32021014 = "Kurasa itu masuk akal.",
  str_homestory_chat_32021015 = "Wah, tak kusangka kau juga pandai berdebat.",
  str_homestory_chat_32021016 = "Saya juga seseorang yang sangat pandai menerima saran.",
  str_homestory_chat_32021017 = "Inilah sebabnya saya memutuskan untuk mendekorasi ulang kantor saya dengan gaya Northland!",
  str_homestory_chat_32022001 = "Gaya Lumopolis!",
  str_homestory_chat_32022002 = "Gaya Lumopolis memiliki nuansa yang sangat klasik dan saleh.",
  str_homestory_chat_32022003 = "Dengan semua kabel dan mesin yang berjalan melalui kantor saya, saya tidak yakin apakah gaya dekorasi seperti itu akan cocok...",
  str_homestory_chat_32022004 = "Tapi, kepribadianmu penuh dengan kontradiksi.",
  str_homestory_chat_32022005 = "Kontras yang tajam inilah yang membuatnya sangat cocok!",
  str_homestory_chat_32022006 = "Benda-benda yang tidak cocok juga memiliki pesona tersendiri.",
  str_homestory_chat_32022007 = "Siapa bilang hal-hal harus cocok untuk menjadi indah?",
  str_homestory_chat_32022008 = "Hahahaha! Anda membuat poin yang bagus!",
  str_homestory_chat_32022009 = "Pengetahuan dan ketajaman persepsi Anda adalah kualitas yang sangat luar biasa.",
  str_homestory_chat_32022010 = "Bisakah mereka berasal dari perjalananmu yang tak terhitung jumlahnya ke seluruh dunia?",
  str_homestory_chat_32022011 = "Saya yakin itu juga karena kita sudah saling kenal begitu lama...",
  str_homestory_chat_32022012 = "Aku akan menganggap itu sebagai pujian!",
  str_homestory_chat_32023001 = "Gaya Umbraton!",
  str_homestory_chat_32023002 = "Apa saran yang sulit untuk ditawarkan.",
  str_homestory_chat_32023003 = "Jadi ceritakan padaku, bagaimana sebenarnya kamu mendefinisikan gaya Umbraton?",
  str_homestory_chat_32023004 = "Dari pengalaman saya, Umbraton cenderung menekankan pada keragaman.",
  str_homestory_chat_32023005 = "Itu keindahannya. Kamu tidak melihat...?",
  str_homestory_chat_32023006 = "Mungkin tampak seperti saran acak, tetapi ketika Anda benar-benar memikirkannya...",
  str_homestory_chat_32023007 = "Ini adalah ide sempurna yang mencakup semua saran!",
  str_homestory_chat_32023008 = "Faktanya, Anda tidak perlu khawatir tentang mendekorasi ulang kantor Anda lagi! Tidak dalam lima puluh tahun ke depan!",
  str_homestory_chat_32023009 = "Wow... Terkadang ide-ideku begitu bagus sampai-sampai aku sendiri terkejut!",
  str_homestory_chat_32023010 = "Anda hanya mencari alasan karena Anda tidak bisa memikirkan ide yang lebih baik, bukan?",
  str_homestory_chat_32023011 = "Heheh... Apakah aku keceplosan?",
  str_homestory_chat_32023012 = "Tidak apa-apa. Saya rasa saya sebagian harus disalahkan karena kamu berakhir seperti ini, jadi saya tidak akan terus mendesak masalah ini.",
  str_homestory_chat_32023013 = "Jadi selama ini kamu sudah tahu!",
  str_homestory_chat_32023014 = "Aku jenius dalam setiap pengertian kata itu. Jangan pernah lupa itu.",
  str_homestory_chat_32024001 = "Gaya Longzhou!",
  str_homestory_chat_32024002 = "Wow, aku tidak percaya kamu menyarankan itu...",
  str_homestory_chat_32024003 = "Aku selalu terpesona dengan gaya dekorasi dari negeri yang jauh itu...",
  str_homestory_chat_32024004 = "Tapi, apakah kamu tahu berapa kira-kira harganya?",
  str_homestory_chat_32024005 = "Bahkan sesuatu yang sederhana seperti kursi kayu...",
  str_homestory_chat_32024006 = "Biayanya sama seperti mendekorasi ulang seluruh kantor saya sekali lagi!",
  str_homestory_chat_32024007 = "Jenis kemewahan itu selalu di luar jangkauan orang biasa seperti kita, teman Caelestiteku.",
  str_homestory_chat_32024008 = "\"Orang normal\"?",
  str_homestory_chat_32024009 = "Aku tak pernah menyangka bisa mendengar kamu menyebut dirimu sendiri sebagai \"orang biasa\" dalam hidupku...",
  str_homestory_chat_32024010 = "Atau untuk menempatkan dirimu di levelku, dalam hal ini...",
  str_homestory_chat_32024011 = "Terima kasih, Longzhou!",
  str_homestory_chat_32024012 = "Apakah benar itu sangat mahal?",
  str_homestory_chat_32024013 = "Saya tidak tahu jika furnitur Longzhou begitu mahal...",
  str_homestory_chat_32024014 = "Maafkan saya, Longzhou!",
  str_homestory_chat_32024015 = "... Ugh, terima kasih telah mengingatkan saya bahwa saya tidak akan pernah mencapai impian saya memiliki kantor ala Longzhou.",
  str_homestory_chat_32024016 = "Sekarang kompensasikan saya untuk penderitaan mental saya!",
  str_homestory_chat_32024017 = "T-Tapi aku tidak punya uang sama sekali!",
  str_homestory_chat_32025001 = "Gaya Caelestite!",
  str_homestory_chat_32025002 = "Jadi gaya Anda sendiri? Jawaban yang benar-benar tak terduga.",
  str_homestory_chat_32025003 = "Maksudku adalah gaya kaumku, bukan gayaku sendiri...",
  str_homestory_chat_32025004 = "Lalu, apakah Anda bersedia untuk mendekorasi ulang kantor saya secara pribadi?",
  str_homestory_chat_32025005 = "Bagaimana kamu bisa mendapatkan ide itu dari saran saya?!",
  str_homestory_chat_32025006 = "Yah, di dunia ini—",
  str_homestory_chat_32025007 = "Satu-satunya yang familiar dengan gaya kaum Caelestite tidak lain adalah dirimu sendiri.",
  str_homestory_chat_32025008 = "K-Kamu tidak perlu mengatakannya seperti itu!",
  str_homestory_chat_32025009 = "Selain itu, ada banyak sejarawan dan arkeolog di Lumopolis dan Federasi Illumina yang bisa membantu kamu...",
  str_homestory_chat_32025010 = "Saya yakin mereka tahu semua tentang gaya kaum Caelestite.",
  str_homestory_chat_32025011 = "Ya, tapi kenapa aku lebih memilih bantuan mereka daripada kamu...",
  str_homestory_chat_32025012 = "Bisakah kamu beri aku, katakanlah satu, alasan?",
  str_homestory_chat_32025013 = "... Aku tidak bisa.",
  str_homestory_chat_32025014 = "Tapi saya bisa memikirkan tiga alasan bagus mengapa kamu ingin bantuan saya.",
  str_homestory_chat_32025015 = "Pertama, aku murah. Kedua, aku tidak akan menagih sebanyak itu. Dan ketiga, aku akan menghemat uangmu...",
  str_homestory_chat_32025016 = "Hahahaha! Kamu tidak seharusnya merendahkan dirimu sendiri, tahu!",
  str_homestory_chat_32025017 = "Saya bertanya karena saya tahu kamu akan melakukan pekerjaan yang hebat dalam mendekorasi kantor saya.",
  str_homestory_chat_32025018 = "Dan juga karena aku sangat menikmati mengobrol denganmu.",
  str_homestory_chat_32025019 = "Itu saja!",
  str_homestory_chat_32199999 = "Apa yang ingin kamu harapkan?",
  str_homestory_chat_32121001 = "Perdamaian dunia.",
  str_homestory_chat_32121002 = "Wow, untuk seseorang membuat permintaan tanpa pamrih seperti ini—",
  str_homestory_chat_32121003 = "Kamu sama sekali tidak menganggapnya serius...",
  str_homestory_chat_32121004 = "Atau kau benar-benar menginginkan sesuatu yang sebesar itu.",
  str_homestory_chat_32121005 = "Jadi, mana yang berlaku untukmu, PlayerName?",
  str_homestory_chat_32121006 = "Tidak menganggapnya serius.",
  str_homestory_chat_32121007 = "Haha, itu memang cocok dengan gaya Anda.",
  str_homestory_chat_32121008 = "Kamu bukanlah tipe orang yang hanya berharap dan berdoa untuk masa depan. Ketika kamu benar-benar menginginkan sesuatu, kamu mengejarnya dan menjadikannya kenyataan...",
  str_homestory_chat_32121009 = "Saya ingin sesuatu yang sebesar itu.",
  str_homestory_chat_32121010 = "Dengan kata lain, kedamaian dunia adalah tujuan sejati Anda dalam hidup ini.",
  str_homestory_chat_32121011 = "Kamu berusaha keras untuk memastikan setiap langkah yang kamu ambil membawa kamu lebih dekat ke mimpi itu...",
  str_homestory_chat_32121012 = "Dalam ribuan tahun hidupku, orang seperti kamu selalu memberiku sakit kepala yang paling parah.",
  str_homestory_chat_32121013 = "Hah? Kenapa?",
  str_homestory_chat_32121014 = "Karena orang-orang seperti kamu juga adalah orang-orang yang pada akhirnya merubah dunia.",
  str_homestory_chat_32122001 = "Damai dan keamanan untuk orang-orang yang kusayangi.",
  str_homestory_chat_32122002 = "Saya sering mendengar keinginan seperti itu di kuil saya.",
  str_homestory_chat_32122003 = "Membuatku bertanya-tanya, apakah orang-orang yang membuat permohonan seperti ini bahagia atau hanya sial?",
  str_homestory_chat_32122004 = "Senang, tentu saja!",
  str_homestory_chat_32122005 = "Ini berarti mereka menyimpan teman dan orang yang mereka cintai di dalam hati mereka, dan menginginkan mereka untuk bahagia juga...",
  str_homestory_chat_32122006 = "Bagaimana mungkin mereka bisa sial?",
  str_homestory_chat_32122007 = "Karena kebahagiaan hanya bertahan sejenak.",
  str_homestory_chat_32122008 = "…!",
  str_homestory_chat_32122009 = "Satu-satunya alasan orang membuat keinginan seperti ini adalah karena mereka sadar akan hal itu, bukan kah kamu setuju?",
  str_homestory_chat_32122010 = "… Benar juga.",
  str_homestory_chat_32122011 = "Dalam dunia yang dikuasai oleh Eclipsite, kita selalu berisiko menghadapi kesialan yang tak terduga.",
  str_homestory_chat_32122012 = "Itulah sebabnya aku ingin melakukan segala yang bisa aku lakukan untuk memastikan teman-temanku aman.",
  str_homestory_chat_32122013 = "Bahkan jika itu sesuatu yang sepele seperti membuat permintaan untuk mereka.",
  str_homestory_chat_32122014 = "Heh. Alam semesta ini tidak kekal, dan namun seringkali orang menemukan kekuatan dan makna karena hal itu.",
  str_homestory_chat_32122015 = "Inilah alasan tepatnya mengapa aku sangat menghormati dan mengagumi manusia.",
  str_homestory_chat_32123001 = "Untuk mengunjungi setiap sudut dunia.",
  str_homestory_chat_32123002 = "Oh? Itu bukanlah harapan yang sering kudengar setiap hari, PlayerName.",
  str_homestory_chat_32123003 = "Kamu sudah lebih dari mampu untuk melakukan itu, jadi kenapa harus menjadikannya sebuah harapan?",
  str_homestory_chat_32123004 = "Bisakah itu karena ada sesuatu yang menghalangi?",
  str_homestory_chat_32123005 = "Aku tidak punya uang.",
  str_homestory_chat_32123006 = "\"Ada mereka yang hidup untuk kesenangan, namun keadaan hidup menyangkal kegembiraan mereka.\"",
  str_homestory_chat_32123007 = "Tapi itu cukup mudah diatasi! Ambil saja beberapa perhiasan saya dan gadai untuk mendapatkan uang tunai!",
  str_homestory_chat_32123008 = "Terlalu banyak monster.",
  str_homestory_chat_32123009 = "\"Sebuah beruang menghalangi jalan sementara harimau dan leopard mengaum di sisi kita.\"",
  str_homestory_chat_32123010 = "Tapi pastinya bahkan Eclipsites yang paling tangguh sekalipun tidak akan menjadi lawan bagi kamu jika aku berada di sisimu, bukan?",
  str_homestory_chat_32123011 = "Ngomong-ngomong, PlayerName, apakah kamu mengerti arti dari puisi-puisiku?",
  str_homestory_chat_32123012 = "Ya, saya mendengar banyak hal saat berkelana di Longzhou.",
  str_homestory_chat_32123013 = "Semakin aku melihat dan mendengar mereka, semakin mereka mulai terasa masuk akal.",
  str_homestory_chat_32123014 = "Kamu benar-benar tahu cara belajar dari perjalananmu, PlayerName!",
  str_homestory_chat_32123015 = "Trims!",
  str_homestory_chat_32123016 = "Lagipula, kamu sekarang adalah teman baikku. Aku tidak bisa membiarkan kamu melakukan semua pekerjaan berat, tahu.",
  str_homestory_chat_32123017 = "Itulah sebabnya saya akan terus menjelajahi dunia dan meningkatkan diri sebanyak mungkin!",
  str_homestory_chat_32123018 = "Bagus, bagus! Aku akan menunggumu.",
  str_homestory_chat_32124001 = "Untuk bersembunyi di Colossus selamanya.",
  str_homestory_chat_32124002 = "Aku benar-benar mengerti! Tidak ada yang lebih nyaman daripada menyendiri di sarang kecilmu sendiri.",
  str_homestory_chat_32124003 = "Benar kan? Terkadang liburan di rumah saja adalah yang kita butuhkan!",
  str_homestory_chat_32124004 = "Terutama saat dingin dan salju turun di luar, seperti pada musim dingin...",
  str_homestory_chat_32124005 = "Tidak ada yang seperti meringkuk di rumah dengan minuman hangat dan buku yang bagus...",
  str_homestory_chat_32124006 = "Apa kamu benar-benar melakukan semua itu?",
  str_homestory_chat_32124007 = "Biasanya aku hanya tidur sepanjang waktu.",
  str_homestory_chat_32124008 = "Kamu harus mencobanya lain kali.",
  str_homestory_chat_32124009 = "Nah, itu terdengar menarik!",
  str_homestory_chat_32124010 = "Hmm... Pertama, aku harus mendapatkan selimut yang bagus dan besar!",
  str_homestory_chat_32124011 = "Mungkin saya akan melakukannya dengan cara Anda lain kali.",
  str_homestory_chat_32124012 = "Oke! Kita bahkan bisa melakukannya bersama!",
  str_homestory_chat_32124013 = "Dengan begitu, kamu bisa membangunkanku pada waktu yang wajar!",
  str_homestory_chat_32124014 = "Aku tidak pernah tahu bahwa keinginan hatimu begitu sederhana, PlayerName.",
  str_homestory_chat_32124015 = "Awalnya saya pikir kamu ingin membawa kembali rakyatmu, atau sesuatu seperti itu...",
  str_homestory_chat_32124016 = "Sudah terlambat untuk mengubah hal-hal seperti itu...",
  str_homestory_chat_32124017 = "Selain itu, harapan seharusnya digunakan untuk meningkatkan hidup kita dan hidup teman-teman kita, bukan?",
  str_homestory_chat_32124018 = "Tepat sekali. Menerima bahwa masa lalu telah selesai adalah tindakan yang berani.",
  str_homestory_chat_32125001 = "Untuk kebahagiaanmu selamanya!",
  str_homestory_chat_32125002 = "Hah? Kamu benar-benar akan menyia-nyiakan permohonan sekali seumur hidup untukku seperti itu?",
  str_homestory_chat_32125003 = "Kenapa?",
  str_homestory_chat_32125004 = "Karena harapan harus diucapkan demi teman dan keluarga kita!",
  str_homestory_chat_32125005 = "Selain itu, lebih baik berjuang untuk hal-hal yang kamu inginkan daripada hanya berharap mendapatkannya.",
  str_homestory_chat_32125006 = "... Hahaha, aku selalu ingin mengatakan itu! Terdengar cukup keren, kan?",
  str_homestory_chat_32125007 = "... Itu berhasil.",
  str_homestory_chat_32125008 = "Tidak perlu tertawa tentang itu juga. Aku tidak akan pernah mengejekmu karena itu.",
  str_homestory_chat_32125009 = "Mungkin aku juga harus membuat permintaan?",
  str_homestory_chat_32125010 = "Oh? Seorang dewi yang sedang berdoa, huh? Sepertinya ini pertama kalinya untuk segalanya!",
  str_homestory_chat_32125011 = "Dengan cahaya matahari dan bulan serta kekuatan sungai dan lautan.",
  str_homestory_chat_32125012 = "May teman saya PlayerName nikmati kekuatan tubuh, istirahat yang nyaman, dan kebahagiaan di hari-hari yang akan datang.",
  str_homestory_chat_32125013 = "A-Apa aku baru saja mendengar namaku...?",
  str_homestory_chat_32125014 = "Dengan kata lain, saya berharap Anda memiliki kesehatan yang baik, makanan yang enak, tidur yang nyenyak...",
  str_homestory_chat_32125015 = "Dan tahun baru yang sangat bahagia!",
  str_homestory_chat_32125016 = "Wow...",
  str_homestory_chat_32125017 = "Sekarang kita bisa memiliki satu tahun bahagia lagi bersama.",
  str_homestory_chat_32125018 = "Percayalah padaku, keinginan naga seharusnya tidak pernah dianggap remeh.",
  str_homestory_chat_32125019 = "G-Mengerti! Juga...",
  str_homestory_chat_32125020 = "Terima kasih, Chen'ni.",
  str_homestory_chat_32299999 = "Apa yang kamu lakukan, PlayerName?",
  str_homestory_chat_32221001a = "Hmm…",
  str_homestory_chat_32221001 = "Aku akan menghabiskan hari ini di tempat tidur.",
  str_homestory_chat_32221002 = "Sepanjang hari? Kamu mengingatkan saya pada salah satu murid senior saya.",
  str_homestory_chat_32221003 = "Murid seniormu?",
  str_homestory_chat_32221004 = "Ya. Dia dulu merawatku dengan sangat baik, tapi...",
  str_homestory_chat_32221005 = "Dia tidak pernah menganggap sesuatu dengan serius. Bahkan, beberapa orang bahkan akan mengatakan dia malas.",
  str_homestory_chat_32221006 = "Bicara tentang tidur siang sepanjang waktu.",
  str_homestory_chat_32221007 = "Tapi kemampuannya sangat hebat, dan master kami menganggapnya sebagai seorang jenius.",
  str_homestory_chat_32221008 = "Ketika aku memikirkannya, dia mungkin berada di level yang sama sekali berbeda dari kita.",
  str_homestory_chat_32221009 = "Akan membaca sedikit.",
  str_homestory_chat_32221010 = "Membaca, huh? Saya penasaran jenis buku apa yang kamu baca?",
  str_homestory_chat_32221011 = "Di masa kuil dulu, saya hanya membaca berbagai jenis buku.",
  str_homestory_chat_32221012 = "Selain studi metafisika, kami juga membaca tentang seni bela diri dan berbagai hal lainnya.",
  str_homestory_chat_32221013 = "Meski dulu aku sedikit lebih tertarik pada latihan bela diri daripada buku...",
  str_homestory_chat_32221014 = "Bagaimana kalau kita berikan pelajaran singkat tentang sastra kepada teman-teman iblis kita?",
  str_homestory_chat_32221015 = "Setelah semua, hanya mengetahui cara bertarung saja tidaklah cukup.",
  str_homestory_chat_32221016 = "Baiklah, aku akan bicara dengan Ah Ding dan yang lainnya. Sampai jumpa nanti!",
  str_homestory_chat_32221017 = "Tentu, sampai jumpa lagi.",
  str_homestory_chat_32222001 = "Mungkin akan menyelesaikan beberapa pekerjaan.",
  str_homestory_chat_32222002 = "Kerja, hah? Iya, aku juga.",
  str_homestory_chat_32222003 = "Aku baru saja menerima pekerjaan baru hari ini.",
  str_homestory_chat_32222004 = "Tampaknya ada sesuatu yang membuat keributan di rumah tua, tetapi mereka tidak tahu apakah itu Eclipsite atau binatang liar.",
  str_homestory_chat_32222005 = "Tidak ada bedanya, sebenarnya. Saya akan menyeret apa pun yang ada di sana dan memberinya pukulan yang bagus.",
  str_homestory_chat_32222006 = "Semoga tidak ada yang salah...",
  str_homestory_chat_32222007 = "Jangan khawatir, Ah Ding dan yang lainnya akan bersama saya.",
  str_homestory_chat_32222008 = "Jika ada yang salah, aku selalu bisa mengandalkan teknik sundulan besi Ah Ding.",
  str_homestory_chat_32222009 = "Semoga berhasil!",
  str_homestory_chat_32222010 = "Yah, sebaiknya aku mulai bersiap-siap untuk pergi.",
  str_homestory_chat_32223001 = "Mungkin akan mengunjungi seorang teman.",
  str_homestory_chat_32223002 = "Mengunjungi seorang teman? Itu selalu baik.",
  str_homestory_chat_32223003 = "Saya telah berkelana di Longzhou selama bertahun-tahun dan telah membuat banyak teman dalam waktu itu.",
  str_homestory_chat_32223004 = "Ngomong-ngomong, pernahkah kamu berteman dengan orang yang tidak memiliki kesamaan apapun denganmu?",
  str_homestory_chat_32223005 = "Ya.",
  str_homestory_chat_32223006 = "Aku punya firasat kau akan bilang begitu.",
  str_homestory_chat_32223007 = "Bagaimanapun, Colossus ini adalah rumah bagi banyak orang dengan keturunan fiendling.",
  str_homestory_chat_32223008 = "Dunia ini luas, dan pandangan orang-orang harus sama luasnya.",
  str_homestory_chat_32223009 = "Tidak terlalu.",
  str_homestory_chat_32223010 = "Benarkah...? Kurasa itu juga bisa dimengerti.",
  str_homestory_chat_32223011 = "Bagaimanapun, dunia ini penuh dengan masalah yang lahir dari kesalahpahaman antar manusia.",
  str_homestory_chat_32223012 = "Tapi, saya pikir orang-orang akan menjadi lebih bijaksana suatu hari nanti...",
  str_homestory_chat_32223013 = "Cukup bijaksana untuk menerima hal-hal yang tidak mereka mengerti.",
  str_homestory_chat_32223014 = "Semoga saja.",
  str_homestory_chat_32224001 = "Saya hendak berolahraga.",
  str_homestory_chat_32224002 = "Olahraga, ya? Tiba-tiba saya tidak merasa lelah lagi!",
  str_homestory_chat_32224003 = "Pelatihan itu seperti membuat istana dari pasir: semuanya akan hancur jika kamu berhenti meski hanya sehari.",
  str_homestory_chat_32224004 = "Jadi, bagaimana menurutmu? Bolehkah aku bergabung denganmu hari ini?",
  str_homestory_chat_32224005 = "Kamu memiliki dasar yang baik, dan latihan pasti akan menggali potensi luar biasa dalam dirimu.",
  str_homestory_chat_32224006 = "T-Tidak apa-apa...",
  str_homestory_chat_32224007 = "Benarkah? Sayang sekali.",
  str_homestory_chat_32224008 = "Mungkin aku akan berlatih dengan anak-anak iblis saja.",
  str_homestory_chat_32224009 = "Tentu. Kamu seharusnya bisa mengangkat Ah Ding tanpa masalah!",
  str_homestory_chat_32224010 = "Di sisi lain, gajah fiendling dari Kerajaan Dian...",
  str_homestory_chat_32224011 = "Saya bahkan tidak akan mencoba mengangkat salah satu dari itu!",
  str_homestory_chat_146901001 = "Pierre",
  str_homestory_chat_124901001 = "Curo",
  str_homestory_chat_151901001 = "Sork",
  str_homestory_chat_173901001 = "Patsy",
  str_homestory_chat_104901001 = "Kuma",
  str_homestory_chat_115901001 = "Hachi",
  str_homestory_chat_247901001 = "Momo",
  str_homestory_chat_32399999 = "Kalau kamu bisa jadi hewan, kamu mau jadi apa?",
  str_homestory_chat_32321001 = "Rubah salju.",
  str_homestory_chat_32321002 = "Aku mengerti kamu! Rubah salju itu keren!",
  str_homestory_chat_32321003 = "Pemburu yang gesit, lincah, luar biasa dengan kemampuan untuk menyatu dengan salju untuk penyamaran!",
  str_homestory_chat_32321004 = "Daya bertahan hidup yang sangat tinggi! Pilihan bagus.",
  str_homestory_chat_32321005 = "Sebenarnya, aku memilih itu hanya karena...",
  str_homestory_chat_32321006 = "Rubah salju itu lucu.",
  str_homestory_chat_32321007 = "Mereka imut dan berbulu.",
  str_homestory_chat_32321008 = "Jika setiap pemburu seberbahaya dirimu...",
  str_homestory_chat_32321009 = "Lebih baik jika saya menjadi hewan yang lembut dan menggerakkan mereka dengan kegemasan saya!",
  str_homestory_chat_32321010 = "Kamu suka rubah salju, bukan?",
  str_homestory_chat_32321011 = "Jika aku adalah salah satunya, mungkin aku akan menjalani sisa hidupku dengan damai di bawah perlindunganmu.",
  str_homestory_chat_32321012 = "Sungguh asumsi yang logis dan masuk akal!",
  str_homestory_chat_32321013 = "Itulah persis bagaimana seorang Aurorian berpikir!",
  str_homestory_chat_32321014 = "Tetapi hewan-hewan di luar di salju tidak peduli tentang membujuk Aurorian.",
  str_homestory_chat_32321015 = "Ahem... Maaf, saya bukan binatang ataupun Aurorian.",
  str_homestory_chat_32321016 = "Saya hanya seorang Caelestite kecil yang lemah yang menempatkan keselamatan di atas segalanya.",
  str_homestory_chat_32322001 = "Beruang grizzly.",
  str_homestory_chat_32322002 = "...",
  str_homestory_chat_32322003 = "PlayerName…",
  str_homestory_chat_32322004 = "Ada apa? Kenapa ada rasa kasihan di matamu?",
  str_homestory_chat_32322005 = "Apa? Tidak, tidak ada rasa kasihan. Aku mengerti.",
  str_homestory_chat_32322006 = "Kamu mudah ditekan tanpa banyak kekuatan fisik, jadi...",
  str_homestory_chat_32322007 = "Secara alami, kamu mendambakan tubuh yang kuat seperti grizzly.",
  str_homestory_chat_32322008 = "Aku mengerti. Sungguh, aku mengerti!",
  str_homestory_chat_32322009 = "Apa katamu?",
  str_homestory_chat_32322010 = "\"Seorang pengecut tanpa banyak kekuatan fisik\"? Itu sedikit berlebihan!",
  str_homestory_chat_32322011 = "Aku hanya berpikir—",
  str_homestory_chat_32322012 = "Hanya berpikir apa?",
  str_homestory_chat_32322013 = "Cara seekor grizzly tidur sepanjang musim dingin adalah hal yang akan aku nikmati!",
  str_homestory_chat_32322014 = "PlayerName…",
  str_homestory_chat_32322015 = "Kenapa sekarang ada lebih banyak rasa kasihan di matamu?",
  str_homestory_chat_32323001 = "Burung Camar.",
  str_homestory_chat_32323002 = "Oh, kamu maksud burung-burung yang terobsesi dengan kentang goreng?",
  str_homestory_chat_32323003 = "Tunggu, tidak...",
  str_homestory_chat_32323004 = "Kentang goreng bukanlah satu-satunya makanan yang mereka makan.",
  str_homestory_chat_32323005 = "Sebaliknya, mereka sama sekali tidak pilih-pilih dalam hal makanan.",
  str_homestory_chat_32323006 = "Buah beri, rumput laut, ikan, serangga... Mereka makan semua itu—dan tentu saja kentang goreng juga.",
  str_homestory_chat_32323007 = "Mereka sangat berpikiran terbuka dan akan mencoba apa saja.",
  str_homestory_chat_32323008 = "Itu sangat dekat dengan cara saya ingin hidup!",
  str_homestory_chat_32323009 = "Sekarang setelah kamu bilang begitu, kamu memang pernah menyebutkannya sebelumnya...",
  str_homestory_chat_32323010 = "Kamu ingin mengunjungi setiap sudut dunia dan melihat segalanya.",
  str_homestory_chat_32323011 = "Itu adalah burung yang sempurna untukmu!",
  str_homestory_chat_32323012 = "Kamu seorang Caelestite dan mereka dikenal berhubungan dengan langit dan terbang.",
  str_homestory_chat_32323013 = "Colossus adalah sayapku.",
  str_homestory_chat_32323014 = "Kamu boleh bepergian bersamaku jika mau, kok!",
  str_homestory_chat_32323015 = "Selama kita tidak makan kentang goreng terus menerus.",
  str_homestory_chat_32323016 = "Berhenti bicara tentang kentang goreng!",
  str_homestory_chat_32324001 = "Kelinci.",
  str_homestory_chat_32324002 = "Benarkah? Itu pilihan yang unik.",
  str_homestory_chat_32324003 = "Kelinci tidak bisa berkelahi dan berada di dasar rantai makanan di alam bebas.",
  str_homestory_chat_32324004 = "Mengapa kamu ingin menjadi hewan yang begitu lemah?",
  str_homestory_chat_32324005 = "Kelinci bukanlah lemah.",
  str_homestory_chat_32324006 = "Tidak ada yang mengawasi kelinci.",
  str_homestory_chat_32324007 = "Penampilan yang pemalu dan tidak berbahaya sebenarnya adalah senjata terbaik mereka.",
  str_homestory_chat_32324008 = "Mengapa Novio memilih kelinci sebagai pasangannya dalam mengumpulkan intelijen jika bukan karena alasan lain?",
  str_homestory_chat_32324009 = "Dibandingkan dengan serangan pendahuluan, saya lebih memilih serangan reaktif.",
  str_homestory_chat_32324010 = "Kelinci memiliki pendengaran yang tajam.",
  str_homestory_chat_32324011 = "Mereka bersembunyi dalam kegelapan dan mendengar segala sesuatu di sekitar mereka.",
  str_homestory_chat_32324012 = "Semua yang mereka rasakan membantu teman-teman mereka.",
  str_homestory_chat_32324013 = "Bukankah itu terdengar sangat mirip dengan Caelestite yang memiliki kemampuan psikis?",
  str_homestory_chat_32324014 = "Benar. Perspektifmu sebagai Caelestite sangat berbeda dari Aurorian.",
  str_homestory_chat_32324015 = "Juga, itu memberi saya wawasan baru untuk meningkatkan perburuan saya.",
  str_homestory_chat_32324016 = "Oh tidak, aku tidak baru saja menjual kelinci-kelinci itu, 'kan?",
  str_homestory_chat_32324017 = "Anda akan melihatnya saat makan malam!",
  str_homestory_chat_32325001 = "Paus.",
  str_homestory_chat_32325002 = "Tuan dari laut! Pilihan yang sangat masuk akal.",
  str_homestory_chat_32325003 = "Apakah itu karena Caelestites menginginkan kekuatan?",
  str_homestory_chat_32325004 = "Tidak terlalu.",
  str_homestory_chat_32325005 = "Ada spesies paus yang disebut orca. Saya dengar mereka sangat menghargai keluarga.",
  str_homestory_chat_32325006 = "Mereka akan hidup bersama keluarga mereka sampai mati.",
  str_homestory_chat_32325007 = "Kurasa itu sesuatu yang saya hargai dan cenderung ke arah itu.",
  str_homestory_chat_32325008 = "PlayerName…",
  str_homestory_chat_32325009 = "Maaf, saya tidak bermaksud mengingatkan Anda tentang masa lalu Anda.",
  str_homestory_chat_32325010 = "Tak apa, jangan khawatir.",
  str_homestory_chat_32325011 = "Aku memiliki keluarga di Colossus.",
  str_homestory_chat_32325012 = "Jadi, keinginan saya sudah menjadi kenyataan.",
  str_homestory_chat_32325013 = "Soroz adalah keluargaku.",
  str_homestory_chat_32325014 = "Kami akan melakukan apa saja untuk yang lain.",
  str_homestory_chat_32325015 = "Ah, aku paham sekarang.",
  str_homestory_chat_32325016 = "Saya sama seperti kamu.",
  str_homestory_chat_32325017 = "Saya kehilangan keluarga saya lama sekali, tetapi saya menemukan keluarga baru.",
  str_homestory_chat_32325018 = "Dalam arti itu, keluarga lebih dari sekedar ikatan darah.",
  str_homestory_chat_32325019 = "Aku tahu kau akan mendapatkannya.",
  str_homestory_chat_32325020 = "Terima kasih, Tiare.",
  str_homestory_chat_32499999 = "Ribbit!",
  str_homestory_chat_32421001 = "Saya lihat teman kecil ini juga suka di sini!",
  str_homestory_chat_32599999 = "Jika Anda harus memilih hobi mengumpulkan, mana yang akan Anda pilih?",
  str_homestory_chat_32521001 = "Patung-patung.",
  str_homestory_chat_32521002 = "Seperti yang digunakan pada meja pasir untuk menentukan taktik pertempuran?",
  str_homestory_chat_32521003 = "Tak pernah terpikir olehku bahwa kau adalah penggemar militer sejati.",
  str_homestory_chat_32521004 = "Ya, itu benar.",
  str_homestory_chat_32521005 = "Semua orang memanggilku Navigator, yang juga membuatku semacam komandan.",
  str_homestory_chat_32521006 = "Lagipula, tidak ada salahnya berlatih strategi bertarung dari waktu ke waktu.",
  str_homestory_chat_32521007 = "PlayerName... Aku tidak menyadari kamu mempersiapkan setiap pertempuran dengan begitu teliti.",
  str_homestory_chat_32521008 = "Aku melihatmu dalam cahaya baru lagi.",
  str_homestory_chat_32521009 = "Saya pikir Anda salah paham...",
  str_homestory_chat_32521010 = "Ketika saya mengatakan patung kecil, saya maksudkan yang berwarna-warni dan mahal—",
  str_homestory_chat_32521011 = "Jadi kamu akan membeli model tentara paling canggih, lengkap dengan sistem senjata penuh?",
  str_homestory_chat_32521012 = "PlayerName... Aku tidak tahu kamu menganggap simulasi pertempuran begitu serius.",
  str_homestory_chat_32521013 = "Aku jarang bertemu orang lain yang sama sepertiku.",
  str_homestory_chat_32521014 = "Ayo terus melakukan yang terbaik, oke?",
  str_homestory_chat_32521015 = "Eh... Oke!",
  str_homestory_chat_32522001 = "Furnitur.",
  str_homestory_chat_32522002 = "Furnitur? Saya rasa kamu memang memiliki cukup banyak item furnitur langka di Cloud Gardens.",
  str_homestory_chat_32522003 = "Jadi, itulah yang kamu sukai.",
  str_homestory_chat_32522004 = "Yep! Furnitur tidak hanya membuat hidup kita lebih nyaman...",
  str_homestory_chat_32522005 = "Ini juga membantu saya menjadi lebih dekat dengan teman-teman saya.",
  str_homestory_chat_32522006 = "Ya, aku pernah melihatmu dan teman-temanmu sedang asyik berbicara di sekitar furniturmu.",
  str_homestory_chat_32522007 = "Aku mengerti sekarang. Kamu menggunakan perabot sebagai semacam \"perangkap teman\".",
  str_homestory_chat_32522008 = "Setelah menyiapkan potongan furnitur yang tepat, kamu menunggu kesempatan yang sempurna—",
  str_homestory_chat_32522009 = "Untuk membuat kenangan tak terlupakan dari petualangan kita.",
  str_homestory_chat_32522010 = "Dan potongan-potongan perabot itu berfungsi sebagai pengingat petualangan-petualangan itu, bukan? Itu masuk akal.",
  str_homestory_chat_32522011 = "Beberapa burung pemangsa memiliki kebiasaan yang serupa.",
  str_homestory_chat_32522012 = "Setelah merobek mangsanya dan melahap dagingnya, mereka menghiasi sarang mereka dengan tulang-tulang—",
  str_homestory_chat_32522013 = "W-W-W-Tunggu sebentar!",
  str_homestory_chat_32522014 = "Ada sesuatu tentang itu yang sepertinya tidak beres!",
  str_homestory_chat_32523001 = "Vice.",
  str_homestory_chat_32523002 = "Kamu akan mengumpulkan... Letnan Vice? Maaf, tapi saya tidak mengerti.",
  str_homestory_chat_32523003 = "Bagaimanapun, dia adalah orang yang sangat unik.",
  str_homestory_chat_32523004 = "Maksudmu kamu tidak mengerti? Sebenarnya ada banyak sekali Vice yang berbeda!",
  str_homestory_chat_32523005 = "Seperti \"Memarahi Saya untuk Membersihkan Gudang\" Vice, dan \"Memaksa Saya untuk Mengerjakan Lebih Banyak Pekerjaan\" Vice...",
  str_homestory_chat_32523006 = "\"Mengingatkanku untuk Membersihkan Kamarku\" Vice, dan \"Memaksaku untuk Makan Makanan yang Tak Terkatakan Jeleknya\" Vice...",
  str_homestory_chat_32523007 = "... Meskipun semua itu terdengar sangat negatif, sepertinya aku paham sekarang.",
  str_homestory_chat_32523008 = "Kamu hanya ingin melihat setiap sisi dari Letnan Vice, 'kan?",
  str_homestory_chat_32523009 = "Ehm, aku tidak bilang begitu!",
  str_homestory_chat_32524001 = "Colossus.",
  str_homestory_chat_32524002 = "Colossus... Benarkah kamu bisa mengoleksinya?",
  str_homestory_chat_32524003 = "Yah, jelas aku tidak akan menaruhnya di rak atau apa pun. Kurasa...",
  str_homestory_chat_32524004 = "Yang benar-benar saya inginkan adalah melihat lebih banyak lagi Colossus di luar sana.",
  str_homestory_chat_32524005 = "PlayerName... Dari yang bisa saya lihat, kamu pasti sangat merindukan rumahmu.",
  str_homestory_chat_32524006 = "Kau benar.",
  str_homestory_chat_32524007 = "Saya pikir saya bisa mengerti.",
  str_homestory_chat_32524008 = "Ketika saya berjuang untuk mengembalikan kehormatan keluarga saya...",
  str_homestory_chat_32524009 = "Segala sesuatu yang mengingatkan saya pada rumah akan memperkuat semangat juang saya seratus kali lipat.",
  str_homestory_chat_32524010 = "Ini tidak begitu.",
  str_homestory_chat_32524011 = "Colossi memiliki banyak hal untuk diajarkan kepada saya tentang diri mereka sendiri, serta tentang Caelestites.",
  str_homestory_chat_32524012 = "Dengan pengetahuan itu, aku bisa siap menghadapi masalah apa pun yang mungkin dialami Soroz di masa mendatang!",
  str_homestory_chat_32524013 = "Jadi daripada terpaku pada masa lalu, kamu berjuang untuk menjaga apa yang kamu hargai di masa sekarang...",
  str_homestory_chat_32524014 = "Kamu benar-benar bertekad, Caelestite.",
  str_homestory_chat_32524015 = "Terima kasih atas pengertianmu, Rachel.",
  str_homestory_chat_32524016 = "Dalam pandanganku, kamu sudah menjadi bagian dari keluargaku sejak lama.",
  str_homestory_chat_32525001 = "Aurorian.",
  str_homestory_chat_32525002 = "Apakah itu arti Aurorian bagi kamu? Barang koleksi?",
  str_homestory_chat_32525003 = "Yah, benar! Bagaimanapun juga, di dalam hati saya adalah seorang yang suka menyelesaikan semuanya!",
  str_homestory_chat_32525004 = "Dan apa artinya itu, tepatnya?",
  str_homestory_chat_32525005 = "Jangan salah paham. Itu hanya metafora.",
  str_homestory_chat_32525006 = "Saya hanya ingin bertarung bersama sebanyak mungkin Aurorian.",
  str_homestory_chat_32525007 = "Dengan cara itu, aku bisa terus mengembangkan koleksiku... Maksudku, kemampuanku untuk beradaptasi...",
  str_homestory_chat_32525008 = "Dan kemudian tidak ada masalah yang terlalu sulit untuk saya tangani! Masuk akal, bukan?",
  str_homestory_chat_32525009 = "Begitu... Maaf telah meragukanmu tadi.",
  str_homestory_chat_32525010 = "Saya mengagumi niat baik Anda yang patut dipuji.",
  str_homestory_chat_32525011 = "Mengapa kita tidak melakukan pertempuran latihan lain waktu?",
  str_homestory_chat_32525012 = "Hah?",
  str_homestory_chat_32699999 = "Nah, kalau bukan Caelestite Terakhir! Sedang apa kamu?",
  str_homestory_chat_32621001 = "Anu…",
  str_homestory_chat_32621002 = "Saya hendak pergi berolahraga.",
  str_homestory_chat_32621003 = "Aku paham! Sedikit latihan kekuatan, ya?",
  str_homestory_chat_32621004 = "Seperti yang saya pikirkan, kamu tidak istirahat bahkan di hari biasa!",
  str_homestory_chat_32621005 = "Apakah kamu juga sering berlatih, Zeta?",
  str_homestory_chat_32621006 = "Kebijaksanaan dan karisma adalah atribut terbaik saya. Bahkan tanpa latihan fisik, saya masih cukup kuat!",
  str_homestory_chat_32621007 = "Misalnya, pernahkah Anda melihat singa melatih dirinya sendiri sebelumnya?",
  str_homestory_chat_32621008 = "Tentu saja tidak! Itu karena sangat tidak dapat diterima jika makhluk yang secara alami kuat berlatih untuk menjadi lebih kuat lagi!",
  str_homestory_chat_32621009 = "Aku berencana untuk beristirahat.",
  str_homestory_chat_32621010 = "Saya mengerti. Beristirahat sebelum pertempuran brutal berikutnya, ya?",
  str_homestory_chat_32621011 = "Seperti yang saya pikirkan, kamu mengambil istirahatmu dengan serius seperti halnya kamu bekerja!",
  str_homestory_chat_32621012 = "Kamu sama seperti saya! Meskipun semua orang bilang saya makan terlalu banyak makanan manis...",
  str_homestory_chat_32621013 = "Aku selalu menyeimbangkan dietku dengan makan permen yang diperkaya vitamin juga!",
  str_homestory_chat_32621014 = "Hmm? Uh-oh, hampir waktunya aku bertemu dengan mereka! Maaf, tapi aku harus pergi!",
  str_homestory_chat_32621015 = "Itu tidak masalah, sampai jumpa nanti.",
  str_homestory_chat_32622001 = "Aku punya hal penting yang harus segera kulakukan.",
  str_homestory_chat_32622002 = "Hal penting? Kedengarannya sangat mencurigakan...",
  str_homestory_chat_32622003 = "Apakah ini sesuatu yang sangat penting sehingga kamu tidak bisa memberi tahu teman-temanmu tentang hal itu?",
  str_homestory_chat_32622004 = "Untuk menjauhkan diri dari masa lalunya yang tidak menyenangkan, dia pergi tanpa mengucapkan selamat tinggal dan menghadapi takdir suramnya sendirian...",
  str_homestory_chat_32622005 = "Tapi jangan khawatir, kamu tidak akan pernah sendirian lagi! Aku akan berada di sisimu kemanapun kamu pergi!",
  str_homestory_chat_32622006 = "Terima kasih, Zeta, tapi ini hanya beberapa pekerjaan pemeliharaan untuk Colossus.",
  str_homestory_chat_32622007 = "Hah? Oh, itu membosankan.",
  str_homestory_chat_32622008 = "Mau bantu saya menyortir beberapa file?",
  str_homestory_chat_32622009 = "Apa? Kamu maksud itu saja?",
  str_homestory_chat_32622010 = "Ehem... Maaf, tapi saya baru saja ingat bahwa saya memiliki sesuatu yang lain yang harus dilakukan sekarang.",
  str_homestory_chat_32622011 = "Prajurit juga bisa sangat sibuk, tahu! Sampai jumpa!",
  str_homestory_chat_32623001 = "Tidak terlalu.",
  str_homestory_chat_32623002 = "\"Bukan apa-apa, ya?\" Huh? Saya rasa itu berarti tidak ada hal buruk yang terjadi.",
  str_homestory_chat_32623003 = "Tapi pejuang penyelamat dunia seperti kita tidak boleh kehilangan fokus!",
  str_homestory_chat_32623004 = "Keburukan mengintai di setiap sudut, jadi kita harus selalu waspada!",
  str_homestory_chat_32623005 = "Hanya jangan terlibat dalam masalah apa pun.",
  str_homestory_chat_32623006 = "Kamu hanya menunggu kerusuhan terjadi, bukan?",
  str_homestory_chat_32623007 = "Santai saja! Kesatria hebat Zeta tidak akan pernah melakukan sesuatu yang bisa menimbulkan masalah!",
  str_homestory_chat_32623008 = "Entah bagaimana sumpahmu justru membuatku semakin khawatir...",
  str_homestory_chat_32624001 = "Sekarang aku agak ingin makan camilan.",
  str_homestory_chat_32624002 = "Camilan? Berarti kamu bertemu dengan orang yang tepat!",
  str_homestory_chat_32624003 = "Saya punya berbagai jenis permen. Ini, pilih yang kamu suka!",
  str_homestory_chat_32624004 = "Tapi, saya ingin sesuatu yang asin.",
  str_homestory_chat_32624005 = "Saya juga punya permen asin! Seperti ini, lolipop cabai hantu!",
  str_homestory_chat_32624006 = "Ini dibuat dengan cabai hantu asli. Mereka bilang kamu tidak akan bisa bernapas hanya setelah beberapa jilatan saja!",
  str_homestory_chat_32624007 = "Tapi saya belum mencobanya sendiri, jadi saya tidak tahu apakah itu benar atau tidak.",
  str_homestory_chat_32624008 = "Lalu kenapa kau memberikannya padaku?",
  str_homestory_chat_32624009 = "Jangan keberatan jika saya melakukannya!",
  str_homestory_chat_32624010 = "Silakan ambil apa saja yang kamu mau. Tapi peringatan, ada beberapa bom dicampur di sana, jadi hati-hati saat memakannya.",
  str_homestory_chat_32624011 = "B-Bom? Yang mana yang bom?",
  str_homestory_chat_32624012 = "Maksudmu kamu tidak bisa membedakan mereka? Itu sangat jelas!",
  str_homestory_chat_32624013 = "Mungkin bagi kamu, tapi saya sama sekali tidak bisa membedakan mereka.",
  str_homestory_chat_32624014 = "Eh, kamu ini menyedihkan. Ini, aku akan memilih satu khusus untukmu.",
  str_homestory_chat_32624015 = "Aku punya beberapa hal lain yang harus dikerjakan, jadi sampai jumpa lagi.",
  str_homestory_chat_32799999 = "Ada game yang ingin kamu mainkan belakangan ini?",
  str_homestory_chat_32721001 = "Permainan bermain peran",
  str_homestory_chat_32721002 = "Ah, pilihan bagus!",
  str_homestory_chat_32721003 = "Kenapa kamu memilih itu?",
  str_homestory_chat_32721004 = "Apakah kamu lebih tertarik pada pengaturan game atau ceritanya?",
  str_homestory_chat_32721005 = "Pengaturan",
  str_homestory_chat_32721006 = "Menyenangkan rasanya merasa seperti tinggal di tempat lain.",
  str_homestory_chat_32721007 = "Jenis pengalaman... Aku mengerti.",
  str_homestory_chat_32721008 = "Cerita",
  str_homestory_chat_32721009 = "Biasanya, ini adalah hal-hal seperti orang baik yang membunuh naga.",
  str_homestory_chat_32721010 = "Namun, aku sama sekali tidak keberatan.",
  str_homestory_chat_32721011 = "Tipe yang membuat bahagia... Aku bisa menggali itu.",
  str_homestory_chat_32721012 = "Kamu tidak suka jenis permainan itu, Batia?",
  str_homestory_chat_32721013 = "Ya, hanya saja... Saya tidak memiliki preferensi khusus.",
  str_homestory_chat_32721014 = "Aku lebih menikmatinya ketika ada banyak pilihan untuk dipilih.",
  str_homestory_chat_32722001 = "Game strategi",
  str_homestory_chat_32722002 = "Itu tidak mengejutkan!",
  str_homestory_chat_32722003 = "Saya ingin meningkatkan kemampuan navigasi saya sebagai Caelestite.",
  str_homestory_chat_32722004 = "Jadi, saya lebih tenang saat menghadapi Eclipsite.",
  str_homestory_chat_32722005 = "Jadi maksudmu…",
  str_homestory_chat_32722006 = "Kamu ingin meningkatkan cara kamu menghadapi mereka melalui permainan strategis?",
  str_homestory_chat_32722007 = "Mengesankan bahwa Anda akan memikirkan hal itu bahkan saat bermain game.",
  str_homestory_chat_32722008 = "Nah, sebenarnya aku sudah berlatih untuk itu.",
  str_homestory_chat_32722009 = "Sangat menyenangkan untuk memainkan berbagai jenis simulasi dan skenario dalam sebuah game.",
  str_homestory_chat_32723001 = "Game kasual",
  str_homestory_chat_32723002 = "Permainan pencocokan ubin cukup mudah, 'kan?",
  str_homestory_chat_32723003 = "Uh, belum tentu.",
  str_homestory_chat_32723004 = "Bahkan jenis permainan seperti itu bisa menjadi sulit dan sangat menantang.",
  str_homestory_chat_32723005 = "Seberapa keras?",
  str_homestory_chat_32723006 = "Kamu sama sekali tidak bisa membuat langkah.",
  str_homestory_chat_32723007 = "Bagaimana menantangnya?",
  str_homestory_chat_32723008 = "Banyak persyaratan aneh yang menuntut waktu dan usaha.",
  str_homestory_chat_32723009 = "Mungkin saya harus mempertimbangkan kembali.",
  str_homestory_chat_32724001 = "Tetrablox! Tetrablox!",
  str_homestory_chat_32724002 = "Kamu juga suka Tetrablox?!",
  str_homestory_chat_32724003 = "Kamu bisa bilang begitu, tapi aku pasti tidak sebaik kamu.",
  str_homestory_chat_32724004 = "Saya tidak cukup cepat untuk membersihkan blok sebanyak itu.",
  str_homestory_chat_32724005 = "Ini sebagian keberuntungan dan sebagian keterampilan... Aku bisa menunjukkan padamu.",
  str_homestory_chat_32724006 = "Mengapa kita tidak berusaha untuk mencapai Level 30 untuk sekarang?",
  str_homestory_chat_32725001 = "Tidak juga",
  str_homestory_chat_32725002 = "Kita harus pergi keluar.",
  str_homestory_chat_32725003 = "Di luar? Maksudmu di luar-luar atau di sini-luar?",
  str_homestory_chat_32725004 = "Luar-luar",
  str_homestory_chat_32725005 = "Uh, saya jarang pergi berlibur...",
  str_homestory_chat_32725006 = "Tak apa. Kita sudah mendapatkan Colossus.",
  str_homestory_chat_32725007 = "Di sini-luar",
  str_homestory_chat_32725008 = "Tidak apa-apa. Nyaman di sini dan kita memiliki payung.",
  str_homestory_chat_32725009 = "Aku tidak menjadi pengganggu untukmu, kan?",
  str_homestory_chat_32725010 = "Kalau kita jatuh...",
  str_homestory_chat_32725011 = "Kita bisa memandangi langit dengan berbaring telentang!",
  str_homestory_chat_32899999 = "Jika kamu bisa mendapatkan barang ajaib, apa yang kamu inginkan?",
  str_homestory_chat_32821001 = "Sebuah printer uang.",
  str_homestory_chat_32821002 = "Astaga! Itu tentu saja... jenis \"sihir\" tertentu, saya kira.",
  str_homestory_chat_32821003 = "Saya bercanda... tapi serius, dana untuk pemeliharaan Colossus benar-benar menipis akhir-akhir ini.",
  str_homestory_chat_32821004 = "Saya sudah mengurus delapan pekerjaan sehari!",
  str_homestory_chat_32821005 = "Jika itu masalahnya, kenapa tidak bekerja untuk True Order?",
  str_homestory_chat_32821006 = "Pembayaran yang saya tawarkan tidak akan merusak reputasi Varaki.",
  str_homestory_chat_32821007 = "Kemana saya harus mengirimkan resume saya?!",
  str_homestory_chat_32821008 = "Tidak perlu formalitas sepele seperti itu. Ketika kesempatan yang dipimpin oleh Truth datang, kita akan bekerja sama secara alami.",
  str_homestory_chat_32821009 = "Memaksanya tidak akan membawa kebaikan apa pun.",
  str_homestory_chat_32821010 = "Itu terdengar agak tidak stabil...",
  str_homestory_chat_32821011 = "Kamu tidak hanya membuat janji kosong, kan?",
  str_homestory_chat_32821012 = "Jujur saja, aku terkejut kamu berpikir begitu.",
  str_homestory_chat_32821013 = "Apakah kamu benar-benar melihat kami di True Order sebagai kelompok yang mencurigakan yang menipu pengikutnya?",
  str_homestory_chat_32821014 = "Tidak mungkin! Hanya saja, akhir-akhir ini aku bertemu terlalu banyak bos yang mencurigakan...",
  str_homestory_chat_32822001 = "Sebuah jubah tembus pandang.",
  str_homestory_chat_32822002 = "Oh...?",
  str_homestory_chat_32822003 = "Kenapa... kau menatapku seperti itu?",
  str_homestory_chat_32822004 = "Heh...",
  str_homestory_chat_32822005 = "Apanya yang lucu dari itu?!",
  str_homestory_chat_32822006 = "Tak perlu malu, Navigator. Wajar memiliki pikiran seperti ini di usiamu.",
  str_homestory_chat_32822007 = "Pikiran apa yang kamu bicarakan? Saya hanya berpikir bahwa jubah ketidaklihatan akan sangat bagus untuk misi penyamaran!",
  str_homestory_chat_32822008 = "Ya, tentu saja. Kamu tidak akan menginginkan sebaliknya.",
  str_homestory_chat_32822009 = "Untuk apa di dunia ini kau pikir aku menginginkannya?",
  str_homestory_chat_32823001 = "Sebuah sapu yang menyapu dengan sendirinya.",
  str_homestory_chat_32823002 = "Oh my, dengan semua barang sihir untuk dipilih, kamu hanya ingin sapu? Keinginanmu cukup sederhana.",
  str_homestory_chat_32823003 = "Jika kamu tidak ingin melakukan pembersihan, mengapa tidak sekadar mendapatkan seorang pelayan?",
  str_homestory_chat_32823004 = "Mungkin seseorang yang setinggi kamu tidak akan mengerti...",
  str_homestory_chat_32823005 = "Tapi memerintah orang lain, meskipun aku membayar mereka, membuatku merasa tidak nyaman.",
  str_homestory_chat_32823006 = "Tapi jika ini sapu ajaib, aku bisa memberikan perintah tanpa merasa bersalah!",
  str_homestory_chat_32823007 = "Saya mengerti. Anda benar-benar jiwa yang baik.",
  str_homestory_chat_32823008 = "Tapi, jika kamu terlalu menekan \"diri\"mu demi orang lain, kamu mungkin akan menyimpang dari Kebenaran.",
  str_homestory_chat_32823009 = "Merawat orang lain adalah bagian dari \"diri sendiri\".",
  str_homestory_chat_32823010 = "Baik diperdebatkan. Kebijaksanaan dan wawasan Anda memang luar biasa.",
  str_homestory_chat_32823011 = "Memang, jika kamu bisa sepenuhnya mengekspresikan sifat lembutmu...",
  str_homestory_chat_32823012 = "Kamu pasti akan menjadi seorang santo yang mengorbankan diri sendiri, sama seperti Nails...",
  str_homestory_chat_32823013 = "T-t-tidak, itu tidak perlu. Aku baik-baik saja menjadi biasa saja!",
  str_homestory_chat_32823014 = "Jadi, hanya orang-orang yang egomania saja yang bisa mendekati Truth?",
  str_homestory_chat_32823015 = "Heh... Kata-katamu cukup tajam; sungguh mengagumkan.",
  str_homestory_chat_32823016 = "Tapi ya, ternyata, mereka yang memahami Truth cenderung menjadi egomaniak.",
  str_homestory_chat_32823017 = "Kata-kata tajammu seperti duri mawar... Mungkin itu adalah Kebenaran yang termanifestasi dalam dirimu... siapa yang tahu.",
  str_homestory_chat_32823018 = "Bukankah Lord of Truth ini sedikit sulit untuk diajak bergaul...?",
  str_homestory_chat_32824001 = "Sebuah jam pasir yang memutar balik waktu.",
  str_homestory_chat_32824002 = "Mundur waktu? Pilihan klasik.",
  str_homestory_chat_32824003 = "Maaf bertanya, tapi apakah karena kamu ingin kembali tujuh belas tahun untuk mengubah apa yang terjadi di Eraveil?",
  str_homestory_chat_32824004 = "Tentu saja.",
  str_homestory_chat_32824005 = "Itu wajar saja bagi Anda untuk menginginkan itu.",
  str_homestory_chat_32824006 = "Jika kamu benar-benar mendapatkan kesempatan untuk mewujudkannya, mungkin... Saya akan berdiri di sisi Anda.",
  str_homestory_chat_32824007 = "Apa? Saya pikir semua orang akan menentang perubahan besar seperti itu dalam sejarah...",
  str_homestory_chat_32824008 = "Aku takut untuk mengubah hal-hal sampai sejauh itu.",
  str_homestory_chat_32824009 = "Seluruh Astra akan terpengaruh...",
  str_homestory_chat_32824010 = "Paling banter, saya hanya akan kembali ke hari sebelum kemarin dan mencari uang yang hilang saya... haha.",
  str_homestory_chat_32824011 = "...Struktur waktu sangat misterius.",
  str_homestory_chat_32824012 = "Cara \"masa lalu\" terbentuk jauh lebih kompleks dari apa yang kita pikirkan.",
  str_homestory_chat_32824013 = "Terkadang, mungkin \"masa depan\" yang membentuk \"masa lalu\".",
  str_homestory_chat_32824014 = "...",
  str_homestory_chat_32825001 = "Sebuah ramuan yang memungkinkan kamu belajar saat tidur.",
  str_homestory_chat_32825002 = "...",
  str_homestory_chat_32825003 = "D-dari matamu, aku melihat ketidaksetujuan yang mendalam...",
  str_homestory_chat_32825004 = "Heh... Aku menghargai kecerdasanmu.",
  str_homestory_chat_32825005 = "Ada banyak sekali novel fantasi yang berpusat pada sihir...",
  str_homestory_chat_32825006 = "Tapi bahkan mereka jarang mendeskripsikan ramuan yang Anda inginkan. Tahukah Anda mengapa?",
  str_homestory_chat_32825007 = "Penulisnya tidak cukup berani?",
  str_homestory_chat_32825008 = "Karena pengetahuan adalah satu-satunya jalan menuju Truth.",
  str_homestory_chat_32825009 = "Dan belajar adalah satu hal yang tidak memungkinkan adanya jalan pintas.",
  str_homestory_chat_32825010 = "Kamu paham sekarang?",
  str_homestory_chat_32825011 = "...Aku benar-benar mengerti, Guru Victoria!",
  str_homestory_chat_32999999 = "Pernahkah kamu bertobat atas sesuatu?",
  str_homestory_chat_32921001 = "Begadang selama tiga hari bermain game.",
  str_homestory_chat_32921002 = "Game...? Apa itu?",
  str_homestory_chat_32921003 = "Mereka adalah setan.",
  str_homestory_chat_32921004 = "Setan? Kamu maksud makhluk jahat seperti Eclipsite atau Necroservants?",
  str_homestory_chat_32921005 = "Aku akan melindungimu, PlayerName, karena inilah alasan mengapa Tuhan telah memberikan kuasa Darah Suci padaku.",
  str_homestory_chat_32921006 = "Darah Suci tidak bisa berbuat apa-apa tentang ini.",
  str_homestory_chat_32921007 = "Setan yang disebut game menggunakan kegembiraan sebagai umpan, membuang-buang masa mudaku dan menguras uangku...",
  str_homestory_chat_32921008 = "Bahkan prajurit terkuat sekalipun tidak bisa melarikan diri dari cengkeraman mereka!",
  str_homestory_chat_32921009 = "Tapi... Tapi sepertinya kau hanya menyerah pada godaan tanpa memberikan perlawanan.",
  str_homestory_chat_32921010 = "Kamu harus melindungiku.",
  str_homestory_chat_32921011 = "Kali berikutnya Gronru menggodaku dengan permainan, kamu harus menghalanginya!",
  str_homestory_chat_32921012 = "Gronru?",
  str_homestory_chat_32921013 = "Dia adalah ratu iblis permainan di neraka. Jika bukan karena dia, aku tidak akan berakhir seperti ini...",
  str_homestory_chat_32921014 = "Bukankah itu hanya... menyalahkan orang lain atas kesalahanmu?",
  str_homestory_chat_32921015 = "Mungkin ini yang seharusnya kau sesali, bukan begitu?",
  str_homestory_chat_32921016 = "Ugh...! Mari kita berhenti membahas topik ini. Selamat tinggal!",
  str_homestory_chat_32922001 = "Menumpuk menara buah di sebuah restoran.",
  str_homestory_chat_32922002 = "Sebuah menara buah?",
  str_homestory_chat_32922003 = "Ehem, kamu tahu restoran-restoran itu dimana kamu bisa mendapatkan salad buah prasmanan jika memesan hidangan utama?",
  str_homestory_chat_32922004 = "Anda dapat mengambil sebanyak yang Anda mau, tapi hanya sekali.",
  str_homestory_chat_32922005 = "Oleh karena itu, menumpuk sebanyak mungkin salad di satu piring menjadi bentuk seni.",
  str_homestory_chat_32922006 = "Jadi, kamu menumpuk... menara buah di piringmu?",
  str_homestory_chat_32922007 = "Jangan, jangan menatapku seperti itu...",
  str_homestory_chat_32922008 = "Itu membutuhkan keterampilan sejati!",
  str_homestory_chat_32922009 = "...Jika kamu merasa bangga, mengapa kamu menyesalinya?",
  str_homestory_chat_32922010 = "Aku makan seluruh menara buah dan mengalami diare selama tiga hari...",
  str_homestory_chat_32922011 = "Maka kamu telah menerima hukuman Tuhan; dosa-dosamu telah dibersihkan, PlayerName.",
  str_homestory_chat_32922012 = "Matamu kembali hangat, yang membuatku merasa semakin aneh...",
  str_homestory_chat_32923001 = "Mengebut.",
  str_homestory_chat_32923002 = "Melaju... Saya tidak tahu jika Colossus memiliki batas kecepatan.",
  str_homestory_chat_32923003 = "Langit kini milikku untuk berkelana dengan bebas...",
  str_homestory_chat_32923004 = "Tetapi di hari-hari ketika banyak Colossus di langit, ada batas kecepatan yang biasa.",
  str_homestory_chat_32923005 = "Mereka bertugas menjaga Colossi dan burung lainnya tetap aman, dan sebagian besar waktu aku mengikuti mereka.",
  str_homestory_chat_32923006 = "Jadi, mengapa kamu mempercepat?",
  str_homestory_chat_32923007 = "<Ulang tahun Vice.",
  str_homestory_chat_32923008 = "Aku bergegas ke Umbraton untuk mengambil salah satu dari lima puluh kue buah ultra mewah edisi terbatas.",
  str_homestory_chat_32923009 = "Ulang tahun Carleen.",
  str_homestory_chat_32923010 = "Aku bergegas ke Lumopolis untuk perjamuan ulang tahun dan harus mengambil gaun malamku dari tukang cuci kering di perjalanan...",
  str_homestory_chat_32923011 = "Oh, begitu…",
  str_homestory_chat_32923012 = "Karena ini untuk dia, aku tidak bisa menyalahkanmu.",
  str_homestory_chat_32923013 = "Dan kamu sudah bertobat dengan tulus, kan?",
  str_homestory_chat_32923014 = "T-Tentu saja!",
  str_homestory_chat_32923015 = "Bahkan tanpa ada yang menegakkannya, Anda masih menaatinya adat istiadat klan Anda dan bertobat ketika Anda melanggar mereka.",
  str_homestory_chat_32923016 = "Karakter mulia Anda patut dikagumi.",
  str_homestory_chat_32923017 = "Tuhan dari Truth akan memberkatimu, PlayerName.",
  str_homestory_chat_32923018 = "Terima kasih... Maksudku, berterima kasihlah pada-Nya!",
  str_homestory_chat_32924001 = "Kurang kegigihan.",
  str_homestory_chat_32924002 = "Apakah sulit bagi kamu untuk menaatinya?",
  str_homestory_chat_32924003 = "Ya... terutama ketika saya memutuskan untuk berolahraga, ehem...",
  str_homestory_chat_32924004 = "Melatih tubuh adalah proses yang menyakitkan. Saya telah melaluinya, jadi saya mengerti.",
  str_homestory_chat_32924005 = "Sebenarnya, Anda tidak perlu memaksakan diri karena kekuatan Anda tidak terletak pada tubuh Anda.",
  str_homestory_chat_32924006 = "Olahraga mungkin tidak cocok untukmu, tapi pasti ada sesuatu yang bisa kamu tekuni, kan?",
  str_homestory_chat_32924007 = "Semacam itu... Saya kira...",
  str_homestory_chat_32924008 = "Misalnya?",
  str_homestory_chat_32924009 = "Makan... tidur...",
  str_homestory_chat_32924010 = "...",
  str_homestory_chat_32924011 = "Masih ada lagi! Seperti...",
  str_homestory_chat_32924012 = "...Seperti bernapas!",
  str_homestory_chat_32924013 = "...",
  str_homestory_chat_33099999 = "Jenis buku apa yang suka kamu baca?",
  str_homestory_chat_33021001 = "Novel.",
  str_homestory_chat_33021002 = "Menarik.",
  str_homestory_chat_33021003 = "Tahu apa? Apa yang kamu sebut novel memiliki sejarah yang sangat singkat.",
  str_homestory_chat_33021004 = "Mereka baru saja memulai di zaman saya.",
  str_homestory_chat_33021005 = "Itu berita baru bagi saya!",
  str_homestory_chat_33021006 = "Aku pikir novel... um, selalu ada?",
  str_homestory_chat_33021007 = "Ini adalah bias kognitif yang umum untuk berpikir bahwa konsep-konsep baru dalam budaya dan masyarakat selalu ada.",
  str_homestory_chat_33021008 = "Bukan hanya novel, konsep seperti masa kecil, cinta, alasan, dan sebagainya juga merupakan produk dari zaman modern.",
  str_homestory_chat_33021009 = "Setelah kamu terbiasa dengan mereka, sulit untuk membayangkan kehidupan dengan cara lain...",
  str_homestory_chat_33021010 = "Oleh karena itu muncul kesalahpahaman bahwa \"mereka selalu ada.\"",
  str_homestory_chat_33021011 = "Agak sulit dipercaya.",
  str_homestory_chat_33021012 = "Tidakkah Aurorian memiliki cerita untuk dibaca di masa lalu?",
  str_homestory_chat_33021013 = "Dulu, kita memiliki epos, drama, dan fabel, yang memiliki elemen penceritaan tetapi sangat berbeda dari novel.",
  str_homestory_chat_33021014 = "Akhir-akhir ini, saya telah membaca beberapa novel terlaris yang dipajang di toko buku. Dibandingkan dengan epos dan sejenisnya...",
  str_homestory_chat_33021015 = "Plot mereka lebih kompleks, emosi lebih bervariasi, tidak diragukan lagi merupakan produk dari kemakmuran sosial.",
  str_homestory_chat_33021016 = "Seratus tahun yang lalu, para Aurorian tidak punya waktu untuk merenungkan hal-hal \"tidak berguna\" seperti itu.",
  str_homestory_chat_33021017 = "Saya melihat... Sungguh pencerahan berbicara dengan Anda!",
  str_homestory_chat_33022001 = "Buku sejarah.",
  str_homestory_chat_33022002 = "Sangat jarang ada orang seumurmu yang tertarik dengan sejarah.",
  str_homestory_chat_33022003 = "Baik untuk membaca sejarah, tetapi berhati-hatilah untuk tidak berpikir bahwa segala sesuatu yang tertulis dalam buku adalah benar-benar benar.",
  str_homestory_chat_33022004 = "Saya mengerti, Pak Wilhelm. Anda maksud \"sejarah ditulis oleh para pemenang,\" bukan?",
  str_homestory_chat_33022005 = "Pernyataan itu hanya mencerminkan distorsi sejarah yang disengaja oleh mereka yang berkuasa. Kenyataannya jauh lebih kompleks.",
  str_homestory_chat_33022006 = "Bahkan ketika sejarawan menulis sejarah dengan niat mulia untuk \"mengembalikan kebenaran\"...",
  str_homestory_chat_33022007 = "Mereka pasti dipengaruhi oleh semangat dan etos zaman mereka sendiri.",
  str_homestory_chat_33022008 = "Apa yang mereka tulis sudah merupakan \"sejarah seperti yang dilihat oleh orang kontemporer,\" bukan \"sejarah\" itu sendiri.",
  str_homestory_chat_33022009 = "Apakah yang kamu katakan... sejarah tidak bisa dipulihkan dengan akurat?",
  str_homestory_chat_33022010 = "Seperti yang diharapkan dari seorang yang muda yang membaca sejarah, kamu sudah menyadari ironi \"sejarah dan kebenaran.\"",
  str_homestory_chat_33023001 = "Puisi.",
  str_homestory_chat_33023002 = "Hmph, kadang-kadang saya pikir kamu terlalu tua untuk usiamu, tapi kemudian kamu mengejutkan saya dengan beberapa minat yang muda.",
  str_homestory_chat_33023003 = "Ada pepatah, \"Meninggal muda saat masa muda masih tersisa adalah berkah bagi seorang penyair.\" Bagaimana pendapatmu tentang itu?",
  str_homestory_chat_33023004 = "Aku setuju.",
  str_homestory_chat_33023005 = "Pikiranmu itu berbahaya.",
  str_homestory_chat_33023006 = "Menulis puisi membutuhkan semangat muda. Lebih baik mati muda daripada menunggu gairah itu memudar.",
  str_homestory_chat_33023007 = "Hidup tanpa hasrat tidak layak untuk dijalani—apakah itu yang kamu pikirkan?",
  str_homestory_chat_33023008 = "Tentu tidak, tapi bagaimana dengan para penyair itu?",
  str_homestory_chat_33023009 = "Selalu ada seseorang yang melihat sesuatu sebagai tujuan dari seluruh hidup mereka, bukan?",
  str_homestory_chat_33023010 = "Tujuan dari seluruh hidup... Bagiku, mungkin itu adalah jalan untuk mendekatkan diri kepada Tuhan.",
  str_homestory_chat_33023011 = "Anda memiliki wawasan yang tajam, PlayerName.",
  str_homestory_chat_33023012 = "Saya tidak setuju.",
  str_homestory_chat_33023013 = "Apakah kamu menentang \"teori bakat bawaan\"?",
  str_homestory_chat_33023014 = "Apa maksudmu?",
  str_homestory_chat_33023015 = "Dari semua bentuk sastra, puisi adalah yang paling menuntut bakat.",
  str_homestory_chat_33023016 = "Banyak penyair hebat meraih ketenaran di usia remaja dan dua puluhan mereka, membakar habis bakat mereka, dan kemudian menjadi medioker.",
  str_homestory_chat_33023017 = "Tapi kamu tidak setuju dengan takdir semacam ini.",
  str_homestory_chat_33023018 = "Selama seseorang hidup, seseorang dapat mengejar puisi yang diberikan oleh ilahi dengan jiwa yang diperkaya oleh pengalaman duniawi.",
  str_homestory_chat_33023019 = "Begitu menurutmu?",
  str_homestory_chat_33023020 = "Saya... mungkin. Saya benci gagasan mengikat kemungkinan-kemungkinan hidup pada \"pemuda\".",
  str_homestory_chat_33023021 = "Setelah dipikir-pikir, itu persis seperti yang kamu maksudkan.",
  str_homestory_chat_33023022 = "Tapi aku tidak pernah bisa mengungkapkannya sebaik kamu! Kamu luar biasa, Mr. Wilhelm!",
  str_homestory_chat_33024001 = "Buku sains populer.",
  str_homestory_chat_33024002 = "Sains, huh... Tidak diragukan lagi telah memberikan kontribusi besar bagi masyarakat.",
  str_homestory_chat_33024003 = "Namun dengan kerangka ilmiah saat ini, Aurorian pasti semakin menjauh dari Kebenaran.",
  str_homestory_chat_33024004 = "Eh, bagaimana bisa?",
  str_homestory_chat_33024005 = "Apakah Victoria pernah berkata padamu, \"Kebenaran memiliki banyak dimensi\"?",
  str_homestory_chat_33024006 = "Dia sering bilang begitu!",
  str_homestory_chat_33024007 = "Inilah tempat misteri itu berada.",
  str_homestory_chat_33024008 = "Sains dibangun berdasarkan prediktabilitas.",
  str_homestory_chat_33024009 = "Melakukan sesuatu sepuluh ribu kali dan mendapatkan hasil yang sama setiap kali itulah yang membuatnya menjadi \"kesimpulan ilmiah.\"",
  str_homestory_chat_33024010 = "Tapi Truth terletak pada percikan satu di antara sejuta.",
  str_homestory_chat_33024011 = "Kamu menangkapnya dalam satu tatapan, dan tatapan itu, tidak peduli berapa kali kamu melakukannya, selalu berbeda.",
  str_homestory_chat_33024012 = "Kamu paham?",
  str_homestory_chat_33024013 = "Aku paham.",
  str_homestory_chat_33024014 = "Omong kosong. Jika kamu benar-benar bisa mendapatkannya dari kata-kata santai saya, apa gunanya True Order?",
  str_homestory_chat_33024015 = "...",
  str_homestory_chat_33024016 = "Aku tak paham.",
  str_homestory_chat_33024017 = "Tidak masalah. Kamu suka sains, jadi terus belajarlah.",
  str_homestory_chat_33024018 = "Ketika ilmu pengetahuan mencapai puncaknya, mungkin itu bisa menjadi gerbang lain menuju Kebenaran.",
  str_homestory_chat_33025001 = "Teks teologi.",
  str_homestory_chat_33025002 = "???",
  str_homestory_chat_33025003 = "...Oh, begitu, ya.",
  str_homestory_chat_33025004 = "Apakah kamu telah membaca... apa namanya? \"Novel fantasi\"? Yang berdasarkan mitos.",
  str_homestory_chat_33025005 = "Dan itulah mengapa kamu tertarik dengan konsep dan pengaturan di dalamnya, benar?",
  str_homestory_chat_33025006 = "Hah? Tidak, Tuan Wilhelm.",
  str_homestory_chat_33025007 = "Mendengar kamu sering menyebut \"Truth\" dan \"Lord\", aku ingin memahami apa yang kamu bicarakan.",
  str_homestory_chat_33025008 = "?!",
  str_homestory_chat_33025009 = "Untuk... saya?",
  str_homestory_chat_33025010 = "Ya. Saya menemukan pembicaraan Anda menarik dan ingin dapat merespons Anda kadang-kadang.",
  str_homestory_chat_33025011 = "...Ugh, bukankah terlalu sembrono membaca teks teologi dengan pola pikir seperti itu?",
  str_homestory_chat_33025012 = "...Bukan, bukan itu.",
  str_homestory_chat_33025013 = "Ada apa?",
  str_homestory_chat_33025014 = "Tidak ada! Ayo baca sekarang.",
  str_homestory_chat_33025015 = "Jika ada sesuatu yang tidak kamu mengerti... jangan ragu untuk bertanya padaku.",
  str_homestory_chat_33199999 = "Apa ada mimpi menarik akhir-akhir ini?",
  str_homestory_chat_33121001 = "Mimpi yang menarik?",
  str_homestory_chat_33121002 = "Sepertinya tidak ada...",
  str_homestory_chat_33121003 = "Hmm... Apakah kamu merasa ada banyak tekanan?",
  str_homestory_chat_33121004 = "Bukankah melelahkan tidur tanpa mimpi indah?",
  str_homestory_chat_33121005 = "Hah? Aku tidak akan bilang begitu...",
  str_homestory_chat_33121006 = "Banyak stres yang hilang setelah tidur malam yang nyenyak.",
  str_homestory_chat_33121007 = "Begitu, ya? Tapi...",
  str_homestory_chat_33121008 = "Tentu.",
  str_homestory_chat_33121009 = "Ah. PlayerName, Anda adalah seorang pria yang optimistis!",
  str_homestory_chat_33121010 = "Hah? Mimpi saya membawa kamu ke kesimpulan ini?",
  str_homestory_chat_33121011 = "Ya! Mereka yang hidup bahagia dan memperlakukan orang lain dengan optimisme...",
  str_homestory_chat_33121012 = "Mereka akan memiliki banyak hal indah dengan orang-orang yang mereka cintai dalam mimpi mereka!",
  str_homestory_chat_33121013 = "Hehe. Tetapi ada cara yang lebih sederhana lagi.",
  str_homestory_chat_33121014 = "Datanglah menemuiku kapan saja jika kau ingin mimpi indah!",
  str_homestory_chat_33121015 = "Baiklah!",
  str_homestory_chat_33122001 = "Dunia tanpa Eclipsite.",
  str_homestory_chat_33122002 = "Wow. Tolong beri saya waktu sebentar untuk memproses ini...",
  str_homestory_chat_33122003 = "Itu akan menjadi gelembung tanpa bintik-bintik!",
  str_homestory_chat_33122004 = "Gelembung yang paling indah, sempurna!",
  str_homestory_chat_33122005 = "Apa yang kamu lakukan di sana?",
  str_homestory_chat_33122006 = "Aku berkeliling bersama semua orang.",
  str_homestory_chat_33122007 = "Wow. Kuharap aku bisa di sana bersamamu!",
  str_homestory_chat_33122008 = "Kami merangkul angin dan menyaksikan kelahiran dunia baru bersama di puncak Colossus...",
  str_homestory_chat_33122009 = "Kami bekerja bersama untuk memulihkan negeri kita.",
  str_homestory_chat_33122010 = "Betapa baik dan tanpa pamrihnya kamu bahkan dalam mimpi-mimpimu!",
  str_homestory_chat_33122011 = "Sangat penting untuk mengembalikan warna-warna gelembung memang.",
  str_homestory_chat_33122012 = "Maukah kamu membawaku bersamamu lain kali untuk merasakan mimpi indah itu bersama-sama?",
  str_homestory_chat_33122013 = "Tentu, saya hanya tidak tahu kapan itu akan terjadi...",
  str_homestory_chat_33123001 = "Longzhou.",
  str_homestory_chat_33123002 = "Longzhou. Saya membacanya dalam buku dongeng...",
  str_homestory_chat_33123003 = "Dongeng di sana cukup mendalam.",
  str_homestory_chat_33123004 = "Mereka suka menggunakan kata-kata besar dan frasa yang aneh. Sulit bagi saya untuk memahami...",
  str_homestory_chat_33123005 = "Budaya Longzhou memang mendalam dan luas.",
  str_homestory_chat_33123006 = "Gadget mereka, kalender, dan Aurorian benar-benar menarik.",
  str_homestory_chat_33123007 = "Benarkah? Aku belum pernah melihat Aurorian dari Longzhou.",
  str_homestory_chat_33123008 = "Aku akan meminta leluhurku untuk memberiku gambaran nanti malam dalam mimpiku.",
  str_homestory_chat_33123009 = "Kau serius?",
  str_homestory_chat_33123010 = "Bagaimana jika saya perkenalkan kamu kepada beberapa Aurorian mereka lain kali?",
  str_homestory_chat_33123011 = "Hore! Kamu sangat baik padaku, sama seperti leluhurku!",
  str_homestory_chat_33124001 = "Sebuah pertunjukan sirkus.",
  str_homestory_chat_33124002 = "Hmm... Sebuah pertunjukan?",
  str_homestory_chat_33124003 = "Saya menonton banyak ketika saya berada di sirkus...",
  str_homestory_chat_33124004 = "Meskipun aku tidak ingat banyak...",
  str_homestory_chat_33124005 = "Saya tahu pasti mereka adalah penampil yang luar biasa!",
  str_homestory_chat_33124006 = "Bagian favoritmu dari pertunjukan ini apa?",
  str_homestory_chat_33124007 = "Kurasa lemparan pisau?",
  str_homestory_chat_33124008 = "Lemparan pisau? Tidak tahu kalau kamu suka sensasi seperti itu.",
  str_homestory_chat_33124009 = "Ini menarik dan selalu berakhir dengan baik!",
  str_homestory_chat_33124010 = "Itulah mengapa saya juga seorang penggemar.",
  str_homestory_chat_33124011 = "Saya kira pertunjukan sulap?",
  str_homestory_chat_33124012 = "Pertunjukan sulap? Jeno adalah pesulap yang luar biasa!",
  str_homestory_chat_33124013 = "Aku ingat betapa misteriusnya perasaan itu! Dia bisa menceritakan banyak hal hanya dengan menggambar beberapa kartu!",
  str_homestory_chat_33124014 = "Hmm... Aku merindukan setiap orang dari sirkus...",
  str_homestory_chat_33124015 = "Mari kita tonton pertunjukan sirkus bersama jika kita mendapatkan kesempatan!",
  str_homestory_chat_33124016 = "Setuju!",
  str_homestory_chat_33125001 = "Eraveil.",
  str_homestory_chat_33125002 = "Eraveil... Itu kampung halamanmu, bukan?",
  str_homestory_chat_33125003 = "Aku lahir di kapal. Rumah adalah konsep yang asing bagi saya.",
  str_homestory_chat_33125004 = "Apakah kamu suka Eraveil?",
  str_homestory_chat_33125005 = "Ya, orang-orang kami memang telah tinggal di sana selama beberapa generasi.",
  str_homestory_chat_33125006 = "Tapi, aku menghabiskan tujuh belas tahun di bawah tanah.",
  str_homestory_chat_33125007 = "Masih banyak yang tidak aku ketahui tentang leluhurku.",
  str_homestory_chat_33125008 = "Itu salah satu alasan mengapa saya sedang bepergian.",
  str_homestory_chat_33125009 = "Wow. Caelestite juga mencoba mempelajari tentang leluhurnya?",
  str_homestory_chat_33125010 = "Kita cukup mirip, bukan?",
  str_homestory_chat_33125011 = "Mungkin leluhurku mengenal leluhurmu?",
  str_homestory_chat_33125012 = "Mungkin mereka dulu adalah teman baik!",
  str_homestory_chat_33125013 = "Haha. Itu pikiran yang sangat menarik.",
  str_homestory_chat_33125014 = "Hehe. Leluhur kita pasti sangat senang melihat kita melanjutkan persahabatan mereka!",
  str_homestory_chat_33299999 = "Apa kamu memiliki sesuatu yang ingin kamu lindungi?",
  str_homestory_chat_33221001 = "Hal-hal yang ingin saya lindungi...",
  str_homestory_chat_33221002 = "Ada begitu banyak, kamu tahu.",
  str_homestory_chat_33221003 = "Bisakah kamu lebih spesifik?",
  str_homestory_chat_33221004 = "Hmm... Sulit untuk dijelaskan.",
  str_homestory_chat_33221005 = "Hal macam apa yang kamu tanyakan?",
  str_homestory_chat_33221006 = "Dari konsep-konsep besar seperti cita-cita dan keyakinan.",
  str_homestory_chat_33221007 = "Hingga ke detail kecil dan rumit.",
  str_homestory_chat_33221008 = "Mungkin kamu bisa memberiku beberapa contoh.",
  str_homestory_chat_33221009 = "Bagaimana kalau...",
  str_homestory_chat_33221010 = "Pisau yang saya hargai, gagak saya, dan senior seperti Tweety.",
  str_homestory_chat_33221011 = "Dalam hal itu... Ada sesuatu yang harus aku lindungi sekarang juga!",
  str_homestory_chat_33221012 = "Untuk melindungi makan malam malam ini, aku harus menghentikan Vice dari mengembangkan hidangan baru!!!",
  str_homestory_chat_33222001 = "Colossus.",
  str_homestory_chat_33222002 = "Aku tahu.",
  str_homestory_chat_33222003 = "Rekanmu meninggalkan medan perang untuk menghabiskan ribuan tahun bersamamu.",
  str_homestory_chat_33222004 = "Dan semangatmu berpadu dalam harmoni yang ajaib.",
  str_homestory_chat_33222005 = "Aku juga terkejut saat membuka pusaka keluarga... Sekarang aku paham.",
  str_homestory_chat_33222006 = "Sekarang kamu sebut itu, kita memang memiliki takdir yang serupa.",
  str_homestory_chat_33222007 = "Memang, bahkan nenek moyang kita bertemu jauh di masa lalu.",
  str_homestory_chat_33222008 = "Kamu telah membantu saya menyelesaikan misi saya, jadi sekarang, saya akan membantu kamu melindungi Colossus.",
  str_homestory_chat_33222009 = "Terima kasih, dengan bantuanmu...",
  str_homestory_chat_33222010 = "Kita pasti bisa melakukannya!",
  str_homestory_chat_33223001 = "Kemuliaan leluhur.",
  str_homestory_chat_33223002 = "Aku memahami perasaannya.",
  str_homestory_chat_33223003 = "Setelah semua, aku telah sampai sejauh ini dengan mengikuti kehendak leluhurku.",
  str_homestory_chat_33223004 = "Perjalanan ini tidak mudah, dipenuhi dengan keraguan...",
  str_homestory_chat_33223005 = "Tapi, aku telah memenuhi takdirku. Dan kamu, ke mana jalanmu membawamu?",
  str_homestory_chat_33223006 = "Ada beberapa pencapaian...",
  str_homestory_chat_33223007 = "Maka, selamat untukmu.",
  str_homestory_chat_33223008 = "Aku masih mengerjakannya...",
  str_homestory_chat_33223009 = "Maka aku akan mengawasimu.",
  str_homestory_chat_33223010 = "Jika kamu butuh bantuan, jangan ragu untuk memberitahuku.",
  str_homestory_chat_33223011 = "Aku tidak hanya berterima kasih atas bantuanmu. Aku benar-benar terpesona oleh sejarah Caelestites.",
  str_homestory_chat_33223012 = "Terima kasih.",
  str_homestory_chat_33224001 = "Keadilan!",
  str_homestory_chat_33224002 = "Oh?",
  str_homestory_chat_33224003 = "Apakah kamu juga ingin menjadi kawan keadilan?",
  str_homestory_chat_33224004 = "Saya sudah!",
  str_homestory_chat_33224005 = "Saya benar-benar menghargai rasa keadilan Anda melalui waktu kita bersama.",
  str_homestory_chat_33224006 = "Aku yakin kamu pasti adalah kandidat yang paling cocok.",
  str_homestory_chat_33224007 = "Tentu saja aku mau!",
  str_homestory_chat_33224008 = "Betulkah? Memiliki tekad dan keyakinan seperti itu sangat mengesankan.",
  str_homestory_chat_33224009 = "Tapi, ini bukan pekerjaan yang mudah.",
  str_homestory_chat_33224010 = "Apakah kamu ingin menjadi asistenku?",
  str_homestory_chat_33224011 = "Tindakan kita melawan kejahatan di malam hari pasti akan lebih efektif dengan kehadiranmu.",
  str_homestory_chat_33224012 = "Uh, jika ini tentang hal ini, tolong izinkan aku untuk memikirkannya sedikit lebih banyak!",
  str_homestory_chat_33225001 = "Persahabatan.",
  str_homestory_chat_33225002 = "Pertemanan memang indah.",
  str_homestory_chat_33225003 = "Saya selalu bergerak, berganti pekerjaan dan tidak pernah benar-benar menetap.",
  str_homestory_chat_33225004 = "Tapi sekarang, aku telah menemukan beberapa orang luar biasa untuk disebut teman, seperti senior saya di Courier Union dan teman spesial itu di malam hari.",
  str_homestory_chat_33225005 = "Mereka adalah teman-teman yang ingin aku lindungi.",
  str_homestory_chat_33225006 = "Apa jenis persahabatan yang ingin kamu lindungi?",
  str_homestory_chat_33225007 = "Persahabatan dengan semua orang di Colossus!",
  str_homestory_chat_33225008 = "Benar, semua orang di Colossus sangat baik.",
  str_homestory_chat_33225009 = "Hanya saja, saya terbiasa menjalani hidup dengan menjaga jarak dari orang lain.",
  str_homestory_chat_33225010 = "Sepertinya aku belum siap, untuk berteman dengan setiap orang.",
  str_homestory_chat_33225011 = "Jadi jika kita sedang membicarakan tentang saat ini...",
  str_homestory_chat_33225012 = "Persahabatanku dengan kamu!",
  str_homestory_chat_33225013 = "Maaf, aku hanya... Aku tidak berpikir aku menyebutkanmu.",
  str_homestory_chat_33225014 = "Lagi pula, keberadaanmu di sisiku telah menjadi sesuatu yang aku terbiasa.",
  str_homestory_chat_33225015 = "Izinkan saya memperbaiki.",
  str_homestory_chat_33225016 = "Menjaga pertemanan kita sangatlah penting.",
  str_homestory_chat_33225017 = "Ini kehormatan saya! Akan kujaga persahabatan ini!",
  str_homestory_chat_33399999 = "Jika suatu hari kamu bangun dan kamu adalah orang terakhir yang tersisa di dunia, apa yang akan kamu lakukan?",
  str_homestory_chat_33321001 = "Lanjutkan tidur.",
  str_homestory_chat_33321002 = "Aku pasti sedang bermimpi.",
  str_homestory_chat_33321003 = "Mengapa begitu? Biasanya, orang akan langsung pergi menjelajah dan melakukan hal-hal yang biasanya tidak bisa mereka lakukan, bukan?",
  str_homestory_chat_33321004 = "Tapi aku bintangnya!",
  str_homestory_chat_33321005 = "Biasanya, banyak hal yang tidak biasa terjadi.",
  str_homestory_chat_33321006 = "Hahaha, kamu, dari semua orang, bahkan lebih sombong daripada saya.",
  str_homestory_chat_33321007 = "Pernahkah kamu memikirkannya? Jika semua orang menghilang, kemampuan psikis kamu akan menjadi tidak berguna, bukan?",
  str_homestory_chat_33321008 = "Yah... Karena tidak ada yang bisa dilakukan, sebaiknya aku tidur saja.",
  str_homestory_chat_33321009 = "Apa yang ingin kamu lakukan tapi tidak bisa?",
  str_homestory_chat_33321010 = "Hmm. Awalnya, sepertinya ada banyak, tetapi setelah dipikirkan lebih lanjut, sepertinya tidak banyak.",
  str_homestory_chat_33321011 = "Aku akan melakukan apa pun yang aku mau, aturan tidak bisa menghentikanku.",
  str_homestory_chat_33321012 = "Tidak ada hal seperti \"sesuatu yang biasanya tidak bisa kamu lakukan\"!",
  str_homestory_chat_33321013 = "Sungguh pria yang berbahaya...",
  str_homestory_chat_33322001 = "Pertama, buru-buru ke taman hiburan di Umbraton atau Harbour City.",
  str_homestory_chat_33322002 = "Lalu, mari kita nikmati kegiatan yang biasanya memerlukan antrean!",
  str_homestory_chat_33322003 = "Haruskah aku menyebutmu... jujur, atau tegang?",
  str_homestory_chat_33322004 = "Mimpi Anda bisa menjadi kenyataan hanya dengan menyelinap masuk ke taman hiburan saat tengah malam.",
  str_homestory_chat_33322005 = "... Siapa yang akan berpikir untuk melakukan hal seperti itu!?",
  str_homestory_chat_33322006 = "Anda adalah Lady Pepita yang bersinar dan tak terbatas.",
  str_homestory_chat_33322007 = "Ayo, aku akan membawamu ke sana malam ini.",
  str_homestory_chat_33322008 = "(Oh, tidak. Aku sebenarnya sedikit terpesona...)",
  str_homestory_chat_33323001 = "Pergi ke toko buku untuk membaca buku secara gratis",
  str_homestory_chat_33323002 = "Aku bisa melihat sepanjang hari, duduk di mana saja yang aku inginkan, dan tidak perlu khawatir tentang tatapan tajam karyawan toko kepadaku... Ah, surga!",
  str_homestory_chat_33323003 = "...",
  str_homestory_chat_33323004 = "Aku tahu harapanku sederhana, tapi kamu tidak perlu menatapku dengan begitu terkejut...",
  str_homestory_chat_33323005 = "Kamu salah paham, saya tidak berpikir keinginanmu itu rendah hati sama sekali.",
  str_homestory_chat_33323006 = "Tetapi jika kamu ingin membaca buku secara gratis, semua yang perlu kamu lakukan adalah mengenakan pakaian yang bagus... dan kamu bisa masuk ke toko buku dan memilih apa saja yang kamu inginkan.",
  str_homestory_chat_33323007 = "Setelah Anda memilih, cukup sebutkan nama bangsawan mana saja. Toko buku dapat mengumpulkan pembayaran di akhir Tsuki.",
  str_homestory_chat_33323008 = "Para bangsawan itu memperlakukan tagihan bulanan mereka seperti serpihan salju, mereka tidak pernah repot-repot untuk memeriksanya satu per satu.",
  str_homestory_chat_33323009 = "K-Kamu... In-Ini adalah kejahatan, bukan?",
  str_homestory_chat_33323010 = "Ha! Bangsawan-bangsawan yang tidak tahu apa-apa, saya lah yang menyebarkan pengetahuan kepada rakyat jelata... Dan kamu menyebut ini sebagai kejahatan?",
  str_homestory_chat_33323011 = "Aku akan bilang ini adalah berkatku.",
  str_homestory_chat_33323012 = "...",
  str_homestory_chat_33324001 = "Mandi di sungai",
  str_homestory_chat_33324002 = "Uih!",
  str_homestory_chat_33324003 = "*batuk*... Sejujurnya, aku sudah lama ingin melakukan ini.",
  str_homestory_chat_33324004 = "Tapi kamu masih khawatir... benar?",
  str_homestory_chat_33324005 = "Tidak, saya pergi sepanjang waktu.",
  str_homestory_chat_33324006 = "Apa?! Kamu tidak khawatir—",
  str_homestory_chat_33324007 = "Ada yang datang?",
  str_homestory_chat_33324008 = "Petey ada di sini. Lagipula, apa jenis orang yang akan menatap orang lain saat mereka sedang mandi?",
  str_homestory_chat_33324009 = "Lagipula, semua orang sama, apa yang perlu dipermalukan?",
  str_homestory_chat_33324010 = "... Tidak, tidak, tunggu! Jangan coba-coba menipuku untuk mandi di sungai sekarang juga!",
  str_homestory_chat_33324011 = "Diserang oleh piranha?",
  str_homestory_chat_33324012 = "Ketika saya pergi mandi di sungai, saya biasanya tertutup lumpur.",
  str_homestory_chat_33324013 = "Hiu akan diracuni dan pingsan.",
  str_homestory_chat_33324014 = "Sangat megah... tidak, bukan itu yang saya maksud untuk dilihat!",
  str_homestory_chat_33325001 = "Duduk di takhta Lumopolis",
  str_homestory_chat_33325002 = "Kamu masih akan menekuk kakimu!",
  str_homestory_chat_33325003 = "Huh, aku kehabisan ide, sudah cukup lama aku duduk.",
  str_homestory_chat_33325004 = "Apa?! Biarkan aku bertanya dulu, kamu tidak berizin, kan...?",
  str_homestory_chat_33325005 = "Bisa jadi ayah Carleen juga akan mengundangku dengan ramah?",
  str_homestory_chat_33325006 = "Apakah kursi itu nyaman untuk duduk?",
  str_homestory_chat_33325007 = "Ck, sama sekali tidak nyaman, ini terlalu keras!",
  str_homestory_chat_33325008 = "Demi Carleen, saya meninggalkan bantal di sana.",
  str_homestory_chat_33325009 = "Aku benar-benar berharap Tuan Kota akan berterima kasih padaku... Hahaha!",
  str_homestory_chat_33325010 = "Bagaimana kamu bisa ke sana?",
  str_homestory_chat_33325011 = "Malam itu, aku sedang menggambar grafiti di dinding putih yang indah, lalu para pengawal datang...",
  str_homestory_chat_33325012 = "Saya baru saja mengetahui bahwa itu adalah Balai Kehakiman Lumopolis.",
  str_homestory_chat_33325013 = "...",
  str_homestory_chat_33325014 = "Dan kemudian saya berlari ke tempat di mana tahta Tuan Kota berada!",
  str_homestory_chat_33325015 = "Demi keamanan, aku harus menjaga jarak tertentu dari kamu...",
  str_homestory_chat_33429999 = "Maukah kamu berbagi beberapa hal menarik tentang waktu ini?",
  str_homestory_chat_33421001 = "Tentu saja, tapi kamu tidak perlu begitu sopan.",
  str_homestory_chat_33421002 = "Sudah begitu lama. Saya hanya tahu sedikit tentang dunia sekarang.",
  str_homestory_chat_33421003 = "Dan aku bisa menjadi lebih merepotkan daripada membantu jika aku tidak menyesuaikan diri dengan dunia modern.",
  str_homestory_chat_33421004 = "Tolong ceritakan lebih banyak tentang dunia ini.",
  str_homestory_chat_33421005 = "Oh, jangan khawatir tentang itu. Kamu lihat, aku telah menghabiskan tujuh belas tahun terakhir di bawah tanah.",
  str_homestory_chat_33421006 = "Saya masih sangat dalam proses menjelajahi dunia ini!",
  str_homestory_chat_33421007 = "Jadi, kita bisa saling berbagi pengalaman satu sama lain.",
  str_homestory_chat_33421008 = "Mari nikmati dunia ini bersama!",
  str_homestory_chat_33421009 = "Ini memang dunia yang hebat.",
  str_homestory_chat_33421010 = "Senangnya bagi saya untuk berbagi pikiran saya dengan Anda.",
  str_homestory_chat_33421011 = "Demi nama Achilles, aku juga akan berbagi semua yang kutahu dengan kamu.",
  str_homestory_chat_33421012 = "Jika kamu ingin mengetahui tentang sesama Caelestite, saya dengan senang hati akan berbagi cerita mereka denganmu.",
  str_homestory_chat_33421013 = "Saya sangat tertarik! Ceritakan tentang mereka suatu hari nanti.",
  str_homestory_chat_33422001 = "Apakah kamu tertarik dengan balapan mobil Rediesel?",
  str_homestory_chat_33422002 = "Mobil... Saya baru saja diperkenalkan dengan istilah itu.",
  str_homestory_chat_33422003 = "Kami dulu menggunakan kereta kuda untuk transportasi di zamanku.",
  str_homestory_chat_33422004 = "Dikatakan bahwa mobil tidak hanya lebih cepat daripada kereta kuda, tetapi juga lebih stabil.",
  str_homestory_chat_33422005 = "Teknologi sekarang ini sungguh mengagumkan.",
  str_homestory_chat_33422006 = "Mau coba mengemudi?",
  str_homestory_chat_33422007 = "Saya belum menguasai keterampilan ini.",
  str_homestory_chat_33422008 = "Mencobanya dengan gegabah kemungkinan akan menimbulkan banyak risiko dan masalah yang tidak perlu.",
  str_homestory_chat_33422009 = "Apakah kamu ingin aku mengajakmu jalan-jalan?",
  str_homestory_chat_33422010 = "Kedengarannya seperti kegiatan yang sempurna untuk waktu luang.",
  str_homestory_chat_33422011 = "Namun, sebagai seorang prajurit, aku benar-benar ingin belajar bagaimana mengendalikan mobilku sendiri.",
  str_homestory_chat_33422012 = "Mungkin kamu bisa berlatih mengemudi di masa depan menggunakan simulator di Colossus. Saya dengan senang hati akan mengajarkanmu.",
  str_homestory_chat_33422013 = "Apa ada alat yang begitu praktis?",
  str_homestory_chat_33422014 = "Tolong biarkan saya mencobanya. Saya memang ingin mempelajari beberapa teknik zaman baru.",
  str_homestory_chat_33422015 = "Bukan masalah!",
  str_homestory_chat_33423001 = "Misalnya, akuarium di Harbour City? Tempat itu cukup bagus.",
  str_homestory_chat_33423002 = "Istilah yang baru. Tempat macam apa itu?",
  str_homestory_chat_33423003 = "Tempat yang sangat seperti mimpi.",
  str_homestory_chat_33423004 = "Seolah-olah tenggelam dalam mimpi tentang laut dalam.",
  str_homestory_chat_33423005 = "Kamu bisa melihat banyak pemandangan yang tidak bisa dilihat di darat.",
  str_homestory_chat_33423006 = "Sebuah tempat yang luar biasa.",
  str_homestory_chat_33423007 = "Mereka memiliki berbagai jenis kehidupan laut.",
  str_homestory_chat_33423008 = "Hanya satu kunjungan sudah cukup untuk belajar banyak tentang lautan.",
  str_homestory_chat_33423009 = "Itu terdengar menarik, aku menantikannya.",
  str_homestory_chat_33423010 = "Semakin banyak orang yang bersama Anda, semakin kaya pengalaman di tempat seperti itu.",
  str_homestory_chat_33423011 = "Kamu dapat mengundang Star Warriors untuk bergabung denganmu di lain waktu.",
  str_homestory_chat_33423012 = "Itu sangat perhatian dari Anda!",
  str_homestory_chat_33423013 = "Jika memungkinkan, saya berharap kamu bisa menjadi pemandu kami dan menemani kami.",
  str_homestory_chat_33423014 = "Kamu juga partner kami.",
  str_homestory_chat_33423015 = "Baiklah! Kapan saja kamu membutuhkanku, aku ada di sana!",
  str_homestory_chat_33424001 = "Anda pasti tertarik pada Latihan Militer Gabungan Illumina, bukan?",
  str_homestory_chat_33424002 = "Latihan Militer Gabungan...",
  str_homestory_chat_33424003 = "Sepertinya ini latihan militer di mana para Aurorian berkumpul bersama?",
  str_homestory_chat_33424004 = "Ya, Aurorian dari semua faksi akan ada di sana.",
  str_homestory_chat_33424005 = "Mereka akan mengasah keterampilan mereka.",
  str_homestory_chat_33424006 = "Dan mereka akan berjuang demi kehormatan.",
  str_homestory_chat_33424007 = "Acara sebesar itu. Aku sangat ingin ada di sana.",
  str_homestory_chat_33424008 = "Apakah Anda telah berpartisipasi dalam Latihan Militer Gabungan? Bagaimana performa Anda?",
  str_homestory_chat_33424009 = "T-Tidak terlalu bagus.",
  str_homestory_chat_33424010 = "Setelah semua, kami tidak berhasil mengamankan kemenangan akhir...",
  str_homestory_chat_33424011 = "Itu bagus!",
  str_homestory_chat_33424012 = "Sudah hebat bisa bertahan sampai akhir!",
  str_homestory_chat_33424013 = "Begitu rupanya. Aku mengerti.",
  str_homestory_chat_33424014 = "Jika diberi kesempatan, saya benar-benar ingin pergi dan melihat sendiri. Aurorian tampaknya hidup baik-baik saja hari ini.",
  str_homestory_chat_33424015 = "Dengan kata lain... jika semua Star Warriors berpartisipasi... hal-hal bisa menjadi sedikit terlalu intens.",
  str_homestory_chat_33425001 = "Kita tidak boleh melewatkan pesona eksotis dari Longzhou!",
  str_homestory_chat_33425002 = "Itu benar-benar tanah yang mempesona di seberang laut.",
  str_homestory_chat_33425003 = "Sebuah kerajaan kuno berkuasa atas banyak kerajaan vasal.",
  str_homestory_chat_33425004 = "Tidak hanya ada Aurorian yang agak berbeda dari kita, tetapi juga ada makhluk yang dikenal sebagai Fiendlings.",
  str_homestory_chat_33425005 = "Sebuah kerajaan kuno, ya ...",
  str_homestory_chat_33425006 = "Setelah bertahan selama berabad-abad, bahkan ribuan tahun, dari berbagai cobaan dan kesulitan.",
  str_homestory_chat_33425007 = "Apakah mereka semua selamat?",
  str_homestory_chat_33425008 = "Benar! Luar biasa, bukan?",
  str_homestory_chat_33425009 = "Saya masih belajar tentang Longzhou.",
  str_homestory_chat_33425010 = "Tapi jika kamu tertarik, saya bisa menceritakan kisah petualangan saya di Longzhou.",
  str_homestory_chat_33425011 = "Ada juga beberapa buku kuno dari Longzhou yang bisa saya bagikan dengan Anda.",
  str_homestory_chat_33425012 = "Sangat baik dari kamu, aku akan memastikan untuk membaca dan mempelajari secara menyeluruh.",
  str_homestory_chat_33425013 = "Dan... sebuah petualangan?",
  str_homestory_chat_33425014 = "Tampaknya Longzhou memiliki banyak cerita dan legenda tentang pahlawan.",
  str_homestory_chat_33425015 = "Aku tak sabar menantikannya.",
  str_homestory_chat_33425016 = "Oke, malam ini aku akan meminta Fireflies membawakanmu beberapa buku."
